static RedirectPolicySpec make_test_redirect_policy() {
    RedirectPolicySpec policy{};
    policy.scheme = RedirectPolicyScheme::Http;
    policy.authority = RedirectPolicyAuthority::RequestHost;
    policy.port = RedirectPolicyPort::ActualListener;
    policy.path = RedirectPolicyPath::Static;
    policy.query = RedirectPolicyQuery::PreserveRaw;
    policy.date = RedirectPolicyDate::Current;
    policy.connection = RedirectPolicyConnection::Close;
    policy.header_order = RedirectPolicyHeaderOrder::LocationThenConnection;
    policy.status_code = 301;
    policy.reason = {"Moved Permanently", 17};
    policy.server = {"nginx/1.29.7", 12};
    policy.content_type = {"text/html", 9};
    policy.target_path = {"/api/", 5};
    policy.body = {kRedirectBody, sizeof(kRedirectBody) - 1};
    return policy;
}

static RedirectPolicySpec make_test_fixed_redirect_policy() {
    RedirectPolicySpec policy = make_test_redirect_policy();
    policy.authority = RedirectPolicyAuthority::Static;
    policy.port = RedirectPolicyPort::Omit;
    policy.query = RedirectPolicyQuery::Discard;
    policy.header_order = RedirectPolicyHeaderOrder::ConnectionThenLocation;
    policy.static_authority = {"redirect.example", 16};
    policy.target_path = {"/new", 4};
    return policy;
}

static RedirectPolicySpec make_test_fixed_302_redirect_policy() {
    RedirectPolicySpec policy = make_test_fixed_redirect_policy();
    policy.status_code = 302;
    policy.reason = {"Moved Temporarily", 17};
    policy.body = {kFixed302RedirectBody, sizeof(kFixed302RedirectBody) - 1};
    return policy;
}

static bool configure_deferred_preflight_test_route(RouteConfig& config) {
    if (!config.add_upstream("backend", 0x7F000001, 9000).has_value()) return false;
    if (config.add_redirect_policy(make_test_fixed_redirect_policy()) != 1) return false;
    ForwardResponsePolicySpec response{};
    response.version = ResponsePolicyVersion::Http11;
    response.framing = ResponsePolicyFraming::ContentLength;
    response.connection = ResponsePolicyConnection::Request;
    response.date = ResponsePolicyDate::Current;
    response.server = {"rut", 3};
    if (config.add_response_policy(response) != 1) return false;
    ForwardFailurePolicySpec failure{};
    failure.version = ForwardFailurePolicyVersion::Http11;
    failure.status_code = 502;
    failure.date = ForwardFailurePolicyDate::Current;
    failure.connection = ForwardFailurePolicyConnection::Request;
    failure.reason = {"Bad Gateway", 11};
    failure.content_type = {"text/plain", 10};
    failure.server = {"rut", 3};
    failure.body = {"bad", 3};
    if (config.add_failure_policy(failure) != 1) return false;
    failure.status_code = 504;
    failure.reason = {"Gateway Time-out", 16};
    failure.body = {"slow", 4};
    if (config.add_failure_policy(failure) != 2) return false;
    if (config.add_policy_bundle(1, 1, 2, 1, ForwardResponseBufferingMode::CompleteContentLength) !=
        1)
        return false;
    // Runtime-only fixture: production deferred publication is private and is
    // proven end-to-end by the loader test. Start from the public neutral API,
    // then forge only the owned RouteEntry metadata needed to exercise H1/H2
    // fail-closed behavior without exposing a native deferred insertion path.
    if (!config.add_jit_handler("/", kRouteMethodGet, &deferred_preflight_handler, false))
        return false;
    config.routes[0].forward_preflight_mode = ForwardPreflightMode::AfterCanonicalSelection;
    config.routes[0].preflight_forward_policy_bundle_id = 1;
    return true;
}

// Date is the sole dynamic field in the pinned redirect wire vector. Keep the
// comparison byte-exact everywhere else, including framing and body bytes.
static bool normalize_redirect_date(u8* data, u32 len) {
    static constexpr char kDatePrefix[] = "\r\nDate: ";
    constexpr u32 kDatePrefixLen = sizeof(kDatePrefix) - 1;
    constexpr u32 kDateLen = 29;  // IMF-fixdate
    for (u32 i = 0; i + kDatePrefixLen + kDateLen + 2 <= len; i++) {
        if (__builtin_memcmp(data + i, kDatePrefix, kDatePrefixLen) != 0) continue;
        const u32 date_start = i + kDatePrefixLen;
        if (data[date_start + kDateLen] != '\r' || data[date_start + kDateLen + 1] != '\n')
            return false;
        for (u32 j = 0; j < kDateLen; j++) data[date_start + j] = 'X';
        return true;
    }
    return false;
}

