// Replacing a header the client sent twice must replace the first AND drop the
// rest, so the client's value can't survive past the override.
TEST(set_header, replaces_all_duplicate_client_fields) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "GET / HTTP/1.1\r\nHost: client\r\nX-Dup: a\r\nX-Dup: b\r\n\r\n";
    const u32 kLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kLen), kLen);
    c->req_header_end = kLen;
    c->req_initial_send_len = kLen;
    c->req_header_overrides[0].name = Str{"X-Dup", 5};
    c->req_header_overrides[0].value = Str{"override", 8};
    c->req_header_override_count = 1;

    CHECK(rut::apply_request_header_overrides(*c));
    const u8* d = c->recv_buf.data();
    const u32 n = c->recv_buf.len();
    CHECK_EQ(count_occurrences(d, n, "X-Dup:"), 1u);
    CHECK(buf_has(d, n, "X-Dup: override\r\n"));
    CHECK(!buf_has(d, n, "X-Dup: a"));
    CHECK(!buf_has(d, n, "X-Dup: b"));
    CHECK(buf_has(d, n, "Host: client\r\n"));  // unrelated header untouched
    // req_header_end stays consistent with the rewritten block (ends in CRLFCRLF).
    REQUIRE(c->req_header_end >= 4 && c->req_header_end <= n);
    CHECK(__builtin_memcmp(d + c->req_header_end - 4, "\r\n\r\n", 4) == 0);
}

// Appending must preserve every client-supplied field and serialize one more
// field before the terminating blank line.
TEST(add_header, preserves_duplicate_client_fields_and_appends) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "GET / HTTP/1.1\r\nHost: client\r\nX-Tag: a\r\nX-Tag: b\r\n\r\n";
    const u32 kLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kLen), kLen);
    c->req_header_end = kLen;
    c->req_initial_send_len = kLen;
    c->req_header_overrides[0].name = Str{"X-Tag", 5};
    c->req_header_overrides[0].value = Str{"tail", 4};
    c->req_header_override_count = 1;
    c->req_header_append_mask = 1;

    CHECK(rut::apply_request_header_overrides(*c));
    const u8* d = c->recv_buf.data();
    const u32 n = c->recv_buf.len();
    CHECK_EQ(count_occurrences(d, n, "X-Tag:"), 3u);
    CHECK(buf_has(d, n, "X-Tag: a\r\n"));
    CHECK(buf_has(d, n, "X-Tag: b\r\n"));
    CHECK(buf_has(d, n, "X-Tag: tail\r\n\r\n"));
    REQUIRE(c->req_header_end >= 4 && c->req_header_end <= n);
    CHECK(__builtin_memcmp(d + c->req_header_end - 4, "\r\n\r\n", 4) == 0);
}

// Injecting a header absent from the request appends one line before the blank
// line; a large value is serialized verbatim (no fixed scratch limit).
TEST(set_header, injects_large_value_without_scratch_limit) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "GET / HTTP/1.1\r\nHost: client\r\n\r\n";
    const u32 kLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kLen), kLen);
    c->req_header_end = kLen;
    c->req_initial_send_len = kLen;
    // A value longer than the old 2048-byte scratch buffer (and still fits 4096).
    static char big[3000];
    for (u32 i = 0; i < sizeof(big); i++) big[i] = 'x';
    c->req_header_overrides[0].name = Str{"X-Big", 5};
    c->req_header_overrides[0].value = Str{big, sizeof(big)};
    c->req_header_override_count = 1;

    CHECK(rut::apply_request_header_overrides(*c));
    const u8* d = c->recv_buf.data();
    const u32 n = c->recv_buf.len();
    CHECK(buf_has(d, n, "X-Big: "));
    CHECK_EQ(n, kLen + 5 + 2 + static_cast<u32>(sizeof(big)) + 2);  // "X-Big" + ": " + val + CRLF
}

// When an override can't fit recv_buf, the function fails closed (returns false)
// so the caller can reject rather than forward without the configured header.
TEST(set_header, fails_closed_when_override_cannot_fit) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "GET / HTTP/1.1\r\nHost: client\r\n\r\n";
    const u32 kLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kLen), kLen);
    c->req_header_end = kLen;
    c->req_initial_send_len = kLen;
    // Leave no spare capacity, so inserting any new header line must fail.
    c->recv_buf.commit(c->recv_buf.write_avail());
    const u32 full = c->recv_buf.len();
    c->req_header_overrides[0].name = Str{"X-Inject", 8};
    c->req_header_overrides[0].value = Str{"v", 1};
    c->req_header_override_count = 1;

    CHECK(!rut::apply_request_header_overrides(*c));  // fail closed
    CHECK_EQ(c->recv_buf.len(), full);                // buffer left untouched
    CHECK_EQ(c->req_header_end, kLen);
}

// Defense-in-depth for overrides recorded directly via RIR (the DSL parser
// validates literals at compile time): a value carrying CRLF would inject extra
// outbound headers, so it must fail the request closed rather than be written.
TEST(set_header, rejects_crlf_injection_value) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "GET / HTTP/1.1\r\nHost: client\r\n\r\n";
    const u32 kLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kLen), kLen);
    c->req_header_end = kLen;
    c->req_initial_send_len = kLen;
    c->req_header_overrides[0].name = Str{"X-Evil", 6};
    c->req_header_overrides[0].value = Str{"a\r\nInjected: yes", 16};
    c->req_header_override_count = 1;
    CHECK(!rut::apply_request_header_overrides(*c));
    CHECK_EQ(c->recv_buf.len(), kLen);  // untouched
    CHECK(!buf_has(c->recv_buf.data(), c->recv_buf.len(), "Injected"));
}

// A value that aliases recv_buf (e.g. a request-derived value recorded via RIR)
// would be shifted/overwritten by the in-place rewrite, so it fails closed.
TEST(set_header, fails_closed_on_recv_buf_aliasing_value) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "GET / HTTP/1.1\r\nHost: client\r\n\r\n";
    const u32 kLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kLen), kLen);
    c->req_header_end = kLen;
    c->req_initial_send_len = kLen;
    // Point the value at the "client" token inside recv_buf (the Host value).
    c->req_header_overrides[0].name = Str{"X-Alias", 7};
    c->req_header_overrides[0].value =
        Str{reinterpret_cast<const char*>(c->recv_buf.data()) + 22, 6};  // "client"
    c->req_header_override_count = 1;
    CHECK(!rut::apply_request_header_overrides(*c));
    CHECK_EQ(c->recv_buf.len(), kLen);  // untouched
}

// An override with no usable parsed header block (req_header_end unset) fails
// closed rather than forwarding the request without the configured mutation.
TEST(set_header, fails_closed_without_header_block) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "GET / HTTP/1.1\r\nHost: client\r\n\r\n";
    const u32 kLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kLen), kLen);
    c->req_header_end = 0;  // parser set no header block
    c->req_header_overrides[0].name = Str{"X-Inject", 8};
    c->req_header_overrides[0].value = Str{"v", 1};
    c->req_header_override_count = 1;
    CHECK(!rut::apply_request_header_overrides(*c));
}

// Recording more overrides than the table holds (reachable only via direct RIR —
// the DSL caps + dedupes) sets the overflow flag (rut_helper_req_set_header), and
// the apply path fails closed so a dropped override is never forwarded as a silent
// no-op. Drive the apply-side contract directly via the flag.
TEST(set_header, fails_closed_on_record_overflow) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "GET / HTTP/1.1\r\nHost: client\r\n\r\n";
    const u32 kLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kLen), kLen);
    c->req_header_end = kLen;
    c->req_initial_send_len = kLen;
    // A valid recorded override plus the overflow signal: still fail closed.
    c->req_header_overrides[0].name = Str{"X-H", 3};
    c->req_header_overrides[0].value = Str{"v", 1};
    c->req_header_override_count = 1;
    c->req_header_override_overflow = true;
    CHECK(!rut::apply_request_header_overrides(*c));
    CHECK_EQ(c->recv_buf.len(), kLen);  // untouched
}

TEST(set_path, snapshots_response_mutations_before_request_rewrite) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "GET /original HTTP/1.1\r\nHost: client\r\n\r\n";
    const u32 kLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kLen), kLen);
    capture_request_metadata(*c);
    REQUIRE_EQ(c->checked_raw_request_target().state, RawRequestTargetWitnessState::Valid);
    REQUIRE(c->checked_raw_request_target().target.eq({"/original", 9}));
    c->req_header_end = kLen;
    c->req_initial_send_len = kLen;
    c->req_path_overridden = true;
    c->req_path_override = {"/forwarded", 10};
    c->resp_header_mutations[0] = {{"X-Original", 10},
                                   {reinterpret_cast<const char*>(c->recv_buf.data()) + 4, 9},
                                   ConnectionBase::RespHeaderMutationMode::Set};
    c->resp_header_mutation_count = 1;

    REQUIRE(snapshot_response_mutations_before_request_rewrite(*c));
    REQUIRE(rewrite_request_line_path(*c));

    CHECK_EQ(c->checked_raw_request_target().state, RawRequestTargetWitnessState::Neutral);
    CHECK(c->resp_header_mutations[0].value.eq({"/original", 9}));
    CHECK(buf_has(c->recv_buf.data(), c->recv_buf.len(), "GET /forwarded HTTP/1.1\r\n"));
    CHECK_FALSE(c->retry_req_snapshot_replayable);
}

TEST(target_transform, h1_forward_rejects_before_upstream_side_effects) {
    SmallLoop loop;
    loop.setup();
    RouteConfig cfg{};
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, 8080).has_value());
    char strip[] = "/api/";
    char replace[] = "/v1/";
    REQUIRE_EQ(cfg.add_target_transform({{strip, 5}, {replace, 4}}), 1u);

    const u16 ids[] = {1,
                       kInvalidForwardTargetTransformId,
                       kInvalidForwardTargetTransformId,
                       kInvalidForwardTargetTransformId};
    for (u16 id : ids) {
        auto* conn = loop.alloc_conn();
        REQUIRE(conn != nullptr);
        conn->request_config = &cfg;
        conn->keep_alive = true;
        conn->target_transform_id = id;
        conn->target_transform_recorded = true;
        JitDispatchOutcome outcome{};
        outcome.kind = JitDispatchOutcome::Kind::Forward;
        outcome.upstream_id = 0;
        loop.backend.clear_ops();

        handle_jit_outcome<SmallLoop>(&loop, *conn, outcome, nullptr, true);

        CHECK_EQ(conn->resp_status, 400u);
        CHECK_EQ(conn->upstream_fd, -1);
        CHECK_FALSE(conn->upstream_slot_held);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 1u);
        conn->reset();
        CHECK_FALSE(conn->target_transform_recorded);
        CHECK_EQ(conn->target_transform_id, 0u);
    }
}

TEST(response_policy, suppress_body_metadata_fails_closed_before_upstream_connect) {
    SmallLoop loop;
    loop.setup();
    RouteConfig cfg{};
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, 8080).has_value());
    static constexpr char kServer[] = "server";
    ForwardResponsePolicySpec policy{};
    policy.version = ResponsePolicyVersion::Http11;
    policy.framing = ResponsePolicyFraming::ContentLength;
    policy.connection = ResponsePolicyConnection::Request;
    policy.date = ResponsePolicyDate::Current;
    policy.head_mode = ResponsePolicyHeadMode::SuppressBody;
    policy.server = {kServer, sizeof(kServer) - 1};
    REQUIRE_EQ(cfg.add_response_policy(policy), 1u);

    const char* requests[] = {
        "GET /api HTTP/1.1\r\nHost: client\r\n\r\n",
        "HEAD /api HTTP/1.1\r\nHost: client\r\n\r\n",
        "HEAD /api HTTP/1.1\r\nHost: client\r\nConnection: close\r\n"
        "Content-Length: 0\r\n\r\n",
        "HEAD /api HTTP/1.1\r\nHost: client\r\nConnection: close\r\n"
        "Transfer-Encoding: identity\r\n\r\n",
        "HEAD /api HTTP/1.1\r\nHost: client\r\nConnection: close\r\n"
        "TE: trailers\r\n\r\n",
        "HEAD /api HTTP/1.1\r\nHost: client\r\nConnection: close\r\n"
        "Expect: 100-continue\r\n\r\n",
        "HEAD /api HTTP/1.1\r\nHost: client\r\nConnection: close\r\n"
        "Upgrade: websocket\r\n\r\n",
    };
    for (const char* request : requests) {
        auto* conn = loop.alloc_conn();
        REQUIRE(conn != nullptr);
        const u32 request_len = static_cast<u32>(strlen(request));
        REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(request), request_len),
                   request_len);
        capture_request_metadata(*conn);
        conn->request_config = &cfg;

        JitDispatchOutcome outcome{};
        outcome.kind = JitDispatchOutcome::Kind::Forward;
        outcome.upstream_id = 0;
        // Exercise the request-policy rewrite before SuppressBody admission;
        // the original hop-by-hop facts must still reject these vectors.
        outcome.request_policy_id = 1;
        outcome.response_policy_id = 1;
        loop.backend.clear_ops();
        handle_jit_outcome<SmallLoop>(&loop, *conn, outcome, nullptr, true);

        CHECK_EQ(conn->resp_status, 400u);
        CHECK_EQ(conn->upstream_fd, -1);
        CHECK_FALSE(conn->upstream_slot_held);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 1u);
        loop.free_conn(*conn);
    }
}

TEST(response_policy, suppress_body_abandon_is_idempotent_and_ignores_late_event) {
    SmallLoop loop;
    loop.setup();
    RouteConfig cfg{};
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, 8080).has_value());
    ForwardResponsePolicySpec policy{};
    static constexpr char kServer[] = "server";
    policy.version = ResponsePolicyVersion::Http11;
    policy.framing = ResponsePolicyFraming::ContentLength;
    policy.connection = ResponsePolicyConnection::Request;
    policy.date = ResponsePolicyDate::Current;
    policy.head_mode = ResponsePolicyHeadMode::SuppressBody;
    policy.server = {kServer, sizeof(kServer) - 1};
    REQUIRE_EQ(cfg.add_response_policy(policy), 1u);

    auto* conn = loop.alloc_conn();
    REQUIRE(conn != nullptr);
    struct ConnGuard {
        SmallLoop* loop;
        Connection* conn;
        ~ConnGuard() {
            if (conn != nullptr && (conn->fd >= 0 || conn->upstream_fd >= 0))
                loop->close_conn(*conn);
        }
    } conn_guard{&loop, conn};
    static constexpr char kRequest[] =
        "HEAD /head HTTP/1.1\r\nHost: client\r\nConnection: close\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    capture_request_metadata(*conn);
    conn->request_config = &cfg;
    conn->response_policy_id = 1;
    conn->response_policy_suppress_body = true;
    conn->req_initial_send_len = conn->recv_buf.len();
    conn->keep_alive = false;
    REQUIRE(loop.alloc_upstream_buf(*conn));
    static constexpr char kResponse[] =
        "HTTP/1.1 200 OK\r\nServer: origin\r\n"
        "Date: Tue, 01 Jan 2030 00:00:00 GMT\r\nContent-Length: 5\r\n\r\nhello";
    REQUIRE_EQ(conn->upstream_recv_buf.write(reinterpret_cast<const u8*>(kResponse),
                                             sizeof(kResponse) - 1),
               sizeof(kResponse) - 1);
    struct FdGuard {
        i32 fd;
        ~FdGuard() {
            if (fd >= 0) close(fd);
        }
    } client_fd{dup(STDERR_FILENO)}, upstream_fd{dup(STDERR_FILENO)};
    REQUIRE_GE(client_fd.fd, 0);
    REQUIRE_GE(upstream_fd.fd, 0);
    conn->fd = client_fd.fd;
    conn->upstream_fd = upstream_fd.fd;
    client_fd.fd = -1;
    upstream_fd.fd = -1;
    conn->upstream_slot_held = true;
    conn->upstream_slot_uid = 0;
    conn->upstream_recv_armed = true;
    conn->upstream_send_armed = true;
    conn->set_slots(
        nullptr, nullptr, &on_upstream_response<SmallLoop>, &on_upstream_request_sent<SmallLoop>);
    loop.backend.clear_ops();

    on_upstream_response<SmallLoop>(
        &loop,
        *conn,
        IoEvent{
            conn->id, static_cast<i32>(sizeof(kResponse) - 1), 0, 0, IoEventType::UpstreamRecv, 0});

    CHECK(conn->upstream_abandoned);
    CHECK_FALSE(conn->upstream_keep_alive);
    CHECK_EQ(conn->upstream_fd, -1);
    CHECK_FALSE(conn->upstream_slot_held);
    CHECK_FALSE(conn->upstream_recv_armed);
    CHECK_FALSE(conn->upstream_send_armed);
    CHECK(conn->on_upstream_recv == nullptr);
    CHECK(conn->on_upstream_send == nullptr);
    const MockOp* sent = loop.backend.last_op(MockOp::Send);
    REQUIRE(sent != nullptr);
    const u32 published_len = sent->send_len;
    CHECK_EQ(published_len, conn->response_header_buf.len());
    CHECK(buf_contains(reinterpret_cast<const char*>(sent->send_buf),
                       sent->send_len,
                       "Content-Length: 5\r\n",
                       static_cast<u32>(strlen("Content-Length: 5\r\n"))));
    CHECK_FALSE(
        buf_contains(reinterpret_cast<const char*>(sent->send_buf), sent->send_len, "hello", 5));
    u8 published[SmallLoop::kBufSize];
    memcpy(published, sent->send_buf, published_len);
    const u32 send_ops_before_late = loop.backend.count_ops(MockOp::Send);

    // This models an old callback retained by an already-harvested upstream
    // event. It must not parse/append or submit another downstream send.
    on_upstream_response<SmallLoop>(
        &loop, *conn, IoEvent{conn->id, 5, 0, 0, IoEventType::UpstreamRecv, 0});
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), send_ops_before_late);
    CHECK_EQ(conn->response_header_buf.len(), published_len);
    CHECK(memcmp(conn->response_header_buf.data(), published, published_len) == 0);

    // The normal downstream completion callback now owns only client cleanup;
    // the upstream slot/fd were already abandoned and must not be released a
    // second time.
    const u32 free_before = loop.free_top;
    on_proxy_response_sent<SmallLoop>(
        &loop,
        *conn,
        IoEvent{conn->id, static_cast<i32>(published_len), 0, 0, IoEventType::Send, 0});
    CHECK_EQ(loop.free_top, free_before + 1);
    CHECK_EQ(loop.conns[conn->id].fd, -1);
    CHECK_FALSE(loop.conns[conn->id].upstream_slot_held);
}

TEST(response_policy, paired_reusable_head_post_connect_failures_close_before_bytes) {
    SmallLoop loop;
    loop.setup();
    RouteConfig cfg{};
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, 8080).has_value());
    ForwardResponsePolicySpec response{};
    response.version = ResponsePolicyVersion::Http11;
    response.framing = ResponsePolicyFraming::ContentLength;
    response.connection = ResponsePolicyConnection::Request;
    response.date = ResponsePolicyDate::Current;
    response.head_mode = ResponsePolicyHeadMode::SuppressBody;
    response.server = {"nginx", 5};
    REQUIRE_EQ(cfg.add_response_policy(response), 1u);
    ForwardFailurePolicySpec failure{};
    failure.version = ForwardFailurePolicyVersion::Http11;
    failure.status_code = 502;
    failure.date = ForwardFailurePolicyDate::Current;
    failure.connection = ForwardFailurePolicyConnection::Request;
    failure.head_mode = FailurePolicyHeadMode::SuppressBody;
    failure.reason = {"Bad Gateway", 11};
    failure.content_type = {"text/plain", 10};
    failure.server = {"nginx", 5};
    failure.body = {"bad", 3};
    REQUIRE_EQ(cfg.add_failure_policy(failure), 1u);

    struct Vector {
        const char* wire;
        i32 result;
        bool upload_complete;
    } vectors[] = {
        {"not-http\r\n\r\n", 12, true},
        {"HTTP/1.1 200 OK\r\nContent-Length: 5\r\n", 0, true},
        {"HTTP/1.1 200 OK\r\nContent-Length: 1\r\n\r\nxx", 41, true},
        {"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok", 40, false},
    };
    for (const auto& vector : vectors) {
        auto* conn = loop.alloc_conn();
        REQUIRE(conn != nullptr);
        conn->fd = dup(STDERR_FILENO);
        conn->upstream_fd = dup(STDERR_FILENO);
        REQUIRE_GE(conn->fd, 0);
        REQUIRE_GE(conn->upstream_fd, 0);
        REQUIRE(loop.alloc_upstream_buf(*conn));
        REQUIRE(loop.alloc_response_header_buf(*conn));
        static constexpr char kRequest[] = "HEAD /head HTTP/1.1\r\nHost: client.example\r\n\r\n";
        REQUIRE_EQ(
            conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
            sizeof(kRequest) - 1);
        capture_request_metadata(*conn);
        conn->request_config = &cfg;
        conn->response_policy_id = 1;
        conn->response_policy_suppress_body = true;
        conn->failure_policy_id = 1;
        conn->failure_policy_suppress_body = true;
        conn->request_upload_complete = vector.upload_complete;
        conn->keep_alive = true;
        conn->state = ConnState::Proxying;
        conn->set_slots(nullptr, nullptr, &on_upstream_response<SmallLoop>, nullptr);
        const u32 wire_len = static_cast<u32>(strlen(vector.wire));
        REQUIRE_EQ(
            conn->upstream_recv_buf.write(reinterpret_cast<const u8*>(vector.wire), wire_len),
            wire_len);
        loop.backend.clear_ops();

        on_upstream_response<SmallLoop>(
            &loop, *conn, {conn->id, vector.result, 0, 0, IoEventType::UpstreamRecv, 0});

        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
        CHECK_EQ(conn->fd, -1);
        CHECK_EQ(conn->upstream_fd, -1);
    }
}

TEST(response_policy, head_mode_config_copy_is_owned_and_atomic) {
    char server[] = "server";
    char hidden[] = "Date";
    ForwardResponsePolicySpec reject{};
    reject.version = ResponsePolicyVersion::Http11;
    reject.framing = ResponsePolicyFraming::ContentLength;
    reject.connection = ResponsePolicyConnection::Request;
    reject.date = ResponsePolicyDate::Current;
    reject.server = {server, 6};
    reject.hide_headers[0] = {hidden, 4};
    reject.hide_header_count = 1;
    auto suppress = reject;
    suppress.head_mode = ResponsePolicyHeadMode::SuppressBody;

    rir::Module module{};
    module.response_policy_count = 2;
    module.response_policies[0] = reject;
    module.response_policies[1] = suppress;
    RouteConfig config{};
    REQUIRE(populate_route_config(config, module));
    CHECK_EQ(config.response_policy_count, 2u);
    CHECK_EQ(config.response_policies[0].head_mode, ResponsePolicyHeadMode::Reject);
    CHECK_EQ(config.response_policies[1].head_mode, ResponsePolicyHeadMode::SuppressBody);
    CHECK(config.response_policies[0].server.ptr != server);
    CHECK(config.response_policies[0].hide_headers[0].ptr != hidden);
    const u32 bytes_before_duplicate = config.response_policy_bytes_used;
    CHECK_EQ(config.add_response_policy(suppress), 2u);
    CHECK_EQ(config.response_policy_bytes_used, bytes_before_duplicate);

    server[0] = 'X';
    hidden[0] = 'X';
    CHECK(config.response_policies[0].server.eq({"server", 6}));
    CHECK(config.response_policies[0].hide_headers[0].eq({"Date", 4}));

    rir::Module malformed = module;
    malformed.response_policies[1].head_mode = ResponsePolicyHeadMode::Invalid;
    RouteConfig untouched{};
    CHECK_FALSE(populate_route_config(untouched, malformed));
    CHECK_EQ(untouched.response_policy_count, 0u);
    CHECK_EQ(untouched.response_policy_bytes_used, 0u);
}

TEST(response_policy, failure_head_mode_config_copy_is_owned_and_deduplicated) {
    char reason[] = "Bad Gateway";
    char type[] = "text/plain";
    char server[] = "rut";
    char body[] = "unavailable";
    ForwardFailurePolicySpec reject{};
    reject.version = ForwardFailurePolicyVersion::Http11;
    reject.status_code = 502;
    reject.date = ForwardFailurePolicyDate::Current;
    reject.connection = ForwardFailurePolicyConnection::Request;
    reject.reason = {reason, 11};
    reject.content_type = {type, 10};
    reject.server = {server, 3};
    reject.body = {body, 11};
    ForwardFailurePolicySpec suppress = reject;
    suppress.head_mode = FailurePolicyHeadMode::SuppressBody;

    rir::Module module{};
    module.failure_policy_count = 2;
    module.failure_policies[0] = reject;
    module.failure_policies[1] = suppress;
    RouteConfig config{};
    REQUIRE(populate_route_config(config, module));
    CHECK_EQ(config.failure_policy_count, 2u);
    CHECK_EQ(config.failure_policies[0].head_mode, FailurePolicyHeadMode::Reject);
    CHECK_EQ(config.failure_policies[1].head_mode, FailurePolicyHeadMode::SuppressBody);
    CHECK(config.failure_policies[0].reason.ptr != reason);
    CHECK(config.failure_policies[0].body.ptr != body);
    const u32 bytes_before_duplicate = config.failure_policy_bytes_used;
    CHECK_EQ(config.add_failure_policy(suppress), 2u);
    CHECK_EQ(config.failure_policy_bytes_used, bytes_before_duplicate);
    reason[0] = 'X';
    body[0] = 'X';
    CHECK(config.failure_policies[0].reason.eq({"Bad Gateway", 11}));
    CHECK(config.failure_policies[0].body.eq({"unavailable", 11}));

    rir::Module malformed = module;
    malformed.failure_policies[1].head_mode = FailurePolicyHeadMode::Invalid;
    RouteConfig untouched{};
    CHECK_FALSE(populate_route_config(untouched, malformed));
    CHECK_EQ(untouched.failure_policy_count, 0u);
    CHECK_EQ(untouched.failure_policy_bytes_used, 0u);

    // The publication helper also accepts a caller-pre-bound upstream. A
    // forged policy must fail before disturbing that unrelated state.
    static constexpr char kBackendName[] = "backend";
    malformed.upstream_count = 1;
    malformed.upstreams[0].name = {kBackendName, sizeof(kBackendName) - 1};
    malformed.upstreams[0].has_address = true;
    malformed.upstreams[0].ip = 0x7F000001;
    malformed.upstreams[0].port = 8080;
    RouteConfig prebound{};
    REQUIRE(prebound.add_upstream("backend", 0x7F000001, 8080).has_value());
    const u32 before_upstreams = prebound.upstream_count;
    const u32 before_addr_count = prebound.upstreams[0].addr_count;
    const u32 before_ip = prebound.upstreams[0].addrs[0].sin_addr.s_addr;
    const u16 before_port = prebound.upstreams[0].addrs[0].sin_port;
    CHECK_FALSE(populate_route_config(prebound, malformed));
    CHECK_EQ(prebound.upstream_count, before_upstreams);
    CHECK_EQ(prebound.upstreams[0].addr_count, before_addr_count);
    CHECK_EQ(prebound.upstreams[0].addrs[0].sin_addr.s_addr, before_ip);
    CHECK_EQ(prebound.upstreams[0].addrs[0].sin_port, before_port);
    CHECK_EQ(prebound.upstreams[0].name_len, 7u);
    CHECK(__builtin_memcmp(prebound.upstreams[0].name, "backend", 7) == 0);
    CHECK_EQ(prebound.failure_policy_count, 0u);
    CHECK_EQ(prebound.failure_policy_bytes_used, 0u);
}

TEST(response_policy,
     timeout_failure_policy_triple_bundle_config_is_owned_deduplicated_and_validated) {
    ForwardResponsePolicySpec response{};
    response.version = ResponsePolicyVersion::Http11;
    response.framing = ResponsePolicyFraming::ContentLength;
    response.connection = ResponsePolicyConnection::Request;
    response.date = ResponsePolicyDate::Current;
    response.server = {"rut", 3};

    ForwardFailurePolicySpec failure{};
    failure.version = ForwardFailurePolicyVersion::Http11;
    failure.status_code = 502;
    failure.date = ForwardFailurePolicyDate::Current;
    failure.connection = ForwardFailurePolicyConnection::Request;
    failure.reason = {"Bad Gateway", 11};
    failure.content_type = {"text/plain", 10};
    failure.server = {"rut", 3};
    failure.body = {"bad", 3};
    ForwardFailurePolicySpec timeout = failure;
    timeout.status_code = 504;
    timeout.reason = {"Gateway Time-out", 16};
    timeout.body = {"slow", 4};

    rir::Module module{};
    module.response_policy_count = 1;
    module.response_policies[0] = response;
    module.failure_policy_count = 2;
    module.failure_policies[0] = failure;
    module.failure_policies[1] = timeout;
    module.policy_bundle_count = 2;
    module.policy_bundles[0] = {1, 1, 0};
    module.policy_bundles[1] = {1, 1, 2};

    RouteConfig config{};
    REQUIRE(populate_route_config(config, module));
    REQUIRE_EQ(config.failure_policy_count, 2u);
    REQUIRE_EQ(config.policy_bundle_count, 2u);
    CHECK_EQ(config.failure_policies[1].status_code, 504u);
    CHECK_EQ(config.policy_bundles[0].timeout_failure_policy_id, 0u);
    CHECK_EQ(config.policy_bundles[1].timeout_failure_policy_id, 2u);
    CHECK(config.policy_bundle_id_is_valid(1));
    CHECK(config.policy_bundle_id_is_valid(2));
    const u32 policy_bytes = config.failure_policy_bytes_used;
    CHECK_EQ(config.add_failure_policy(timeout), 2u);
    CHECK_EQ(config.failure_policy_bytes_used, policy_bytes);
    CHECK_EQ(config.add_policy_bundle(1, 1, 2), 2u);

    auto rejects_transactionally = [&](const rir::Module& forged) {
        RouteConfig untouched{};
        CHECK_FALSE(populate_route_config(untouched, forged));
        CHECK_EQ(untouched.response_policy_count, 0u);
        CHECK_EQ(untouched.failure_policy_count, 0u);
        CHECK_EQ(untouched.policy_bundle_count, 0u);
        CHECK_EQ(untouched.failure_policy_bytes_used, 0u);
    };
    rir::Module forged_id = module;
    forged_id.policy_bundles[1].timeout_failure_policy_id = 3;
    rejects_transactionally(forged_id);
    rir::Module wrong_role = module;
    wrong_role.policy_bundles[1].failure_policy_id = 2;
    rejects_transactionally(wrong_role);
    rir::Module incompatible = module;
    incompatible.failure_policies[1].head_mode = FailurePolicyHeadMode::SuppressBody;
    rejects_transactionally(incompatible);
    rir::Module bad_status = module;
    bad_status.failure_policies[1].status_code = 600;
    rejects_transactionally(bad_status);
    rir::Module over_capacity = module;
    over_capacity.failure_policy_count = kMaxForwardFailurePolicies + 1;
    rejects_transactionally(over_capacity);
}

TEST(response_policy, response_read_timeout_bundle_config_shapes_are_exact_and_fail_closed) {
    ForwardResponsePolicySpec response{};
    response.version = ResponsePolicyVersion::Http11;
    response.framing = ResponsePolicyFraming::ContentLength;
    response.connection = ResponsePolicyConnection::Request;
    response.date = ResponsePolicyDate::Current;
    response.server = {"rut", 3};

    ForwardFailurePolicySpec failure{};
    failure.version = ForwardFailurePolicyVersion::Http11;
    failure.status_code = 502;
    failure.date = ForwardFailurePolicyDate::Current;
    failure.connection = ForwardFailurePolicyConnection::Request;
    failure.reason = {"Bad Gateway", 11};
    failure.content_type = {"text/plain", 10};
    failure.server = {"rut", 3};
    failure.body = {"bad", 3};
    ForwardFailurePolicySpec timeout = failure;
    timeout.status_code = 504;
    timeout.reason = {"Gateway Time-out", 16};
    timeout.body = {"slow", 4};

    rir::Module module{};
    module.response_policy_count = 1;
    module.response_policies[0] = response;
    module.failure_policy_count = 2;
    module.failure_policies[0] = failure;
    module.failure_policies[1] = timeout;
    module.policy_bundle_count = 5;
    module.policy_bundles[0] = {0, 0, 0, 1};
    module.policy_bundles[1] = {0, 0, 0, 2};
    module.policy_bundles[2] = {1, 0, 0, 2};
    module.policy_bundles[3] = {1, 1, 2, 3};
    module.policy_bundles[4] = {1, 1, 2, 3, ForwardResponseBufferingMode::CompleteContentLength};

    RouteConfig config{};
    REQUIRE(populate_route_config(config, module));
    REQUIRE_EQ(config.policy_bundle_count, 5u);
    for (u32 i = 0; i < 5; i++) {
        CHECK(config.policy_bundle_id_is_valid(static_cast<u16>(i + 1)));
        CHECK_EQ(config.policy_bundles[i].response_read_timeout_seconds,
                 module.policy_bundles[i].response_read_timeout_seconds);
        CHECK_EQ(config.policy_bundles[i].response_buffering,
                 module.policy_bundles[i].response_buffering);
    }
    CHECK_EQ(config.add_policy_bundle(0, 0, 0, 1), 1u);
    CHECK_EQ(config.add_policy_bundle(0, 0, 0, 2), 2u);
    CHECK_EQ(config.add_policy_bundle(1, 0, 0, 2), 3u);
    CHECK_EQ(config.add_policy_bundle(1, 1, 2, 3), 4u);
    CHECK_EQ(
        config.add_policy_bundle(1, 1, 2, 3, ForwardResponseBufferingMode::CompleteContentLength),
        5u);
    CHECK_EQ(config.add_policy_bundle(0, 0), 0u);
    CHECK_EQ(config.add_policy_bundle(0, 0, 0, 64), 0u);

    auto rejects = [&](const rir::Module& forged) {
        RouteConfig untouched{};
        CHECK_FALSE(populate_route_config(untouched, forged));
        CHECK_EQ(untouched.response_policy_count, 0u);
        CHECK_EQ(untouched.failure_policy_count, 0u);
        CHECK_EQ(untouched.policy_bundle_count, 0u);
    };
    rir::Module all_zero = module;
    all_zero.policy_bundles[0] = {};
    rejects(all_zero);
    rir::Module out_of_range = module;
    out_of_range.policy_bundles[0].response_read_timeout_seconds = 64;
    rejects(out_of_range);
    rir::Module response_only = module;
    response_only.policy_bundles[0] = {1, 0, 0, 0};
    rejects(response_only);
    rir::Module forged_buffering = module;
    forged_buffering.policy_bundles[4].response_buffering =
        static_cast<ForwardResponseBufferingMode>(2);
    rejects(forged_buffering);
    rir::Module buffering_without_timeout = module;
    buffering_without_timeout.policy_bundles[4].response_read_timeout_seconds = 0;
    rejects(buffering_without_timeout);

    // Existing failure-only bundle behavior remains valid when duration is absent.
    RouteConfig legacy{};
    REQUIRE_EQ(legacy.add_failure_policy(failure), 1u);
    REQUIRE_EQ(legacy.add_policy_bundle(0, 1), 1u);
    CHECK(legacy.policy_bundle_id_is_valid(1));
    CHECK_EQ(legacy.policy_bundles[0].response_read_timeout_seconds, 0u);
}

TEST(response_read_timeout, h1_rejects_before_every_forward_effect_and_preserves_absence) {
    RouteConfig config{};
    REQUIRE(config.add_upstream("backend", 0x7F000001, 9000).has_value());
    config.upstreams[0].max_inflight = 1;
    REQUIRE_EQ(config.add_target_transform({{"/api/", 5}, {"/v1/", 4}}), 1u);
    REQUIRE_EQ(config.add_policy_bundle(0, 0, 0, 5), 1u);
    auto forged = std::make_unique<RouteConfig>();
    REQUIRE(forged->add_upstream("backend", 0x7F000001, 9000).has_value());
    forged->upstreams[0].max_inflight = 1;
    REQUIRE_EQ(forged->add_target_transform({{"/api/", 5}, {"/v1/", 4}}), 1u);
    REQUIRE_EQ(forged->add_policy_bundle(0, 0, 0, 5), 1u);
    forged->policy_bundles[0].response_read_timeout_seconds = 64;
    CHECK_FALSE(forged->policy_bundle_id_is_valid(1));

    static constexpr char kGet[] = "GET /api/x HTTP/1.1\r\nHost: client\r\n\r\n";
    static constexpr char kPost[] =
        "POST /api HTTP/1.1\r\nHost: client\r\nContent-Length: 3\r\n\r\n";
    struct Vector {
        const RouteConfig* config;
        const char* request;
        u32 request_len;
        u16 bundle_id;
        u16 upstream_id;
        bool body_wait;
        bool target_transform;
        bool response_mutation;
    } vectors[] = {
        {&config, kGet, sizeof(kGet) - 1, 1, 0, false, false, false},
        {&config, kPost, sizeof(kPost) - 1, 1, 0, true, false, false},
        {&config, kGet, sizeof(kGet) - 1, 1, 0, false, true, false},
        {&config, kGet, sizeof(kGet) - 1, 1, 0, false, false, true},
        {&config, kGet, sizeof(kGet) - 1, 1, 99, false, false, false},
        {nullptr, kGet, sizeof(kGet) - 1, 1, 0, false, false, false},
        {&config, kGet, sizeof(kGet) - 1, 99, 0, false, false, false},
        {forged.get(), kGet, sizeof(kGet) - 1, 1, 0, false, false, false},
    };

    SmallLoop loop;
    loop.setup();
    for (const auto& vector : vectors) {
        auto* conn = loop.alloc_conn();
        REQUIRE(conn != nullptr);
        REQUIRE_EQ(
            conn->recv_buf.write(reinterpret_cast<const u8*>(vector.request), vector.request_len),
            vector.request_len);
        capture_request_metadata(*conn);
        conn->request_config = vector.config;
        if (vector.target_transform) {
            conn->target_transform_recorded = true;
            conn->target_transform_id = 1;
        }
        if (vector.response_mutation) {
            conn->resp_header_mutation_pending_count = 1;
            conn->resp_header_mutation_count = 1;
        }
        JitDispatchOutcome outcome{};
        outcome.kind = JitDispatchOutcome::Kind::Forward;
        outcome.upstream_id = vector.upstream_id;
        outcome.policy_bundle_id = vector.bundle_id;
        outcome.request_policy_id = vector.body_wait ? 1 : 0;
        loop.backend.clear_ops();
        handle_jit_outcome<SmallLoop>(&loop, *conn, outcome, nullptr, true);
        CHECK_EQ(loop.free_top, SmallLoop::kMaxConns);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    }

    // With no explicit duration the existing forwarding path is unchanged.
    auto* legacy = loop.alloc_conn();
    REQUIRE(legacy != nullptr);
    REQUIRE_EQ(legacy->recv_buf.write(reinterpret_cast<const u8*>(kGet), sizeof(kGet) - 1),
               sizeof(kGet) - 1);
    capture_request_metadata(*legacy);
    legacy->request_config = &config;
    JitDispatchOutcome legacy_outcome{};
    legacy_outcome.kind = JitDispatchOutcome::Kind::Forward;
    legacy_outcome.upstream_id = 0;
    loop.backend.clear_ops();
    handle_jit_outcome<SmallLoop>(&loop, *legacy, legacy_outcome, nullptr, true);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 1u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
    CHECK(legacy->upstream_slot_held);
    loop.close_conn(*legacy);
}

TEST(response_read_timeout, h1_route_preflight_closes_before_body_wait_or_handler) {
    SmallLoop loop;
    loop.setup();
    RouteConfig config{};
    REQUIRE(config.add_upstream("backend", 0x7F000001, 9000).has_value());
    REQUIRE_EQ(config.add_policy_bundle(0, 0, 0, 5), 1u);
    REQUIRE(
        config.add_jit_handler("/upload", 'P', &response_read_timeout_preflight_handler, true, 1));
    const RouteConfig* active = &config;
    loop.config_ptr = &active;
    response_read_timeout_preflight_handler_calls = 0;

    auto* conn = loop.alloc_conn();
    REQUIRE(conn != nullptr);
    const u32 conn_id = conn->id;
    static constexpr char kRequest[] =
        "POST /upload HTTP/1.1\r\nHost: x\r\nContent-Length: 7\r\n\r\npay";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.backend.clear_ops();
    on_header_received<SmallLoop>(
        &loop, *conn, make_ev(conn_id, IoEventType::Recv, sizeof(kRequest) - 1));

    CHECK_EQ(response_read_timeout_preflight_handler_calls, 0u);
    CHECK_EQ(loop.free_top, SmallLoop::kMaxConns);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
    CHECK_EQ(__builtin_memcmp(loop.recv_storage[conn_id], kRequest, sizeof(kRequest) - 1), 0);

    // A forged deferred marker is represented but cannot enter the eager
    // preflight or handler path in this behavior-neutral phase.
    config.routes[0].forward_preflight_mode = ForwardPreflightMode::AfterCanonicalSelection;
    auto* deferred = loop.alloc_conn();
    REQUIRE(deferred != nullptr);
    const u32 deferred_id = deferred->id;
    REQUIRE_EQ(
        deferred->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
        sizeof(kRequest) - 1);
    loop.backend.clear_ops();
    on_header_received<SmallLoop>(
        &loop, *deferred, make_ev(deferred_id, IoEventType::Recv, sizeof(kRequest) - 1));
    CHECK_EQ(response_read_timeout_preflight_handler_calls, 0u);
    CHECK_EQ(loop.free_top, SmallLoop::kMaxConns);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
}

TEST(response_read_timeout,
     h1_deferred_selector_redirects_without_preflight_and_arms_exact_bundle_before_forward) {
    static constexpr char kRedirectRequest[] =
        "GET /old?x=1 HTTP/1.1\r\nHost: ignored.example\r\nConnection: close\r\n\r\n";
    static constexpr char kForwardRequest[] =
        "GET / HTTP/1.1\r\nHost: client.example\r\nConnection: close\r\n\r\n";

    {
        DeferredPreflightMockLoop loop;
        loop.setup();
        loop.listener_context = {
            ListenerAddress::IPv4Wildcard, ListenerTransport::Cleartext, static_cast<u16>(8080)};
        auto config = std::make_unique<RouteConfig>();
        REQUIRE(configure_deferred_preflight_test_route(*config));
        const RouteConfig* active = config.get();
        loop.config_ptr = &active;
        deferred_preflight_test_outcome = DeferredPreflightTestOutcome::Redirect;
        deferred_preflight_handler_calls = 0;
        auto* conn = loop.alloc_conn();
        REQUIRE(conn != nullptr);
        const u32 id = conn->id;
        REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kRedirectRequest),
                                        sizeof(kRedirectRequest) - 1),
                   sizeof(kRedirectRequest) - 1);
        loop.backend.clear_ops();
        on_header_received<DeferredPreflightMockLoop>(
            &loop, *conn, make_ev(id, IoEventType::Recv, sizeof(kRedirectRequest) - 1));
        CHECK_EQ(deferred_preflight_handler_calls, 1u);
        CHECK_EQ(conn->resp_status, 301u);
        CHECK(conn->response_read_deadline_owner_is_neutral());
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 1u);
        u8 normalized[SmallLoop::kBufSize]{};
        REQUIRE(conn->send_buf.len() <= sizeof(normalized));
        __builtin_memcpy(normalized, conn->send_buf.data(), conn->send_buf.len());
        REQUIRE(normalize_redirect_date(normalized, conn->send_buf.len()));
        const std::string expected = expected_fixed_redirect_wire();
        CHECK_EQ(conn->send_buf.len(), static_cast<u32>(expected.size()));
        CHECK_EQ(__builtin_memcmp(normalized, expected.data(), expected.size()), 0);
        loop.close_conn(*conn);
    }

    {
        DeferredPreflightMockLoop loop;
        loop.setup();
        loop.listener_context = {
            ListenerAddress::IPv4Wildcard, ListenerTransport::Cleartext, static_cast<u16>(8080)};
        auto config = std::make_unique<RouteConfig>();
        REQUIRE(configure_deferred_preflight_test_route(*config));
        const RouteConfig* active = config.get();
        loop.config_ptr = &active;
        deferred_preflight_test_outcome = DeferredPreflightTestOutcome::ForwardBundle;
        deferred_preflight_handler_calls = 0;
        auto* conn = loop.alloc_conn();
        REQUIRE(conn != nullptr);
        const u32 id = conn->id;
        REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kForwardRequest),
                                        sizeof(kForwardRequest) - 1),
                   sizeof(kForwardRequest) - 1);
        loop.backend.clear_ops();
        on_header_received<DeferredPreflightMockLoop>(
            &loop, *conn, make_ev(id, IoEventType::Recv, sizeof(kForwardRequest) - 1));
        CHECK_EQ(deferred_preflight_handler_calls, 1u);
        CHECK_EQ(conn->response_read_deadline_state, ResponseReadDeadlineState::Validated);
        CHECK_EQ(conn->response_read_deadline_bundle_id, 1u);
        CHECK_EQ(conn->response_read_deadline_buffering,
                 ForwardResponseBufferingMode::CompleteContentLength);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 1u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
        CHECK_FALSE(conn->upstream_slot_held);
        loop.close_conn(*conn);
    }
}

