TEST(response_buffering, unsupported_loop_rejects_before_handler_or_forward_effects) {
    SmallLoop loop;
    loop.setup();
    RouteConfig config{};
    REQUIRE(config.add_upstream("backend", 0x7F000001, 9000).has_value());

    ForwardResponsePolicySpec response{};
    response.version = ResponsePolicyVersion::Http11;
    response.framing = ResponsePolicyFraming::ContentLength;
    response.connection = ResponsePolicyConnection::Request;
    response.date = ResponsePolicyDate::Current;
    response.server = {"rut", 3};
    REQUIRE_EQ(config.add_response_policy(response), 1u);

    ForwardFailurePolicySpec failure{};
    failure.version = ForwardFailurePolicyVersion::Http11;
    failure.status_code = 502;
    failure.date = ForwardFailurePolicyDate::Current;
    failure.connection = ForwardFailurePolicyConnection::Request;
    failure.reason = {"Bad Gateway", 11};
    failure.content_type = {"text/plain", 10};
    failure.server = {"rut", 3};
    failure.body = {"bad", 3};
    REQUIRE_EQ(config.add_failure_policy(failure), 1u);
    auto timeout = failure;
    timeout.status_code = 504;
    timeout.reason = {"Gateway Time-out", 16};
    timeout.body = {"slow", 4};
    REQUIRE_EQ(config.add_failure_policy(timeout), 2u);
    REQUIRE_EQ(
        config.add_policy_bundle(1, 1, 2, 1, ForwardResponseBufferingMode::CompleteContentLength),
        1u);
    REQUIRE(config.add_jit_handler(
        "/buffered", kRouteMethodGet, &response_read_timeout_preflight_handler, false, 1));
    const RouteConfig* active = &config;
    loop.config_ptr = &active;
    response_read_timeout_preflight_handler_calls = 0;

    auto* conn = loop.alloc_conn();
    REQUIRE(conn != nullptr);
    const u32 conn_id = conn->id;
    static constexpr char kRequest[] = "GET /buffered HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.backend.clear_ops();
    on_header_received<SmallLoop>(
        &loop, *conn, make_ev(conn_id, IoEventType::Recv, sizeof(kRequest) - 1));

    CHECK_EQ(response_read_timeout_preflight_handler_calls, 0u);
    CHECK_EQ(loop.free_top, SmallLoop::kMaxConns);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
    CHECK_EQ(__builtin_memcmp(loop.recv_storage[conn_id], kRequest, sizeof(kRequest) - 1), 0);
}

TEST(response_read_timeout, route_preflight_marker_fails_closed_for_every_nonzero_shape) {
    RouteConfig duration{};
    REQUIRE_EQ(duration.add_policy_bundle(0, 0, 0, 5), 1u);
    REQUIRE(duration.add_jit_handler(
        "/legacy", kRouteMethodGet, &response_read_timeout_preflight_handler, false, 1));
    REQUIRE_EQ(duration.route_count, 1u);
    CHECK_EQ(duration.routes[0].forward_preflight_mode, ForwardPreflightMode::EagerDirect);
    CHECK_EQ(duration.routes[0].preflight_forward_policy_bundle_id, 1u);
    REQUIRE(duration.add_jit_handler("/plain",
                                     kRouteMethodGet,
                                     &response_read_timeout_later_handler,
                                     false,
                                     ForwardPreflightMode::None,
                                     0));
    REQUIRE_EQ(duration.route_count, 2u);
    CHECK_EQ(duration.routes[1].forward_preflight_mode, ForwardPreflightMode::None);
    CHECK_EQ(duration.routes[1].preflight_forward_policy_bundle_id, 0u);

    const u32 stable_route_count = duration.route_count;
    std::vector<u8> stable_config(sizeof(RouteConfig));
    __builtin_memcpy(stable_config.data(), &duration, sizeof(RouteConfig));
    CHECK_FALSE(duration.add_jit_handler("/none-with-id",
                                         kRouteMethodGet,
                                         &response_read_timeout_preflight_handler,
                                         false,
                                         ForwardPreflightMode::None,
                                         1));
    CHECK_FALSE(duration.add_jit_handler("/eager-without-id",
                                         kRouteMethodGet,
                                         &response_read_timeout_preflight_handler,
                                         false,
                                         ForwardPreflightMode::EagerDirect,
                                         0));
    CHECK_FALSE(duration.add_jit_handler("/deferred",
                                         kRouteMethodGet,
                                         &response_read_timeout_preflight_handler,
                                         false,
                                         ForwardPreflightMode::AfterCanonicalSelection,
                                         1));
    CHECK_FALSE(duration.add_jit_handler("/invalid",
                                         kRouteMethodGet,
                                         &response_read_timeout_preflight_handler,
                                         false,
                                         static_cast<ForwardPreflightMode>(0xff),
                                         1));
    CHECK_FALSE(duration.add_jit_handler("/bad-id",
                                         kRouteMethodGet,
                                         &response_read_timeout_preflight_handler,
                                         false,
                                         ForwardPreflightMode::EagerDirect,
                                         99));
    CHECK_EQ(duration.route_count, stable_route_count);
    CHECK_EQ(__builtin_memcmp(stable_config.data(), &duration, sizeof(RouteConfig)), 0);

    RouteEntry route{};
    CHECK_FALSE(route_requires_response_read_timeout_preflight_close(&route, &duration));
    route.preflight_forward_policy_bundle_id = 1;
    CHECK(route_requires_response_read_timeout_preflight_close(&route, &duration));
    CHECK(route_requires_response_read_timeout_preflight_close(&route, nullptr));
    route.forward_preflight_mode = ForwardPreflightMode::EagerDirect;
    route.preflight_forward_policy_bundle_id = 99;
    CHECK(route_requires_response_read_timeout_preflight_close(&route, &duration));
    route.forward_preflight_mode = ForwardPreflightMode::AfterCanonicalSelection;
    route.preflight_forward_policy_bundle_id = 1;
    CHECK(route_requires_response_read_timeout_preflight_close(&route, &duration));
    route.forward_preflight_mode = static_cast<ForwardPreflightMode>(0xff);
    CHECK(route_requires_response_read_timeout_preflight_close(&route, &duration));

    RouteConfig zero_duration{};
    ForwardFailurePolicySpec failure{};
    failure.version = ForwardFailurePolicyVersion::Http11;
    failure.status_code = 502;
    failure.date = ForwardFailurePolicyDate::Current;
    failure.connection = ForwardFailurePolicyConnection::Request;
    failure.reason = {"Bad Gateway", 11};
    failure.content_type = {"text/plain", 10};
    failure.server = {"rut", 3};
    failure.body = {"bad", 3};
    REQUIRE_EQ(zero_duration.add_failure_policy(failure), 1u);
    REQUIRE_EQ(zero_duration.add_policy_bundle(0, 1), 1u);
    route.forward_preflight_mode = ForwardPreflightMode::EagerDirect;
    route.preflight_forward_policy_bundle_id = 1;
    CHECK(route_requires_response_read_timeout_preflight_close(&route, &zero_duration));
}

static Connection* setup_target_transform_request(SmallLoop& loop,
                                                  RouteConfig& cfg,
                                                  const char* request,
                                                  u32 request_len,
                                                  bool path_override = false) {
    auto* conn = loop.alloc_conn();
    if (!conn ||
        conn->recv_buf.write(reinterpret_cast<const u8*>(request), request_len) != request_len)
        return nullptr;
    capture_request_metadata(*conn);
    conn->request_config = &cfg;
    conn->target_transform_id = 1;
    conn->target_transform_recorded = true;
    conn->req_path_overridden = path_override;
    return conn;
}

TEST(response_policy, target_transform_bundle_suppress_body_fails_before_materialization) {
    SmallLoop loop;
    loop.setup();
    RouteConfig cfg{};
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, 8080).has_value());
    char strip[] = "/api/";
    char replace[] = "/v1/";
    REQUIRE_EQ(cfg.add_target_transform({{strip, 5}, {replace, 4}}), 1u);

    static constexpr char kServer[] = "server";
    static constexpr char kReason[] = "Bad Gateway";
    static constexpr char kType[] = "text/plain";
    static constexpr char kBody[] = "unavailable";
    ForwardResponsePolicySpec response{};
    response.version = ResponsePolicyVersion::Http11;
    response.framing = ResponsePolicyFraming::ContentLength;
    response.connection = ResponsePolicyConnection::Request;
    response.date = ResponsePolicyDate::Current;
    response.head_mode = ResponsePolicyHeadMode::SuppressBody;
    response.server = {kServer, sizeof(kServer) - 1};
    REQUIRE_EQ(cfg.add_response_policy(response), 1u);

    ForwardFailurePolicySpec failure{};
    failure.version = ForwardFailurePolicyVersion::Http11;
    failure.status_code = 502;
    failure.date = ForwardFailurePolicyDate::Current;
    failure.connection = ForwardFailurePolicyConnection::Request;
    failure.reason = {kReason, sizeof(kReason) - 1};
    failure.content_type = {kType, sizeof(kType) - 1};
    failure.server = {kServer, sizeof(kServer) - 1};
    failure.body = {kBody, sizeof(kBody) - 1};
    REQUIRE_EQ(cfg.add_failure_policy(failure), 1u);
    REQUIRE_EQ(cfg.add_policy_bundle(1, 1), 1u);
    CHECK_EQ(cfg.policy_bundles[0].response_policy_id, 1u);
    CHECK_EQ(cfg.policy_bundles[0].failure_policy_id, 1u);

    const char request[] = "GET /api/x?tag=a%2Fb HTTP/1.1\r\nHost: client\r\n\r\n";
    const u32 request_len = sizeof(request) - 1;
    for (const bool use_bundle : {false, true}) {
        auto* conn = setup_target_transform_request(loop, cfg, request, request_len);
        REQUIRE(conn != nullptr);
        const u32 before_len = conn->recv_buf.len();
        u8 before[SmallLoop::kBufSize];
        __builtin_memcpy(before, conn->recv_buf.data(), before_len);

        JitDispatchOutcome outcome{};
        outcome.kind = JitDispatchOutcome::Kind::Forward;
        outcome.upstream_id = 0;
        if (use_bundle)
            outcome.policy_bundle_id = 1;
        else
            outcome.response_policy_id = 1;
        loop.backend.clear_ops();
        handle_jit_outcome<SmallLoop>(&loop, *conn, outcome, nullptr, true);

        CHECK_EQ(conn->resp_status, 400u);
        CHECK_EQ(conn->upstream_fd, -1);
        CHECK_FALSE(conn->upstream_slot_held);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 1u);
        CHECK_EQ(conn->recv_buf.len(), before_len);
        CHECK_EQ(__builtin_memcmp(conn->recv_buf.data(), before, before_len), 0);
        CHECK(conn->target_transform_recorded);
        CHECK_EQ(conn->target_transform_id, 1u);
        CHECK_FALSE(conn->req_path_overridden);
        CHECK_FALSE(conn->upstream_send_armed);
        loop.free_conn(*conn);
    }
}

TEST(response_policy, failure_suppress_body_fails_closed_before_wait_rewrite_or_transform) {
    SmallLoop loop;
    loop.setup();
    RouteConfig cfg{};
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, 8080).has_value());
    char strip[] = "/api/";
    char replace[] = "/";
    REQUIRE_EQ(cfg.add_target_transform({{strip, 5}, {replace, 1}}), 1u);
    static constexpr char kReason[] = "Bad Gateway";
    static constexpr char kType[] = "text/plain";
    static constexpr char kServer[] = "rut";
    static constexpr char kBody[] = "unavailable";
    ForwardFailurePolicySpec failure{};
    failure.version = ForwardFailurePolicyVersion::Http11;
    failure.status_code = 502;
    failure.date = ForwardFailurePolicyDate::Current;
    failure.connection = ForwardFailurePolicyConnection::Request;
    failure.head_mode = FailurePolicyHeadMode::SuppressBody;
    failure.reason = {kReason, sizeof(kReason) - 1};
    failure.content_type = {kType, sizeof(kType) - 1};
    failure.server = {kServer, sizeof(kServer) - 1};
    failure.body = {kBody, sizeof(kBody) - 1};
    REQUIRE_EQ(cfg.add_failure_policy(failure), 1u);
    REQUIRE_EQ(cfg.add_policy_bundle(0, 1), 1u);

    const char* get_request = "GET /api/x?tag=a%2Fb HTTP/1.1\r\nHost: client\r\n\r\n";
    for (const bool use_bundle : {false, true}) {
        auto* conn = setup_target_transform_request(
            loop, cfg, get_request, static_cast<u32>(strlen(get_request)));
        REQUIRE(conn != nullptr);
        const u32 before_len = conn->recv_buf.len();
        u8 before[SmallLoop::kBufSize];
        __builtin_memcpy(before, conn->recv_buf.data(), before_len);
        JitDispatchOutcome outcome{};
        outcome.kind = JitDispatchOutcome::Kind::Forward;
        outcome.upstream_id = 0;
        if (use_bundle)
            outcome.policy_bundle_id = 1;
        else
            outcome.failure_policy_id = 1;
        loop.backend.clear_ops();
        handle_jit_outcome<SmallLoop>(&loop, *conn, outcome, nullptr, true);
        CHECK_EQ(conn->resp_status, 400u);
        CHECK_EQ(conn->upstream_fd, -1);
        CHECK_FALSE(conn->upstream_slot_held);
        CHECK_FALSE(conn->request_policy_body_pending);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 1u);
        CHECK_EQ(conn->recv_buf.len(), before_len);
        CHECK_EQ(__builtin_memcmp(conn->recv_buf.data(), before, before_len), 0);
        CHECK(conn->target_transform_recorded);
        CHECK_EQ(conn->target_transform_id, 1u);
        loop.free_conn(*conn);
    }

    // A fixed Content-Length request with no body is a body-wait candidate.
    // The failure disposition must reject before entering that state or
    // submitting a receive, even though policy id 1 itself is otherwise valid.
    const char post_headers[] =
        "POST /api HTTP/1.1\r\nHost: client\r\nContent-Length: 3\r\n"
        "Connection: close\r\n\r\n";
    auto* post = loop.alloc_conn();
    REQUIRE(post != nullptr);
    REQUIRE_EQ(
        post->recv_buf.write(reinterpret_cast<const u8*>(post_headers), sizeof(post_headers) - 1),
        sizeof(post_headers) - 1);
    capture_request_metadata(*post);
    post->request_config = &cfg;
    JitDispatchOutcome post_outcome{};
    post_outcome.kind = JitDispatchOutcome::Kind::Forward;
    post_outcome.upstream_id = 0;
    post_outcome.request_policy_id = 1;
    post_outcome.failure_policy_id = 1;
    loop.backend.clear_ops();
    handle_jit_outcome<SmallLoop>(&loop, *post, post_outcome, nullptr, true);
    CHECK_EQ(post->resp_status, 400u);
    CHECK_FALSE(post->request_policy_body_pending);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 1u);
    loop.free_conn(*post);
}

