TEST(redirect, h1_timer_resume_rejects_without_proxy) {
    SmallLoop loop;
    loop.setup();
    RouteConfig cfg{};
    REQUIRE(cfg.add_upstream("backend", 0x7F000001, 9000).has_value());
    RedirectPolicySpec policy{};
    policy.scheme = RedirectPolicyScheme::Http;
    policy.authority = RedirectPolicyAuthority::RequestHost;
    policy.port = RedirectPolicyPort::ActualListener;
    policy.path = RedirectPolicyPath::Static;
    policy.query = RedirectPolicyQuery::PreserveRaw;
    policy.date = RedirectPolicyDate::Current;
    policy.connection = RedirectPolicyConnection::Close;
    policy.header_order = RedirectPolicyHeaderOrder::LocationThenConnection;
    policy.status_code = 301;
    policy.reason = {"Moved Permanently", 16};
    policy.server = {"rut", 3};
    policy.content_type = {"text/html", 9};
    policy.target_path = {"/api/", 5};
    REQUIRE_EQ(cfg.add_redirect_policy(policy), 1u);
    REQUIRE(cfg.add_jit_handler("/api", 'G', &h1_timer_then_redirect_handler, false));
    const RouteConfig* active = &cfg;
    loop.config_ptr = &active;
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    const char request[] = "GET /api HTTP/1.1\r\nHost: client\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(request), sizeof(request) - 1),
               sizeof(request) - 1);
    loop.backend.inject(make_ev(conn->id, IoEventType::Recv, sizeof(request) - 1));
    IoEvent events[8];
    const u32 count = loop.backend.wait(events, 8);
    for (u32 i = 0; i < count; i++) loop.dispatch(events[i]);
    CHECK_EQ(conn->state, ConnState::ExecHandler);
    CHECK_EQ(conn->pending_handler_fn, &h1_timer_then_redirect_handler);
    loop.backend.clear_ops();
    resume_jit_handler(&loop, *conn);
    CHECK_EQ(conn->resp_status, 400u);
    CHECK_EQ(conn->state, ConnState::Sending);
    CHECK_EQ(conn->pending_handler_fn, nullptr);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 1u);
    CHECK_EQ(conn->send_buf.len(), sizeof(kRedirectRejectedH1) - 1);
    CHECK_EQ(__builtin_memcmp(
                 conn->send_buf.data(), kRedirectRejectedH1, sizeof(kRedirectRejectedH1) - 1),
             0);
    loop.free_conn(*conn);
}

TEST(set_path, streamed_pipeline_stash_preserves_response_mutation_snapshot) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    const char kReq[] = "POST /original HTTP/1.1\r\nHost: client\r\n\r\nbody";
    const u32 kReqLen = sizeof(kReq) - 1;
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kReq), kReqLen), kReqLen);
    c->req_initial_send_len = kReqLen;
    c->resp_header_mutations[0] = {{"X-Original", 10},
                                   {reinterpret_cast<const char*>(c->recv_buf.data()) + 5, 9},
                                   ConnectionBase::RespHeaderMutationMode::Set};
    c->resp_header_mutation_count = 1;

    REQUIRE(snapshot_response_mutations_before_request_rewrite(*c));
    reserve_response_mutation_snapshot(*c);
    const u32 snapshot_len = c->retry_req_send_len;
    REQUIRE_EQ(snapshot_len, kReqLen);

    c->recv_buf.reset();
    static const char final_body_and_pipeline[] = "tailGET /next HTTP/1.1\r\nHost: client\r\n\r\n";
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(final_body_and_pipeline),
                                 sizeof(final_body_and_pipeline) - 1),
               sizeof(final_body_and_pipeline) - 1);
    c->req_initial_send_len = 4;
    pipeline_stash(*c);

    CHECK(c->resp_header_mutations[0].value.eq({"/original", 9}));
    REQUIRE_EQ(c->pipeline_stash_len, sizeof(final_body_and_pipeline) - 1 - 4);
    CHECK(buf_has(
        c->send_buf.data() + snapshot_len, c->pipeline_stash_len, "GET /next HTTP/1.1\r\n"));
}

// === Recv ===

static bool dispatch_complete_http1_test_request(SmallLoop& loop, Connection& conn) {
    static constexpr char kRequest[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    if (conn.recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1u) !=
        sizeof(kRequest) - 1u)
        return false;
    loop.dispatch(make_ev(conn.id, IoEventType::Recv, static_cast<i32>(sizeof(kRequest) - 1u)));
    return true;
}

TEST(recv, then_send) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    loop.backend.clear_ops();
    static constexpr char kRequest[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.dispatch(make_ev(c->id, IoEventType::Recv, sizeof(kRequest) - 1));
    CHECK_EQ(c->state, ConnState::Sending);
    CHECK_EQ(c->on_send, &on_response_sent<SmallLoop>);
    // recv_buf preserved until on_response_sent (allows proxy to read it)
    CHECK_EQ(c->recv_buf.len(), sizeof(kRequest) - 1);
    CHECK_GT(c->send_buf.len(), 0u);
    auto* op = loop.backend.last_op(MockOp::Send);
    REQUIRE(op != nullptr);
    CHECK_EQ(op->fd, 42);
}

TEST(recv, eof) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    loop.inject_and_dispatch(make_ev(cid, IoEventType::Recv, 0));
    CHECK_EQ(loop.conns[cid].fd, -1);
    CHECK(loop.conns[cid].on_recv == nullptr && loop.conns[cid].on_send == nullptr);
}

TEST(recv, error_connreset) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    loop.inject_and_dispatch(make_ev(cid, IoEventType::Recv, -104));
    CHECK_EQ(loop.conns[cid].fd, -1);
}

// === Send ===

TEST(send, keepalive_loop) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    static constexpr char kRequest[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.dispatch(make_ev(c->id, IoEventType::Recv, sizeof(kRequest) - 1));
    CHECK_EQ(c->on_send, &on_response_sent<SmallLoop>);
    loop.backend.clear_ops();
    loop.inject_and_dispatch(
        make_ev(c->id, IoEventType::Send, static_cast<i32>(c->send_buf.len())));
    CHECK_EQ(c->state, ConnState::ReadingHeader);
    CHECK_EQ(c->on_recv, &on_header_received<SmallLoop>);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 1u);
}

