// Bytes that race into recv_buf while a client→upstream tunnel send is in flight
// must be forwarded next, never dropped: the send-completion consumes ONLY the
// submitted length and re-sends the remainder, keeping client recv paused until
// the buffer drains. Regression guard for the buffered-bytes-after-send finding.
TEST(websocket, client_to_upstream_sent_resends_raced_bytes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->is_ws_tunnel = true;
    conn->upstream_fd = 43;
    const u32 cid = conn->id;

    const u8 hello[] = {'H', 'E', 'L', 'L', 'O'};
    REQUIRE_EQ(conn->recv_buf.write(hello, sizeof(hello)), sizeof(hello));
    loop.backend.op_count = 0;
    on_ws_client_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Recv, 5));
    REQUIRE(conn->ws_client_send_pending);
    CHECK_EQ(conn->ws_client_send_len, 5u);

    // More client bytes arrive while the HELLO send is still pending (e.g. a recv
    // CQE harvested before the pause took effect). They append to recv_buf.
    const u8 world[] = {'W', 'O', 'R', 'L', 'D'};
    REQUIRE_EQ(conn->recv_buf.write(world, sizeof(world)), sizeof(world));
    CHECK_EQ(conn->recv_buf.len(), 10u);

    // HELLO send completes (5 bytes). Consume exactly 5; forward WORLD next.
    loop.backend.op_count = 0;
    on_ws_client_to_upstream_sent<SmallLoop>(
        &loop, *conn, make_ev(cid, IoEventType::UpstreamSend, 5));
    REQUIRE_EQ(conn->recv_buf.len(), 5u);
    REQUIRE_EQ(loop.backend.op_count, 2u);
    CHECK_EQ(loop.backend.ops[0].type, MockOp::Send);
    CHECK_EQ(loop.backend.ops[0].fd, 43);
    CHECK_EQ(loop.backend.ops[0].send_len, 5u);
    REQUIRE(loop.backend.ops[0].send_buf != nullptr);
    CHECK_EQ(__builtin_memcmp(loop.backend.ops[0].send_buf, world, sizeof(world)), 0);
    CHECK_EQ(loop.backend.ops[1].type, MockOp::PauseRecv);
    CHECK(conn->ws_client_send_pending);
    CHECK_EQ(conn->ws_client_send_len, 5u);
    CHECK_EQ(loop.conns[cid].fd, 42);  // not closed
}

// Symmetric guard for the upstream→client direction: backend bytes that race in
// while an upstream→client send is in flight are re-sent, not dropped.
TEST(websocket, upstream_to_client_sent_resends_raced_bytes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->is_ws_tunnel = true;
    conn->upstream_fd = 43;
    const u32 cid = conn->id;

    const u8 ping[] = {'P', 'I', 'N', 'G'};
    REQUIRE_EQ(conn->upstream_recv_buf.write(ping, sizeof(ping)), sizeof(ping));
    loop.backend.op_count = 0;
    on_ws_upstream_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, 4));
    REQUIRE(conn->ws_upstream_send_pending);
    CHECK_EQ(conn->ws_upstream_send_len, 4u);

    const u8 pong[] = {'P', 'O', 'N', 'G'};
    REQUIRE_EQ(conn->upstream_recv_buf.write(pong, sizeof(pong)), sizeof(pong));
    CHECK_EQ(conn->upstream_recv_buf.len(), 8u);

    loop.backend.op_count = 0;
    on_ws_upstream_to_client_sent<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Send, 4));
    REQUIRE_EQ(conn->upstream_recv_buf.len(), 4u);
    REQUIRE_EQ(loop.backend.op_count, 2u);
    CHECK_EQ(loop.backend.ops[0].type, MockOp::Send);
    CHECK_EQ(loop.backend.ops[0].fd, 42);  // client fd
    CHECK_EQ(loop.backend.ops[0].send_len, 4u);
    REQUIRE(loop.backend.ops[0].send_buf != nullptr);
    CHECK_EQ(__builtin_memcmp(loop.backend.ops[0].send_buf, pong, sizeof(pong)), 0);
    CHECK_EQ(loop.backend.ops[1].type, MockOp::PauseUpstreamRecv);
    CHECK(conn->ws_upstream_send_pending);
    CHECK_EQ(conn->ws_upstream_send_len, 4u);
    CHECK_EQ(loop.conns[cid].fd, 42);  // not closed
}

// A client half-close (FIN) while its client→upstream send is still draining
// must NOT truncate the last frame: defer the teardown until the send completes,
// then close. Regression guard for the drain-before-close finding.
TEST(websocket, client_half_close_defers_until_send_drains) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->is_ws_tunnel = true;
    conn->upstream_fd = 43;
    const u32 cid = conn->id;

    const u8 bye[] = {'B', 'Y', 'E'};
    REQUIRE_EQ(conn->recv_buf.write(bye, sizeof(bye)), sizeof(bye));
    on_ws_client_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Recv, 3));
    REQUIRE(conn->ws_client_send_pending);

    // FIN arrives while the BYE frame is still in flight to the upstream.
    loop.backend.op_count = 0;
    on_ws_client_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Recv, 0));
    CHECK(conn->ws_client_eof);
    CHECK_EQ(loop.conns[cid].fd, 42);                    // deferred, not closed
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);  // no extra send pending

    // The send completes; only now does the tunnel tear down.
    on_ws_client_to_upstream_sent<SmallLoop>(
        &loop, *conn, make_ev(cid, IoEventType::UpstreamSend, 3));
    CHECK_EQ(loop.conns[cid].fd, -1);  // closed after the last frame flushed
}

// A negative recv error (e.g. ECONNRESET) is NOT a clean FIN — close at once
// rather than entering the drain path (which could keep forwarding bytes).
TEST(websocket, recv_error_closes_immediately) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->is_ws_tunnel = true;
    conn->upstream_fd = 43;
    const u32 cid = conn->id;

    on_ws_client_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Recv, -ECONNRESET));
    CHECK(!conn->ws_client_eof);       // not treated as a drainable FIN
    CHECK_EQ(loop.conns[cid].fd, -1);  // closed immediately
}

// Symmetric guard for a backend half-close while its upstream→client send drains.
TEST(websocket, backend_half_close_defers_until_send_drains) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->is_ws_tunnel = true;
    conn->upstream_fd = 43;
    const u32 cid = conn->id;

    const u8 bye[] = {'B', 'Y', 'E'};
    REQUIRE_EQ(conn->upstream_recv_buf.write(bye, sizeof(bye)), sizeof(bye));
    on_ws_upstream_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, 3));
    REQUIRE(conn->ws_upstream_send_pending);

    loop.backend.op_count = 0;
    on_ws_upstream_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, 0));
    CHECK(conn->ws_upstream_eof);
    CHECK_EQ(loop.conns[cid].fd, 42);  // deferred, not closed
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);

    on_ws_upstream_to_client_sent<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Send, 3));
    CHECK_EQ(loop.conns[cid].fd, -1);  // closed after the last frame flushed
}

// nginx-style drain-then-close: a FIN on one side must flush BOTH directions'
// in-flight data before tearing down — the opposite direction's pending send is
// not dropped. The tunnel closes only once both directions have drained.
TEST(websocket, half_close_drains_both_directions_before_close) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->is_ws_tunnel = true;
    conn->upstream_fd = 43;
    const u32 cid = conn->id;

    // A client→upstream send and an independent upstream→client send both in flight.
    const u8 c2u[] = {'C', '2', 'U'};
    REQUIRE_EQ(conn->recv_buf.write(c2u, sizeof(c2u)), sizeof(c2u));
    on_ws_client_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Recv, 3));
    REQUIRE(conn->ws_client_send_pending);
    const u8 u2c[] = {'U', '2', 'C'};
    REQUIRE_EQ(conn->upstream_recv_buf.write(u2c, sizeof(u2c)), sizeof(u2c));
    on_ws_upstream_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, 3));
    REQUIRE(conn->ws_upstream_send_pending);

    // Client FIN while both sends drain → defer.
    on_ws_client_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Recv, 0));
    CHECK(conn->ws_client_eof);
    CHECK_EQ(loop.conns[cid].fd, 42);

    // client→upstream completes; the upstream→client send must still drain.
    on_ws_client_to_upstream_sent<SmallLoop>(
        &loop, *conn, make_ev(cid, IoEventType::UpstreamSend, 3));
    CHECK_EQ(loop.conns[cid].fd, 42);  // opposite direction NOT dropped

    // upstream→client completes → both drained → tunnel tears down.
    on_ws_upstream_to_client_sent<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Send, 3));
    CHECK_EQ(loop.conns[cid].fd, -1);  // closed only after both flushed
}

// A backend that closes during the pre-tunnel 101 drain must defer teardown
// (preserve buffered 101 bytes) rather than close mid-handshake.
TEST(websocket, pre_tunnel_backend_close_defers) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->upstream_fd = 43;
    const u32 cid = conn->id;

    on_ws_pre_tunnel_upstream_recv<SmallLoop>(
        &loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, 0));
    CHECK(conn->ws_pre_tunnel_upstream_closed);
    CHECK_EQ(loop.conns[cid].fd, 42);  // not closed mid-handshake
}

// A negative pre-tunnel recv (e.g. ECONNRESET) is a hard failure, not a clean
// EOF — close immediately rather than advertising a successful upgrade.
TEST(websocket, pre_tunnel_recv_error_closes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->upstream_fd = 43;
    const u32 cid = conn->id;

    on_ws_pre_tunnel_upstream_recv<SmallLoop>(
        &loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, -ECONNRESET));
    CHECK(!conn->ws_pre_tunnel_upstream_closed);  // not a deferred clean close
    CHECK_EQ(loop.conns[cid].fd, -1);             // closed immediately
}

// Backend FIN with no pending send and an empty buffer tears the tunnel down.
TEST(websocket, backend_eof_no_pending_closes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->is_ws_tunnel = true;
    conn->upstream_fd = 43;
    const u32 cid = conn->id;

    on_ws_upstream_recv<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, 0));
    CHECK_EQ(loop.conns[cid].fd, -1);  // closed
}

// A pre-tunnel -ENOBUFS (backend filled upstream_recv_buf before the 101 sent)
// pauses the upstream direction rather than closing the handshake.
TEST(websocket, pre_tunnel_enobufs_pauses) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->upstream_fd = 43;
    const u32 cid = conn->id;
    conn->upstream_recv_buf.commit(conn->upstream_recv_buf.write_avail());
    CHECK_EQ(conn->upstream_recv_buf.write_avail(), 0u);

    loop.backend.op_count = 0;
    on_ws_pre_tunnel_upstream_recv<SmallLoop>(
        &loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, -ENOBUFS));
    CHECK_EQ(loop.conns[cid].fd, 42);  // not closed
    REQUIRE_EQ(loop.backend.op_count, 1u);
    CHECK_EQ(loop.backend.ops[0].type, MockOp::PauseUpstreamRecv);
}

// on_ws_101_sent forwards client bytes already buffered at tunnel install
// (e.g. a recovered pipeline stash) into the upstream direction.
TEST(websocket, upgrade_101_sent_forwards_buffered_client_bytes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->upstream_fd = 43;
    conn->resp_status = 101;
    conn->ws_upgrade_response_len = 64;
    conn->ws_upgrade_sent_len = 64;

    const u8 cb[] = {'H', 'I'};
    REQUIRE_EQ(conn->recv_buf.write(cb, sizeof(cb)), sizeof(cb));

    loop.backend.op_count = 0;
    on_ws_101_sent<SmallLoop>(&loop, *conn, make_ev(conn->id, IoEventType::Send, 64));
    CHECK(conn->is_ws_tunnel);
    CHECK(conn->ws_client_send_pending);
    bool saw = false;
    for (u32 i = 0; i < loop.backend.op_count; i++)
        if (loop.backend.ops[i].type == MockOp::Send && loop.backend.ops[i].fd == 43) saw = true;
    CHECK(saw);  // buffered client bytes forwarded upstream
}

// io_uring regression: with NO buffered post-upgrade client bytes, on_ws_101_sent must re-arm
// the client recv via ws_resume_client_recv (which clears recv_paused_for_send), NOT a bare
// submit_recv. ws_stop_client_poll paused the client recv on the 101 path (io_uring:
// recv_paused_for_send = true); a bare submit_recv no-ops while that flag is set, and with no
// client send ever in flight to clear it the tunnel would stall and never read further frames.
TEST(websocket, upgrade_101_sent_rearms_client_recv_when_no_buffered_bytes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->upstream_fd = 43;
    conn->resp_status = 101;
    conn->ws_upgrade_response_len = 64;
    conn->ws_upgrade_sent_len = 64;
    REQUIRE_EQ(conn->recv_buf.len(), 0u);  // no buffered client bytes -> the no-buffered path
    // Simulate ws_stop_client_poll having paused the client recv on the io_uring 101 path.
    conn->recv_paused_for_send = true;

    on_ws_101_sent<SmallLoop>(&loop, *conn, make_ev(conn->id, IoEventType::Send, 64));
    CHECK(conn->is_ws_tunnel);
    CHECK_FALSE(conn->recv_paused_for_send);  // re-armed (was stuck true before the fix → stall)
}

// If the backend half-closed during the 101 drain AND both early upstream bytes
// and buffered client bytes exist, on_ws_101_sent must enter drain mode: flush
// BOTH directions before closing, never arm new client reads, and tear down only
// once both drained.
TEST(websocket, upgrade_101_sent_drains_both_when_backend_closed_pretunnel) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->upstream_fd = 43;
    conn->resp_status = 101;
    conn->ws_upgrade_response_len = 64;
    conn->ws_upgrade_sent_len = 64;
    conn->ws_pre_tunnel_upstream_closed = true;  // backend FIN during the 101 drain
    const u32 cid = conn->id;

    const u8 early[] = {'H', 'E', 'L', 'L', 'O'};  // early upstream→client bytes
    REQUIRE_EQ(conn->upstream_recv_buf.write(early, sizeof(early)), sizeof(early));
    const u8 cb[] = {'H', 'I'};  // buffered client→upstream bytes
    REQUIRE_EQ(conn->recv_buf.write(cb, sizeof(cb)), sizeof(cb));

    loop.backend.op_count = 0;
    on_ws_101_sent<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::Send, 64));
    CHECK(conn->is_ws_tunnel);
    CHECK(conn->ws_upstream_eof);                        // entered drain mode (not a fresh tunnel)
    CHECK_EQ(loop.conns[cid].fd, 42);                    // not closed — both sends draining
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);  // did NOT arm new client reads
    bool to_upstream = false, to_client = false;
    for (u32 i = 0; i < loop.backend.op_count; i++) {
        const MockOp& op = loop.backend.ops[i];
        if (op.type == MockOp::Send && op.fd == 43) to_upstream = true;  // client→upstream
        if (op.type == MockOp::Send && op.fd == 42) to_client = true;    // upstream→client
    }
    CHECK(to_upstream);  // buffered client bytes flushed to upstream
    CHECK(to_client);    // early upstream bytes flushed to client

    // Both directions drain → only then does the tunnel close.
    on_ws_client_to_upstream_sent<SmallLoop>(
        &loop, *conn, make_ev(cid, IoEventType::UpstreamSend, sizeof(cb)));
    CHECK_EQ(loop.conns[cid].fd, 42);  // upstream→client still draining
    on_ws_upstream_to_client_sent<SmallLoop>(
        &loop, *conn, make_ev(cid, IoEventType::Send, sizeof(early)));
    CHECK_EQ(loop.conns[cid].fd, -1);  // both drained → closed
}

// Entering tunnel mode must release the upstream max_inflight slot so a
// long-lived tunnel doesn't hold an in-flight request slot for its lifetime.
TEST(websocket, upgrade_101_sent_releases_upstream_slot) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->upstream_fd = 43;
    conn->resp_status = 101;
    conn->ws_upgrade_response_len = 64;
    conn->ws_upgrade_sent_len = 64;
    conn->upstream_slot_held = true;  // slot taken at proxy dispatch

    on_ws_101_sent<SmallLoop>(&loop, *conn, make_ev(conn->id, IoEventType::Send, 64));
    CHECK(conn->is_ws_tunnel);
    CHECK(!conn->upstream_slot_held);  // released at the 101, not held until close
}

// pipeline_recover must prepend the stash before bytes already read into
// recv_buf (client frames that raced in before tunnel install), not drop them.
TEST(websocket, pipeline_recover_preserves_raced_recv_bytes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);

    const u8 stash[] = {'A', 'B'};  // bytes right after the upgrade request
    conn->send_buf.reset();
    REQUIRE_EQ(conn->send_buf.write(stash, sizeof(stash)), sizeof(stash));
    conn->pipeline_stash_len = sizeof(stash);

    const u8 raced[] = {'C', 'D', 'E'};  // arrived later, before tunnel install
    conn->recv_buf.reset();
    REQUIRE_EQ(conn->recv_buf.write(raced, sizeof(raced)), sizeof(raced));

    REQUIRE(pipeline_recover(*conn) == PipelineTransitionResult::Advanced);
    REQUIRE_EQ(conn->recv_buf.len(), 5u);
    CHECK_EQ(__builtin_memcmp(conn->recv_buf.data(), "ABCDE", 5), 0);  // stash then raced
    CHECK_EQ(conn->pipeline_stash_len, 0u);
}

// The legacy loop's timer tick must NOT close a WebSocket tunnel on idle timeout
// (the is_ws_tunnel exemption). Covers event_loop.h's `if (is_ws_tunnel) return`.
TEST(legacy_loop, ws_tunnel_exempt_from_idle_timeout) {
    auto loop = std::make_unique<EventLoop<MockBackend>>();
    REQUIRE(loop->init(0, -1).has_value());
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = -1;
    c->is_ws_tunnel = true;
    loop->timer.add(c, 1);
    IoEvent tick{};
    tick.type = IoEventType::Timeout;
    tick.result = 2;  // wheel fires slots[cursor] then advances; add(_,1) needs 2
    loop->dispatch(tick);
    // The tunnel was exempted (early return), not closed.
    CHECK(c->is_ws_tunnel);
    loop->shutdown();
}
#endif  // RUT_ENABLE_WEBSOCKET

// Cover the legacy EventLoop<Backend> accessors + free_conn slice release.
TEST(legacy_loop, accessors_and_free_release_slices) {
    auto loop = std::make_unique<EventLoop<MockBackend>>();
    REQUIRE(loop->init(0, -1).has_value());
    CHECK(!loop->is_draining());
    loop->clear_upstream_fd(0);
    loop->clear_upstream_fd(EventLoop<MockBackend>::kMaxConns - 1);

    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop->alloc_upstream_buf(*c));
    REQUIRE(c->recv_slice != nullptr);
    REQUIRE(c->upstream_recv_slice != nullptr);
    c->fd = -1;
    loop->free_conn(*c);  // must return the pooled slices
    CHECK_EQ(c->recv_slice, nullptr);
    CHECK_EQ(c->upstream_recv_slice, nullptr);
    loop->shutdown();
}

namespace {
bool g_tls_pending_send_called = false;
u32 g_tls_pending_send_result = 0;
bool g_tls_set_slots_recv_called = false;

void tls_pending_send_probe(void* /*lp*/, Connection& conn, IoEvent ev) {
    g_tls_pending_send_called = true;
    g_tls_pending_send_result = static_cast<u32>(ev.result);
    conn.on_send = nullptr;
}

void tls_set_slots_recv_probe(void*, Connection&, IoEvent) {
    g_tls_set_slots_recv_called = true;
}

void tls_set_slots_send_probe(void*, Connection&, IoEvent) {}
}  // namespace

TEST(connection_base, set_slots_redirects_recv_slot_for_iouring_tls) {
    Connection conn;
    u8 tls_in_storage[SmallLoop::kBufSize];
    u8 tls_out_storage[SmallLoop::kBufSize];
    conn.reset();
    conn.id = 77;
    conn.tls_active = true;
    conn.tls_engine.ssl = reinterpret_cast<SSL*>(0x1);
    conn.tls_in_slice = tls_in_storage;
    conn.tls_out_slice = tls_out_storage;

    g_tls_set_slots_recv_called = false;
    conn.set_slots(&tls_set_slots_recv_probe, &tls_set_slots_send_probe, nullptr, nullptr);

    CHECK(conn.uses_iouring_tls());
    CHECK(conn.on_recv == nullptr);
    CHECK(conn.tls_pending_on_recv == &tls_set_slots_recv_probe);
    CHECK(g_tls_set_slots_recv_called == false);
    conn.tls_engine.ssl = nullptr;
}

TEST(tls_engine, accessor_helpers_track_ciphertext_offsets) {
    TlsEngine engine;
    u8 in[16];
    u8 out[16];
    tls_engine_set_input(engine, in, sizeof(in));
    tls_engine_set_output(engine, out, sizeof(out));

    CHECK_EQ(tls_engine_input_consumed(engine), 0u);
    CHECK_EQ(tls_engine_output_len(engine), 0u);

    engine.in_off = 4;
    CHECK_EQ(tls_engine_input_consumed(engine), 4u);

    engine.out_len = 7;
    CHECK_EQ(tls_engine_output_len(engine), 7u);
}

TEST(tls_iouring, drain_completion_invokes_saved_send_continuation) {
    Connection conn;
    u8 recv_storage[SmallLoop::kBufSize];
    u8 send_storage[SmallLoop::kBufSize];
    u8 tls_out_storage[256];
    conn.reset();
    conn.id = 7;
    conn.fd = 42;
    conn.recv_slice = recv_storage;
    conn.send_slice = send_storage;
    conn.recv_buf.bind(recv_storage, SmallLoop::kBufSize);
    conn.send_buf.bind(send_storage, SmallLoop::kBufSize);
    conn.tls_out_buf.bind(tls_out_storage, sizeof(tls_out_storage));
    conn.tls_active = true;
    conn.tls_out_inflight = true;
    conn.tls_out_inflight_len = 0;  // ciphertext already drained; just complete
    conn.tls_send_src = reinterpret_cast<const u8*>("plain");
    conn.tls_send_len = 5;
    conn.tls_send_off = 5;  // fully encrypted — no parked remainder
    conn.tls_pending_on_send = &tls_pending_send_probe;
    conn.on_send = &tls_on_out_drain<IoUringEventLoop>;
    g_tls_pending_send_called = false;
    g_tls_pending_send_result = 0;

    tls_on_out_drain<IoUringEventLoop>(nullptr, conn, make_ev(conn.id, IoEventType::Send, 9));

    CHECK(g_tls_pending_send_called);
    CHECK_EQ(g_tls_pending_send_result, 5u);  // fires with the plaintext length
    CHECK(!conn.tls_out_inflight);
    CHECK(conn.tls_send_src == nullptr);
    CHECK_EQ(conn.tls_send_len, 0u);
    CHECK(conn.tls_pending_on_send == nullptr);
}

TEST(tls_iouring, ensure_draining_empty_buffer_is_noop) {
    Connection conn;
    conn.reset();
    conn.id = 8;
    conn.tls_active = true;
    // tls_out_buf is empty — nothing to submit, no loop deref.
    CHECK(tls_ensure_draining<IoUringEventLoop>(nullptr, conn));
    CHECK(!conn.tls_out_inflight);
}

// A response started while a control/handshake flight is in flight overwrites
// on_send via transition_to_sending(); tls_ensure_draining must restore the
// drain hook so the in-flight send's Send CQE still clears tls_out_inflight
// (rather than being dispatched as the response completion → stuck buffer).
TEST(tls_iouring, ensure_draining_restores_hook_while_inflight) {
    Connection conn;
    conn.reset();
    conn.id = 9;
    conn.tls_active = true;
    conn.tls_out_inflight = true;            // a ciphertext send is already draining
    conn.on_send = &tls_pending_send_probe;  // upper layer overwrote it (response start)
    // inflight → returns true without touching the loop (safe to pass nullptr).
    CHECK(tls_ensure_draining<IoUringEventLoop>(nullptr, conn));
    CHECK(conn.on_send == &tls_on_out_drain<IoUringEventLoop>);  // hook restored
    CHECK(conn.tls_out_inflight);                                // still inflight, untouched
}

TEST(tls_iouring, input_buffer_fits_full_ciphertext_record) {
    CHECK_GE(IoUringEventLoop::kTlsInputSize, SlicePool::kSliceSize + 1024);
}

// Round-4 race fix #F: a TLS proxy-stream -ENOBUFS with NO parked tail must fail
// closed. A wait() batch harvests the whole multishot CQE burst into the 16 KiB
// upstream_recv_buf before the first callback drains it, so it can overflow even
// with tls_send_src == nullptr; the backend already discarded the uncopied
// suffix, so pause+replay would silently truncate the proxied download.
TEST(tls_iouring, proxy_stream_enobufs_without_parked_tail_closes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->tls_proxy_stream = true;
    conn->tls_send_src = nullptr;  // no parked tail (the newly-covered case)
    const u32 cid = conn->id;

    on_response_body_recvd<SmallLoop>(
        &loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, -ENOBUFS));
    CHECK_EQ(loop.conns[cid].fd, -1);  // fail closed

    // Contrast: a plaintext (non-proxy-TLS) -ENOBUFS on a full buffer still
    // self-heals by pausing, not closing — the broadened guard didn't regress it.
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 43));
    auto* plain = loop.find_fd(43);
    REQUIRE(plain != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*plain));
    plain->upstream_recv_buf.commit(plain->upstream_recv_buf.write_avail());  // full
    const u32 pcid = plain->id;
    on_response_body_recvd<SmallLoop>(
        &loop, *plain, make_ev(pcid, IoEventType::UpstreamRecv, -ENOBUFS));
    CHECK_EQ(loop.conns[pcid].fd, 43);  // paused, not closed
}

// Round-4 race fix #H: while a TLS proxy tail is parked (tls_send_src points into
// upstream_recv_buf), a raced multishot upstream CQE must be deferred. Re-running
// the encrypt path now would double-encrypt the parked tail (the drain path still
// owns it) and double-count the body; the parked-drain replay owns those bytes.
TEST(tls_iouring, proxy_stream_defers_raced_cqe_while_tail_parked) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->tls_proxy_stream = true;
    const u8 raced[] = {'A', 'B', 'C', 'D'};
    REQUIRE_EQ(conn->upstream_recv_buf.write(raced, sizeof(raced)), sizeof(raced));
    conn->tls_send_src = conn->upstream_recv_buf.data();  // tail parked at front
    conn->tls_send_len = 8;
    conn->tls_send_off = 0;
    const u32 cid = conn->id;
    const u32 kBefore = conn->upstream_recv_buf.len();

    loop.backend.op_count = 0;
    on_response_body_recvd<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, 4));
    CHECK_EQ(loop.conns[cid].fd, 42);                  // not closed
    CHECK_EQ(loop.backend.op_count, 0u);               // deferred — no encrypt/send/recv op
    CHECK_EQ(conn->upstream_recv_buf.len(), kBefore);  // buffer untouched
    CHECK(conn->tls_send_src != nullptr);              // tail still parked for the drain
}

// Round-4 race fix #C (cross-request half): proxy_stream_complete must clear
// tls_recv_paused_hw at the keep-alive boundary, so a high-watermark pause from
// one response can't leak into the next request and let the low-watermark resume
// spuriously re-arm the upstream read. (The in-request resume gate itself —
// tls_on_out_drain skipping the resume when resp_fully_buffered — needs the real
// IoUringEventLoop TLS-drain interface and is exercised by the real-io_uring
// proxy_tls_iouring.large_body_streams_through_watermark integration test.)
TEST(tls_iouring, proxy_stream_complete_clears_hw_pause) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->tls_proxy_stream = true;
    conn->resp_fully_buffered = true;
    conn->tls_recv_paused_hw = true;
    conn->throttle_paused = true;  // round-5 #4: a throttle pause must not leak
    conn->throttle_pending_len = 99;
    conn->keep_alive = true;  // stays open, so the flags are readable afterward
    const u32 cid = conn->id;

    proxy_stream_complete<SmallLoop>(&loop, *conn);
    CHECK_EQ(loop.conns[cid].fd, 42);  // kept alive
    CHECK(!conn->tls_recv_paused_hw);  // cleared at the keep-alive boundary
    CHECK(!conn->tls_proxy_stream);    // per-response state reset
    CHECK(!conn->resp_fully_buffered);
    CHECK(!conn->throttle_paused);  // #4: throttle pause cleared (leaked tick no-ops)
    CHECK_EQ(conn->throttle_pending_len, 0u);
}

// Round-6 #A: a throttled response completed via proxy_stream_complete with the
// throttle pause cleared (round-5 #4) must restore the keepalive deadline —
// arm_throttle_timer had pulled the connection off the keepalive wheel, and the
// now-no-op throttle timer would otherwise leave an idle keep-alive client with no
// deadline at all.
TEST(tls_iouring, proxy_stream_complete_restores_keepalive_after_throttle) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    loop.timer.remove(conn);            // arm_throttle_timer pulled it off the wheel
    REQUIRE(conn->timer_node.empty());  // confirm: no keepalive deadline armed
    conn->tls_proxy_stream = true;
    conn->resp_fully_buffered = true;
    conn->throttle_paused = true;  // completing while throttled
    conn->keep_alive = true;
    const u32 cid = conn->id;

    proxy_stream_complete<SmallLoop>(&loop, *conn);
    CHECK_EQ(loop.conns[cid].fd, 42);  // kept alive
    CHECK(!conn->timer_node.empty());  // keepalive timer restored (back on the wheel)
}

// Round-5 #3: when the final body chunk parked a TLS proxy tail (body parser
// complete, but resp_fully_buffered not set until the tail drains), a racing
// upstream EOF must be ignored — the drain owns the remaining body bytes. A tail
// parked mid-body (body NOT complete) is a genuine truncation and still closes.
TEST(tls_iouring, proxy_stream_parked_complete_tail_ignores_eof) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*conn));
    conn->tls_proxy_stream = true;
    conn->tls_send_src = conn->upstream_recv_buf.data();  // tail parked
    conn->tls_send_len = 4;
    conn->resp_body_mode = BodyMode::ContentLength;
    conn->resp_body_remaining = 0;  // body parser already complete
    const u32 cid = conn->id;
    on_response_body_recvd<SmallLoop>(&loop, *conn, make_ev(cid, IoEventType::UpstreamRecv, 0));
    CHECK_EQ(loop.conns[cid].fd, 42);  // EOF ignored — complete-on-drain

    // Contrast: tail parked mid-body (more body expected) → EOF is a truncation.
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 43));
    auto* trunc = loop.find_fd(43);
    REQUIRE(trunc != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*trunc));
    trunc->tls_proxy_stream = true;
    trunc->tls_send_src = trunc->upstream_recv_buf.data();
    trunc->tls_send_len = 4;
    trunc->resp_body_mode = BodyMode::ContentLength;
    trunc->resp_body_remaining = 10;  // body NOT complete
    const u32 tcid = trunc->id;
    on_response_body_recvd<SmallLoop>(&loop, *trunc, make_ev(tcid, IoEventType::UpstreamRecv, 0));
    CHECK_EQ(loop.conns[tcid].fd, -1);  // truncation → closed
}

// Round-5 #2: throttle_resume's deferred re-arm (kRemaining == 0) must fail closed
// when submit_recv_upstream can't queue under SQ pressure — otherwise the watermark
// flag is already gone and nothing retries, stalling the response until timeout.
TEST(tls_iouring, throttle_resume_fails_closed_when_rearm_fails) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->throttle_paused = true;
    conn->throttle_pending_len = 0;  // kRemaining == 0 → the deferred re-arm path
    conn->throttle_down_bps = 0;     // budget available → proceeds to re-arm
    const u32 cid = conn->id;

    loop.backend.fail_upstream_recv = true;  // simulate io_uring SQ pressure
    throttle_resume<SmallLoop>(&loop, *conn);
    CHECK_EQ(loop.conns[cid].fd, -1);  // fail closed, not silently stalled
}

// Two proxy cycles on same connection (keep-alive)
TEST(proxy, keepalive_two_cycles) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    static constexpr char kRequest[] = "GET /proxy HTTP/1.1\r\nHost: x\r\n\r\n";

    for (int cycle = 0; cycle < 2; cycle++) {
        REQUIRE_EQ(
            conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
            sizeof(kRequest) - 1);
        loop.dispatch(make_ev(conn->id, IoEventType::Recv, sizeof(kRequest) - 1));
        conn->upstream_fd = 100 + cycle;
        conn->on_upstream_send = &on_upstream_connected<SmallLoop>;
        conn->state = ConnState::Proxying;
        loop.submit_connect(*conn, nullptr, 0);
        loop.inject_and_dispatch(make_ev(conn->id, IoEventType::UpstreamConnect, 0));
        loop.inject_and_dispatch(make_ev(conn->id, IoEventType::UpstreamSend, 100));
        inject_upstream_response(loop, *conn);
        loop.inject_and_dispatch(
            make_ev(conn->id, IoEventType::Send, static_cast<i32>(kMockHttpResponseLen)));
        CHECK_EQ(conn->state, ConnState::ReadingHeader);
    }
}

// === recv-into-buffer integration ===

// Verify recv_buf data() pointer is stable and readable after recv
TEST(recv_buf, data_accessible_after_recv) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);

    // Manually write real data to simulate what epoll wait() does
    c->recv_buf.reset();
    const u8 req[] = "GET / HTTP/1.1\r\n\r\n";
    c->recv_buf.write(req, sizeof(req) - 1);

    CHECK_EQ(c->recv_buf.len(), sizeof(req) - 1);
    CHECK_EQ(c->recv_buf.data()[0], 'G');
    CHECK_EQ(c->recv_buf.data()[1], 'E');
    CHECK_EQ(c->recv_buf.data()[2], 'T');
}

// Verify recv_buf doesn't accumulate across keepalive cycles.
// Callback resets recv_buf after consuming; backend appends to clean buffer.
TEST(recv_buf, reset_between_keepalive_cycles) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);

    static constexpr char kFirst[] = "GET /first HTTP/1.1\r\nHost: x\r\n\r\n";
    static constexpr char kSecond[] = "GET /second HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kFirst), sizeof(kFirst) - 1),
               sizeof(kFirst) - 1);
    loop.dispatch(make_ev(c->id, IoEventType::Recv, sizeof(kFirst) - 1));
    CHECK_EQ(c->recv_buf.len(), sizeof(kFirst) - 1);  // still has data

    // Send response → on_response_sent resets recv_buf before next recv
    loop.inject_and_dispatch(
        make_ev(c->id, IoEventType::Send, static_cast<i32>(c->send_buf.len())));
    CHECK_EQ(c->state, ConnState::ReadingHeader);
    CHECK_EQ(c->recv_buf.len(), 0u);  // reset by on_response_sent

    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kSecond), sizeof(kSecond) - 1),
               sizeof(kSecond) - 1);
    loop.dispatch(make_ev(c->id, IoEventType::Recv, sizeof(kSecond) - 1));
    CHECK_EQ(c->recv_buf.len(), sizeof(kSecond) - 1);  // preserved until send completes
    CHECK_EQ(c->state, ConnState::Sending);
}

// Verify recv_buf capacity via direct Buffer API (not through dispatch)
TEST(recv_buf, capacity_boundary) {
    SmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    // Fill recv_buf to capacity
    u32 avail = c->recv_buf.write_avail();
    CHECK_EQ(avail, SmallLoop::kBufSize);
    c->recv_buf.commit(avail);
    CHECK_EQ(c->recv_buf.len(), SmallLoop::kBufSize);
    CHECK_EQ(c->recv_buf.write_avail(), 0u);
    loop.free_conn(*c);
}

// Verify recv_buf survives connection reuse (alloc → close → alloc)
TEST(recv_buf, survives_connection_reuse) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;

    // recv → preserved → send response (resets) → EOF → close
    static constexpr char kRequest[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.dispatch(make_ev(cid, IoEventType::Recv, sizeof(kRequest) - 1));
    CHECK_EQ(c->recv_buf.len(), sizeof(kRequest) - 1);  // preserved until send
    loop.inject_and_dispatch(make_ev(cid, IoEventType::Send, static_cast<i32>(c->send_buf.len())));
    CHECK_EQ(c->state, ConnState::ReadingHeader);
    loop.inject_and_dispatch(make_ev(cid, IoEventType::Recv, 0));  // EOF → close
    CHECK_EQ(loop.conns[cid].fd, -1);

    // Reuse same slot
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 55));
    // Find which slot got reused
    auto* c2 = loop.find_fd(55);
    REQUIRE(c2 != nullptr);
    // recv_buf must be fresh after reset
    CHECK_EQ(c2->recv_buf.len(), 0u);
    CHECK(c2->recv_buf.valid());
    CHECK_EQ(c2->recv_buf.write_avail(), SmallLoop::kBufSize);
}

// Proxy: verify recv_buf.data() is what gets forwarded upstream
TEST(recv_buf, proxy_forwards_recv_data) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);

    // Simulate recv with real request data
    conn->recv_buf.reset();
    const u8 req[] = "GET /api HTTP/1.1\r\nHost: upstream\r\n\r\n";
    conn->recv_buf.write(req, sizeof(req) - 1);

    // Switch to proxy mode
    conn->upstream_fd = 100;
    conn->on_upstream_send = &on_upstream_connected<SmallLoop>;
    conn->state = ConnState::Proxying;
    loop.submit_connect(*conn, nullptr, 0);

    // Upstream connect succeeds → should forward recv_buf content
    loop.backend.clear_ops();
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::UpstreamConnect, 0));

    auto* send_op = loop.backend.last_op(MockOp::Send);
    REQUIRE(send_op != nullptr);
    CHECK_EQ(send_op->fd, 100);  // upstream_fd
    // Verify the send buffer points to recv_buf data
    CHECK_EQ(send_op->send_buf, conn->recv_buf.data());
    CHECK_EQ(send_op->send_len, conn->recv_buf.len());
}

// Verify Buffer invariants hold through full proxy round-trip
TEST(recv_buf, buffer_state_through_proxy_cycle) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);

    // recv request — preserved in recv_buf
    static constexpr char kRequest[] = "GET /proxy HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.dispatch(make_ev(conn->id, IoEventType::Recv, sizeof(kRequest) - 1));
    CHECK_EQ(conn->recv_buf.len(), sizeof(kRequest) - 1);
    CHECK(!conn->recv_buf.is_released());

    // proxy flow
    conn->upstream_fd = 100;
    conn->on_upstream_send = &on_upstream_connected<SmallLoop>;
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::UpstreamConnect, 0));
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::UpstreamSend, 100));

    // upstream response → upstream_recv_buf gets new data (valid HTTP response)
    inject_upstream_response(loop, *conn);
    CHECK_EQ(conn->upstream_recv_buf.len(), kMockHttpResponseLen);
    CHECK(!conn->upstream_recv_buf.is_released());

    // send to client → back to ReadingHeader
    loop.inject_and_dispatch(
        make_ev(conn->id, IoEventType::Send, static_cast<i32>(kMockHttpResponseLen)));
    CHECK_EQ(conn->state, ConnState::ReadingHeader);
    // Buffer still valid for next request
    CHECK(conn->recv_buf.valid());
}

// recv error doesn't corrupt buffer state; connection is closed
TEST(recv_buf, error_closes_cleanly) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);

    // First complete recv → callback builds a response and preserves the request.
    REQUIRE(dispatch_complete_http1_test_request(loop, *c));
    CHECK_EQ(c->recv_buf.len(), sizeof("GET / HTTP/1.1\r\nHost: x\r\n\r\n") - 1u);  // preserved

    // Send response → on_response_sent resets recv_buf
    loop.inject_and_dispatch(
        make_ev(c->id, IoEventType::Send, static_cast<i32>(c->send_buf.len())));
    CHECK_EQ(c->recv_buf.len(), 0u);  // reset

    // Error recv — connection closed
    u32 cid = c->id;
    loop.inject_and_dispatch(make_ev(cid, IoEventType::Recv, -104));
    CHECK_EQ(loop.conns[cid].fd, -1);  // closed
}

// === Semantic correctness: append-based recv + callback-driven reset ===

// Multi-packet recv: two recv events accumulate before callback runs.
// This tests the core semantic fix — backend appends, callback resets.
TEST(recv_semantic, multi_packet_accumulation) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);

    static constexpr char kRequest[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    static constexpr u32 kFirstPacketLen = 10u;
    static_assert(kFirstPacketLen < sizeof(kRequest) - 1u);

    // Manually simulate two recv packets WITHOUT going through dispatch.
    // This mimics what a real backend does when two packets arrive before
    // the event loop dispatches the first.
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kRequest), kFirstPacketLen),
               kFirstPacketLen);
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kRequest) + kFirstPacketLen,
                                 sizeof(kRequest) - 1u - kFirstPacketLen),
               sizeof(kRequest) - 1u - kFirstPacketLen);
    CHECK_EQ(c->recv_buf.len(), sizeof(kRequest) - 1u);  // accumulated

    // Now dispatch a recv event — callback sees total accumulated data
    IoEvent ev = make_ev(c->id, IoEventType::Recv, sizeof(kRequest) - 1u);
    loop.dispatch(ev);
    CHECK_EQ(c->state, ConnState::Sending);
    CHECK_EQ(c->recv_buf.len(), sizeof(kRequest) - 1u);  // preserved until on_response_sent
}

// recv when recv_buf is full: backend should not crash or corrupt
TEST(recv_semantic, buffer_full_no_crash) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);

    // Fill recv_buf to capacity
    c->recv_buf.commit(4096);
    CHECK_EQ(c->recv_buf.write_avail(), 0u);

    // inject_and_dispatch with result > 0 tries to commit but buf is full.
    // Mock converts to -ENOBUFS, callback sees error → closes connection.
    u32 cid = c->id;
    loop.inject_and_dispatch(make_ev(cid, IoEventType::Recv, 100));
    CHECK_EQ(loop.conns[cid].fd, -1);  // closed due to -ENOBUFS
}

// send_state cleanup: verify partial send state doesn't leak across connection reuse
TEST(recv_semantic, send_state_no_leak_across_reuse) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;

    // Normal recv-send cycle
    static constexpr char kRequest[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.dispatch(make_ev(cid, IoEventType::Recv, sizeof(kRequest) - 1));
    loop.inject_and_dispatch(make_ev(cid, IoEventType::Send, static_cast<i32>(c->send_buf.len())));

    // Close connection
    loop.close_conn(*c);
    CHECK_EQ(loop.conns[cid].fd, -1);

    // Reuse slot — recv_buf and send_buf should be clean
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 55));
    auto* c2 = loop.find_fd(55);
    REQUIRE(c2 != nullptr);
    CHECK_EQ(c2->recv_buf.len(), 0u);
    CHECK_EQ(c2->send_buf.len(), 0u);
    CHECK_EQ(c2->recv_buf.write_avail(), SmallLoop::kBufSize);
    CHECK_EQ(c2->send_buf.write_avail(), SmallLoop::kBufSize);

    // New cycle works cleanly
    REQUIRE_EQ(c2->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.dispatch(make_ev(c2->id, IoEventType::Recv, sizeof(kRequest) - 1));
    CHECK_EQ(c2->state, ConnState::Sending);
    CHECK_GT(c2->send_buf.len(), 0u);
}

// Proxy: recv_buf not reset until proxy response fully sent
TEST(recv_semantic, proxy_recv_buf_lifetime) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);

    // Receive original request — preserved for proxy forwarding
    static constexpr char kRequest[] = "GET /proxy HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.dispatch(make_ev(conn->id, IoEventType::Recv, sizeof(kRequest) - 1));
    CHECK_EQ(conn->recv_buf.len(), sizeof(kRequest) - 1);  // preserved

    // Switch to proxy mode and connect upstream
    conn->upstream_fd = 100;
    conn->on_upstream_send = &on_upstream_connected<SmallLoop>;
    conn->state = ConnState::Proxying;

    // Upstream connect succeeds → forwards recv_buf to upstream
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::UpstreamConnect, 0));

    // Upstream request sent → on_upstream_request_sent resets upstream_recv_buf for response.
    // recv_buf retains original request data (not touched).
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::UpstreamSend, sizeof(kRequest) - 1));
    CHECK_EQ(conn->upstream_recv_buf.len(), 0u);  // reset by on_upstream_request_sent

    // Upstream response received → data goes into upstream_recv_buf (valid HTTP response)
    inject_upstream_response(loop, *conn);
    // on_upstream_response does NOT reset upstream_recv_buf (send still in progress)
    CHECK_EQ(conn->on_send, &on_proxy_response_sent<SmallLoop>);

    // Proxy response sent → on_proxy_response_sent resets upstream_recv_buf and recv_buf.
    loop.inject_and_dispatch(
        make_ev(conn->id, IoEventType::Send, static_cast<i32>(kMockHttpResponseLen)));
    CHECK_EQ(conn->upstream_recv_buf.len(), 0u);  // reset by on_proxy_response_sent
    CHECK_EQ(conn->recv_buf.len(), 0u);           // reset by on_proxy_response_sent (keep-alive)
    CHECK_EQ(conn->state, ConnState::ReadingHeader);
}

// Connection alloc+free clears buffers, re-alloc rebinds them
TEST(recv_semantic, reset_clears_both_buffers) {
    SmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);

    // Write data to both buffers
    c->recv_buf.write(reinterpret_cast<const u8*>("GET"), 3);
    c->send_buf.write(reinterpret_cast<const u8*>("HTTP"), 4);
    CHECK_EQ(c->recv_buf.len(), 3u);
    CHECK_EQ(c->send_buf.len(), 4u);

    loop.free_conn(*c);

    // Re-alloc: buffers should be rebound and empty
    Connection* c2 = loop.alloc_conn();
    REQUIRE(c2 != nullptr);
    CHECK_EQ(c2->recv_buf.len(), 0u);
    CHECK_EQ(c2->send_buf.len(), 0u);
    CHECK(c2->recv_buf.valid());
    CHECK(c2->send_buf.valid());
    CHECK_EQ(c2->recv_buf.write_avail(), SmallLoop::kBufSize);
    CHECK_EQ(c2->send_buf.write_avail(), SmallLoop::kBufSize);
    CHECK(!c2->recv_buf.is_released());
    CHECK(!c2->send_buf.is_released());
    loop.free_conn(*c2);
}

// === Callback type guard: close on unexpected event type ===

// on_header_received expects Recv — Send event should close
TEST(type_guard, header_recv_ignores_wrong_type) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    // UpstreamSend goes to on_upstream_send (null) → ignored by dispatch.
    loop.dispatch(make_ev(c->id, IoEventType::UpstreamSend, 100));
    CHECK(c->fd >= 0);
}

// on_response_sent expects Send — Recv event should close
TEST(type_guard, response_sent_rejects_recv) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    REQUIRE(dispatch_complete_http1_test_request(loop, *c));
    CHECK_EQ(c->on_send, &on_response_sent<SmallLoop>);
    // Dispatch a Recv event while expecting Send → ignored (pipelined data).
    loop.dispatch(make_ev(cid, IoEventType::Recv, 50));
    CHECK(loop.conns[cid].fd >= 0);  // not closed — bytes buffered for pipeline
}

// on_upstream_connected expects UpstreamConnect — Recv should close
TEST(type_guard, upstream_connected_ignores_wrong_type) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->upstream_fd = 100;
    conn->on_upstream_send = &on_upstream_connected<SmallLoop>;
    // Recv goes to on_recv (on_header_received), not on_upstream_send.
    loop.dispatch(make_ev(conn->id, IoEventType::Recv, 50));
    CHECK(conn->fd >= 0);
}

// on_upstream_request_sent expects Send — Recv should close
TEST(type_guard, upstream_request_sent_ignores_wrong_type) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->on_upstream_send = &on_upstream_request_sent<SmallLoop>;
    // Recv goes to on_recv, not on_upstream_send.
    loop.dispatch(make_ev(conn->id, IoEventType::Recv, 50));
    CHECK(conn->fd >= 0);
}

// on_upstream_response expects UpstreamRecv — Send should close
TEST(type_guard, upstream_response_rejects_send) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    u32 cid = conn->id;
    conn->on_upstream_recv = &on_upstream_response<SmallLoop>;
    // Send goes to on_send slot (null) → ignored by dispatch.
    // Connection stays alive — wrong event types never reach callbacks.
    loop.dispatch(make_ev(cid, IoEventType::Send, 50));
    CHECK(loop.conns[cid].fd >= 0);
}

// on_proxy_response_sent expects Send — Recv should close
TEST(type_guard, proxy_response_sent_ignores_wrong_type) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    REQUIRE(conn != nullptr);
    conn->on_send = &on_proxy_response_sent<SmallLoop>;
    // UpstreamRecv goes to on_upstream_recv (null) → ignored.
    loop.dispatch(make_ev(conn->id, IoEventType::UpstreamRecv, 50));
    CHECK(conn->fd >= 0);
}

// === Timer tick overflow clamp ===

// Verify dispatch clamps large tick counts to TimerWheel::kSlots
TEST(timer_clamp, large_tick_count_clamped) {
    SmallLoop loop;
    loop.setup();
    loop.keepalive_timeout = 0;  // expire on first tick

    // Accept a connection
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;

    // Dispatch a Timeout with a huge tick count — should be clamped to kSlots,
    // not overflow i32 or loop billions of times
    loop.dispatch(make_ev(0, IoEventType::Timeout, 0x7FFFFFFF));

    // Connection should be expired (clamped 64 ticks > timeout 0)
    CHECK_EQ(loop.conns[cid].fd, -1);
}

// Verify dispatch handles tick count of 0 gracefully (coerces to 1)
TEST(timer_clamp, zero_tick_coerced_to_one) {
    SmallLoop loop;
    loop.setup();
    loop.keepalive_timeout = 1;
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;

    // Dispatch Timeout with result=0 — should still advance one tick
    loop.dispatch(make_ev(0, IoEventType::Timeout, 0));
    // After 1 tick, keepalive_timeout=1 conn is in slot but not yet expired
    CHECK_EQ(loop.conns[cid].fd, 42);
    // Second tick expires it
    loop.dispatch(make_ev(0, IoEventType::Timeout, 1));
    CHECK_EQ(loop.conns[cid].fd, -1);
}

// === Copilot round 4 regression tests ===

// io_uring init returns -errno (not -1) on failure.
// We can't easily make mmap fail, but verify the convention:
// successful MockBackend init returns success.
TEST(copilot4, init_returns_success) {
    SmallLoop loop;
    loop.setup();
    CHECK(loop.backend.init(0, -1).has_value());
}

// MmapArena init returns Expected on failure.
// Verify success returns has_value().
TEST(copilot4, arena_init_returns_success) {
    MmapArena a;
    CHECK(a.init(4096).has_value());
    a.destroy();
}

// MmapArena init with absurdly large size should fail gracefully.
// mmap of near-max u64 will fail → should return error.
TEST(copilot4, arena_init_huge_fails) {
    MmapArena a;
    auto rc = a.init(static_cast<u64>(-1));  // ~18 exabytes
    CHECK(!rc);
    // Should carry a real errno code
    CHECK(rc.error().code > 0);
}

// MmapArena alloc overflow protection
TEST(copilot4, arena_alloc_overflow_returns_null) {
    MmapArena a;
    REQUIRE(a.init(4096).has_value());
    // size close to u64 max → overflow in (size+7) alignment
    void* p = a.alloc(static_cast<u64>(-1));
    CHECK(p == nullptr);
    a.destroy();
}

