// === Idle-reuse dead-socket fallback (retry_reused_upstream) ===

// A reused upstream that died before any response retries on a fresh connect for
// an idempotent method: a new connect is submitted and upstream_reused is cleared
// (one-shot, so a fresh-connect failure isn't retried again).
TEST(upstream_reuse, fallback_retries_idempotent_method) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    RouteConfig cfg{};
    auto uid = cfg.add_upstream("api", 0x7F000001, 8080);
    REQUIRE(uid.has_value());
    c->request_config = &cfg;
    c->upstream_idx = static_cast<u16>(uid.value());
    c->upstream_backend_idx = 0;
    c->req_method = static_cast<u8>(LogHttpMethod::Get);  // idempotent
    c->upstream_reused = true;
    // The bodyless request must still be replayable from recv_buf (the retry
    // re-sends straight out of it).
    static const char get_req[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(get_req), sizeof(get_req) - 1);
    c->req_initial_send_len = sizeof(get_req) - 1;
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    loop.backend.clear_ops();

    CHECK(rut::retry_reused_upstream(&loop, *c));
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 1u);  // fresh connect submitted
    CHECK(!c->upstream_reused);                             // one-shot
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// A reused idempotent request whose body already began streaming upstream must NOT
// retry: recv_buf was reset + refilled with body chunks, so the original request is
// gone and a replay would send a truncated/garbage request. (Finding 1 regression —
// e.g. a PUT mid-upload after a dead pooled socket.)
TEST(upstream_reuse, fallback_refuses_streamed_body_upload) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    RouteConfig cfg{};
    auto uid = cfg.add_upstream("api", 0x7F000001, 8080);
    REQUIRE(uid.has_value());
    c->request_config = &cfg;
    c->upstream_idx = static_cast<u16>(uid.value());
    c->upstream_backend_idx = 0;
    c->req_method = static_cast<u8>(LogHttpMethod::Put);  // idempotent method...
    c->upstream_reused = true;
    // ...but a body chunk has already been streamed: recv_buf holds only that chunk,
    // not the headers/body, and req_body_streamed records the loss.
    c->req_body_streamed = true;
    c->req_body_mode = BodyMode::ContentLength;
    c->req_body_remaining = 0;  // counters can read "complete" yet upload isn't replayable
    static const char chunk[] = "trailing-body-bytes";
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(chunk), sizeof(chunk) - 1);
    c->req_initial_send_len = sizeof(chunk) - 1;
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    loop.backend.clear_ops();

    CHECK(!rut::retry_reused_upstream(&loop, *c));          // refused
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);  // no fresh connect
    CHECK(!c->upstream_reused);                             // still cleared (one-shot)
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// A bodyless DELETE (no buffered body) stays retryable — request_fully_resendable
// allows it since recv_buf still holds the complete request.
TEST(upstream_reuse, fallback_retries_bodyless_delete) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    RouteConfig cfg{};
    auto uid = cfg.add_upstream("api", 0x7F000001, 8080);
    REQUIRE(uid.has_value());
    c->request_config = &cfg;
    c->upstream_idx = static_cast<u16>(uid.value());
    c->upstream_backend_idx = 0;
    c->req_method = static_cast<u8>(LogHttpMethod::Delete);
    c->upstream_reused = true;
    c->req_body_mode = BodyMode::None;
    static const char del_req[] = "DELETE /x HTTP/1.1\r\nHost: x\r\n\r\n";
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(del_req), sizeof(del_req) - 1);
    c->req_initial_send_len = sizeof(del_req) - 1;
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    loop.backend.clear_ops();

    CHECK(rut::retry_reused_upstream(&loop, *c));
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 1u);
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// A non-idempotent reused request is NOT resent (the backend may have received it
// before the reset → double-execution risk); the caller falls through to 502.
TEST(upstream_reuse, fallback_skips_non_idempotent_method) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    RouteConfig cfg{};
    auto uid = cfg.add_upstream("api", 0x7F000001, 8080);
    REQUIRE(uid.has_value());
    c->request_config = &cfg;
    c->upstream_idx = static_cast<u16>(uid.value());
    c->upstream_backend_idx = 0;
    c->req_method = static_cast<u8>(LogHttpMethod::Post);  // NOT idempotent
    c->upstream_reused = true;
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    loop.backend.clear_ops();

    CHECK(!rut::retry_reused_upstream(&loop, *c));          // no retry
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);  // no fresh connect
    CHECK(!c->upstream_reused);                             // still cleared (one-shot)
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// A non-reused (freshly-connected) failure never triggers the fallback.
TEST(upstream_reuse, fallback_noop_when_not_reused) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->upstream_reused = false;
    loop.backend.clear_ops();
    CHECK(!rut::retry_reused_upstream(&loop, *c));
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
}

// Regression: a reused-socket send error must NOT retry when an early upstream
// response is already buffered (the backend replied while our send was in flight).
// on_upstream_request_sent serves the buffered response instead of reconnecting.
TEST(upstream_reuse, send_error_with_buffered_response_serves_not_retries) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->upstream_reused = true;
    c->req_method = static_cast<u8>(LogHttpMethod::Get);  // idempotent → retry IS eligible
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    // Backend already replied (early response buffered) before our send errored.
    static const char kResp[] = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nhi";
    c->upstream_recv_buf.reset();
    c->upstream_recv_buf.write(reinterpret_cast<const u8*>(kResp), sizeof(kResp) - 1);
    loop.backend.clear_ops();

    rut::on_upstream_request_sent<SmallLoop>(
        static_cast<void*>(&loop), *c, make_ev(c->id, IoEventType::UpstreamSend, -1));

    // The buffered response is served (no fresh connect / dropped response).
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
}

// Findings 1+2: when a request is forwarded to a REUSED pooled socket, the
// request-sent path snapshots the resendable request into send_buf and then
// RELEASES recv_buf unconditionally (so the just-sent request can't leak into the
// next request, and pipelined downstream bytes flow through pipeline_recover).
TEST(upstream_reuse, request_sent_reused_snapshots_into_send_buf) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    c->upstream_reused = true;
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_body_mode = BodyMode::None;
    static const char get_req[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    const u32 len = sizeof(get_req) - 1;
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(get_req), len);
    c->req_initial_send_len = len;
    c->upstream_recv_buf.reset();  // no early response buffered
    loop.backend.clear_ops();

    rut::on_upstream_request_sent<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamSend, static_cast<i32>(len)));

    CHECK_EQ(c->retry_req_send_len, len);  // snapshot length recorded
    CHECK_EQ(c->recv_buf.len(), 0u);       // recv_buf released for ALL conns
    CHECK_EQ(c->send_buf.len(), len);      // request bytes copied into send_buf
    CHECK(__builtin_memcmp(c->send_buf.data(), get_req, len) == 0);
    CHECK(rut::request_fully_resendable(*c));  // replayable from the snapshot
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// Regression: when GET1 and pipelined GET2 arrive in the same read, the reused-fd
// send-success path must keep a retry copy of GET1 while also stashing GET2.
TEST(upstream_reuse, request_sent_reused_snapshots_before_pipeline_stash) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    c->upstream_reused = true;
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_body_mode = BodyMode::None;
    static const char get1[] = "GET /one HTTP/1.1\r\nHost: x\r\n\r\n";
    static const char get2[] = "GET /two HTTP/1.1\r\nHost: x\r\n\r\n";
    const u32 len1 = sizeof(get1) - 1;
    const u32 len2 = sizeof(get2) - 1;
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(get1), len1);
    c->recv_buf.write(reinterpret_cast<const u8*>(get2), len2);
    c->req_initial_send_len = len1;
    c->upstream_recv_buf.reset();
    loop.backend.clear_ops();

    rut::on_upstream_request_sent<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamSend, static_cast<i32>(len1)));

    CHECK_EQ(c->retry_req_send_len, len1);
    CHECK_EQ(c->pipeline_stash_len, len2);
    CHECK_EQ(c->send_buf.len(), len1 + len2);
    CHECK(__builtin_memcmp(c->send_buf.data(), get1, len1) == 0);
    CHECK(__builtin_memcmp(c->send_buf.data() + len1, get2, len2) == 0);
    CHECK_EQ(c->recv_buf.len(), 0u);

    CHECK(rut::request_fully_resendable(*c));
    REQUIRE(rut::pipeline_recover(*c) == rut::PipelineTransitionResult::Advanced);
    CHECK_EQ(c->recv_buf.len(), len2);
    CHECK(__builtin_memcmp(c->recv_buf.data(), get2, len2) == 0);
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// Dynamic response mutations may borrow req.path/req.header slices from recv_buf.
// Even a fresh upstream must preserve those bytes before releasing recv_buf.
TEST(response_headers, request_backed_forward_mutation_survives_recv_reuse) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    c->upstream_reused = false;
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_body_mode = BodyMode::None;
    static const char request[] = "GET /path HTTP/1.1\r\nHost: x\r\n\r\n";
    const u32 len = sizeof(request) - 1;
    c->recv_buf.write(reinterpret_cast<const u8*>(request), len);
    c->req_initial_send_len = len;
    auto& mutation = c->resp_header_mutations[c->resp_header_mutation_count++];
    mutation.mode = ConnectionBase::RespHeaderMutationMode::Set;
    mutation.name = {"X-Path", 6};
    mutation.value = {reinterpret_cast<const char*>(c->recv_buf.data() + 4), 5};

    rut::on_upstream_request_sent<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamSend, static_cast<i32>(len)));

    REQUIRE_EQ(c->retry_req_send_len, len);
    REQUIRE_EQ(c->recv_buf.len(), 0u);
    CHECK(mutation.value.ptr == reinterpret_cast<const char*>(c->send_buf.data() + 4));
    CHECK((mutation.value.eq(Str{"/path", 5})));
    c->recv_buf.write(reinterpret_cast<const u8*>("overwritten"), 11);
    CHECK((mutation.value.eq(Str{"/path", 5})));
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// Regression: retry_req_send_len is also the offset to the stashed pipelined
// suffix. Receiving response bytes proves GET1 will not be retried, but the
// marker must survive until pipeline_recover copies GET2 from after GET1.
TEST(upstream_reuse, response_preserves_stash_offset_until_pipeline_recover) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    c->upstream_reused = true;
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_body_mode = BodyMode::None;
    static const char get1[] = "GET /one HTTP/1.1\r\nHost: x\r\n\r\n";
    static const char get2[] = "GET /two HTTP/1.1\r\nHost: x\r\n\r\n";
    const u32 len1 = sizeof(get1) - 1;
    const u32 len2 = sizeof(get2) - 1;
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(get1), len1);
    c->recv_buf.write(reinterpret_cast<const u8*>(get2), len2);
    c->req_initial_send_len = len1;
    c->upstream_recv_buf.reset();
    loop.backend.clear_ops();

    rut::on_upstream_request_sent<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamSend, static_cast<i32>(len1)));

    REQUIRE_EQ(c->retry_req_send_len, len1);
    REQUIRE_EQ(c->pipeline_stash_len, len2);
    REQUIRE_EQ(c->send_buf.len(), len1 + len2);

    static const char resp[] = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok";
    c->upstream_recv_buf.reset();
    c->upstream_recv_buf.write(reinterpret_cast<const u8*>(resp), sizeof(resp) - 1);
    rut::on_upstream_response<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamRecv, static_cast<i32>(sizeof(resp) - 1)));

    CHECK_EQ(c->retry_req_send_len, len1);
    REQUIRE(rut::pipeline_recover(*c) == rut::PipelineTransitionResult::Advanced);
    CHECK_EQ(c->retry_req_send_len, 0u);
    CHECK_EQ(c->recv_buf.len(), len2);
    CHECK(__builtin_memcmp(c->recv_buf.data(), get2, len2) == 0);
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// A fresh (non-reused) connection takes NO snapshot — there is nothing to retry —
// and recv_buf is still released at request-sent (unchanged original lifecycle).
TEST(upstream_reuse, request_sent_fresh_takes_no_snapshot) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    c->upstream_reused = false;  // fresh connect
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_body_mode = BodyMode::None;
    static const char get_req[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    const u32 len = sizeof(get_req) - 1;
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(get_req), len);
    c->req_initial_send_len = len;
    c->upstream_recv_buf.reset();
    loop.backend.clear_ops();

    rut::on_upstream_request_sent<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamSend, static_cast<i32>(len)));

    CHECK_EQ(c->retry_req_send_len, 0u);  // no snapshot for a fresh connect
    CHECK_EQ(c->recv_buf.len(), 0u);      // recv_buf released
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// Finding 1 (post-send dead socket): after recv_buf was reset at request-sent, the
// EOF-before-any-response path retries and on_upstream_connected replays the request
// from the send_buf snapshot (not recv_buf, which is now empty).
TEST(upstream_reuse, retry_replays_request_from_snapshot) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    RouteConfig cfg{};
    auto uid = cfg.add_upstream("api", 0x7F000001, 8080);
    REQUIRE(uid.has_value());
    c->request_config = &cfg;
    c->upstream_idx = static_cast<u16>(uid.value());
    c->upstream_backend_idx = 0;
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_body_mode = BodyMode::None;
    c->upstream_reused = true;
    // Post request-sent state: recv_buf empty, snapshot held in send_buf.
    static const char get_req[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    const u32 len = sizeof(get_req) - 1;
    c->recv_buf.reset();  // released at request-sent
    c->send_buf.reset();
    c->send_buf.write(reinterpret_cast<const u8*>(get_req), len);
    c->retry_req_send_len = len;
    c->upstream_recv_buf.reset();  // no response byte → EOF
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    loop.backend.clear_ops();

    CHECK(rut::request_fully_resendable(*c));  // replayable via the snapshot

    // EOF before any response → fresh connect submitted, reuse cleared (one-shot).
    rut::on_upstream_response<SmallLoop>(
        static_cast<void*>(&loop), *c, make_ev(c->id, IoEventType::UpstreamRecv, 0));
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 1u);
    CHECK(!c->upstream_reused);
    CHECK_EQ(c->retry_req_send_len, len);  // snapshot retained for the replay

    // Drive the fresh connect to completion: the request is re-sent from send_buf.
    loop.backend.clear_ops();
    rut::on_upstream_connected<SmallLoop>(
        static_cast<void*>(&loop), *c, make_ev(c->id, IoEventType::UpstreamConnect, 0));
    const MockOp* op = loop.backend.last_op(MockOp::Send);  // upstream send
    REQUIRE(op != nullptr);
    CHECK(op->send_buf == c->send_buf.data());  // replayed from the snapshot, not recv_buf
    CHECK_EQ(op->send_len, len);
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// The snapshot-based retry remains valid when the client pipelined another request
// into recv_buf during the upstream wait: replay comes from send_buf, while recv_buf
// is preserved for the next dispatch.
TEST(upstream_reuse, retry_allowed_when_pipelined_bytes_buffered) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_body_mode = BodyMode::None;
    static const char get_req[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    const u32 len = sizeof(get_req) - 1;
    c->send_buf.reset();
    c->send_buf.write(reinterpret_cast<const u8*>(get_req), len);
    c->retry_req_send_len = len;
    // A pipelined next request raced into recv_buf during the wait.
    static const char pipelined[] = "GET /next HTTP/1.1\r\n\r\n";
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(pipelined), sizeof(pipelined) - 1);

    CHECK(rut::request_fully_resendable(*c));  // replayable from the snapshot
}

// Before the initial reused-fd send completes, recv_buf can still contain the original
// request followed by pipelined bytes. The retry can replay only the request prefix;
// the normal successful-send path stashes the surplus for the next dispatch.
TEST(upstream_reuse, pre_send_retry_allows_pipelined_suffix) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->req_body_mode = BodyMode::None;
    static const char get_req[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    static const char pipelined[] = "GET /next HTTP/1.1\r\n\r\n";
    const u32 len = sizeof(get_req) - 1;
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(get_req), len);
    c->recv_buf.write(reinterpret_cast<const u8*>(pipelined), sizeof(pipelined) - 1);
    c->req_initial_send_len = len;
    c->retry_req_send_len = 0;

    CHECK(rut::request_fully_resendable(*c));
}

// Finding (F3): on the snapshot-retry path the request was replayed from send_buf, so
// recv_buf holds NO original request. If the client pipelines another request into
// recv_buf while the fresh connect/send is in flight, the retry's on_upstream_request_-
// sent must NOT run pipeline_stash (which would mis-slice at the ORIGINAL request's
// req_initial_send_len) nor reset recv_buf (which would drop those bytes). It must
// preserve recv_buf so the completion path dispatches it as the next request.
TEST(upstream_reuse, retry_preserves_pipelined_bytes) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_body_mode = BodyMode::None;
    // On the retry path: the original request lives in send_buf (replayed already),
    // and retry_req_send_len marks it. req_initial_send_len is the ORIGINAL length.
    static const char orig[] = "GET /orig HTTP/1.1\r\nHost: x\r\n\r\n";
    const u32 orig_len = sizeof(orig) - 1;
    c->send_buf.reset();
    c->send_buf.write(reinterpret_cast<const u8*>(orig), orig_len);
    c->retry_req_send_len = orig_len;
    c->req_initial_send_len = orig_len;
    c->pipeline_stash_len = 0;  // a snapshot is only taken with no pipelined surplus
    // The client pipelined a DIFFERENT-length next request during the in-flight retry;
    // it sits at offset 0 of recv_buf (a clean request boundary).
    static const char pipelined[] = "GET /next HTTP/1.1\r\nHost: x\r\nX: y\r\n\r\n";
    const u32 pl_len = sizeof(pipelined) - 1;
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(pipelined), pl_len);
    c->upstream_recv_buf.reset();  // no early response yet
    loop.backend.clear_ops();

    rut::on_upstream_request_sent<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamSend, static_cast<i32>(orig_len)));

    // recv_buf preserved byte-for-byte; nothing stashed (no mis-slice, no drop).
    CHECK_EQ(c->recv_buf.len(), pl_len);
    CHECK_EQ(c->pipeline_stash_len, 0);
    CHECK_EQ(__builtin_memcmp(c->recv_buf.data(), pipelined, pl_len), 0);
}

// Finding 3: a final body chunk send that FAILS on the early-response path
// (on_body_send_with_early_response, which otherwise ignores ev.result) must mark
// the upload incomplete so the desynced socket is never pooled.
TEST(upstream_reuse, early_response_failed_body_send_marks_incomplete) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->req_method = static_cast<u8>(LogHttpMethod::Post);
    // An early keep-alive response is buffered while the body upload was still going.
    static const char kResp[] =
        "HTTP/1.1 413 Payload Too Large\r\nContent-Length: 0\r\nConnection: keep-alive\r\n\r\n";
    c->upstream_recv_buf.reset();
    c->upstream_recv_buf.write(reinterpret_cast<const u8*>(kResp), sizeof(kResp) - 1);
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    loop.backend.clear_ops();
    CHECK(!c->upstream_request_incomplete);  // precondition

    rut::on_body_send_with_early_response<SmallLoop>(
        static_cast<void*>(&loop), *c, make_ev(c->id, IoEventType::UpstreamSend, -1));

    CHECK(c->upstream_request_incomplete);  // failed chunk send → not poolable
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// A buffered request-policy body must not select the strict response serializer
// merely because its body counters read complete. Both an early final response
// while the request send is still in flight and a failed request send fail closed
// with 502, release the slot marker, and close the upstream fd.
TEST(response_policy, buffered_request_requires_successful_upload) {
    SmallLoop loop;
    loop.setup();
    RouteConfig cfg{};
    ForwardResponsePolicySpec policy{};
    static constexpr char kServer[] = "nginx/1.29.7";
    policy.version = ResponsePolicyVersion::Http11;
    policy.framing = ResponsePolicyFraming::ContentLength;
    policy.connection = ResponsePolicyConnection::KeepAlive;
    policy.date = ResponsePolicyDate::Current;
    policy.server = {kServer, sizeof(kServer) - 1};
    REQUIRE_EQ(cfg.add_response_policy(policy), 1u);

    auto prepare = [&](Connection* c, bool zero_content_length = false) {
        REQUIRE(c != nullptr);
        REQUIRE(loop.alloc_upstream_buf(*c));
        c->request_config = &cfg;
        c->response_policy_id = 1;
        c->request_policy_id = 1;
        c->request_body_fully_buffered = true;
        c->request_policy_body_pending = false;
        c->req_body_mode = zero_content_length ? BodyMode::None : BodyMode::ContentLength;
        c->req_body_remaining = 0;
        c->req_body_streamed = false;
        c->req_http_version = static_cast<u8>(HttpVersion::Http11);
        c->req_method = static_cast<u8>(LogHttpMethod::Post);
        c->req_keep_alive = true;
        c->req_path_canon = {"api", 3};
        // Mirror proxy dispatch: both callbacks below are failure exits after
        // the upstream concurrency slot has already been acquired.
        c->upstream_slot_held = true;
        c->upstream_slot_uid = 1;
        static constexpr char kRequest[] =
            "POST /api HTTP/1.1\r\nHost: x\r\nContent-Length: 1\r\n\r\nX";
        static constexpr char kRequestZero[] =
            "POST /api HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\n\r\n";
        const char* request = zero_content_length ? kRequestZero : kRequest;
        const u32 request_len = zero_content_length ? static_cast<u32>(sizeof(kRequestZero) - 1)
                                                    : static_cast<u32>(sizeof(kRequest) - 1);
        REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(request), request_len),
                   request_len);
        c->req_initial_send_len = c->recv_buf.len();
        c->upstream_fd = dup(2);
        REQUIRE(c->upstream_fd >= 0);
        REQUIRE(loop.alloc_response_header_buf(*c));
        static constexpr char kResponse[] = "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n";
        REQUIRE_EQ(c->upstream_recv_buf.write(reinterpret_cast<const u8*>(kResponse),
                                              sizeof(kResponse) - 1),
                   sizeof(kResponse) - 1);
    };

    auto* early = loop.alloc_conn();
    prepare(early);
    on_body_send_with_early_response<SmallLoop>(
        static_cast<void*>(&loop), *early, make_ev(early->id, IoEventType::UpstreamSend, 1));
    CHECK_EQ(early->resp_status, kStatusBadGateway);
    CHECK_EQ(early->upstream_fd, -1);
    CHECK(!early->upstream_slot_held);

    auto* failed = loop.alloc_conn();
    prepare(failed);
    on_upstream_request_sent<SmallLoop>(
        static_cast<void*>(&loop), *failed, make_ev(failed->id, IoEventType::UpstreamSend, -EPIPE));
    CHECK_EQ(failed->resp_status, kStatusBadGateway);
    CHECK(failed->upstream_request_incomplete);
    CHECK_EQ(failed->upstream_fd, -1);
    CHECK(!failed->upstream_slot_held);

    // If the response CQE was delivered before the terminal full-send CQE,
    // the positive completion still proves the complete buffered request was
    // uploaded. The old callback left request_upload_complete false here and
    // incorrectly rejected the otherwise valid strict response. Cover both a
    // nonzero fixed body and explicit Content-Length: 0 (BodyMode::None).
    auto complete_success = [&](bool zero_content_length) {
        auto* complete = loop.alloc_conn();
        prepare(complete, zero_content_length);
        const u32 full_send_len = complete->req_initial_send_len;
        on_body_send_with_early_response<SmallLoop>(
            static_cast<void*>(&loop),
            *complete,
            make_ev(complete->id, IoEventType::UpstreamSend, static_cast<i32>(full_send_len)));
        CHECK_EQ(complete->resp_status, 200u);
        CHECK(complete->request_upload_complete);
        CHECK(!complete->upstream_request_incomplete);
        CHECK(buf_has(complete->response_header_buf.data(),
                      complete->response_header_buf.len(),
                      "HTTP/1.1 200 OK"));
        on_proxy_response_sent<SmallLoop>(
            static_cast<void*>(&loop),
            *complete,
            make_ev(complete->id,
                    IoEventType::Send,
                    static_cast<i32>(complete->response_header_buf.len())));
        CHECK(!complete->upstream_slot_held);
        CHECK_EQ(complete->upstream_fd, -1);
        loop.close_conn(*complete);
    };
    complete_success(false);
    complete_success(true);
}

// Finding 4: a stale same-batch UpstreamSend dispatched into the on_upstream_connected
// slot (after a retry swapped the slot) must be ignored — it is the old fd's send
// completion, not a connect result. on_upstream_connected only ever handles connect
// events, so any UpstreamSend reaching it is dropped (no premature request send on
// the not-yet-connected fresh fd, no teardown).
TEST(upstream_reuse, stale_upstream_send_ignored_in_connected_slot) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = dup(2);
    REQUIRE(c->fd >= 0);
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    loop.backend.clear_ops();

    // A positive byte count would otherwise look like a successful connect result.
    rut::on_upstream_connected<SmallLoop>(
        static_cast<void*>(&loop), *c, make_ev(c->id, IoEventType::UpstreamSend, 128));

    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);     // no request send issued
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);  // no reconnect issued
    CHECK(c->fd >= 0);                                      // connection untouched
    if (c->fd >= 0) close(c->fd);
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// proxy_upstream_reusable: a clean keep-alive, fully-uploaded request on the
// current config is poolable.
TEST(upstream_reuse, reusable_true_for_clean_keepalive) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    RouteConfig cfg{};
    const RouteConfig* active = &cfg;
    loop.config_ptr = &active;
    c->request_config = &cfg;
    c->upstream_keep_alive = true;
    c->upstream_abandoned = false;
    c->req_body_mode = BodyMode::None;
    c->req_body_remaining = 0;
    CHECK(rut::proxy_upstream_reusable(&loop, *c));
}

// A request that ran on a now-replaced config must not be pooled (hot reload may
// have repointed the (upstream_idx, backend_idx) endpoint to a different backend).
TEST(upstream_reuse, reusable_rejects_stale_config) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    RouteConfig cur{};
    RouteConfig old{};
    const RouteConfig* active = &cur;
    loop.config_ptr = &active;
    c->request_config = &old;  // ran on a since-swapped config
    c->upstream_keep_alive = true;
    c->req_body_mode = BodyMode::None;
    CHECK(!rut::proxy_upstream_reusable(&loop, *c));
}

// An incomplete request upload (early upstream response cut the body short) leaves
// the backend mid-read → not poolable.
TEST(upstream_reuse, reusable_rejects_incomplete_upload) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    RouteConfig cfg{};
    const RouteConfig* active = &cfg;
    loop.config_ptr = &active;
    c->request_config = &cfg;
    c->upstream_keep_alive = true;
    c->req_body_mode = BodyMode::ContentLength;
    c->req_body_remaining = 10;  // body not fully forwarded
    CHECK(!rut::proxy_upstream_reusable(&loop, *c));
}

// Finding 3: a body send that FAILED leaves the upload truncated even though the
// body counters (advanced before the send) read "complete". upstream_request_incomplete
// is the authoritative signal, so proxy_upstream_reusable must refuse to pool —
// otherwise the next request on the socket would be parsed as the leftover body.
TEST(upstream_reuse, reusable_rejects_failed_body_send) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    RouteConfig cfg{};
    const RouteConfig* active = &cfg;
    loop.config_ptr = &active;
    c->request_config = &cfg;
    c->upstream_keep_alive = true;
    c->upstream_abandoned = false;
    // Counters look complete (advanced before the failed submit_send_upstream)...
    c->req_body_mode = BodyMode::ContentLength;
    c->req_body_remaining = 0;
    CHECK(rut::proxy_upstream_reusable(&loop, *c));  // sanity: complete counters alone pool
    // ...but the send actually failed, so the upload never landed.
    c->upstream_request_incomplete = true;
    CHECK(!rut::proxy_upstream_reusable(&loop, *c));
}

// An upgrade (WebSocket) request is a GET but must never be replayed on a reused-
// socket failure — replaying could open a duplicate backend session.
TEST(upstream_reuse, fallback_skips_upgrade_request) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    RouteConfig cfg{};
    auto uid = cfg.add_upstream("api", 0x7F000001, 8080);
    REQUIRE(uid.has_value());
    c->request_config = &cfg;
    c->upstream_idx = static_cast<u16>(uid.value());
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_wants_upgrade = true;  // WebSocket/Upgrade GET
    c->upstream_reused = true;
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    loop.backend.clear_ops();
    CHECK(!rut::retry_reused_upstream(&loop, *c));
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    if (c->upstream_fd >= 0) close(c->upstream_fd);
}

// An upstream that sends bytes beyond its declared Content-Length is desynced —
// on_upstream_response must clear upstream_keep_alive so the fd isn't pooled.
TEST(upstream_reuse, overlong_response_not_reusable) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    // Declares Content-Length: 2 but the buffer carries 3 body bytes ("hiX").
    static const char kResp[] =
        "HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: keep-alive\r\n\r\nhiX";
    c->upstream_recv_buf.reset();
    c->upstream_recv_buf.write(reinterpret_cast<const u8*>(kResp), sizeof(kResp) - 1);
    rut::on_upstream_response<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamRecv, static_cast<i32>(sizeof(kResp) - 1)));
    CHECK(!c->upstream_keep_alive);  // overlong body → not reusable
}

// A no-body response (204/304/HEAD) with any bytes after the headers means a
// desynced keep-alive backend — not reusable.
TEST(upstream_reuse, no_body_response_with_surplus_not_reusable) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    // 204 No Content carries no body, but the backend appended a stray byte.
    static const char kResp[] = "HTTP/1.1 204 No Content\r\nConnection: keep-alive\r\n\r\nX";
    c->upstream_recv_buf.reset();
    c->upstream_recv_buf.write(reinterpret_cast<const u8*>(kResp), sizeof(kResp) - 1);
    rut::on_upstream_response<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamRecv, static_cast<i32>(sizeof(kResp) - 1)));
    CHECK(!c->upstream_keep_alive);  // surplus after no-body headers → not reusable
}

// A clean, self-framed keep-alive response to a keep-alive request marks the
// upstream fd reusable (upstream_keep_alive = true → it gets pooled).
TEST(upstream_reuse, keepalive_request_pools_clean_response) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    // The forwarded request asked the origin to keep the connection alive.
    c->req_keep_alive = true;
    static const char kResp[] =
        "HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: keep-alive\r\n\r\nhi";
    c->upstream_recv_buf.reset();
    c->upstream_recv_buf.write(reinterpret_cast<const u8*>(kResp), sizeof(kResp) - 1);
    rut::on_upstream_response<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamRecv, static_cast<i32>(sizeof(kResp) - 1)));
    CHECK(c->upstream_keep_alive);  // request + response both keep-alive → reusable
}

// Finding (F1) regression: a request that carried Connection: close (req_keep_alive
// false) forwards that close intent to the origin verbatim, so even a self-framed
// HTTP/1.1 keep-alive RESPONSE must NOT be pooled — the origin may close right after.
// Gating on the parsed-request keep-alive (not conn.keep_alive, which is drain-derived)
// is what catches this on a live (non-draining) shard.
TEST(upstream_reuse, connection_close_request_not_pooled) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    REQUIRE(loop.alloc_upstream_buf(*c));
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    // Live shard: conn.keep_alive stays true (it tracks drain state, not the request).
    c->keep_alive = true;
    // ...but the client's request carried Connection: close, forwarded to the origin.
    c->req_keep_alive = false;
    // The response itself is a perfectly self-framed keep-alive reply.
    static const char kResp[] =
        "HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: keep-alive\r\n\r\nhi";
    c->upstream_recv_buf.reset();
    c->upstream_recv_buf.write(reinterpret_cast<const u8*>(kResp), sizeof(kResp) - 1);
    rut::on_upstream_response<SmallLoop>(
        static_cast<void*>(&loop),
        *c,
        make_ev(c->id, IoEventType::UpstreamRecv, static_cast<i32>(sizeof(kResp) - 1)));
    CHECK(!c->upstream_keep_alive);  // request asked origin to close → never pooled
}

// capture_request_metadata records the parsed request's keep-alive intent on the
// Connection so the upstream-pool gate reads it (not the drain-derived conn.keep_alive).
TEST(upstream_reuse, capture_records_request_keep_alive) {
    SmallLoop loop;
    loop.setup();
    auto* c = loop.alloc_conn();
    REQUIRE(c != nullptr);

    // HTTP/1.1 with no Connection header → keep-alive request.
    static const char ka[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(ka), sizeof(ka) - 1);
    rut::capture_request_metadata(*c);
    CHECK(c->req_keep_alive);

    // HTTP/1.1 with Connection: close → not keep-alive.
    static const char close_req[] = "GET / HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(close_req), sizeof(close_req) - 1);
    rut::capture_request_metadata(*c);
    CHECK(!c->req_keep_alive);

    // HTTP/1.0 default is close.
    static const char http10[] = "GET / HTTP/1.0\r\nHost: x\r\n\r\n";
    c->recv_buf.reset();
    c->recv_buf.write(reinterpret_cast<const u8*>(http10), sizeof(http10) - 1);
    rut::capture_request_metadata(*c);
    CHECK(!c->req_keep_alive);
}

// === RouteTable validation ===

TEST(route, add_proxy_invalid_upstream_id) {
    RouteConfig cfg;
    // No upstreams added — upstream_id 0 is invalid
    CHECK(!cfg.add_proxy("/api/", 0, 0));
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_proxy_path_too_long) {
    RouteConfig cfg;
    (void)cfg.add_upstream("x", 0x7F000001, 80);
    char long_path[256];
    for (u32 i = 0; i < 255; i++) long_path[i] = 'a';
    long_path[255] = '\0';
    CHECK(!cfg.add_proxy(long_path, 0, 0));  // exceeds 128-char RouteEntry::path
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_static_path_too_long) {
    RouteConfig cfg;
    char long_path[256];
    for (u32 i = 0; i < 255; i++) long_path[i] = 'b';
    long_path[255] = '\0';
    CHECK(!cfg.add_static(long_path, 0, 200));
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_upstream_at_capacity) {
    RouteConfig cfg;
    for (u32 i = 0; i < RouteConfig::kMaxUpstreams; i++) {
        CHECK(cfg.add_upstream("x", 0x7F000001, static_cast<u16>(8080 + i)).has_value());
    }
    CHECK(!cfg.add_upstream("overflow", 0x7F000001, 9999).has_value());  // full
}

// ============================================================================
// is_routable_path rejection — PR-A added a uniform path-validation gate
// to add_*. These tests pin the rejected shapes so a regression doesn't
// silently relax the contract.
// ============================================================================

TEST(route, add_rejects_null_path) {
    RouteConfig cfg;
    CHECK(!cfg.add_static(nullptr, 0, 200));
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_rejects_empty_path) {
    RouteConfig cfg;
    CHECK(!cfg.add_static("", 0, 200));
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_rejects_path_without_leading_slash) {
    RouteConfig cfg;
    CHECK(!cfg.add_static("api", 0, 200));
    CHECK(!cfg.add_static("api/v1", 0, 200));
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_rejects_path_with_query) {
    // '?' belongs to the query component of a URI; matching is on path
    // only. Routing on a path with '?' would be surprising — at match
    // time the segment trie strips it from the request, so the route
    // would be effectively unmatchable.
    RouteConfig cfg;
    (void)cfg.add_upstream("u", 0x7F000001, 80);
    CHECK(!cfg.add_static("/api?foo=1", 0, 200));
    CHECK(!cfg.add_proxy("/api?x", 0, 0));
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_rejects_path_with_fragment) {
    RouteConfig cfg;
    CHECK(!cfg.add_static("/api#frag", 0, 200));
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_accepts_well_formed_path_after_rejection) {
    // A previous rejected add_* must not poison route_count or leave
    // partial state — a follow-up valid add_* should succeed.
    RouteConfig cfg;
    CHECK(!cfg.add_static("api", 0, 200));    // missing leading '/'
    CHECK(!cfg.add_static("/x?y", 0, 200));   // has '?'
    CHECK(!cfg.add_static(nullptr, 0, 200));  // null
    CHECK_EQ(cfg.route_count, 0u);
    CHECK(cfg.add_static("/api", 0, 200));  // valid
    CHECK_EQ(cfg.route_count, 1u);
}

static u64 route_table_dummy_handler(void*, jit::HandlerCtx*, const u8*, u32, void*) {
    return jit::HandlerResult::make_status(204).pack();
}

TEST(route, default_dispatch_kind_is_art_jit) {
    // Phase 2 default: ArtJit. Until install_art_jit_fn is called,
    // match() falls back to scalar ArtTrie::match — slower but
    // correct. SegmentTrie is opt-in via use_segment_trie().
    RouteConfig cfg;
    CHECK_EQ(cfg.dispatch_kind(), RouteConfig::DispatchKind::ArtJit);
}

TEST(route, use_segment_trie_swaps_dispatch_pre_add) {
    RouteConfig cfg;
    CHECK(cfg.use_segment_trie());
    CHECK_EQ(cfg.dispatch_kind(), RouteConfig::DispatchKind::SegmentTrie);
    CHECK(cfg.use_art());
    CHECK_EQ(cfg.dispatch_kind(), RouteConfig::DispatchKind::ArtJit);
}

TEST(route, add_refuses_param_path_under_art_dispatch) {
    // ArtJit is byte-prefix based and cannot interpret ":param" segments.
    // Dynamic route paths must use SegmentTrie so request segments are
    // compared one segment at a time.
    RouteConfig cfg;
    CHECK(!cfg.add_static("/users/:id", 0, 200));
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_methods_reject_invalid_method_keys) {
    RouteConfig cfg;
    REQUIRE(cfg.add_upstream("api", 0x7F000001, 8080).has_value());
    CHECK(!cfg.add_static("/static", 0xff, 200));
    CHECK(!cfg.add_proxy("/proxy", 0xff, 0));
    CHECK(!cfg.add_jit_handler("/jit", 0xff, &route_table_dummy_handler));
    CHECK_EQ(cfg.route_count, 0u);
}

TEST(route, add_jit_handler_rejects_null_and_records_body_dependency) {
    RouteConfig cfg;
    CHECK(!cfg.add_jit_handler("/upload", 0, nullptr));
    REQUIRE(cfg.add_jit_handler("/upload", 'P', &route_table_dummy_handler, true));
    REQUIRE_EQ(cfg.route_count, 1u);
    CHECK_EQ(cfg.routes[0].action, RouteAction::JitHandler);
    CHECK_EQ(cfg.routes[0].method, route_method_key_from_legacy_char('P'));
    CHECK(cfg.routes[0].needs_req_body);
    CHECK_EQ(cfg.routes[0].fn, &route_table_dummy_handler);
}

TEST(route, configure_route_dispatch_selects_segment_trie_for_param_route) {
    rir::Function funcs[1]{};
    funcs[0].route_pattern = Str{"/users/:id", 10};
    rir::Module mod{};
    mod.functions = funcs;
    mod.func_count = 1;

    RouteConfig cfg;
    CHECK(configure_route_dispatch(cfg, mod));
    CHECK_EQ(cfg.dispatch_kind(), RouteConfig::DispatchKind::SegmentTrie);
    CHECK(cfg.add_static("/users/:id", 0, 200));
}

TEST(route, configure_route_dispatch_selects_segment_trie_for_boundary_overlap) {
    rir::Function funcs[2]{};
    funcs[0].route_pattern = Str{"/api", 4};
    funcs[1].route_pattern = Str{"/apix", 5};
    rir::Module mod{};
    mod.functions = funcs;
    mod.func_count = 2;

    RouteConfig cfg;
    CHECK(configure_route_dispatch(cfg, mod));
    CHECK_EQ(cfg.dispatch_kind(), RouteConfig::DispatchKind::SegmentTrie);
}

TEST(route, configure_route_dispatch_refuses_after_route_add) {
    rir::Function funcs[1]{};
    funcs[0].route_pattern = Str{"/users/:id", 10};
    rir::Module mod{};
    mod.functions = funcs;
    mod.func_count = 1;

    RouteConfig cfg;
    REQUIRE(cfg.add_static("/health", 0, 200));
    CHECK(!configure_route_dispatch(cfg, mod));
    CHECK_EQ(cfg.dispatch_kind(), RouteConfig::DispatchKind::ArtJit);
}

TEST(route, configure_route_dispatch_rejects_malformed_modules) {
    RouteConfig cfg;
    rir::Module too_many{};
    too_many.func_count = RouteConfig::kMaxRoutes + 1;
    CHECK(!configure_route_dispatch(cfg, too_many));

    rir::Module missing_funcs{};
    missing_funcs.func_count = 1;
    missing_funcs.functions = nullptr;
    CHECK(!configure_route_dispatch(cfg, missing_funcs));

    rir::Function funcs[1]{};
    funcs[0].route_pattern = Str{nullptr, 1};
    rir::Module null_pattern{};
    null_pattern.functions = funcs;
    null_pattern.func_count = 1;
    CHECK(!configure_route_dispatch(cfg, null_pattern));
}

TEST(route, rir_function_needs_req_body_guard_paths) {
    rir::Function fn{};
    CHECK(!rir_function_needs_req_body(fn));

    rir::Block blocks[2]{};
    fn.blocks = blocks;
    fn.block_count = 2;
    blocks[0].insts = nullptr;
    blocks[0].inst_count = 1;

    rir::Instruction insts[1]{};
    blocks[1].insts = insts;
    blocks[1].inst_count = 1;
    insts[0].op = rir::Opcode::ReqHeader;
    CHECK(!rir_function_needs_req_body(fn));

    insts[0].op = rir::Opcode::ReqBody;
    CHECK(rir_function_needs_req_body(fn));
}

TEST(route, populate_route_config_rejects_malformed_runtime_tables) {
    RouteConfig cfg;

    rir::Module too_many_upstreams{};
    too_many_upstreams.upstream_count = rir::Module::kMaxUpstreams + 1;
    CHECK(!populate_route_config(cfg, too_many_upstreams));

    rir::Module too_many_bodies{};
    too_many_bodies.response_body_count = rir::Module::kMaxResponseBodies + 1;
    CHECK(!populate_route_config(cfg, too_many_bodies));

    rir::Module too_many_header_sets{};
    too_many_header_sets.header_set_count = rir::Module::kMaxHeaderSets + 1;
    CHECK(!populate_route_config(cfg, too_many_header_sets));

    rir::Module too_many_header_entries{};
    too_many_header_entries.header_pool_used = rir::Module::kMaxHeaderPoolEntries + 1;
    CHECK(!populate_route_config(cfg, too_many_header_entries));

    rir::Module bad_header_ref{};
    bad_header_ref.header_set_count = 1;
    bad_header_ref.header_pool_used = 1;
    bad_header_ref.header_sets[0] = {1, 1};
    CHECK(!populate_route_config(cfg, bad_header_ref));

    rir::Module oversized_header_set{};
    oversized_header_set.header_set_count = 1;
    oversized_header_set.header_pool_used = RouteConfig::kMaxHeadersPerSet + 1;
    oversized_header_set.header_sets[0] = {0, RouteConfig::kMaxHeadersPerSet + 1};
    CHECK(!populate_route_config(cfg, oversized_header_set));
}

TEST(route, segment_trie_matches_param_path) {
    RouteConfig cfg;
    REQUIRE(cfg.use_segment_trie());
    CHECK(cfg.add_static("/users/:id", 0, 201));
    CHECK(cfg.add_static("/users/me", 0, 202));
    auto* dynamic = cfg.match(reinterpret_cast<const u8*>("/users/42"), 9, 0);
    REQUIRE(dynamic != nullptr);
    CHECK_EQ(dynamic->status_code, 201u);
    auto* literal = cfg.match(reinterpret_cast<const u8*>("/users/me"), 9, 0);
    REQUIRE(literal != nullptr);
    CHECK_EQ(literal->status_code, 202u);

    RouteParam params[kMaxRouteParams]{};
    u32 param_count = 0;
    auto* captured =
        cfg.match_canonical(Str{"users/42", 8}, 0, params, &param_count, kMaxRouteParams);
    REQUIRE(captured != nullptr);
    CHECK_EQ(captured->status_code, 201u);
    REQUIRE_EQ(param_count, 1u);
    CHECK((Str{params[0].name, params[0].name_len}.eq(Str{"id", 2})));
    CHECK((Str{params[0].value, params[0].value_len}.eq(Str{"42", 2})));
}

TEST(route, use_dispatch_refuses_after_first_add) {
    // Same contract as the retired set_dispatch: once a route is
    // added, the chosen state struct has been populated; swapping
    // would leave the new state empty and silently mismatch.
    RouteConfig cfg;
    REQUIRE(cfg.use_segment_trie());
    REQUIRE(cfg.add_static("/a", 0, 200));
    CHECK(!cfg.use_art());           // post-add_* refused
    CHECK(!cfg.use_segment_trie());  // also refused (no-op swap)
    CHECK_EQ(cfg.dispatch_kind(), RouteConfig::DispatchKind::SegmentTrie);
}

TEST(route, art_jit_default_falls_back_to_scalar_when_no_install) {
    // ArtJit kind without install_art_jit_fn means art_jit_fn_ is
    // null; match() must transparently fall back to scalar ART
    // descent. Verifies the default config can route correctly
    // without the JIT pipeline being wired up.
    RouteConfig cfg;
    REQUIRE(cfg.add_static("/api/v1/users", 0, 200));
    REQUIRE(cfg.add_static("/admin", 0, 200));
    const RouteEntry* r1 = cfg.match(reinterpret_cast<const u8*>("/api/v1/users"), 13, 0);
    REQUIRE(r1 != nullptr);
    CHECK_EQ(r1->status_code, 200u);
    const RouteEntry* r2 = cfg.match(reinterpret_cast<const u8*>("/admin"), 6, 0);
    REQUIRE(r2 != nullptr);
    CHECK_EQ(r2->status_code, 200u);
}

TEST(route, add_response_body_basic) {
    RouteConfig cfg;
    const u16 idx = cfg.add_response_body("Hello", 5);
    REQUIRE_EQ(idx, 1u);
    REQUIRE_EQ(cfg.response_body_count, 1u);
    CHECK_EQ(cfg.response_bodies[0].len, 5u);
    CHECK_EQ(cfg.response_bodies[0].data[0], 'H');
    CHECK_EQ(cfg.response_bodies[0].data[4], 'o');
    // Second body gets a distinct index.
    const u16 idx2 = cfg.add_response_body("World", 5);
    CHECK_EQ(idx2, 2u);
}

TEST(route, add_response_body_rejects_overflowing_len) {
    // Subtraction-based capacity check: `body_pool_used + len` would
    // wrap when len is near u32 max. The guarded code rejects the
    // request cleanly rather than writing out of bounds.
    RouteConfig cfg;
    // Body table + pool start empty. Try a len that would overflow
    // kResponseBodyPoolBytes - body_pool_used = kResponseBodyPoolBytes.
    CHECK_EQ(cfg.add_response_body("x", 0xFFFFFFFFu), 0u);
    // After a small successful add, a len near u32 max still overflows.
    const u16 ok = cfg.add_response_body("Hi", 2);
    REQUIRE_EQ(ok, 1u);
    CHECK_EQ(cfg.add_response_body("x", 0xFFFFFFFEu), 0u);
    // Null data with non-zero len is also rejected.
    CHECK_EQ(cfg.add_response_body(nullptr, 1), 0u);
    // Null data with zero len is a valid (empty) body.
    CHECK_EQ(cfg.add_response_body(nullptr, 0), 2u);
}

TEST(route, add_response_body_rejects_at_capacity) {
    RouteConfig cfg;
    for (u32 i = 0; i < RouteConfig::kMaxResponseBodies; i++) {
        CHECK_EQ(cfg.add_response_body("", 0), static_cast<u16>(i + 1));
    }
    CHECK_EQ(cfg.add_response_body("x", 1), 0u);  // table full
}

TEST(route, add_route_at_capacity) {
    RouteConfig cfg;
    (void)cfg.add_upstream("x", 0x7F000001, 80);
    for (u32 i = 0; i < RouteConfig::kMaxRoutes; i++) {
        char path[8];
        path[0] = '/';
        path[1] = static_cast<char>('0' + (i / 100) % 10);
        path[2] = static_cast<char>('0' + (i / 10) % 10);
        path[3] = static_cast<char>('0' + i % 10);
        path[4] = '\0';
        CHECK(cfg.add_proxy(path, 0, 0));
    }
    CHECK(!cfg.add_proxy("/overflow", 0, 0));  // full
}

// === Error source ===

TEST(error, from_errno_captures_source) {
    errno = ENOMEM;
    Error e = Error::from_errno(Error::Source::Mmap);
    CHECK_EQ(e.code, ENOMEM);
    CHECK_EQ(static_cast<u8>(e.source), static_cast<u8>(Error::Source::Mmap));
}

TEST(error, make_with_code) {
    Error e = Error::make(EINVAL, Error::Source::Socket);
    CHECK_EQ(e.code, EINVAL);
    CHECK_EQ(static_cast<u8>(e.source), static_cast<u8>(Error::Source::Socket));
}

// === SlicePool integration ===

TEST(slice_conn, alloc_binds_slices) {
    SmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    CHECK(c->recv_slice != nullptr);
    CHECK(c->send_slice != nullptr);
    CHECK(c->recv_buf.valid());
    CHECK(c->send_buf.valid());
    CHECK_EQ(c->recv_buf.write_avail(), SmallLoop::kBufSize);
    CHECK_EQ(c->send_buf.write_avail(), SmallLoop::kBufSize);
    loop.free_conn(*c);
}

TEST(slice_conn, free_clears_slices) {
    SmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    loop.free_conn(*c);
    // Sync backend: slices freed immediately, pointers cleared by reset.
    CHECK_EQ(loop.conns[cid].recv_slice, nullptr);
    CHECK_EQ(loop.conns[cid].send_slice, nullptr);
    CHECK_EQ(loop.conns[cid].recv_buf.write_avail(), 0u);
    CHECK_EQ(loop.conns[cid].send_buf.write_avail(), 0u);
}

TEST(slice_conn, slice_reuse_after_free) {
    SmallLoop loop;
    loop.setup();
    Connection* c1 = loop.alloc_conn();
    REQUIRE(c1 != nullptr);
    u8* r1 = c1->recv_slice;
    u8* s1 = c1->send_slice;
    // Write data then free
    c1->recv_buf.write(reinterpret_cast<const u8*>("hello"), 5);
    loop.free_conn(*c1);

    // Re-alloc should get same slot back (LIFO) with inline storage
    Connection* c2 = loop.alloc_conn();
    REQUIRE(c2 != nullptr);
    // SmallLoop uses per-slot inline arrays; same slot ⇒ same storage.
    CHECK(c2->recv_slice == r1);
    CHECK(c2->send_slice == s1);
    // Buffer should be fresh (reset by bind)
    CHECK_EQ(c2->recv_buf.len(), 0u);
    loop.free_conn(*c2);
}

TEST(slice_conn, pool_exhaustion_returns_null) {
    SmallLoop loop;
    loop.setup();
    Connection* conns[SmallLoop::kMaxConns];
    u32 alloc_count = 0;
    // Allocate all connections
    for (u32 i = 0; i < SmallLoop::kMaxConns; i++) {
        conns[i] = loop.alloc_conn();
        if (conns[i]) alloc_count++;
    }
    CHECK_EQ(alloc_count, SmallLoop::kMaxConns);
    // Next alloc should fail
    CHECK(loop.alloc_conn() == nullptr);
    // Free one and retry
    loop.free_conn(*conns[0]);
    Connection* c = loop.alloc_conn();
    CHECK(c != nullptr);
    CHECK(c->recv_buf.valid());
    // Cleanup
    loop.free_conn(*c);
    for (u32 i = 1; i < alloc_count; i++) loop.free_conn(*conns[i]);
}

TEST(slice_conn, buffers_usable_through_request_cycle) {
    SmallLoop loop;
    loop.setup();
    // Accept → recv → build response → send → free
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    CHECK(c->recv_buf.valid());
    CHECK(c->send_buf.valid());

    // A valid request fills recv_buf and qualifies the local response for reuse.
    static constexpr char kRequest[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.dispatch(make_ev(c->id, IoEventType::Recv, sizeof(kRequest) - 1));
    CHECK(c->recv_buf.len() > 0);
    CHECK(c->send_buf.len() > 0);  // response built by on_header_received

    // Send completes
    u32 send_len = c->send_buf.len();
    loop.inject_and_dispatch(make_ev(c->id, IoEventType::Send, static_cast<i32>(send_len)));
    // Keep-alive: buffers reset for next request
    CHECK_EQ(c->recv_buf.len(), 0u);
    CHECK(c->recv_buf.valid());
}

TEST(slice_conn, real_eventloop_pool_init) {
    // Verify real EventLoop allocates pool with 3*kMaxConns slices.
    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto rc = loop->init(0, -1);
    REQUIRE(rc.has_value());

    // Lazy commit: pool starts empty, max set to 5 * kMaxConns (recv + send + upstream +
    // the two WebSocket terminate-mode reassembly slices).
    CHECK_EQ(loop->pool.max_count, RealLoop::kMaxConns * 6);
    CHECK_EQ(loop->pool.count, 0u);

    // Alloc a connection — triggers lazy grow, consumes 2 slices
    Connection* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    CHECK_GT(loop->pool.count, 0u);  // grew from 0
    CHECK_EQ(c->recv_buf.write_avail(), SlicePool::kSliceSize);
    CHECK_EQ(c->send_buf.write_avail(), SlicePool::kSliceSize);

    // Sync backend (epoll): slices returned to pool immediately on free.
    u32 avail_before = loop->pool.available();
    loop->free_conn(*c);
    CHECK_EQ(loop->pool.available(), avail_before + 2);

    // Realloc works normally.
    Connection* c2 = loop->alloc_conn();
    REQUIRE(c2 != nullptr);

    loop->free_conn(*c2);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(slice_conn, real_eventloop_idle_slots_hold_no_buffers) {
    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto rc = loop->init(0, -1);
    REQUIRE(rc.has_value());

    CHECK_EQ(loop->active_count(), 0u);
    CHECK_EQ(loop->pool.in_use(), 0u);
    CHECK_EQ(loop->pool.count, 0u);
    for (u32 i = 0; i < RealLoop::kMaxConns; i++) {
        CHECK_EQ(loop->conns[i].recv_slice, nullptr);
        CHECK_EQ(loop->conns[i].send_slice, nullptr);
        CHECK_EQ(loop->conns[i].upstream_recv_slice, nullptr);
        CHECK_EQ(loop->conns[i].recv_buf.write_avail(), 0u);
        CHECK_EQ(loop->conns[i].send_buf.write_avail(), 0u);
        CHECK_EQ(loop->conns[i].upstream_recv_buf.write_avail(), 0u);
    }

    Connection* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    CHECK_EQ(loop->active_count(), 1u);
    CHECK_EQ(loop->pool.in_use(), 2u);
    CHECK(c->recv_slice != nullptr);
    CHECK(c->send_slice != nullptr);

    loop->free_conn(*c);
    CHECK_EQ(loop->active_count(), 0u);
    CHECK_EQ(loop->pool.in_use(), 0u);
    CHECK_EQ(loop->pool.available(), loop->pool.count);
    CHECK_EQ(loop->conns[cid].recv_slice, nullptr);
    CHECK_EQ(loop->conns[cid].send_slice, nullptr);
    CHECK_EQ(loop->conns[cid].recv_buf.write_avail(), 0u);
    CHECK_EQ(loop->conns[cid].send_buf.write_avail(), 0u);

    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(slice_conn, real_eventloop_upstream_slice_returns_on_free) {
    RealLoop* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto rc = loop->init(0, -1);
    REQUIRE(rc.has_value());

    Connection* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    CHECK_EQ(loop->pool.in_use(), 2u);

    REQUIRE(loop->alloc_upstream_buf(*c));
    CHECK(c->upstream_recv_slice != nullptr);
    CHECK_EQ(loop->pool.in_use(), 3u);
    CHECK_EQ(c->upstream_recv_buf.write_avail(), SlicePool::kSliceSize);

    loop->free_conn(*c);
    CHECK_EQ(loop->pool.in_use(), 0u);
    CHECK_EQ(loop->pool.available(), loop->pool.count);
    CHECK_EQ(loop->conns[cid].recv_slice, nullptr);
    CHECK_EQ(loop->conns[cid].send_slice, nullptr);
    CHECK_EQ(loop->conns[cid].upstream_recv_slice, nullptr);
    CHECK_EQ(loop->conns[cid].upstream_recv_buf.write_avail(), 0u);

    loop->shutdown();
    destroy_real_loop(loop);
}

// === close_conn cancels in-flight I/O before freeing ===

// Closing a connection in Sending state must cancel I/O on its fd
// before the slot (and its pooled slices) become reusable.
TEST(close_cancel, cancels_client_fd) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;

    // Drive to Sending state (recv → response built → waiting for send completion).
    REQUIRE(dispatch_complete_http1_test_request(loop, *c));
    CHECK_EQ(c->state, ConnState::Sending);

    loop.backend.clear_ops();
    loop.close_conn(*c);

    // A Cancel op must have been recorded for the client fd before free.
    const MockOp* cancel_op = loop.backend.last_op(MockOp::Cancel);
    REQUIRE(cancel_op != nullptr);
    CHECK_EQ(cancel_op->conn_id, cid);
}

// Closing a proxying connection must cancel I/O on both client and upstream fds.
TEST(close_cancel, cancels_both_fds_when_proxying) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;

    // Simulate a proxying connection with both fds active.
    c->upstream_fd = 99;
    c->state = ConnState::Proxying;

    loop.backend.clear_ops();
    loop.close_conn(*c);

    // Should have two Cancel ops: one for client fd, one for upstream fd.
    CHECK_EQ(loop.backend.count_ops(MockOp::Cancel), 2u);
    CHECK_EQ(loop.conns[cid].fd, -1);
    CHECK_EQ(loop.conns[cid].upstream_fd, -1);
}

// After close+cancel, the freed slot is fully reusable.
TEST(close_cancel, slot_reusable_after_cancel) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    loop.inject_and_dispatch(make_ev(cid, IoEventType::Recv, 50));

    loop.close_conn(*c);

    // Reuse the slot with a new accept.
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 55));
    auto* c2 = loop.find_fd(55);
    REQUIRE(c2 != nullptr);
    CHECK_EQ(c2->recv_buf.len(), 0u);
    CHECK_EQ(c2->send_buf.len(), 0u);
}

// No cancel should be emitted for fds that are already -1 (idle connection).
TEST(close_cancel, no_cancel_for_idle_conn) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);

    // Complete a valid keep-alive request-response cycle. This keeps the slot
    // allocated while leaving it idle for the explicit invalid-fd guard below.
    static constexpr char kRequest[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(c->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    loop.dispatch(make_ev(c->id, IoEventType::Recv, sizeof(kRequest) - 1));
    u32 send_len = c->send_buf.len();
    loop.inject_and_dispatch(make_ev(c->id, IoEventType::Send, static_cast<i32>(send_len)));
    REQUIRE_EQ(c->state, ConnState::ReadingHeader);
    REQUIRE_EQ(c->fd, 42);

    // Force the allocated idle slot's fds to -1 to test the cancel guard path.
    c->fd = -1;
    c->upstream_fd = -1;
    loop.backend.clear_ops();
    loop.close_conn(*c);
    CHECK_EQ(loop.backend.count_ops(MockOp::Cancel), 0u);
}

// === SlicePool prealloc ===

TEST(pool_prealloc, prealloc_commits_slices) {
    SlicePool pool;
    auto rc = pool.init(64, 32);
    REQUIRE(rc.has_value());
    // prealloc rounds up to kGrowStep (256), so count >= 32.
    CHECK_GE(pool.count, 32u);
    // All committed slices are on free stack (none allocated yet).
    CHECK_EQ(pool.available(), pool.count);
    pool.destroy();
}

TEST(pool_prealloc, prealloc_zero_is_lazy) {
    SlicePool pool;
    auto rc = pool.init(64, 0);
    REQUIRE(rc.has_value());
    CHECK_EQ(pool.count, 0u);
    CHECK_EQ(pool.available(), 0u);
    pool.destroy();
}

// === Async reclaim (io_uring-style deferred reclamation) ===

TEST(async_reclaim, pending_ops_tracks_submits) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = 42;
    CHECK_EQ(c->pending_ops, 0u);
    loop.submit_recv(*c);
    CHECK_EQ(c->pending_ops, 1u);
    loop.submit_send(*c, c->send_buf.data(), 10);
    CHECK_EQ(c->pending_ops, 2u);
}

TEST(async_reclaim, pending_ops_decrements_on_dispatch) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = 42;
    c->state = ConnState::ReadingHeader;
    loop.submit_recv(*c);
    CHECK_EQ(c->pending_ops, 1u);
    // Clear slots so dispatch only does CQE accounting, not callbacks.
    c->on_recv = nullptr;
    c->on_send = nullptr;
    c->on_upstream_recv = nullptr;
    c->on_upstream_send = nullptr;
    // Dispatch a recv CQE with more=0 (final).
    loop.dispatch(make_ev_more(c->id, IoEventType::Recv, 50, 0));
    CHECK_EQ(c->pending_ops, 0u);
}

TEST(async_reclaim, pending_ops_no_decrement_on_more) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = 42;
    c->state = ConnState::ReadingHeader;
    loop.submit_recv(*c);
    CHECK_EQ(c->pending_ops, 1u);
    // Clear slots so dispatch only does CQE accounting.
    c->on_recv = nullptr;
    c->on_send = nullptr;
    c->on_upstream_recv = nullptr;
    c->on_upstream_send = nullptr;
    // Dispatch a recv CQE with more=1 (multishot intermediate).
    loop.dispatch(make_ev_more(c->id, IoEventType::Recv, 50, 1));
    CHECK_EQ(c->pending_ops, 1u);
    CHECK_EQ(c->recv_armed, true);
}

TEST(async_reclaim, reclaim_pending_skips_nonzero_ops) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    c->fd = 42;
    // Submit recv so pending_ops > 0.
    loop.submit_recv(*c);
    CHECK_EQ(c->pending_ops, 1u);
    u32 free_before = loop.free_top;
    // Close the connection: pending_ops>0 so it goes to pending_free.
    loop.close_conn(*c);
    CHECK_EQ(loop.pending_free_count, 1u);
    CHECK_EQ(loop.free_top, free_before);  // not reclaimed yet
    // Call reclaim_pending: pending_ops still > 0, should stay deferred.
    loop.reclaim_pending();
    CHECK_EQ(loop.pending_free_count, 1u);
    CHECK_EQ(loop.free_top, free_before);
    // Verify the slot is the one we closed.
    CHECK_EQ(loop.pending_free[0], cid);
}

TEST(async_reclaim, reclaim_pending_reclaims_zero_ops) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    c->fd = 42;
    // Submit recv so pending_ops > 0, then close.
    loop.submit_recv(*c);
    loop.close_conn(*c);
    CHECK_EQ(loop.pending_free_count, 1u);
    u32 free_before = loop.free_top;
    // Manually zero out pending_ops to simulate CQEs having drained.
    loop.conns[cid].pending_ops = 0;
    loop.reclaim_pending();
    CHECK_EQ(loop.pending_free_count, 0u);
    CHECK_EQ(loop.free_top, free_before + 1);
}

TEST(async_reclaim, inline_reclaim_on_stale_cqe) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    u32 cid = c->id;
    c->fd = 42;
    // Submit recv (pending_ops=1), then close.
    // close_conn adds cancel count to pending_ops (pending_ops=1+1=2),
    // then defers to pending_free since pending_ops > 0.
    loop.submit_recv(*c);
    CHECK_EQ(c->pending_ops, 1u);
    loop.close_conn(*c);
    CHECK_EQ(loop.pending_free_count, 1u);
    CHECK_GT(loop.conns[cid].pending_ops, 1u);  // recv + cancel CQEs

    u32 free_before = loop.free_top;
    u32 ops = loop.conns[cid].pending_ops;
    // Dispatch stale CQEs until pending_ops reaches 0.
    // Each CQE represents either the cancelled recv or the cancel op itself.
    for (u32 i = 0; i < ops; i++) {
        IoEvent stale = make_ev_more(cid, IoEventType::Recv, -125, 0);
        loop.dispatch(stale);
    }
    CHECK_EQ(loop.conns[cid].pending_ops, 0u);
    CHECK_EQ(loop.pending_free_count, 0u);
    CHECK_EQ(loop.free_top, free_before + 1);
}

TEST(async_reclaim, recv_armed_skips_duplicate_submit) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = 42;
    loop.submit_recv(*c);
    CHECK_EQ(c->recv_armed, true);
    CHECK_EQ(c->pending_ops, 1u);
    u32 ops_before = loop.backend.count_ops(MockOp::Recv);
    // Second submit should be a no-op.
    loop.submit_recv(*c);
    CHECK_EQ(c->pending_ops, 1u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), ops_before);
}

TEST(async_reclaim, upstream_recv_armed_independent) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = 42;
    c->upstream_fd = 43;
    c->state = ConnState::Proxying;
    // Submit both client recv and upstream recv.
    loop.submit_recv(*c);
    loop.submit_recv_upstream(*c);
    CHECK_EQ(c->recv_armed, true);
    CHECK_EQ(c->upstream_recv_armed, true);
    CHECK_EQ(c->pending_ops, 2u);
    // Clear slots so dispatch only does CQE accounting.
    c->on_recv = nullptr;
    c->on_send = nullptr;
    c->on_upstream_recv = nullptr;
    c->on_upstream_send = nullptr;
    // Dispatch final upstream recv CQE (more=0).
    IoEvent ev = make_ev_more(c->id, IoEventType::UpstreamRecv, 100, 0);
    loop.dispatch(ev);
    // upstream_recv_armed cleared, but recv_armed still set.
    CHECK_EQ(c->upstream_recv_armed, false);
    CHECK_EQ(c->recv_armed, true);
    CHECK_EQ(c->pending_ops, 1u);
}

TEST(async_reclaim, close_skips_cancel_when_no_ops) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = 42;
    // pending_ops == 0: no in-flight I/O.
    CHECK_EQ(c->pending_ops, 0u);
    loop.backend.clear_ops();
    loop.close_conn(*c);
    CHECK_EQ(loop.backend.count_ops(MockOp::Cancel), 0u);
}

TEST(async_reclaim, close_cancels_when_ops_pending) {
    AsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = 42;
    loop.submit_recv(*c);
    CHECK_GT(c->pending_ops, 0u);
    loop.backend.clear_ops();
    loop.close_conn(*c);
    CHECK_GT(loop.backend.count_ops(MockOp::Cancel), 0u);
}

TEST(async_reclaim, sqe_fail_no_pending_ops_increment) {
    FailRecvAsyncSmallLoop loop;
    loop.setup();
    Connection* c = loop.alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = 42;
    CHECK_EQ(c->pending_ops, 0u);
    loop.submit_recv(*c);
    // add_recv returned false: pending_ops must not have incremented.
    CHECK_EQ(c->pending_ops, 0u);
    CHECK_EQ(c->recv_armed, false);
}

// === Body Streaming ===

// Helper: inject custom data into recv_buf and dispatch an event.
// Does NOT use inject_and_dispatch (which writes garbage bytes).
template <typename Loop>
static void inject_custom_recv(
    Loop& loop, Connection& conn, IoEventType type, const u8* data, u32 len) {
    // Route to upstream_recv_buf for UpstreamRecv, recv_buf for Recv.
    auto& buf = (type == IoEventType::UpstreamRecv) ? conn.upstream_recv_buf : conn.recv_buf;
    buf.reset();
    u8* dst = buf.write_ptr();
    u32 avail = buf.write_avail();
    u32 n = len < avail ? len : avail;
    for (u32 j = 0; j < n; j++) dst[j] = data[j];
    buf.commit(n);
    IoEvent ev = make_ev(conn.id, type, static_cast<i32>(n));
    loop.backend.inject(ev);
    IoEvent events[8];
    u32 ne = loop.backend.wait(events, 8);
    for (u32 i = 0; i < ne; i++) loop.dispatch(events[i]);
}

// Helper: set up a proxy connection and send request to upstream.
// Returns the connection pointer (upstream_fd = 100, client fd = 42).
static Connection* setup_proxy_conn(SmallLoop& loop) {
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    if (!conn) return nullptr;

    // Simulate receiving an HTTP request.
    // Write a valid GET request into recv_buf.
    const char* req = "GET / HTTP/1.1\r\nHost: test\r\n\r\n";
    u32 req_len = 30;
    conn->recv_buf.reset();
    u8* dst = conn->recv_buf.write_ptr();
    for (u32 i = 0; i < req_len; i++) dst[i] = static_cast<u8>(req[i]);
    conn->recv_buf.commit(req_len);
    IoEvent recv_ev = make_ev(conn->id, IoEventType::Recv, static_cast<i32>(req_len));
    loop.backend.inject(recv_ev);
    IoEvent events[8];
    u32 n = loop.backend.wait(events, 8);
    for (u32 i = 0; i < n; i++) loop.dispatch(events[i]);

    // Switch to proxy mode.
    conn->upstream_fd = 100;
    conn->on_upstream_send = &on_upstream_connected<SmallLoop>;
    conn->state = ConnState::Proxying;
    loop.submit_connect(*conn, nullptr, 0);

    // Upstream connect succeeds.
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::UpstreamConnect, 0));

    // Request sent to upstream (send result = recv_buf.len()).
    loop.inject_and_dispatch(
        make_ev(conn->id, IoEventType::UpstreamSend, static_cast<i32>(conn->recv_buf.len())));

    // Now conn is waiting for upstream response (on_upstream_response).
    return conn;
}

// Helper: set up proxy with HEAD request method.
static Connection* setup_proxy_conn_head(SmallLoop& loop) {
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* conn = loop.find_fd(42);
    if (!conn) return nullptr;

    // Write a HEAD request.
    const char* req = "HEAD / HTTP/1.1\r\nHost: test\r\n\r\n";
    u32 req_len = 31;
    conn->recv_buf.reset();
    u8* dst = conn->recv_buf.write_ptr();
    for (u32 i = 0; i < req_len; i++) dst[i] = static_cast<u8>(req[i]);
    conn->recv_buf.commit(req_len);

    // Dispatch the recv event (this parses the request and captures metadata).
    IoEvent recv_ev = make_ev(conn->id, IoEventType::Recv, static_cast<i32>(req_len));
    loop.backend.inject(recv_ev);
    IoEvent events[8];
    u32 n = loop.backend.wait(events, 8);
    for (u32 i = 0; i < n; i++) loop.dispatch(events[i]);

    // Switch to proxy mode.
    conn->upstream_fd = 100;
    conn->on_upstream_send = &on_upstream_connected<SmallLoop>;
    conn->state = ConnState::Proxying;
    loop.submit_connect(*conn, nullptr, 0);

    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::UpstreamConnect, 0));
    loop.inject_and_dispatch(
        make_ev(conn->id, IoEventType::UpstreamSend, static_cast<i32>(conn->recv_buf.len())));

    return conn;
}

// Large Content-Length response body that requires multiple recv→send cycles.
// SmallLoop has 4KB buffers. A 10KB body needs 3 recv→send cycles.
TEST(streaming, large_content_length) {
    SmallLoop loop;
    loop.setup();
    auto* conn = setup_proxy_conn(loop);
    REQUIRE(conn != nullptr);

    // Upstream response: headers + first body fragment.
    // Total body = 10000 bytes. Headers + some initial body fit in 4KB.
    const char* resp_hdr =
        "HTTP/1.1 200 OK\r\n"
        "Content-Length: 10000\r\n"
        "\r\n";
    u32 hdr_len = 0;
    while (resp_hdr[hdr_len]) hdr_len++;

    // Build initial upstream_recv_buf: headers + as much body as fits in 4KB.
    u32 initial_body = SmallLoop::kBufSize - hdr_len;
    conn->upstream_recv_buf.reset();
    u8* dst = conn->upstream_recv_buf.write_ptr();
    for (u32 i = 0; i < hdr_len; i++) dst[i] = static_cast<u8>(resp_hdr[i]);
    for (u32 i = 0; i < initial_body; i++) dst[hdr_len + i] = static_cast<u8>(i & 0xFF);
    conn->upstream_recv_buf.commit(hdr_len + initial_body);

    // Dispatch: upstream response with headers + initial body.
    IoEvent ev =
        make_ev(conn->id, IoEventType::UpstreamRecv, static_cast<i32>(hdr_len + initial_body));
    loop.backend.inject(ev);
    IoEvent events[8];
    u32 n = loop.backend.wait(events, 8);
    for (u32 i = 0; i < n; i++) loop.dispatch(events[i]);

    // Should be in streaming mode (not on_proxy_response_sent).
    CHECK_EQ(conn->on_send, &on_response_header_sent<SmallLoop>);
    CHECK_EQ(conn->resp_body_mode, BodyMode::ContentLength);

    // Simulate send completion of the initial headers+body.
    loop.backend.clear_ops();
    loop.inject_and_dispatch(
        make_ev(conn->id, IoEventType::Send, static_cast<i32>(hdr_len + initial_body)));
    // Should now be waiting for more upstream body data.
    CHECK_EQ(conn->on_upstream_recv, &on_response_body_recvd<SmallLoop>);

    // Track remaining body.
    u32 body_sent = initial_body;
    u32 total_body = 10000;

    // Stream body in chunks until complete.
    while (body_sent < total_body) {
        u32 chunk = total_body - body_sent;
        if (chunk > SmallLoop::kBufSize) chunk = SmallLoop::kBufSize;

        // Inject upstream body data.
        u8 body_chunk[SmallLoop::kBufSize];
        for (u32 i = 0; i < chunk; i++) body_chunk[i] = static_cast<u8>(i & 0xFF);
        inject_custom_recv(loop, *conn, IoEventType::UpstreamRecv, body_chunk, chunk);

        // Should have forwarded to client.
        CHECK_EQ(conn->on_send, &on_response_body_sent<SmallLoop>);

        // Simulate send completion.
        loop.inject_and_dispatch(make_ev(conn->id, IoEventType::Send, static_cast<i32>(chunk)));
        body_sent += chunk;

        if (body_sent < total_body) {
            // More body to stream.
            CHECK_EQ(conn->on_upstream_recv, &on_response_body_recvd<SmallLoop>);
        }
    }

    // Body complete — should be back to reading next request (keep-alive).
    CHECK_EQ(conn->state, ConnState::ReadingHeader);
    CHECK_EQ(conn->on_recv, &on_header_received<SmallLoop>);
}

// Chunked response body streaming.
TEST(streaming, chunked_response) {
    SmallLoop loop;
    loop.setup();
    auto* conn = setup_proxy_conn(loop);
    REQUIRE(conn != nullptr);

    // Upstream response with chunked transfer encoding (headers only, no body yet).
    const char* resp_hdr =
        "HTTP/1.1 200 OK\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n";
    u32 hdr_len = 0;
    while (resp_hdr[hdr_len]) hdr_len++;

    conn->upstream_recv_buf.reset();
    u8* dst = conn->upstream_recv_buf.write_ptr();
    for (u32 i = 0; i < hdr_len; i++) dst[i] = static_cast<u8>(resp_hdr[i]);
    conn->upstream_recv_buf.commit(hdr_len);

    IoEvent ev = make_ev(conn->id, IoEventType::UpstreamRecv, static_cast<i32>(hdr_len));
    loop.backend.inject(ev);
    IoEvent events[8];
    u32 n = loop.backend.wait(events, 8);
    for (u32 i = 0; i < n; i++) loop.dispatch(events[i]);

    // Should be streaming (headers sent, waiting for send completion).
    CHECK_EQ(conn->on_send, &on_response_header_sent<SmallLoop>);
    CHECK_EQ(conn->resp_body_mode, BodyMode::Chunked);

    // Send completion of headers.
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::Send, static_cast<i32>(hdr_len)));
    CHECK_EQ(conn->on_upstream_recv, &on_response_body_recvd<SmallLoop>);

    // First chunk: "A\r\n0123456789\r\n" (10 bytes of data).
    const char* chunk1 = "A\r\n0123456789\r\n";
    u32 chunk1_len = 0;
    while (chunk1[chunk1_len]) chunk1_len++;
    inject_custom_recv(
        loop, *conn, IoEventType::UpstreamRecv, reinterpret_cast<const u8*>(chunk1), chunk1_len);
    CHECK_EQ(conn->on_send, &on_response_body_sent<SmallLoop>);

    // Send completion.
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::Send, static_cast<i32>(chunk1_len)));
    // Not done yet — recv more.
    CHECK_EQ(conn->on_upstream_recv, &on_response_body_recvd<SmallLoop>);

    // Final chunk: "0\r\n\r\n".
    const char* chunk_end = "0\r\n\r\n";
    u32 end_len = 5;
    inject_custom_recv(
        loop, *conn, IoEventType::UpstreamRecv, reinterpret_cast<const u8*>(chunk_end), end_len);
    CHECK_EQ(conn->on_send, &on_response_body_sent<SmallLoop>);

    // Send completion of final chunk.
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::Send, static_cast<i32>(end_len)));

    // Body complete — back to keep-alive.
    CHECK_EQ(conn->state, ConnState::ReadingHeader);
    CHECK_EQ(conn->on_recv, &on_header_received<SmallLoop>);
}

