TEST(exact_local_response,
     fresh_header_absent_delete_put_and_patch_exclusions_and_forged_owners_fail_closed) {
    SmallLoop loop;
    loop.setup();
    ShardMetrics metrics{};
    metrics.init();
    AccessLogRing access{};
    access.init();
    CaptureRing capture{};
    capture.init();
    ShardEpoch epoch{};
    loop.metrics = &metrics;
    loop.access_log = &access;
    loop.epoch = &epoch;
    REQUIRE(loop.set_capture(&capture));
    RouteConfig config{};
    REQUIRE(install_representation200_exact(config, "/static"));

    auto closes_without_effect = [&](const char* request, u64 expected_epoch_delta) {
        loop.backend.clear_ops();
        const u32 free_before = loop.free_top;
        const u64 requests_before = metrics.requests_total;
        const u64 active_before = metrics.requests_active;
        const u32 access_before = access.available();
        const u32 capture_before = capture.available();
        const u64 epoch_before = epoch.epoch.load(std::memory_order_acquire);
        Connection* rejected = dispatch_unmatched_request(loop, config, request);
        REQUIRE(rejected != nullptr);
        CHECK_EQ(loop.free_top, free_before);
        CHECK_EQ(rejected->fd, -1);
        CHECK_EQ(rejected->downstream_completed_request_count, 0u);
        CHECK_EQ(rejected->upstream_fd, -1);
        CHECK_FALSE(rejected->upstream_slot_held);
        CHECK_EQ(rejected->upstream_attempts, 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
        CHECK_EQ(metrics.requests_total, requests_before);
        CHECK_EQ(metrics.requests_active, active_before);
        CHECK_EQ(access.available(), access_before);
        CHECK_EQ(capture.available(), capture_before);
        CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), epoch_before + expected_epoch_delta);
    };

    static constexpr const char* kDeleteAdmittedParseRejected[] = {
        "DELETE /static HTTP/1.1\r\nHost: x\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nConnection: close, close\r\n\r\n",
        "DELETE /static? HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "DELETE /static?x=1 HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nContent-Length: "
        "0\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nContent-Length: 1\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nContent-Length: 1\r\nConnection: close\r\n\r\nx",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: chunked\r\nConnection: "
        "close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nTE: trailers\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nExpect: 100-continue\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nConnection: Upgrade\r\nUpgrade: websocket\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\nx",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\nGET /next "
        "HTTP/1.1\r\nHost: x\r\n\r\n",
        "TRACE /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
    };
    for (const char* request : kDeleteAdmittedParseRejected) closes_without_effect(request, 2);

    static constexpr const char* kPutAdmittedParseRejected[] = {
        "PUT /static HTTP/1.1\r\nHost: x\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nConnection: keep-alive\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nConnection: close, close\r\n\r\n",
        "PUT /static? HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PUT /static?x=1 HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nContent-Length: "
        "0\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nContent-Length: 1\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nContent-Length: 1\r\nConnection: close\r\n\r\nx",
        "PUT /static HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: chunked\r\nConnection: "
        "close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nTE: trailers\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nExpect: 100-continue\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nConnection: Upgrade\r\nUpgrade: websocket\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\nx",
        "PUT /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\nGET /next "
        "HTTP/1.1\r\nHost: x\r\n\r\n",
    };
    for (const char* request : kPutAdmittedParseRejected) closes_without_effect(request, 2);

    static constexpr const char* kPatchAdmittedParseRejected[] = {
        "PATCH /static HTTP/1.1\r\nHost: x\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nConnection: keep-alive\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nConnection: close, close\r\n\r\n",
        "PATCH /static? HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PATCH /static?x=1 HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nContent-Length: "
        "0\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nContent-Length: 1\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nContent-Length: 1\r\nConnection: close\r\n\r\nx",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: chunked\r\nConnection: "
        "close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nTE: trailers\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nExpect: 100-continue\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nConnection: Upgrade\r\nUpgrade: websocket\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\nx",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\nGET /next "
        "HTTP/1.1\r\nHost: x\r\n\r\n",
    };
    for (const char* request : kPatchAdmittedParseRejected) closes_without_effect(request, 2);

    static constexpr const char* kDeleteEarlyRejected[] = {
        "DELETE /static#fragment HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.0\r\nHost: x\r\nConnection: close\r\n\r\n",
        "DELETE http://example.test/static HTTP/1.1\r\nHost: example.test\r\nConnection: "
        "close\r\n\r\n",
        "DELETE example.test:80 HTTP/1.1\r\nHost: example.test\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nContent-Length: nope\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nContent-Length: "
        "1\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nTransfer-Encoding: "
        "chunked\r\nConnection: close\r\n\r\n",
        "BREW /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
    };
    for (const char* request : kDeleteEarlyRejected) closes_without_effect(request, 0);

    static constexpr const char* kPutEarlyRejected[] = {
        "PUT /static#fragment HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.0\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PUT * HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PUT http://example.test/static HTTP/1.1\r\nHost: example.test\r\nConnection: "
        "close\r\n\r\n",
        "PUT example.test:80 HTTP/1.1\r\nHost: example.test\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nContent-Length: nope\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nContent-Length: "
        "1\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nTransfer-Encoding: "
        "chunked\r\nConnection: close\r\n\r\n",
    };
    for (const char* request : kPutEarlyRejected) closes_without_effect(request, 0);

    static constexpr const char* kPatchEarlyRejected[] = {
        "PATCH /static#fragment HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.0\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PATCH * HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PATCH http://example.test/static HTTP/1.1\r\nHost: example.test\r\nConnection: "
        "close\r\n\r\n",
        "PATCH example.test:80 HTTP/1.1\r\nHost: example.test\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nContent-Length: nope\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nContent-Length: "
        "1\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nTransfer-Encoding: "
        "chunked\r\nConnection: close\r\n\r\n",
    };
    for (const char* request : kPatchEarlyRejected) closes_without_effect(request, 0);

    Connection forged{};
    u8 recv[512]{}, send[512]{}, upstream[512]{}, response[512]{};
    auto reset_forged = [&](LogHttpMethod method) {
        forged.reset();
        // Episode/tombstone identity and quarantine are deliberately sticky
        // across slot reset. This fixture models a canonical fresh transport
        // for each independent mutation, so restore their accept-time values.
        forged.upstream_episode = 1;
        forged.upstream_retiring_episode = 0;
        forged.upstream_episode_quarantined = false;
        forged.recv_slice = recv;
        forged.send_slice = send;
        forged.upstream_recv_slice = upstream;
        forged.response_header_slice = response;
        forged.recv_buf.bind(recv, sizeof(recv));
        forged.send_buf.bind(send, sizeof(send));
        forged.upstream_recv_buf.bind(upstream, sizeof(upstream));
        forged.response_header_buf.bind(response, sizeof(response));
        static constexpr char kDelete[] =
            "DELETE /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
        static constexpr char kPut[] =
            "PUT /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
        static constexpr char kPatch[] =
            "PATCH /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
        const char* request = method == LogHttpMethod::Delete ? kDelete
                              : method == LogHttpMethod::Put  ? kPut
                                                              : kPatch;
        const u32 request_len = static_cast<u32>(strlen(request));
        REQUIRE_EQ(forged.recv_buf.write(reinterpret_cast<const u8*>(request), request_len),
                   request_len);
        capture_request_metadata(forged);
        if (method == LogHttpMethod::Delete) {
            REQUIRE(exact_strict_local_response_delete_request_is_admitted(forged));
        } else if (method == LogHttpMethod::Put) {
            REQUIRE(exact_strict_local_response_put_request_is_admitted(forged));
        } else {
            REQUIRE_EQ(method, LogHttpMethod::Patch);
            REQUIRE(exact_strict_local_response_patch_request_is_admitted(forged));
        }
        REQUIRE(exact_strict_local_response_request_is_admitted(forged));
    };
    auto rejected = [&](auto mutate) {
        for (const LogHttpMethod method :
             {LogHttpMethod::Delete, LogHttpMethod::Put, LogHttpMethod::Patch}) {
            reset_forged(method);
            mutate(forged);
            if (method == LogHttpMethod::Delete) {
                CHECK_FALSE(exact_strict_local_response_delete_request_is_admitted(forged));
            } else if (method == LogHttpMethod::Put) {
                CHECK_FALSE(exact_strict_local_response_put_request_is_admitted(forged));
            } else {
                CHECK_FALSE(exact_strict_local_response_patch_request_is_admitted(forged));
            }
            CHECK_FALSE(exact_strict_local_response_request_is_admitted(forged));
        }
    };
    rejected([](Connection& c) { c.downstream_completed_request_count = 1; });
    rejected([](Connection& c) { c.req_client_connection_count = 2; });
    rejected([](Connection& c) { c.req_client_connection_close_exact = false; });
    rejected([](Connection& c) { c.req_keep_alive = true; });
    rejected([](Connection& c) { c.req_client_keep_alive = true; });
    rejected([](Connection& c) { c.req_client_has_content_length = true; });
    rejected([](Connection& c) { c.req_client_content_length_count = 1; });
    rejected([](Connection& c) { c.req_content_length = 1; });
    rejected([](Connection& c) {
        c.req_client_transfer_encoding = RequestTransferEncoding::FinalChunked;
    });
    rejected([](Connection& c) { c.req_client_has_transfer_encoding = true; });
    rejected([](Connection& c) { c.req_client_has_te = true; });
    rejected([](Connection& c) { c.req_client_has_expect = true; });
    rejected([](Connection& c) { c.req_client_has_upgrade_header = true; });
    rejected([](Connection& c) { c.req_body_remaining = 1; });
    rejected([](Connection& c) { c.request_body_fully_buffered = true; });
    rejected([](Connection& c) { c.request_upload_complete = true; });
    rejected([](Connection& c) { c.req_body_streamed = true; });
    rejected([](Connection& c) { c.pipeline_depth = 1; });
    rejected([](Connection& c) { c.http1_pipeline_request_generation = 1; });
    rejected([](Connection& c) { c.http1_pipeline_boundary_owners_settled = true; });
    rejected([](Connection& c) { c.pipeline_stash_len = 1; });
    rejected([](Connection& c) {
        static constexpr u8 kByte = 'x';
        (void)c.send_buf.write(&kByte, 1);
    });
    rejected([](Connection& c) { c.send_progress = 1; });
    rejected([](Connection& c) { c.send_armed = true; });
    rejected([](Connection& c) { c.on_send = &on_response_sent<SmallLoop>; });
    rejected([](Connection& c) { c.response_read_deadline_owner_generation = 1; });
    rejected([](Connection& c) { c.http1_prebuilt_wait = 1; });
    rejected([](Connection& c) {
        c.http1_prebuilt_response_layout = Http1PrebuiltResponseLayout::FullContentLengthNonHead;
    });
    rejected([](Connection& c) { c.http1_boundary_deferred = true; });
    rejected([](Connection& c) { c.http1_boundary_ready = true; });
    rejected([](Connection& c) { c.retry_req_send_len = 1; });
    rejected([](Connection& c) { c.upstream_attempts = 1; });
    rejected([](Connection& c) { c.upstream_fd = 99; });
    rejected([](Connection& c) { c.upstream_slot_held = true; });
    rejected([](Connection& c) { c.upstream_connect_armed = true; });
    rejected([](Connection& c) { c.upstream_send_armed = true; });
    rejected([](Connection& c) { c.upstream_recv_armed = true; });
    rejected([](Connection& c) { c.on_upstream_recv = &on_upstream_response<SmallLoop>; });
    rejected([](Connection& c) { c.idle_return_fd = 99; });
    rejected([](Connection& c) { c.upstream_episode_quarantined = true; });
    rejected([](Connection& c) {
        c.upstream_episode = 1;
        c.upstream_retiring_episode = 2;
    });
    rejected([](Connection& c) { c.tls_active = true; });
    rejected([](Connection& c) { c.protocol = ConnProtocol::Http2; });

    CHECK(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Delete,
                                                                     HttpMethod::DELETE));
    CHECK(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Put,
                                                                     HttpMethod::PUT));
    CHECK(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Patch,
                                                                     HttpMethod::PATCH));
    CHECK_FALSE(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Delete,
                                                                           HttpMethod::PUT));
    CHECK_FALSE(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Put,
                                                                           HttpMethod::DELETE));
    CHECK_FALSE(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Delete,
                                                                           HttpMethod::PATCH));
    CHECK_FALSE(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Patch,
                                                                           HttpMethod::DELETE));
    CHECK_FALSE(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Put,
                                                                           HttpMethod::PATCH));
    CHECK_FALSE(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Patch,
                                                                           HttpMethod::PUT));
    CHECK_FALSE(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Trace,
                                                                           HttpMethod::TRACE));
    CHECK_FALSE(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Delete,
                                                                           HttpMethod::TRACE));
    CHECK_FALSE(exact_strict_local_response_fresh_method_pair_is_supported(LogHttpMethod::Trace,
                                                                           HttpMethod::DELETE));

    // Captured metadata and the independently reparsed raw method must agree;
    // neither supported method may borrow the other's proof.
    static constexpr LogHttpMethod kFreshMethods[] = {
        LogHttpMethod::Delete,
        LogHttpMethod::Put,
        LogHttpMethod::Patch,
    };
    for (const LogHttpMethod raw_method : kFreshMethods) {
        for (const LogHttpMethod metadata_method : kFreshMethods) {
            if (raw_method == metadata_method) continue;
            reset_forged(raw_method);
            forged.req_method = static_cast<u8>(metadata_method);
            CHECK_FALSE(exact_strict_local_response_delete_request_is_admitted(forged));
            CHECK_FALSE(exact_strict_local_response_put_request_is_admitted(forged));
            CHECK_FALSE(exact_strict_local_response_patch_request_is_admitted(forged));
            CHECK_FALSE(exact_strict_local_response_request_is_admitted(forged));
        }
    }

    reset_forged(LogHttpMethod::Patch);
    forged.recv_buf.reset();
    static constexpr char kTrace[] =
        "TRACE /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
    REQUIRE_EQ(forged.recv_buf.write(reinterpret_cast<const u8*>(kTrace), sizeof(kTrace) - 1u),
               sizeof(kTrace) - 1u);
    capture_request_metadata(forged);
    REQUIRE_EQ(forged.req_method, static_cast<u8>(LogHttpMethod::Trace));
    CHECK_FALSE(exact_strict_local_response_delete_request_is_admitted(forged));
    CHECK_FALSE(exact_strict_local_response_put_request_is_admitted(forged));
    CHECK_FALSE(exact_strict_local_response_patch_request_is_admitted(forged));
    CHECK_FALSE(exact_strict_local_response_request_is_admitted(forged));
}

TEST(exact_local_response, depth_one_matching_exclusions_fail_before_second_response) {
    static constexpr const char* kRejected[] = {
        "GET /static HTTP/1.1\r\nHost: x\r\n\r\n",
        "POST /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "DELETE /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PUT /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "PATCH /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
        "POST /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
        "GET /static HTTP/1.1\r\nHost: x\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
        "GET /static HTTP/1.1\r\nHost: x\r\nConnection: close, keep-alive\r\n\r\n",
        ("GET /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n"
         "GET /third HTTP/1.1\r\nHost: x\r\n\r\n"),
    };
    for (const char* rejected : kRejected) {
        SmallLoop loop;
        loop.setup();
        RouteConfig config{};
        REQUIRE(install_representation200_exact(config, "/static"));
        REQUIRE(config.add_static("/", kRouteMethodGet, 204));
        const RouteConfig* active = &config;
        loop.config_ptr = &active;
        Connection* conn = loop.alloc_conn();
        REQUIRE(conn != nullptr);
        conn->fd = 88;
        static constexpr char kFirst[] = "GET /first HTTP/1.1\r\nHost: x\r\n\r\n";
        REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kFirst), sizeof(kFirst) - 1),
                   sizeof(kFirst) - 1);
        const u32 rejected_len = static_cast<u32>(strlen(rejected));
        REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(rejected), rejected_len),
                   rejected_len);
        const u32 id = conn->id;
        on_header_received<SmallLoop>(
            &loop,
            *conn,
            make_ev(id, IoEventType::Recv, static_cast<i32>(sizeof(kFirst) - 1 + rejected_len)));
        REQUIRE_EQ(conn->resp_status, 204u);
        const u32 response1_len = conn->send_buf.len();
        loop.inject_and_dispatch(make_ev(id, IoEventType::Send, static_cast<i32>(response1_len)));
        CHECK_EQ(loop.conns[id].fd, -1);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    }
}

TEST(exact_local_response,
     provenance_overwrites_preserves_fragmented_reparse_and_consumes_on_dispatch) {
    SmallLoop loop;
    loop.setup();
    RouteConfig config{};
    REQUIRE(install_representation200_exact(config, "/static"));
    const RouteConfig* active = &config;
    loop.config_ptr = &active;
    Connection* conn = loop.alloc_conn();
    REQUIRE(conn != nullptr);
    conn->fd = 89;
    conn->pipeline_depth = 1;
    conn->http1_pipeline_boundary_owners_settled = false;
    static constexpr char kPartial[] = "GET /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kPartial), sizeof(kPartial) - 1),
               sizeof(kPartial) - 1);

    // pipeline_dispatch is the only writer of true. The incomplete parse then
    // re-enters ReadingHeader without replacing that old-boundary provenance.
    pipeline_dispatch<SmallLoop>(&loop, *conn);
    REQUIRE_GE(conn->fd, 0);
    CHECK(conn->http1_pipeline_boundary_owners_settled);
    CHECK_EQ(conn->http1_pipeline_request_generation, 0u);
    CHECK_EQ(conn->state, ConnState::ReadingHeader);

    static constexpr char kEnd[] = "\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kEnd), sizeof(kEnd) - 1),
               sizeof(kEnd) - 1);
    on_header_received<SmallLoop>(
        &loop, *conn, make_ev(conn->id, IoEventType::Recv, static_cast<i32>(sizeof(kEnd) - 1)));
    REQUIRE_GE(conn->fd, 0);
    CHECK_EQ(conn->http1_pipeline_request_generation, conn->handler_gen);
    CHECK_FALSE(conn->http1_pipeline_boundary_owners_settled);
    CHECK_EQ(conn->resp_status, 200u);
    CHECK_FALSE(conn->keep_alive);
    const u32 response_len = conn->send_buf.len();
    loop.inject_and_dispatch(make_ev(conn->id, IoEventType::Send, static_cast<i32>(response_len)));

    Connection* depth_zero = loop.alloc_conn();
    REQUIRE(depth_zero != nullptr);
    depth_zero->fd = 90;
    depth_zero->http1_pipeline_boundary_owners_settled = true;
    static constexpr char kDepthZero[] =
        "GET /other HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
    REQUIRE_EQ(
        depth_zero->recv_buf.write(reinterpret_cast<const u8*>(kDepthZero), sizeof(kDepthZero) - 1),
        sizeof(kDepthZero) - 1);
    on_header_received<SmallLoop>(
        &loop,
        *depth_zero,
        make_ev(depth_zero->id, IoEventType::Recv, static_cast<i32>(sizeof(kDepthZero) - 1)));
    CHECK_FALSE(depth_zero->http1_pipeline_boundary_owners_settled);
}

TEST(exact_local_response, provenance_half_set_and_stale_combinations_fail_closed) {
    Connection conn{};
    u8 recv[512]{}, send[512]{}, upstream[512]{}, response[512]{};
    conn.reset();
    conn.recv_slice = recv;
    conn.send_slice = send;
    conn.upstream_recv_slice = upstream;
    conn.response_header_slice = response;
    conn.recv_buf.bind(recv, sizeof(recv));
    conn.send_buf.bind(send, sizeof(send));
    conn.upstream_recv_buf.bind(upstream, sizeof(upstream));
    conn.response_header_buf.bind(response, sizeof(response));
    static constexpr char kRequest[] =
        "GET /static HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
    REQUIRE_EQ(conn.recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    capture_request_metadata(conn);
    conn.pipeline_depth = 1;
    conn.handler_gen = 17;
    conn.http1_pipeline_request_generation = 17;
    conn.http1_pipeline_boundary_owners_settled = true;
    conn.req_start_us = 1;
    REQUIRE(exact_strict_local_response_request_is_admitted(conn));

    CHECK_FALSE(conn.req_client_has_content_length);
    CHECK_EQ(conn.req_client_content_length_count, 0u);
    conn.req_client_content_length_count = 1;
    CHECK_FALSE(exact_strict_local_response_request_is_admitted(conn));
    conn.req_client_content_length_count = 0;
    conn.req_client_has_content_length = true;
    CHECK_FALSE(exact_strict_local_response_request_is_admitted(conn));
    conn.req_client_has_content_length = false;
    REQUIRE(exact_strict_local_response_request_is_admitted(conn));

    conn.http1_pipeline_boundary_owners_settled = false;
    CHECK_FALSE(exact_strict_local_response_request_is_admitted(conn));
    conn.http1_pipeline_boundary_owners_settled = true;
    conn.http1_pipeline_request_generation = 16;
    CHECK_FALSE(exact_strict_local_response_request_is_admitted(conn));
    conn.http1_pipeline_request_generation = 17;
    conn.pipeline_depth = 0;
    CHECK_FALSE(exact_strict_local_response_request_is_admitted(conn));
    conn.pipeline_depth = 2;
    CHECK_FALSE(exact_strict_local_response_request_is_admitted(conn));

    conn.reset();
    CHECK_FALSE(conn.http1_pipeline_boundary_owners_settled);
    CHECK_EQ(conn.http1_pipeline_request_generation, 0u);
}

TEST(unmatched_local_response, connect_exact_and_strict_gate_fail_closed_without_effects) {
    SmallLoop loop;
    loop.setup();
    RouteConfig config{};
    const auto connect = make_unmatched_policy(405, "Not Allowed", "connect");
    REQUIRE_EQ(config.add_strict_local_response_policy(connect), 1u);
    REQUIRE(config.set_unmatched_policy_id(kRouteMethodConnect, 1));
    REQUIRE(config.unmatched_policy_table_is_valid());

    Connection* selected = dispatch_unmatched_request(
        loop,
        config,
        "CONNECT example.test:443 HTTP/1.1\r\nHost: other.test\r\nConnection: close\r\n\r\n");
    REQUIRE(selected != nullptr);
    CHECK_EQ(selected->resp_status, 405u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);

    auto closes_zero = [&](const char* request, RouteConfig& cfg) {
        loop.backend.clear_ops();
        const u32 before = loop.free_top;
        Connection* stale = dispatch_unmatched_request(loop, cfg, request);
        REQUIRE(stale != nullptr);
        CHECK_EQ(loop.free_top, before);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    };
    closes_zero("CONNECT example.test:443 HTTP/1.1\r\nBroken\r\n\r\n", config);
    closes_zero("CONNECT example.test:443 HTTP/1.0\r\nHost: x\r\n\r\n", config);

    RouteConfig partial{};
    partial.unmatched_policy_ids[kRouteMethodConnect] = 1;
    closes_zero("CONNECT example.test:443 HTTP/1.1\r\nHost: x\r\n\r\n", partial);

    auto oversized_wire = std::make_unique<RouteConfig>();
    const std::string large_body(kMaxStrictLocalResponseBodyLen, 'x');
    auto large = make_unmatched_policy(400, "Bad", "x");
    large.body = {large_body.data(), static_cast<u32>(large_body.size())};
    REQUIRE_EQ(oversized_wire->add_strict_local_response_policy(large), 1u);
    REQUIRE(oversized_wire->set_unmatched_policy_id(kRouteMethodOptions, 1));
    closes_zero("OPTIONS * HTTP/1.1\r\nHost: x\r\n\r\n", *oversized_wire);
}

TEST(unmatched_local_response, head_suppression_body_framing_and_keepalive_lifecycle) {
    SmallLoop loop;
    loop.setup();
    RouteConfig config{};
    const auto head = make_unmatched_policy(
        404, "Missing", "representation", StrictLocalResponseHeadMode::SuppressBody);
    const auto options = make_unmatched_policy(400, "Bad", "bad");
    REQUIRE_EQ(config.add_strict_local_response_policy(head), 1u);
    REQUIRE_EQ(config.add_strict_local_response_policy(options), 2u);
    REQUIRE(config.set_unmatched_policy_id(kRouteMethodHead, 1));
    REQUIRE(config.set_unmatched_policy_id(kRouteMethodOptions, 2));
    REQUIRE(config.unmatched_policy_table_is_valid());

    Connection* head_conn = dispatch_unmatched_request(
        loop, config, "HEAD /miss HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n");
    REQUIRE(head_conn != nullptr);
    CHECK_EQ(head_conn->resp_status, 404u);
    CHECK(buf_contains(reinterpret_cast<const char*>(head_conn->send_buf.data()),
                       head_conn->send_buf.len(),
                       "Content-Length: 14\r\n",
                       20));
    CHECK_FALSE(buf_contains(reinterpret_cast<const char*>(head_conn->send_buf.data()),
                             head_conn->send_buf.len(),
                             "representation",
                             14));

    RouteConfig forged_head{};
    REQUIRE_EQ(forged_head.add_strict_local_response_policy(options), 1u);
    REQUIRE(forged_head.set_unmatched_policy_id(kRouteMethodOptions, 1));
    forged_head.unmatched_policy_ids[kRouteMethodOptions] = 0;
    forged_head.unmatched_policy_ids[kRouteMethodHead] = 1;
    loop.backend.clear_ops();
    const u32 before = loop.free_top;
    (void)dispatch_unmatched_request(loop, forged_head, "HEAD /miss HTTP/1.1\r\nHost: x\r\n\r\n");
    CHECK_EQ(loop.free_top, before);
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);

    Connection* cl = dispatch_unmatched_request(
        loop, config, "OPTIONS * HTTP/1.1\r\nHost: x\r\nContent-Length: 5\r\n\r\nxy");
    REQUIRE(cl != nullptr);
    CHECK_FALSE(cl->keep_alive);
    CHECK_EQ(cl->on_recv, nullptr);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
    CHECK(buf_contains(reinterpret_cast<const char*>(cl->send_buf.data()),
                       cl->send_buf.len(),
                       "Connection: close\r\n",
                       19));

    loop.backend.clear_ops();
    Connection* chunked = dispatch_unmatched_request(
        loop, config, "OPTIONS * HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: chunked\r\n\r\n2\r\nx");
    REQUIRE(chunked != nullptr);
    CHECK_FALSE(chunked->keep_alive);
    CHECK_EQ(chunked->on_recv, nullptr);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);

    loop.backend.clear_ops();
    Connection* reusable =
        dispatch_unmatched_request(loop, config, "OPTIONS * HTTP/1.1\r\nHost: x\r\n\r\n");
    REQUIRE(reusable != nullptr);
    CHECK(reusable->keep_alive);
    const u32 reusable_id = reusable->id;
    const u32 send_len = reusable->send_buf.len();
    loop.backend.clear_ops();
    loop.inject_and_dispatch(make_ev(reusable_id, IoEventType::Send, static_cast<i32>(send_len)));
    Connection* after = &loop.conns[reusable_id];
    CHECK_EQ(after->state, ConnState::ReadingHeader);
    CHECK_EQ(after->on_recv, &on_header_received<SmallLoop>);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 1u);
}

TEST(unmatched_local_response,
     representation200_runtime_wire_partial_send_accounting_and_fail_closed_boundaries) {
    SmallLoop loop;
    loop.setup();
    ShardMetrics metrics{};
    metrics.init();
    AccessLogRing access{};
    access.init();
    CaptureRing capture{};
    capture.init();
    ShardEpoch epoch{};
    loop.metrics = &metrics;
    loop.access_log = &access;
    loop.epoch = &epoch;
    REQUIRE(loop.set_capture(&capture));

    RouteConfig config{};
    const auto policy = make_representation200_policy();
    REQUIRE_EQ(config.add_strict_local_response_policy(policy), 1u);
    REQUIRE(config.set_unmatched_policy_id(kRouteMethodAny, 1));
    REQUIRE(config.unmatched_policy_table_is_valid());
    const RouteConfig* active = &config;
    loop.config_ptr = &active;

    Connection* conn = loop.alloc_conn();
    REQUIRE(conn != nullptr);
    conn->fd = 42;
    const u32 conn_id = conn->id;
    static constexpr char kKeepAlive[] = "GET /miss HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(
        conn->recv_buf.write(reinterpret_cast<const u8*>(kKeepAlive), sizeof(kKeepAlive) - 1),
        sizeof(kKeepAlive) - 1);
    on_header_received<SmallLoop>(
        &loop,
        *conn,
        make_ev(conn_id, IoEventType::Recv, static_cast<i32>(sizeof(kKeepAlive) - 1)));
    REQUIRE_EQ(conn->resp_status, 200u);
    REQUIRE(conn->keep_alive);
    CHECK(conn->request_config == &config);
    CHECK_EQ(conn->upstream_fd, -1);
    CHECK_FALSE(conn->upstream_slot_held);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    CHECK_EQ(metrics.requests_total, 0u);
    CHECK_EQ(access.available(), 0u);
    CHECK_EQ(capture.available(), 0u);
    CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), 1u);

    u8 normalized[SmallLoop::kBufSize]{};
    const u32 first_wire_len = conn->send_buf.len();
    REQUIRE(first_wire_len <= sizeof(normalized));
    __builtin_memcpy(normalized, conn->send_buf.data(), first_wire_len);
    REQUIRE(normalize_redirect_date(normalized, first_wire_len));
    const std::string expected_keepalive = expected_representation200_wire(true, false);
    REQUIRE_EQ(first_wire_len, static_cast<u32>(expected_keepalive.size()));
    CHECK_EQ(__builtin_memcmp(normalized, expected_keepalive.data(), expected_keepalive.size()), 0);

    // Neither a partial completion nor its continuation may publish accounting.
    static constexpr u32 kFirstPartial = 7;
    REQUIRE_GT(first_wire_len, kFirstPartial);
    loop.inject_and_dispatch(make_ev(conn_id, IoEventType::Send, kFirstPartial));
    CHECK_EQ(metrics.requests_total, 0u);
    CHECK_EQ(access.available(), 0u);
    CHECK_EQ(capture.available(), 0u);
    CHECK_EQ(conn->send_progress, kFirstPartial);
    const MockOp* remainder = loop.backend.last_op(MockOp::Send);
    REQUIRE(remainder != nullptr);
    CHECK_EQ(remainder->send_len, first_wire_len - kFirstPartial);
    CHECK_EQ(remainder->send_buf, conn->send_buf.data() + kFirstPartial);
    loop.inject_and_dispatch(
        make_ev(conn_id, IoEventType::Send, static_cast<i32>(first_wire_len - kFirstPartial)));
    REQUIRE_EQ(conn->state, ConnState::ReadingHeader);
    CHECK_EQ(metrics.requests_total, 1u);
    CHECK_EQ(metrics.requests_active, 0u);
    CHECK_EQ(access.available(), 1u);
    CHECK_EQ(capture.available(), 1u);
    CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), 2u);

    // The same connection's explicit-close successor uses the same owned
    // profile, publishes once, then reaches the real close lifecycle.
    static constexpr char kClose[] =
        "GET /miss?second=1 HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kClose), sizeof(kClose) - 1),
               sizeof(kClose) - 1);
    on_header_received<SmallLoop>(
        &loop, *conn, make_ev(conn_id, IoEventType::Recv, static_cast<i32>(sizeof(kClose) - 1)));
    REQUIRE_EQ(conn->resp_status, 200u);
    REQUIRE_FALSE(conn->keep_alive);
    const u32 second_wire_len = conn->send_buf.len();
    REQUIRE(second_wire_len <= sizeof(normalized));
    __builtin_memcpy(normalized, conn->send_buf.data(), second_wire_len);
    REQUIRE(normalize_redirect_date(normalized, second_wire_len));
    const std::string expected_close = expected_representation200_wire(false, false);
    REQUIRE_EQ(second_wire_len, static_cast<u32>(expected_close.size()));
    CHECK_EQ(__builtin_memcmp(normalized, expected_close.data(), expected_close.size()), 0);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    loop.inject_and_dispatch(
        make_ev(conn_id, IoEventType::Send, static_cast<i32>(second_wire_len)));
    CHECK_EQ(loop.free_top, SmallLoop::kMaxConns);
    CHECK_EQ(metrics.requests_total, 2u);
    CHECK_EQ(metrics.requests_active, 0u);
    CHECK_EQ(access.available(), 2u);
    CHECK_EQ(capture.available(), 2u);
    CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), 4u);

    for (const u8 expected_method :
         {static_cast<u8>(LogHttpMethod::Get), static_cast<u8>(LogHttpMethod::Get)}) {
        AccessLogEntry entry{};
        REQUIRE(access.pop(entry));
        CHECK_EQ(entry.status, 200u);
        CHECK_EQ(entry.method, expected_method);
    }
    for (u32 i = 0; i < 2; i++) {
        CaptureEntry entry{};
        REQUIRE(capture.pop(entry));
        CHECK_EQ(entry.resp_status, 200u);
        CHECK_EQ(entry.method, static_cast<u8>(LogHttpMethod::Get));
        CHECK_GT(entry.raw_header_len, 0u);
    }

    // HEAD retains representation length but publishes no body. Bodyless POST
    // and origin-form OPTIONS both publish the representation, matching the
    // pinned nginx profile without entering upstream selection.
    struct MethodCase {
        const char* request;
        LogHttpMethod method;
        bool suppress_body;
    };
    const MethodCase methods[] = {
        {"HEAD /miss HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n", LogHttpMethod::Head, true},
        {"POST /miss HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n", LogHttpMethod::Post, false},
        {"OPTIONS /miss HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n",
         LogHttpMethod::Options,
         false},
    };
    for (const auto& test : methods) {
        loop.backend.clear_ops();
        Connection* method_conn = dispatch_unmatched_request(loop, config, test.request);
        REQUIRE(method_conn != nullptr);
        CHECK_EQ(method_conn->resp_status, 200u);
        CHECK_EQ(method_conn->req_method, static_cast<u8>(test.method));
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
        const u32 wire_len = method_conn->send_buf.len();
        REQUIRE(wire_len <= sizeof(normalized));
        __builtin_memcpy(normalized, method_conn->send_buf.data(), wire_len);
        REQUIRE(normalize_redirect_date(normalized, wire_len));
        const std::string expected = expected_representation200_wire(false, test.suppress_body);
        REQUIRE_EQ(wire_len, static_cast<u32>(expected.size()));
        CHECK_EQ(__builtin_memcmp(normalized, expected.data(), expected.size()), 0);
        loop.inject_and_dispatch(
            make_ev(method_conn->id, IoEventType::Send, static_cast<i32>(wire_len)));
    }

    auto closes_before_bytes = [&](RouteConfig& candidate, const char* request) {
        loop.backend.clear_ops();
        const u32 free_before = loop.free_top;
        (void)dispatch_unmatched_request(loop, candidate, request);
        CHECK_EQ(loop.free_top, free_before);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    };
    closes_before_bytes(config, "GET /miss HTTP/1.0\r\nHost: x\r\n\r\n");

    RouteConfig forged{};
    REQUIRE_EQ(forged.add_strict_local_response_policy(policy), 1u);
    REQUIRE(forged.set_unmatched_policy_id(kRouteMethodAny, 1));
    forged.strict_local_response_policies[0].head_mode = StrictLocalResponseHeadMode::Reject;
    closes_before_bytes(forged, "GET /miss HTTP/1.1\r\nHost: x\r\n\r\n");
}

namespace {
struct StrictLocalSendFailureLoop : SmallLoop {
    u32 close_calls = 0;
    bool close_during_submit = false;
    bool close_saw_request_inflight = false;
    const RouteConfig* close_saw_request_config = nullptr;
    ConnState close_saw_state = ConnState::ReadingHeader;
    u32 close_saw_send_len = 0;
    u32 close_saw_send_progress = 0;
    u32 close_saw_completed_requests = 0;
    u32 close_saw_capture_header_len = 0;

    bool submit_send(Connection& conn, const u8* buf, u32 len) {
        if (close_during_submit) {
            close_conn(conn);
            return false;
        }
        return SmallLoop::submit_send_impl(conn, buf, len);
    }

    void close_conn(Connection& conn) {
        close_calls++;
        close_saw_request_inflight = conn.req_start_us != 0;
        close_saw_request_config = conn.request_config;
        close_saw_state = conn.state;
        close_saw_send_len = conn.send_buf.len();
        close_saw_send_progress = conn.send_progress;
        close_saw_completed_requests = conn.downstream_completed_request_count;
        close_saw_capture_header_len = conn.capture_header_len;
        SmallLoop::close_conn_impl(conn);
    }
};

bool configure_strict_local_send_failure_loop(StrictLocalSendFailureLoop& loop,
                                              ShardMetrics& metrics,
                                              AccessLogRing& access,
                                              CaptureRing& capture,
                                              ShardEpoch& epoch,
                                              const RouteConfig*& active,
                                              RouteConfig& config,
                                              bool no_content204 = false) {
    loop.setup();
    metrics.init();
    access.init();
    capture.init();
    loop.metrics = &metrics;
    loop.access_log = &access;
    loop.epoch = &epoch;
    if (!loop.set_capture(&capture)) return false;
    const auto policy =
        no_content204 ? make_no_content204_policy() : make_representation200_policy();
    if (config.add_strict_local_response_policy(policy) != 1u ||
        !config.set_unmatched_policy_id(kRouteMethodAny, 1) ||
        !config.unmatched_policy_table_is_valid())
        return false;
    active = &config;
    loop.config_ptr = &active;
    return true;
}
}  // namespace

TEST(unmatched_local_response,
     no_content204_synchronous_initial_and_partial_resubmit_failures_publish_no_success) {
    auto run = [&](bool fail_resubmit) {
        StrictLocalSendFailureLoop loop;
        ShardMetrics metrics{};
        AccessLogRing access{};
        CaptureRing capture{};
        ShardEpoch epoch{};
        RouteConfig config{};
        const RouteConfig* active = nullptr;
        REQUIRE(configure_strict_local_send_failure_loop(
            loop, metrics, access, capture, epoch, active, config, true));
        REQUIRE_EQ(strict_local_response_policy_profile(config.strict_local_response_policies[0]),
                   StrictLocalResponseProfile::NoContent204);

        Connection* conn = loop.alloc_conn();
        REQUIRE(conn != nullptr);
        conn->fd = fail_resubmit ? 47 : 46;
        metrics.on_accept();
        static constexpr char kRequest[] = "GET /miss HTTP/1.1\r\nHost: x\r\n\r\n";
        REQUIRE_EQ(
            conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
            sizeof(kRequest) - 1);
        const u32 conn_id = conn->id;
        const u32 free_before = loop.free_top;
        loop.backend.clear_ops();
        loop.backend.fail_send = !fail_resubmit;
        on_header_received<StrictLocalSendFailureLoop>(
            &loop,
            *conn,
            make_ev(conn_id, IoEventType::Recv, static_cast<i32>(sizeof(kRequest) - 1)));

        if (fail_resubmit) {
            REQUIRE_EQ(loop.close_calls, 0u);
            REQUIRE_EQ(conn->resp_status, 204u);
            const u32 wire_len = conn->send_buf.len();
            REQUIRE_GT(wire_len, 7u);
            u8 normalized[SmallLoop::kBufSize]{};
            __builtin_memcpy(normalized, conn->send_buf.data(), wire_len);
            REQUIRE(normalize_strict_local_response_date(normalized, wire_len));
            const auto expected =
                expected_no_content204_wire(config.strict_local_response_policies[0].server, true);
            REQUIRE_EQ(wire_len, expected.size());
            CHECK_EQ(__builtin_memcmp(normalized, expected.data(), wire_len), 0);
            loop.backend.clear_ops();
            loop.backend.fail_send = true;
            on_response_sent<StrictLocalSendFailureLoop>(
                &loop, *conn, make_ev(conn_id, IoEventType::Send, 7));
        }

        CHECK_EQ(loop.close_calls, 1u);
        CHECK(loop.close_saw_request_inflight);
        CHECK(loop.close_saw_request_config == &config);
        CHECK_EQ(loop.close_saw_state, ConnState::Sending);
        CHECK_GT(loop.close_saw_send_len, 0u);
        CHECK_EQ(loop.close_saw_send_progress, fail_resubmit ? 7u : 0u);
        CHECK_EQ(loop.free_top, free_before + 1u);
        CHECK_EQ(loop.conns[conn_id].fd, -1);
        CHECK_EQ(loop.conns[conn_id].request_config, nullptr);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
        CHECK_EQ(metrics.requests_total, 0u);
        CHECK_EQ(metrics.requests_active, 0u);
        CHECK_EQ(access.available(), 0u);
        CHECK_EQ(capture.available(), 0u);
        CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), 2u);
    };
    run(false);
    run(true);
}

TEST(unmatched_local_response,
     synchronous_initial_send_failure_closes_without_success_publication_or_stale_ownership) {
    StrictLocalSendFailureLoop loop;
    ShardMetrics metrics{};
    AccessLogRing access{};
    CaptureRing capture{};
    ShardEpoch epoch{};
    RouteConfig config{};
    const RouteConfig* active = nullptr;
    REQUIRE(configure_strict_local_send_failure_loop(
        loop, metrics, access, capture, epoch, active, config));

    Connection* conn = loop.alloc_conn();
    REQUIRE(conn != nullptr);
    conn->fd = 42;
    conn->downstream_completed_request_count = 7;
    metrics.on_accept();
    static constexpr char kRequest[] = "GET /miss HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);
    const u32 conn_id = conn->id;
    const u32 free_before = loop.free_top;
    loop.backend.clear_ops();
    loop.backend.fail_send = true;

    on_header_received<StrictLocalSendFailureLoop>(
        &loop, *conn, make_ev(conn_id, IoEventType::Recv, static_cast<i32>(sizeof(kRequest) - 1)));

    CHECK_EQ(loop.close_calls, 1u);
    CHECK(loop.close_saw_request_inflight);
    CHECK(loop.close_saw_request_config == &config);
    CHECK_EQ(loop.close_saw_state, ConnState::Sending);
    CHECK_GT(loop.close_saw_send_len, 0u);
    CHECK_EQ(loop.close_saw_send_progress, 0u);
    CHECK_EQ(loop.close_saw_completed_requests, 7u);
    CHECK_GT(loop.close_saw_capture_header_len, 0u);
    CHECK_EQ(loop.free_top, free_before + 1u);
    CHECK_EQ(loop.conns[conn_id].fd, -1);
    CHECK_EQ(loop.conns[conn_id].on_send, nullptr);
    CHECK_EQ(loop.conns[conn_id].request_config, nullptr);
    CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
    CHECK_EQ(loop.backend.count_ops(MockOp::Connect), 0u);
    CHECK_EQ(metrics.requests_total, 0u);
    CHECK_EQ(metrics.requests_active, 0u);
    CHECK_EQ(metrics.connections_closed, 1u);
    CHECK_EQ(metrics.connections_active, 0u);
    CHECK_EQ(access.available(), 0u);
    CHECK_EQ(capture.available(), 0u);
    CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), 2u);

    // A late completion cannot repeat closure or accounting after the slot was
    // terminally returned and reset.
    loop.backend.fail_send = false;
    loop.inject_and_dispatch(make_ev(conn_id, IoEventType::Send, 1));
    CHECK_EQ(loop.close_calls, 1u);
    CHECK_EQ(metrics.connections_closed, 1u);
    CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), 2u);
}

