// === Coverage: epoll_event_loop init and helpers ===

TEST(epoll_loop, init_success) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    // Test init with invalid fd (still succeeds for init path)
    auto res = loop->init(0, -1, 0);
    CHECK(res.has_value());
    CHECK_EQ(loop->shard_id, 0u);
    CHECK_EQ(loop->free_top, EpollEventLoop::kMaxConns);
    CHECK_EQ(loop->keepalive_timeout, EpollEventLoop::kDefaultKeepaliveTimeout);
    CHECK_EQ(loop->active_count(), 0u);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(epoll_loop, alloc_free_conn) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    CHECK(c->recv_slice != nullptr);
    CHECK(c->send_slice != nullptr);
    CHECK_EQ(loop->active_count(), 1u);
    loop->free_conn(*c);
    CHECK_EQ(loop->active_count(), 0u);
    loop->shutdown();
    destroy_real_loop(loop);
}

// close_conn must drop any in-flight partial-send bookkeeping so a reused
// conn_id + fd number cannot resurrect a stale send. Without this, pause_recv /
// add_recv would match the leftover entry (remaining > 0 && ss.fd == fd), arm
// EPOLLOUT, and send from the dangling ss.src into the new connection's fd.
TEST(epoll_loop, close_clears_partial_send_state) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    const u32 cid = c->id;
    c->fd = -1;  // no real socket to ::close

    // Simulate a partial client→upstream and upstream→client send still recorded
    // when the connection closes.
    loop->backend.send_state[cid] = {
        reinterpret_cast<const u8*>(0x1000), 7, 0, 16, IoEventType::Send, false, 0};
    loop->backend.upstream_send_state[cid] = {reinterpret_cast<const u8*>(0x2000),
                                              9,
                                              0,
                                              16,
                                              IoEventType::UpstreamSend,
                                              false,
                                              0,
                                              c->upstream_episode};

    loop->close_conn(*c);

    CHECK_EQ(loop->backend.send_state[cid].remaining, 0u);
    CHECK_EQ(loop->backend.send_state[cid].fd, -1);
    CHECK(loop->backend.send_state[cid].src == nullptr);
    CHECK_EQ(loop->backend.upstream_send_state[cid].remaining, 0u);
    CHECK_EQ(loop->backend.upstream_send_state[cid].fd, -1);
    CHECK(loop->backend.upstream_send_state[cid].src == nullptr);

    loop->shutdown();
    destroy_real_loop(loop);
}

// ws_unpoll_upstream must remove the upstream fd from the epoll set so a hung-up
// backend (EPOLLHUP is delivered even with the interest mask zeroed) stops waking
// the level-triggered loop during a slow pre-tunnel 101 drain. A control fd kept
// readable guarantees wait() returns promptly instead of blocking on the -1
// timeout, keeping the test from hanging.
TEST(epoll_loop, ws_unpoll_upstream_deregisters_upstream_fd) {
    struct Cleanup {
        RealLoop* loop = nullptr;
        bool initialized = false;
        Connection* upstream = nullptr;
        Connection* control = nullptr;
        i32 upstream_peer = -1;
        i32 control_peer = -1;

        ~Cleanup() {
            if (initialized) {
                if (upstream) loop->close_conn(*upstream);
                if (control) loop->close_conn(*control);
                loop->shutdown();
            }
            if (upstream_peer >= 0) close(upstream_peer);
            if (control_peer >= 0) close(control_peer);
            destroy_real_loop(loop);
        }
    } cleanup;

    cleanup.loop = create_real_loop();
    auto* loop = cleanup.loop;
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    cleanup.initialized = res.has_value();
    REQUIRE(cleanup.initialized);
    struct itimerspec disarmed_timer{};
    REQUIRE_EQ(timerfd_settime(loop->backend.timer_fd, 0, &disarmed_timer, nullptr), 0);
    auto* up = loop->alloc_conn();
    cleanup.upstream = up;
    REQUIRE(up != nullptr);
    auto* ctl = loop->alloc_conn();
    cleanup.control = ctl;
    REQUIRE(ctl != nullptr);
    const u32 up_cid = up->id;
    const u32 active_episode = up->upstream_episode;

    i32 ufds[2] = {-1, -1};
    i32 cfds[2] = {-1, -1};
    REQUIRE(socketpair(AF_UNIX, SOCK_STREAM, 0, ufds) == 0);
    up->upstream_fd = ufds[0];
    cleanup.upstream_peer = ufds[1];
    REQUIRE(socketpair(AF_UNIX, SOCK_STREAM, 0, cfds) == 0);
    ctl->fd = cfds[0];
    cleanup.control_peer = cfds[1];

    REQUIRE(loop->begin_upstream_episode(*up));
    REQUIRE(loop->backend.add_recv_upstream(ufds[0], up_cid, active_episode));
    REQUIRE(loop->backend.add_recv(cfds[0], ctl->id));
    REQUIRE_EQ(loop->backend.active_upstream_episode[up_cid], active_episode);
    REQUIRE_EQ(loop->backend.upstream_fd_map[up_cid], ufds[0]);

    close(cleanup.upstream_peer);  // upstream peer closes → fd reports EPOLLHUP
    cleanup.upstream_peer = -1;
    struct pollfd upstream_ready{ufds[0], POLLIN, 0};
    REQUIRE_EQ(poll(&upstream_ready, 1, 1000), 1);
    REQUIRE((upstream_ready.revents & POLLHUP) != 0);

    loop->ws_unpoll_upstream(*up);
    CHECK_EQ(loop->backend.active_upstream_episode[up_cid], active_episode);
    CHECK_EQ(loop->backend.upstream_fd_map[up_cid], ufds[0]);

    const u8 one = 'x';
    REQUIRE(write(cfds[1], &one, 1) == 1);  // keep wait() non-blocking
    IoEvent events[16];
    u32 n = loop->backend.wait(events, 16, loop->conns, RealLoop::kMaxConns);
    bool saw_upstream = false, saw_ctl = false;
    for (u32 i = 0; i < n; i++) {
        if (events[i].conn_id == up_cid && events[i].type == IoEventType::UpstreamRecv)
            saw_upstream = true;
        if (events[i].conn_id == ctl->id && events[i].type == IoEventType::Recv) saw_ctl = true;
    }
    CHECK(saw_ctl);        // wait() ran and returned the ready control fd
    CHECK(!saw_upstream);  // the hung-up upstream fd was deregistered, no spin
    CHECK_EQ(loop->backend.active_upstream_episode[up_cid], active_episode);
    CHECK_EQ(loop->backend.upstream_fd_map[up_cid], ufds[0]);
    struct pollfd epoll_ready{loop->backend.epoll_fd, POLLIN, 0};
    CHECK_EQ(poll(&epoll_ready, 1, 0), 0);  // no deferred HUP remains after control recv

    // Production teardown detaches the already-unpolled fd, retires its owner,
    // and closes it before the Connection slot is released.
    REQUIRE(loop->detach_upstream_close(*up));
    REQUIRE_EQ(up->upstream_fd, -1);
    REQUIRE_EQ(up->upstream_episode, active_episode + 1);
    REQUIRE_EQ(loop->backend.active_upstream_episode[up_cid], 0u);
    REQUIRE_EQ(loop->backend.upstream_fd_map[up_cid], -1);

    // No-op when production lifecycle teardown has removed the upstream fd.
    const u32 retired_episode = up->upstream_episode;
    loop->ws_unpoll_upstream(*up);
    CHECK_EQ(up->upstream_episode, retired_episode);
    CHECK_EQ(loop->backend.active_upstream_episode[up_cid], 0u);
    CHECK_EQ(loop->backend.upstream_fd_map[up_cid], -1);
}

// Re-arming a recv must preserve a pending opposite-direction send's EPOLLOUT on
// the same fd (full-duplex tunnel backpressure). Drive the send to completion to
// prove the EPOLLOUT survived the re-arm; also exercise the TLS-pending branches.
// Pre-tunnel backend EOF on the real epoll loop: records the deferred close and
// deregisters the upstream fd (exercises ws_stop_upstream_poll's epoll branch).
#if RUT_ENABLE_WEBSOCKET
TEST(epoll_loop, ws_pre_tunnel_backend_eof_defers_and_deregisters) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);

    i32 fds[2];
    REQUIRE(socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == 0);
    c->upstream_fd = fds[0];
    REQUIRE(loop->backend.add_recv_upstream(fds[0], c->id, c->upstream_episode));

    on_ws_pre_tunnel_upstream_recv<RealLoop>(
        loop, *c, make_ev(c->id, IoEventType::UpstreamRecv, 0));
    CHECK(c->ws_pre_tunnel_upstream_closed);  // deferred, flag recorded

    close(fds[0]);
    close(fds[1]);
    c->upstream_fd = -1;
    loop->free_conn(*c);
    loop->shutdown();
    destroy_real_loop(loop);
}
#endif  // RUT_ENABLE_WEBSOCKET

TEST(epoll_loop, add_recv_preserves_pending_send_epollout) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    const u32 cid = c->id;

    i32 dfds[2], ufds[2];
    REQUIRE(socketpair(AF_UNIX, SOCK_STREAM, 0, dfds) == 0);
    REQUIRE(socketpair(AF_UNIX, SOCK_STREAM, 0, ufds) == 0);
    c->fd = dfds[0];
    c->upstream_fd = ufds[0];

    // Downstream: an upstream→client send is pending on the client fd. Re-arming
    // the client recv must keep EPOLLOUT so the send still drains.
    REQUIRE(loop->backend.add_recv(dfds[0], cid));
    static const u8 down[] = {'P', 'O', 'N', 'G'};
    loop->backend.send_state[cid] = {down, dfds[0], 0, sizeof(down), IoEventType::Send, false, 0};
    REQUIRE(loop->backend.add_recv(dfds[0], cid));
    IoEvent ev[8];
    u32 n = loop->backend.wait(ev, 8, loop->conns, RealLoop::kMaxConns);
    bool saw_send = false;
    for (u32 i = 0; i < n; i++)
        if (ev[i].conn_id == cid && ev[i].type == IoEventType::Send) saw_send = true;
    CHECK(saw_send);  // EPOLLOUT preserved across the recv re-arm
    u8 rb[8];
    CHECK_EQ(recv(dfds[1], rb, sizeof(rb), MSG_DONTWAIT), static_cast<ssize_t>(sizeof(down)));

    // Upstream: symmetric — a client→upstream send pending on the upstream fd.
    REQUIRE(loop->begin_upstream_episode(*c));
    REQUIRE(loop->backend.add_recv_upstream(ufds[0], cid, loop->conns[cid].upstream_episode));
    static const u8 up[] = {'P', 'I', 'N', 'G'};
    loop->backend.upstream_send_state[cid] = {up,
                                              ufds[0],
                                              0,
                                              sizeof(up),
                                              IoEventType::UpstreamSend,
                                              false,
                                              0,
                                              loop->conns[cid].upstream_episode};
    REQUIRE(loop->backend.add_recv_upstream(ufds[0], cid, loop->conns[cid].upstream_episode));
    n = loop->backend.wait(ev, 8, loop->conns, RealLoop::kMaxConns);
    bool saw_usend = false;
    for (u32 i = 0; i < n; i++)
        if (ev[i].conn_id == cid && ev[i].type == IoEventType::UpstreamSend) saw_usend = true;
    CHECK(saw_usend);
    CHECK_EQ(recv(ufds[1], rb, sizeof(rb), MSG_DONTWAIT), static_cast<ssize_t>(sizeof(up)));

    // TLS-pending sub-branches: WANT_READ keeps EPOLLIN only, WANT_WRITE adds
    // EPOLLOUT. Just exercise the re-arm paths (no SSL drive).
    loop->backend.send_state[cid] = {
        down, dfds[0], 0, sizeof(down), IoEventType::Send, true, EPOLLIN};
    CHECK(loop->backend.add_recv(dfds[0], cid));
    loop->backend.send_state[cid] = {
        down, dfds[0], 0, sizeof(down), IoEventType::Send, true, EPOLLOUT};
    CHECK(loop->backend.add_recv(dfds[0], cid));
    loop->backend.upstream_send_state[cid] = {up,
                                              ufds[0],
                                              0,
                                              sizeof(up),
                                              IoEventType::UpstreamSend,
                                              true,
                                              EPOLLIN,
                                              loop->conns[cid].upstream_episode};
    CHECK(loop->backend.add_recv_upstream(ufds[0], cid, loop->conns[cid].upstream_episode));

    loop->backend.clear_send_state(cid);
    close(dfds[0]);
    close(dfds[1]);
    close(ufds[0]);
    close(ufds[1]);
    c->fd = -1;
    c->upstream_fd = -1;
    loop->free_conn(*c);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(epoll_loop, upstream_recv_registration_failure_queues_local_error) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    const u32 cid = c->id;

    i32 fds[2];
    REQUIRE(socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == 0);
    c->upstream_fd = fds[0];

    // Leave exactly one completion slot for the registration-failure event;
    // older entries must remain intact.
    for (u32 i = 0; i < EpollBackend::kPendingCap - 1; i++) {
        loop->backend.pending_completions[i] = {
            700u + i, static_cast<i32>(i), 0, 0, IoEventType::Recv, 0, 0, 0};
    }
    loop->backend.pending_count = EpollBackend::kPendingCap - 1;

    close(loop->backend.epoll_fd);
    loop->backend.epoll_fd = -1;
    CHECK(loop->backend.add_recv_upstream(fds[0], cid, loop->conns[cid].upstream_episode));
    REQUIRE_EQ(loop->backend.pending_count, EpollBackend::kPendingCap);
    CHECK_EQ(loop->backend.pending_completions[62].conn_id, 762u);
    CHECK_EQ(loop->backend.pending_completions[63].conn_id, cid);
    CHECK_EQ(loop->backend.pending_completions[63].type, IoEventType::UpstreamRecv);
    CHECK_LT(loop->backend.pending_completions[63].result, 0);
    CHECK_EQ(loop->backend.pending_completions[63].aux, kLocalSubmitFailureAux);
    CHECK_EQ(loop->backend.upstream_fd_map[cid], -1);

    close(fds[0]);
    close(fds[1]);
    c->upstream_fd = -1;
    loop->free_conn(*c);
    loop->shutdown();
    destroy_real_loop(loop);
}

