TEST(epoll_loop, epoch_enter_leave) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());
    // Without epoch wired, no-op
    loop->epoch_enter();
    loop->epoch_leave();
    // Wire epoch
    ShardEpoch epoch{};
    epoch.epoch.store(0, std::memory_order_relaxed);
    loop->epoch = &epoch;
    loop->epoch_enter();
    CHECK_EQ(epoch.epoch.load(std::memory_order_relaxed), 1u);
    loop->epoch_leave();
    CHECK_EQ(epoch.epoch.load(std::memory_order_relaxed), 2u);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(epoll_loop, poll_command_config_swap) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());
    // Without control, no-op
    loop->poll_command();

    // Wire control block
    ShardControlBlock ctrl{};
    RouteConfig cfg{};
    const RouteConfig* cfg_ptr = nullptr;
    loop->control = &ctrl;
    loop->config_ptr = &cfg_ptr;
    ctrl.pending_config.store(&cfg, std::memory_order_relaxed);
    loop->poll_command();
    CHECK_EQ(cfg_ptr, &cfg);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(epoll_episode, invalid_upstream_registration_has_no_side_effects) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    const auto before = backend.upstream_send_state[0];
    const u32 pending_before = backend.pending_count;
    CHECK_FALSE(backend.add_recv_upstream(-1, 0, 0));
    CHECK_FALSE(backend.add_send_upstream(-1, 0, nullptr, 1, kInvalidUpstreamEventEpisode));
    CHECK_FALSE(backend.add_connect(-1, 0, nullptr, 0, 0));
    CHECK_EQ(backend.upstream_fd_map[0], -1);
    CHECK_EQ(backend.pending_count, pending_before);
    CHECK_EQ(backend.upstream_send_state[0].src, before.src);
    CHECK_EQ(backend.upstream_send_state[0].upstream_episode, before.upstream_episode);
    backend.pause_upstream_recv(0, 0, true);
    backend.quiesce_recv(0, true, kInvalidUpstreamEventEpisode);
    CHECK_EQ(backend.upstream_fd_map[0], -1);
    backend.shutdown();
}

TEST(epoll_episode_lifecycle, clean_begin_and_strict_preconditions) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    Connection conn{};
    conn.reset();
    conn.id = 7;
    conn.upstream_episode = 1;

    CHECK(backend.begin_upstream_episode(conn.id, conn.upstream_episode));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 1u);
    CHECK_FALSE(backend.begin_upstream_episode(conn.id, conn.upstream_episode));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 1u);

    // Only a backend rebuild clears the ownership table. A live slot release
    // quarantines nonzero ownership instead of rewinding it.
    backend.shutdown();
    REQUIRE(backend.init(0, -1).has_value());
    CHECK_FALSE(backend.begin_upstream_episode(EpollBackend::kMaxFdMap, 1));
    CHECK_FALSE(backend.begin_upstream_episode(conn.id, 0));
    CHECK_FALSE(backend.begin_upstream_episode(conn.id, kInvalidUpstreamEventEpisode));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 0u);

    backend.upstream_fd_map[conn.id] = 123;
    CHECK_FALSE(backend.begin_upstream_episode(conn.id, 1));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 0u);
    backend.upstream_fd_map[conn.id] = -1;

    static const u8 payload[] = {'d', 'i', 'r', 't', 'y'};
    backend.upstream_send_state[conn.id] = {payload,
                                            123,
                                            0,
                                            sizeof(payload),
                                            IoEventType::UpstreamSend,
                                            false,
                                            0,
                                            conn.upstream_episode};
    CHECK_FALSE(backend.begin_upstream_episode(conn.id, 1));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 0u);
    backend.clear_send_state(conn.id);

    CHECK(backend.begin_upstream_episode(conn.id, conn.upstream_episode));
    CHECK_EQ(backend.active_upstream_episode[conn.id], conn.upstream_episode);
    backend.shutdown();
    REQUIRE(backend.init(0, -1).has_value());
    CHECK_EQ(backend.active_upstream_episode[conn.id], 0u);
    backend.shutdown();
}

TEST(epoll_episode_lifecycle, retire_requires_matching_detached_current_state) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    Connection conn{};
    conn.reset();
    conn.id = 3;
    conn.upstream_episode = 9;
    REQUIRE(backend.begin_upstream_episode(conn.id, conn.upstream_episode));

    CHECK_FALSE(backend.retire_upstream_episode_after_detach(conn, 8));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 9u);
    CHECK_EQ(conn.upstream_episode, 9u);

    backend.active_upstream_episode[conn.id] = 10;
    CHECK_FALSE(backend.retire_upstream_episode_after_detach(conn, 9));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 10u);
    CHECK_EQ(conn.upstream_episode, 9u);
    backend.active_upstream_episode[conn.id] = 9;

    backend.upstream_fd_map[conn.id] = 456;
    CHECK_FALSE(backend.retire_upstream_episode_after_detach(conn, 9));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 9u);
    CHECK_EQ(conn.upstream_episode, 9u);
    backend.upstream_fd_map[conn.id] = -1;

    static const u8 payload[] = {'s', 't', 'a', 'l', 'e'};
    backend.upstream_send_state[conn.id] = {
        payload, 456, 0, sizeof(payload), IoEventType::UpstreamSend, false, 0, 9};
    CHECK_FALSE(backend.retire_upstream_episode_after_detach(conn, 9));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 9u);
    CHECK_EQ(conn.upstream_episode, 9u);
    CHECK_EQ(backend.upstream_send_state[conn.id].upstream_episode, 9u);
    backend.clear_send_state(conn.id);

    CHECK(backend.retire_upstream_episode_after_detach(conn, 9));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 0u);
    CHECK_EQ(conn.upstream_episode, 10u);
    CHECK_FALSE(backend.retire_upstream_episode_after_detach(conn, 9));
    CHECK_EQ(backend.active_upstream_episode[conn.id], 0u);
    CHECK_EQ(conn.upstream_episode, 10u);

    // A reset is not allowed to rewind the generation token.
    conn.reset();
    CHECK_EQ(conn.upstream_episode, 10u);
    CHECK_EQ(backend.active_upstream_episode[conn.id], 0u);
    backend.shutdown();
}

TEST(epoll_episode_lifecycle, unexpected_del_failure_closes_and_is_not_reusable) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    i32 fds[2] = {-1, -1};
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK, 0, fds), 0);

    Connection conn{};
    conn.reset();
    conn.id = 0;
    conn.upstream_episode = 1;
    REQUIRE(backend.begin_upstream_episode(conn.id, conn.upstream_episode));
    conn.upstream_fd = fds[0];
    backend.upstream_fd_map[conn.id] = fds[0];
    REQUIRE(backend.add_recv_upstream(fds[0], conn.id, conn.upstream_episode));
    conn.upstream_recv_armed = true;
    conn.upstream_send_armed = true;

    static const u8 payload[] = {'s', 't', 'a', 'l', 'e'};
    backend.upstream_send_state[conn.id] = {
        payload, fds[0], 0, sizeof(payload), IoEventType::UpstreamSend, false, 0, 1};

    // The injected failure is deterministic and occurs on the DEL itself,
    // after the fd has been registered in epoll.
    SyscallFaultConfig fault_config;
    fault_config.epoll_ctl_errno = EINVAL;
    fault_config.epoll_ctl_failures = 1;
    i32 detached_fd = 123;
    {
        ScopedSyscallFault fault(fault_config);
        CHECK_FALSE(backend.detach_upstream(conn, &detached_fd));
    }

    CHECK_EQ(detached_fd, -1);
    CHECK_EQ(conn.upstream_fd, -1);
    CHECK_FALSE(conn.upstream_recv_armed);
    CHECK_FALSE(conn.upstream_send_armed);
    CHECK_EQ(backend.upstream_fd_map[conn.id], -1);
    CHECK_EQ(backend.upstream_send_state[conn.id].src, nullptr);
    CHECK_EQ(backend.upstream_send_state[conn.id].fd, -1);
    CHECK_EQ(backend.upstream_send_state[conn.id].remaining, 0u);
    CHECK_EQ(backend.upstream_send_state[conn.id].upstream_episode, 0u);
    CHECK_EQ(backend.active_upstream_episode[conn.id], 0u);
    CHECK_EQ(conn.upstream_episode, 2u);
    errno = 0;
    CHECK_EQ(fcntl(fds[0], F_GETFD), -1);
    CHECK_EQ(errno, EBADF);
    fds[0] = -1;

    close(fds[1]);
    fds[1] = -1;
    backend.shutdown();
}

TEST(epoll_episode_lifecycle, already_unregistered_del_is_reusable) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    i32 fds[2] = {-1, -1};
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK, 0, fds), 0);

    Connection conn{};
    conn.reset();
    conn.id = 1;
    conn.upstream_episode = 3;
    REQUIRE(backend.begin_upstream_episode(conn.id, conn.upstream_episode));
    conn.upstream_fd = fds[0];
    backend.upstream_fd_map[conn.id] = fds[0];

    // This fd was never registered, so EPOLL_CTL_DEL reports ENOENT. That is
    // an already-detached state and remains eligible for pool ownership.
    i32 detached_fd = -1;
    CHECK(backend.detach_upstream(conn, &detached_fd));
    CHECK_EQ(detached_fd, fds[0]);
    CHECK_EQ(conn.upstream_fd, -1);
    CHECK_EQ(backend.upstream_fd_map[conn.id], -1);
    CHECK_EQ(backend.active_upstream_episode[conn.id], 0u);
    CHECK_EQ(conn.upstream_episode, 4u);
    CHECK_GE(fcntl(detached_fd, F_GETFD), 0);

    close(detached_fd);
    close(fds[1]);
    backend.shutdown();
}

TEST(epoll_episode_lifecycle, unexpected_del_and_close_failure_quarantines_slot) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    REQUIRE(loop->init(0, -1, 0).has_value());

    i32 fds[2] = {-1, -1};
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK, 0, fds), 0);
    auto* conn = loop->alloc_conn();
    REQUIRE(conn != nullptr);
    const u32 cid = conn->id;
    conn->upstream_episode = 1;
    REQUIRE(loop->begin_upstream_episode(*conn));
    conn->upstream_fd = fds[0];
    REQUIRE(loop->backend.add_recv_upstream(fds[0], cid, conn->upstream_episode));

    SyscallFaultConfig del_fault;
    del_fault.epoll_ctl_errno = EINVAL;
    del_fault.epoll_ctl_failures = 1;
    auto close_fault = rut::test_fault::io_fault_for_fd(fds[0]);
    close_fault.close_errno = EINTR;
    close_fault.close_failures = 1;
    i32 detached_fd = 123;
    {
        ScopedIoFault close_scope(close_fault);
        ScopedSyscallFault del_scope(del_fault);
        CHECK_FALSE(loop->detach_upstream_for_pool(*conn, detached_fd));
    }

    CHECK_EQ(detached_fd, -1);
    CHECK_EQ(conn->upstream_fd, -1);
    CHECK_EQ(loop->backend.upstream_fd_map[cid], -1);
    CHECK_EQ(loop->backend.active_upstream_episode[cid], EpollBackend::kUpstreamEpisodeExhausted);
    CHECK_EQ(conn->upstream_episode, 1u);
    CHECK_GE(fcntl(fds[0], F_GETFD), 0);

    // A later fd-less cleanup must not retire the quarantined owner or expose
    // the consumed descriptor to a pool caller.
    i32 second_detached_fd = 456;
    CHECK_FALSE(loop->detach_upstream_for_pool(*conn, second_detached_fd));
    CHECK_EQ(second_detached_fd, -1);
    CHECK_EQ(loop->backend.active_upstream_episode[cid], EpollBackend::kUpstreamEpisodeExhausted);
    CHECK_EQ(conn->upstream_episode, 1u);

    loop->free_conn(*conn);
    auto* reused = loop->alloc_conn();
    REQUIRE(reused != nullptr);
    CHECK_EQ(reused->id, cid);
    CHECK_EQ(loop->backend.active_upstream_episode[cid], EpollBackend::kUpstreamEpisodeExhausted);
    CHECK_FALSE(loop->begin_upstream_episode(*reused));
    loop->free_conn(*reused);

    // The injected close failure treats the descriptor as consumed, but this
    // test still owns the raw fd and can release it after the fault scope.
    close(fds[0]);
    close(fds[1]);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(epoll_episode_lifecycle, max_token_quarantines_without_wrap) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());

    Connection conn{};
    conn.reset();
    conn.id = 5;
    conn.upstream_episode = kIoUserDataMaxUpstreamEpisode;
    REQUIRE(backend.begin_upstream_episode(conn.id, conn.upstream_episode));

    // The max token cannot be reused safely. Retire must fail closed and
    // poison ownership, rather than silently wrapping to one.
    CHECK_FALSE(backend.retire_upstream_episode_after_detach(conn, kIoUserDataMaxUpstreamEpisode));
    CHECK_EQ(backend.active_upstream_episode[conn.id], EpollBackend::kUpstreamEpisodeExhausted);
    CHECK_EQ(conn.upstream_episode, kIoUserDataMaxUpstreamEpisode);
    CHECK_FALSE(backend.begin_upstream_episode(conn.id, conn.upstream_episode));
    CHECK_NE(backend.active_upstream_episode[conn.id], 0u);
    CHECK_NE(backend.active_upstream_episode[conn.id], 1u);

    // A non-max token still advances normally, including to the max token;
    // only retiring that final token quarantines ownership.
    Connection normal{};
    normal.reset();
    normal.id = 6;
    normal.upstream_episode = kIoUserDataMaxUpstreamEpisode - 1u;
    REQUIRE(backend.begin_upstream_episode(normal.id, normal.upstream_episode));
    CHECK(backend.retire_upstream_episode_after_detach(normal, kIoUserDataMaxUpstreamEpisode - 1u));
    CHECK_EQ(normal.upstream_episode, kIoUserDataMaxUpstreamEpisode);
    CHECK_EQ(backend.active_upstream_episode[normal.id], 0u);
    REQUIRE(backend.begin_upstream_episode(normal.id, normal.upstream_episode));
    CHECK_FALSE(
        backend.retire_upstream_episode_after_detach(normal, kIoUserDataMaxUpstreamEpisode));
    CHECK_EQ(normal.upstream_episode, kIoUserDataMaxUpstreamEpisode);
    CHECK_EQ(backend.active_upstream_episode[normal.id], EpollBackend::kUpstreamEpisodeExhausted);
    backend.shutdown();
}

TEST(epoll_episode_lifecycle, slot_release_quarantines_episode_owner) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    REQUIRE(loop->init(0, -1, 0).has_value());

    auto* inactive = loop->alloc_conn();
    REQUIRE(inactive != nullptr);
    const u32 inactive_id = inactive->id;
    CHECK_EQ(loop->backend.active_upstream_episode[inactive_id], 0u);

    auto* active = loop->alloc_conn();
    REQUIRE(active != nullptr);
    const u32 cid = active->id;
    active->upstream_episode = 17;
    REQUIRE(loop->begin_upstream_episode(*active));
    loop->free_conn(*active);
    CHECK_EQ(loop->backend.active_upstream_episode[cid], EpollBackend::kUpstreamEpisodeExhausted);

    auto* reused = loop->alloc_conn();
    REQUIRE(reused != nullptr);
    CHECK_EQ(reused->id, cid);
    CHECK_EQ(loop->backend.active_upstream_episode[cid], EpollBackend::kUpstreamEpisodeExhausted);
    CHECK_FALSE(loop->begin_upstream_episode(*reused));
    loop->free_conn(*reused);

    // Exhausted ownership is sticky across another ordinary free/reallocate
    // cycle, while a never-used slot remains inactive.
    auto* exhausted_again = loop->alloc_conn();
    REQUIRE(exhausted_again != nullptr);
    CHECK_EQ(exhausted_again->id, cid);
    CHECK_EQ(loop->backend.active_upstream_episode[cid], EpollBackend::kUpstreamEpisodeExhausted);
    loop->free_conn(*exhausted_again);

    // The never-used slot was held throughout the active slot's reuse cycle.
    CHECK_EQ(loop->backend.active_upstream_episode[inactive_id], 0u);
    loop->free_conn(*inactive);
    auto* inactive_reused = loop->alloc_conn();
    REQUIRE(inactive_reused != nullptr);
    CHECK_EQ(inactive_reused->id, inactive_id);
    CHECK_EQ(loop->backend.active_upstream_episode[inactive_id], 0u);
    loop->free_conn(*inactive_reused);

    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(epoll_episode_lifecycle, abnormal_nonzero_owner_is_quarantined_on_release) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    REQUIRE(loop->init(0, -1, 0).has_value());
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    const u32 cid = c->id;
    loop->backend.active_upstream_episode[cid] = 0x80000000u;
    loop->free_conn(*c);
    CHECK_EQ(loop->backend.active_upstream_episode[cid], EpollBackend::kUpstreamEpisodeExhausted);
    auto* reused = loop->alloc_conn();
    REQUIRE(reused != nullptr);
    CHECK_FALSE(loop->begin_upstream_episode(*reused));
    loop->free_conn(*reused);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(epoll_episode, stale_raw_recv_does_not_touch_buffer_and_current_token_recovers) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    i32 fds[2] = {-1, -1};
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK, 0, fds), 0);
    Connection conns[1]{};
    conns[0].reset();
    conns[0].id = 0;
    conns[0].upstream_episode = 2;
    u8 storage[64] = {};
    conns[0].upstream_recv_buf.bind(storage, sizeof(storage));
    REQUIRE(backend.begin_upstream_episode(0, 1));
    REQUIRE(backend.add_recv_upstream(fds[0], 0, 1));
    static constexpr char kBytes[] = "stale";
    REQUIRE_EQ(write(fds[1], kBytes, sizeof(kBytes) - 1), static_cast<ssize_t>(sizeof(kBytes) - 1));
    IoEvent events[2]{};
    CHECK_EQ(backend.wait(events, 2, conns, 1), 0u);
    CHECK_EQ(conns[0].upstream_recv_buf.len(), 0u);
    // The same registration is now current without an EPOLL_CTL_MOD.
    conns[0].upstream_episode = 1;
    const u32 n = backend.wait(events, 2, conns, 1);
    REQUIRE_EQ(n, 1u);
    CHECK_EQ(events[0].type, IoEventType::UpstreamRecv);
    CHECK_EQ(events[0].result, static_cast<i32>(sizeof(kBytes) - 1));
    CHECK_EQ(events[0].upstream_episode, 1u);
    CHECK_EQ(conns[0].upstream_recv_buf.len(), sizeof(kBytes) - 1);
    close(fds[0]);
    close(fds[1]);
    backend.shutdown();
}

TEST(epoll_episode, current_recv_drops_stale_send_interest_without_mutating_state) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    i32 fds[2] = {-1, -1};
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK, 0, fds), 0);
    Connection conns[1]{};
    conns[0].reset();
    conns[0].id = 0;
    conns[0].upstream_episode = 1;
    u8 storage[64] = {};
    conns[0].upstream_recv_buf.bind(storage, sizeof(storage));
    REQUIRE(backend.begin_upstream_episode(0, 1));
    static const u8 payload[] = {'o', 'l', 'd'};
    backend.upstream_send_state[0] = {
        payload, fds[0], 0, sizeof(payload), IoEventType::UpstreamSend, false, 0, 2};
    REQUIRE(backend.add_recv_upstream(fds[0], 0, 1));
    REQUIRE_EQ(write(fds[1], "r", 1), 1);
    const auto before = backend.upstream_send_state[0];
    IoEvent events[2]{};
    REQUIRE_EQ(backend.wait(events, 2, conns, 1), 1u);
    CHECK_EQ(events[0].type, IoEventType::UpstreamRecv);
    CHECK_EQ(events[0].result, 1);
    CHECK_EQ(backend.upstream_send_state[0].src, before.src);
    CHECK_EQ(backend.upstream_send_state[0].remaining, before.remaining);
    u8 peer[sizeof(payload)] = {};
    CHECK_EQ(recv(fds[1], peer, sizeof(peer), MSG_DONTWAIT), -1);
    CHECK(errno == EAGAIN || errno == EWOULDBLOCK);
    close(fds[0]);
    close(fds[1]);
    backend.shutdown();
}

TEST(epoll_episode, stale_partial_send_does_not_touch_state_or_wire) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    i32 fds[2] = {-1, -1};
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK, 0, fds), 0);
    u32 filled = 0;
    u8 fill[4096] = {};
    for (;;) {
        ssize_t nfill = send(fds[0], fill, sizeof(fill), MSG_NOSIGNAL);
        if (nfill > 0) {
            filled += static_cast<u32>(nfill);
            continue;
        }
        break;
    }
    REQUIRE_GT(filled, 0u);
    Connection conns[1]{};
    conns[0].reset();
    conns[0].id = 0;
    conns[0].upstream_episode = 2;
    static const u8 payload[] = {'s', 't', 'a', 'l', 'e'};
    REQUIRE(backend.begin_upstream_episode(0, 1));
    REQUIRE(backend.add_send_upstream(fds[0], 0, payload, sizeof(payload), 1));
    u8 drained[8192];
    while (recv(fds[1], drained, sizeof(drained), MSG_DONTWAIT) > 0) {
    }
    const auto before = backend.upstream_send_state[0];
    IoEvent events[2]{};
    CHECK_EQ(backend.wait(events, 2, conns, 1), 0u);
    CHECK_EQ(backend.upstream_send_state[0].src, before.src);
    CHECK_EQ(backend.upstream_send_state[0].offset, before.offset);
    CHECK_EQ(backend.upstream_send_state[0].remaining, before.remaining);
    CHECK_EQ(backend.upstream_send_state[0].upstream_episode, before.upstream_episode);
    CHECK_EQ(recv(fds[1], drained, sizeof(drained), MSG_DONTWAIT), -1);
    CHECK(errno == EAGAIN || errno == EWOULDBLOCK);
    close(fds[0]);
    close(fds[1]);
    backend.shutdown();
}

TEST(epoll_episode, synthetic_upstream_completion_preserves_episode_and_aux) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    i32 fds[2] = {-1, -1};
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK, 0, fds), 0);
    static const u8 payload[] = {'o', 'k'};
    Connection conns[1]{};
    conns[0].reset();
    conns[0].id = 0;
    conns[0].upstream_episode = 7;
    REQUIRE(backend.begin_upstream_episode(0, 7));
    REQUIRE(backend.add_send_upstream(fds[0], 0, payload, sizeof(payload), 7));
    IoEvent events[2]{};
    REQUIRE_EQ(backend.wait(events, 2, conns, 1), 1u);
    CHECK_EQ(events[0].type, IoEventType::UpstreamSend);
    CHECK_EQ(events[0].result, static_cast<i32>(sizeof(payload)));
    CHECK_EQ(events[0].upstream_episode, 7u);
    close(fds[0]);
    close(fds[1]);

    backend.shutdown();
    EpollBackend failure_backend{};
    REQUIRE(failure_backend.init(0, -1).has_value());
    close(failure_backend.epoll_fd);
    failure_backend.epoll_fd = -1;
    conns[0].upstream_episode = 9;
    REQUIRE(failure_backend.begin_upstream_episode(0, 9));
    CHECK(failure_backend.add_recv_upstream(-1, 0, 9));
    REQUIRE_EQ(failure_backend.wait(events, 2, conns, 1), 1u);
    CHECK_EQ(events[0].type, IoEventType::UpstreamRecv);
    CHECK_EQ(events[0].upstream_episode, 9u);
    CHECK_EQ(events[0].aux, kLocalSubmitFailureAux);
    failure_backend.shutdown();
}

namespace {
bool g_epoll_episode_callback_called = false;
u32 g_epoll_episode_callback_count = 0;

struct RealEpollEpisodeGuard {
    struct TrackedConnection {
        Connection* ptr = nullptr;
        u32 id = 0;
        bool live = false;
    };

    static constexpr u32 kMaxTrackedConnections = 8;

    RealLoop* loop = nullptr;
    bool initialized = false;
    UpstreamPool* upstream_pool = nullptr;
    bool upstream_pool_initialized = false;
    i32 listener_fd = -1;
    i32 peer_fds[2] = {-1, -1};
    TrackedConnection connections[kMaxTrackedConnections]{};

    ~RealEpollEpisodeGuard() {
        if (initialized && loop) {
            // close_conn is required even for fd == -1: an upstream-only
            // connection can still own an active episode or a timer entry.
            for (u32 i = kMaxTrackedConnections; i > 0; i--) {
                TrackedConnection& tracked = connections[i - 1];
                if (!tracked.live) continue;
                Connection* conn = tracked.ptr;
                tracked.live = false;
                loop->close_conn(*conn);
            }
            // A borrowed/current upstream fd is owned by its Connection after
            // take_idle(), so the pool is drained only after conn teardown.
            if (upstream_pool && upstream_pool_initialized) upstream_pool->shutdown();
            loop->upstream = nullptr;
            loop->shutdown();
        }
        for (i32& fd : peer_fds) {
            if (fd >= 0) {
                close(fd);
                fd = -1;
            }
        }
        if (listener_fd >= 0) {
            close(listener_fd);
            listener_fd = -1;
        }
        destroy_real_loop(loop);
        loop = nullptr;
    }

    bool create() {
        loop = create_real_loop();
        return loop != nullptr;
    }

    bool init() {
        if (!loop) return false;
        auto result = loop->init(0, -1, 0);
        if (!result.has_value()) return false;
        initialized = true;
        return true;
    }

    void attach_pool(UpstreamPool& pool) {
        upstream_pool = &pool;
        upstream_pool->init();
        upstream_pool_initialized = true;
        loop->upstream = upstream_pool;
    }

    Connection* alloc_conn() {
        if (!loop) return nullptr;
        Connection* conn = loop->alloc_conn();
        if (conn && !track_conn(*conn)) {
            loop->free_conn(*conn);
            return nullptr;
        }
        return conn;
    }

    // The connect helper also calls this before creating its socket, making
    // ownership explicit at the first fallible step even if a future caller
    // does not allocate through alloc_conn().
    bool track_conn(Connection& conn) {
        for (u32 i = kMaxTrackedConnections; i > 0; i--) {
            const TrackedConnection& tracked = connections[i - 1];
            if (tracked.live && tracked.ptr == &conn && tracked.id == conn.id) return true;
        }
        for (TrackedConnection& tracked : connections) {
            if (!tracked.live) {
                tracked.ptr = &conn;
                tracked.id = conn.id;
                tracked.live = true;
                return true;
            }
        }
        return false;
    }

    void close_conn(Connection& conn) {
        mark_conn_dead(conn);
        loop->close_conn(conn);
    }

    void free_conn(Connection& conn) {
        mark_conn_dead(conn);
        loop->free_conn(conn);
    }

    // Production callbacks can free a tracked slot before the test regains
    // control. Forget it by the allocation-time id (reset() clears id) so the
    // destructor does not close the already-returned slot a second time.
    void release_conn(Connection& conn, u32 allocated_id) {
        for (u32 i = kMaxTrackedConnections; i > 0; i--) {
            TrackedConnection& tracked = connections[i - 1];
            if (tracked.live && tracked.ptr == &conn && tracked.id == allocated_id) {
                tracked.live = false;
                return;
            }
        }
    }

private:
    void mark_conn_dead(Connection& conn) {
        for (u32 i = kMaxTrackedConnections; i > 0; i--) {
            TrackedConnection& tracked = connections[i - 1];
            if (tracked.live && tracked.ptr == &conn && tracked.id == conn.id) {
                tracked.live = false;
                return;
            }
        }
    }
};

struct ScopedBackendHealthReset {
    ScopedBackendHealthReset() { reset_backend_health(); }
    ScopedBackendHealthReset(const ScopedBackendHealthReset&) = delete;
    ScopedBackendHealthReset& operator=(const ScopedBackendHealthReset&) = delete;
    ~ScopedBackendHealthReset() { reset_backend_health(); }
};

struct EpollEpisodeSocketGuard {
    EpollBackend* backend;
    i32* fds;
    ~EpollEpisodeSocketGuard() {
        if (fds[0] >= 0) close(fds[0]);
        if (fds[1] >= 0) close(fds[1]);
        backend->shutdown();
    }
};

void epoll_episode_callback_probe(void*, ConnectionBase&, IoEvent) {
    g_epoll_episode_callback_called = true;
}

void epoll_episode_counting_callback(void*, ConnectionBase&, IoEvent) {
    g_epoll_episode_callback_count++;
}

bool wait_for_real_upstream_completion(EpollEventLoop& loop, IoEvent& completion) {
    for (u32 attempt = 0; attempt < 4; attempt++) {
        if (loop.backend.pending_count == 0) {
            struct pollfd ready{loop.backend.epoll_fd, POLLIN, 0};
            if (poll(&ready, 1, 1000) <= 0) return false;
        }
        IoEvent event{};
        const u32 count = loop.backend.wait(&event, 1, loop.conns, EpollEventLoop::kMaxConns);
        if (count == 0) continue;
        if (event.type == IoEventType::UpstreamConnect) {
            completion = event;
            return true;
        }
    }
    return false;
}

bool wait_for_real_upstream_event(EpollEventLoop& loop,
                                  IoEventType expected_type,
                                  IoEvent& completion) {
    for (u32 attempt = 0; attempt < 4; attempt++) {
        if (loop.backend.pending_count == 0) {
            struct pollfd ready{loop.backend.epoll_fd, POLLIN, 0};
            if (poll(&ready, 1, 1000) <= 0) return false;
        }
        IoEvent event{};
        const u32 count = loop.backend.wait(&event, 1, loop.conns, EpollEventLoop::kMaxConns);
        if (count == 0) continue;
        if (event.type == expected_type) {
            completion = event;
            return true;
        }
    }
    return false;
}

Connection* track_single_health_probe(RealEpollEpisodeGuard& guard,
                                      u16 upstream_idx,
                                      u32 backend_idx) {
    Connection* found = nullptr;
    u32 match_count = 0;
    bool all_tracked = true;
    for (u32 i = 0; i < EpollEventLoop::kMaxConns; i++) {
        Connection& conn = guard.loop->conns[i];
        if (!conn.is_health_probe || conn.upstream_idx != upstream_idx ||
            conn.upstream_backend_idx != backend_idx)
            continue;
        if (found == nullptr) found = &conn;
        match_count++;
        if (!guard.track_conn(conn)) all_tracked = false;
    }
    return match_count == 1 && all_tracked ? found : nullptr;
}

bool recv_exact_from_real_peer(i32 fd, char* dst, u32 len) {
    u32 received = 0;
    for (u32 attempt = 0; attempt < 4 && received < len; attempt++) {
        struct pollfd readable{fd, POLLIN, 0};
        if (poll(&readable, 1, 1000) <= 0) return false;
        const ssize_t nr = recv(fd, dst + received, len - received, MSG_DONTWAIT);
        if (nr <= 0) return false;
        received += static_cast<u32>(nr);
    }
    return received == len;
}

bool accept_real_upstream_peer(i32 listener_fd, i32& peer_fd) {
    struct pollfd ready{listener_fd, POLLIN, 0};
    if (poll(&ready, 1, 1000) <= 0) return false;
    peer_fd = accept4(listener_fd, nullptr, nullptr, SOCK_NONBLOCK | SOCK_CLOEXEC);
    return peer_fd >= 0;
}

bool connect_real_upstream(RealEpollEpisodeGuard& guard,
                           Connection& conn,
                           i32 listener_fd,
                           i32& peer_fd,
                           IoEvent& completion) {
    if (!guard.track_conn(conn)) return false;
    EpollEventLoop& loop = *guard.loop;
    conn.upstream_fd = UpstreamPool::create_socket();
    if (conn.upstream_fd < 0) return false;

    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = __builtin_bswap16(get_port(listener_fd));
    addr.sin_addr.s_addr = __builtin_bswap32(0x7F000001);
    if (!loop.submit_connect(conn, &addr, sizeof(addr))) return false;
    if (!accept_real_upstream_peer(listener_fd, peer_fd)) return false;
    return wait_for_real_upstream_completion(loop, completion);
}

bool poll_ready_without_terminal(i32 fd, short expected, i32 timeout_ms, bool expect_ready) {
    static constexpr u32 kMaxInterruptedPolls = 8;
    for (u32 attempt = 0; attempt < kMaxInterruptedPolls; attempt++) {
        struct pollfd ready{fd, expected, 0};
        const i32 rc = poll(&ready, 1, timeout_ms);
        if (rc < 0 && errno == EINTR) continue;
        if (rc == 0) return !expect_ready;
        if (rc != 1 || (ready.revents & (POLLERR | POLLHUP | POLLNVAL)) != 0) return false;
        if (expect_ready) return (ready.revents & expected) == expected;
        return ready.revents == 0;
    }
    return false;
}

bool fill_real_tcp_send_queue(i32 sender, i32 peer, u8 pattern, u32& accepted) {
    static constexpr u32 kMaxFill = 4u * 1024u * 1024u;
    static constexpr u32 kMaxSendCalls = 65536;
    i32 small_buffer = 4096;
    if (setsockopt(sender, SOL_SOCKET, SO_SNDBUF, &small_buffer, sizeof(small_buffer)) != 0 ||
        setsockopt(peer, SOL_SOCKET, SO_RCVBUF, &small_buffer, sizeof(small_buffer)) != 0)
        return false;

    u8 filler[4096];
    __builtin_memset(filler, pattern, sizeof(filler));
    accepted = 0;
    for (u32 call = 0; call < kMaxSendCalls && accepted < kMaxFill; call++) {
        const u32 requested = std::min<u32>(sizeof(filler), static_cast<u32>(kMaxFill - accepted));
        const ssize_t nw = send(sender, filler, requested, MSG_NOSIGNAL);
        if (nw > 0) {
            accepted += static_cast<u32>(nw);
            continue;
        }
        if (nw < 0 && errno == EINTR) continue;
        if (nw < 0 && (errno == EAGAIN || errno == EWOULDBLOCK))
            return accepted > 0 && poll_ready_without_terminal(sender, POLLOUT, 0, false);
        return false;
    }
    return false;
}

bool drain_exact_tcp_filler(i32 peer, u32 expected, u8 pattern) {
    static constexpr u32 kMaxPolls = 64;
    static constexpr u32 kMaxRecvCalls = 65536;
    u8 observed[8192];
    u32 received = 0;
    u32 recv_calls = 0;
    for (u32 poll_attempt = 0;
         poll_attempt < kMaxPolls && received < expected && recv_calls < kMaxRecvCalls;
         poll_attempt++) {
        if (!poll_ready_without_terminal(peer, POLLIN, 100, true)) continue;
        while (received < expected && recv_calls++ < kMaxRecvCalls) {
            const u32 wanted = std::min<u32>(sizeof(observed), expected - received);
            const ssize_t nr = recv(peer, observed, wanted, MSG_DONTWAIT);
            if (nr > 0) {
                for (ssize_t i = 0; i < nr; i++) {
                    if (observed[i] != pattern) return false;
                }
                received += static_cast<u32>(nr);
                continue;
            }
            if (nr < 0 && errno == EINTR) continue;
            if (nr < 0 && (errno == EAGAIN || errno == EWOULDBLOCK)) break;
            return false;
        }
    }
    return received == expected;
}

bool recv_exact_stream_to_eof(i32 peer, const u8* expected, u32 expected_len) {
    static constexpr u32 kMaxPolls = 64;
    static constexpr u32 kMaxInterruptedPolls = 8;
    static constexpr u32 kMaxRecvCalls = 65536;
    if (expected_len > 0 && expected == nullptr) return false;
    u8 observed[8192];
    u32 received = 0;
    u32 recv_calls = 0;
    for (u32 poll_attempt = 0; poll_attempt < kMaxPolls && recv_calls < kMaxRecvCalls;
         poll_attempt++) {
        struct pollfd readable{peer, POLLIN, 0};
        i32 poll_rc = -1;
        for (u32 interrupted = 0; interrupted < kMaxInterruptedPolls; interrupted++) {
            readable.revents = 0;
            poll_rc = poll(&readable, 1, 100);
            if (poll_rc < 0 && errno == EINTR) continue;
            break;
        }
        if (poll_rc == 0) continue;
        if (poll_rc != 1 || (readable.revents & (POLLERR | POLLNVAL)) != 0 ||
            (readable.revents & (POLLIN | POLLHUP)) == 0)
            return false;

        while (recv_calls++ < kMaxRecvCalls) {
            const ssize_t nr = recv(peer, observed, sizeof(observed), MSG_DONTWAIT);
            if (nr > 0) {
                const u32 count = static_cast<u32>(nr);
                if (received > expected_len || count > expected_len - received) return false;
                if (__builtin_memcmp(observed, expected + received, count) != 0) return false;
                received += count;
                continue;
            }
            if (nr == 0) return received == expected_len;
            if (errno == EINTR) continue;
            if (errno == EAGAIN || errno == EWOULDBLOCK) break;
            return false;
        }
    }
    return false;
}
}  // namespace

TEST(epoll_episode, dispatch_rejects_stale_tag_before_callback) {
    auto loop = std::make_unique<EpollEventLoop>();
    REQUIRE(loop->init(0, -1).has_value());
    auto* conn = loop->alloc_conn();
    REQUIRE(conn != nullptr);
    conn->fd = -1;
    conn->upstream_episode = 1;
    REQUIRE(loop->begin_upstream_episode(*conn));
    conn->upstream_recv_armed = true;
    conn->upstream_send_armed = true;
    g_epoll_episode_callback_called = false;
    conn->on_upstream_send = &epoll_episode_callback_probe;
    const bool recv_armed_before = conn->upstream_recv_armed;
    const bool send_armed_before = conn->upstream_send_armed;
    loop->timer.add(conn, 5);
    ListNode* timer_node_before = conn->timer_node.prev;
    loop->dispatch({conn->id, 0, 0, 0, IoEventType::UpstreamSend, 0, 0, 2});
    CHECK_EQ(conn->timer_node.prev, timer_node_before);
    CHECK_FALSE(g_epoll_episode_callback_called);
    CHECK_EQ(conn->upstream_recv_armed, recv_armed_before);
    CHECK_EQ(conn->upstream_send_armed, send_armed_before);
    // Positive control: the same callback is reached when the token matches.
    g_epoll_episode_callback_called = false;
    loop->dispatch({conn->id, 0, 0, 0, IoEventType::UpstreamSend, 0, 0, 1});
    CHECK(g_epoll_episode_callback_called);
    loop->free_conn(*conn);
    loop->shutdown();
}

TEST(epoll_episode_lifecycle, pooled_same_fd_stale_raw_readiness_is_fenced_before_io) {
    UpstreamPool upstream_pool{};
    RealEpollEpisodeGuard guard{};
    REQUIRE(guard.create());
    REQUIRE(guard.init());
    guard.attach_pool(upstream_pool);
    auto* loop = guard.loop;

    auto listener_result = create_listen_socket(0);
    REQUIRE(listener_result.has_value());
    guard.listener_fd = listener_result.value();
    const i32 listener_fd = guard.listener_fd;

    auto* conn = guard.alloc_conn();
    REQUIRE(conn != nullptr);
    const u32 conn_id = conn->id;
    const u32 first_episode = conn->upstream_episode;
    REQUIRE_EQ(first_episode, 1u);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], 0u);

    IoEvent first_connect{};
    REQUIRE(connect_real_upstream(guard, *conn, listener_fd, guard.peer_fds[0], first_connect));
    REQUIRE_EQ(first_connect.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(first_connect.result, 0);
    REQUIRE_EQ(first_connect.upstream_episode, first_episode);
    const i32 first_fd = conn->upstream_fd;
    REQUIRE_GE(first_fd, 0);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], first_episode);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], first_fd);

    // The production pool-return path synchronously detaches the registration,
    // retires episode 1, and parks the still-connected descriptor.
    REQUIRE(loop->return_idle_upstream(*conn, 9, 2));
    CHECK_EQ(conn->upstream_fd, -1);
    CHECK_EQ(conn->upstream_episode, first_episode + 1);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], 0u);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], -1);
    CHECK_EQ(upstream_pool.idle_count.load(std::memory_order_acquire), 1u);

    // The production borrow path returns the exact descriptor to the same
    // Connection slot and begins episode 2 before publishing its fd map entry.
    REQUIRE(loop->reuse_idle_upstream(*conn, 9, 2));
    const u32 second_episode = conn->upstream_episode;
    REQUIRE_EQ(second_episode, first_episode + 1);
    REQUIRE_EQ(conn->id, conn_id);
    REQUIRE_EQ(conn->upstream_fd, first_fd);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], second_episode);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], first_fd);
    CHECK_EQ(upstream_pool.idle_count.load(std::memory_order_acquire), 0u);
    CHECK_EQ(upstream_pool.free_top, UpstreamPool::kMaxConns);
    REQUIRE(loop->alloc_upstream_buf(*conn));

    // Install a real epoll readiness record tagged with the retired episode.
    // Ownership stays on episode 2: only the kernel registration carries token 1.
    REQUIRE(loop->backend.add_recv_upstream(first_fd, conn_id, first_episode));
    static constexpr char kPayload[] = "episode-two-payload";
    REQUIRE_EQ(send(guard.peer_fds[0], kPayload, sizeof(kPayload) - 1, MSG_NOSIGNAL),
               static_cast<ssize_t>(sizeof(kPayload) - 1));

    IoEvent stale_events[1]{};
    CHECK_EQ(loop->backend.wait(stale_events, 1, loop->conns, EpollEventLoop::kMaxConns), 0u);
    CHECK_EQ(conn->upstream_recv_buf.len(), 0u);
    CHECK_EQ(conn->upstream_fd, first_fd);
    CHECK_EQ(conn->upstream_episode, second_episode);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], second_episode);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], first_fd);
    char peeked[sizeof(kPayload)]{};
    REQUIRE_EQ(recv(first_fd, peeked, sizeof(kPayload) - 1, MSG_PEEK | MSG_DONTWAIT),
               static_cast<ssize_t>(sizeof(kPayload) - 1));
    CHECK_EQ(__builtin_memcmp(peeked, kPayload, sizeof(kPayload) - 1), 0);

    // Positive control: production re-registration with episode 2 consumes the
    // untouched bytes and dispatches one current completion.
    REQUIRE(loop->submit_recv_upstream(*conn));
    IoEvent current{};
    REQUIRE_EQ(loop->backend.wait(&current, 1, loop->conns, EpollEventLoop::kMaxConns), 1u);
    REQUIRE_EQ(current.type, IoEventType::UpstreamRecv);
    REQUIRE_EQ(current.result, static_cast<i32>(sizeof(kPayload) - 1));
    REQUIRE_EQ(current.upstream_episode, second_episode);
    REQUIRE_EQ(conn->upstream_recv_buf.len(), sizeof(kPayload) - 1);
    CHECK_EQ(__builtin_memcmp(conn->upstream_recv_buf.data(), kPayload, sizeof(kPayload) - 1), 0);
    g_epoll_episode_callback_count = 0;
    conn->on_upstream_recv = &epoll_episode_counting_callback;
    loop->dispatch(current);
    CHECK_EQ(g_epoll_episode_callback_count, 1u);

    guard.close_conn(*conn);
    errno = 0;
    CHECK_EQ(fcntl(first_fd, F_GETFD), -1);
    CHECK_EQ(errno, EBADF);
    CHECK_EQ(upstream_pool.idle_count.load(std::memory_order_acquire), 0u);
    CHECK_EQ(upstream_pool.free_top, UpstreamPool::kMaxConns);
}

TEST(epoll_episode_lifecycle, failed_connect_retry_retires_before_replacement_begin) {
    ScopedBackendHealthReset health_reset{};
    RouteConfig cfg{};
    const RouteConfig* active = &cfg;
    RealEpollEpisodeGuard guard{};
    REQUIRE(guard.create());
    REQUIRE(guard.init());
    auto* loop = guard.loop;

    auto listener_result = create_listen_socket(0);
    REQUIRE(listener_result.has_value());
    guard.listener_fd = listener_result.value();
    const i32 listener_fd = guard.listener_fd;
    const u16 listener_port = get_port(listener_fd);

    auto upstream_id = cfg.add_upstream("retry", 0x7F000001, listener_port);
    REQUIRE(upstream_id.has_value());
    REQUIRE(cfg.add_upstream_backend(upstream_id.value(), 0x7F000001, listener_port));
    REQUIRE(cfg.add_proxy("/api", 0, upstream_id.value()));
    loop->config_ptr = &active;

    auto* conn = guard.alloc_conn();
    REQUIRE(conn != nullptr);
    const u32 conn_id = conn->id;
    const u32 first_episode = conn->upstream_episode;
    REQUIRE_EQ(first_episode, 1u);
    conn->state = ConnState::ReadingHeader;
    conn->keep_alive = true;
    conn->on_recv = &on_header_received<EpollEventLoop>;
    loop->timer.add(conn, loop->keepalive_timeout);

    static constexpr char kRequest[] = "GET /api HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kRequest), sizeof(kRequest) - 1),
               sizeof(kRequest) - 1);

    // Only the initial request dispatch is faulted. The first production
    // create_socket() therefore gets a real descriptor, but its connect queues a
    // real epoll-backend failure completion. The retry runs after this scope.
    rut::test_fault::IoFaultConfig connect_fault{};
    connect_fault.fd = rut::test_fault::kMatchAllIoFds;
    connect_fault.connect_errno = ECONNREFUSED;
    connect_fault.connect_failures = 1;
    {
        ScopedIoFault fault_scope(connect_fault);
        loop->dispatch(make_ev(conn_id, IoEventType::Recv, sizeof(kRequest) - 1));
        REQUIRE_EQ(fault_scope.remaining_connect_failures(), 0);
    }

    const u8 first_backend = conn->upstream_backend_idx;
    REQUIRE_LT(first_backend, 2u);
    BackendHealth* first_health = backend_health(upstream_id.value(), first_backend);
    BackendHealth* other_health = backend_health(upstream_id.value(), first_backend ^ 1u);
    REQUIRE(first_health != nullptr);
    REQUIRE(other_health != nullptr);
    CHECK_EQ(first_health->fails, 0u);
    CHECK_EQ(first_health->eject_until_us, 0u);
    CHECK_FALSE(first_health->active_down);
    CHECK_EQ(other_health->fails, 0u);
    CHECK_EQ(other_health->eject_until_us, 0u);
    CHECK_FALSE(other_health->active_down);

    IoEvent first_failure{};
    REQUIRE(wait_for_real_upstream_completion(*loop, first_failure));
    REQUIRE_EQ(first_failure.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(first_failure.result, -ECONNREFUSED);
    REQUIRE_EQ(first_failure.conn_id, conn_id);
    REQUIRE_EQ(first_failure.upstream_episode, first_episode);
    const i32 first_fd = conn->upstream_fd;
    REQUIRE_GE(first_fd, 0);
    CHECK_EQ(conn->upstream_attempts, 1u);
    CHECK_EQ(conn->upstream_episode, first_episode);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], first_episode);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], first_fd);
    CHECK_EQ(conn->on_upstream_send, &on_upstream_connected<EpollEventLoop>);

    // This is the production failure callback: record passive health, detach and
    // retire episode 1, then begin and submit episode 2 on the same Connection.
    loop->dispatch(first_failure);
    const u32 second_episode = conn->upstream_episode;
    REQUIRE_EQ(conn->id, conn_id);
    REQUIRE_EQ(second_episode, first_episode + 1);
    REQUIRE_EQ(conn->upstream_attempts, 2u);
    const u8 second_backend = conn->upstream_backend_idx;
    REQUIRE_LT(second_backend, 2u);
    REQUIRE_NE(second_backend, first_backend);
    const i32 second_fd = conn->upstream_fd;
    REQUIRE_GE(second_fd, 0);
    CHECK_EQ(second_fd, first_fd);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], second_episode);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], second_fd);
    CHECK_EQ(conn->on_upstream_send, &on_upstream_connected<EpollEventLoop>);
    CHECK_FALSE(conn->upstream_recv_armed);
    CHECK_FALSE(conn->upstream_send_armed);
    const auto& replacement_send_state = loop->backend.upstream_send_state[conn_id];
    CHECK_EQ(replacement_send_state.src, nullptr);
    CHECK_EQ(replacement_send_state.fd, -1);
    CHECK_EQ(replacement_send_state.offset, 0u);
    CHECK_EQ(replacement_send_state.remaining, 0u);
    CHECK_EQ(replacement_send_state.upstream_episode, 0u);
    CHECK_EQ(first_health->fails, 1u);
    CHECK_EQ(first_health->eject_until_us, 0u);
    CHECK_FALSE(first_health->active_down);
    CHECK_EQ(other_health->fails, 0u);

    REQUIRE(accept_real_upstream_peer(listener_fd, guard.peer_fds[0]));
    IoEvent second_success{};
    REQUIRE(wait_for_real_upstream_completion(*loop, second_success));
    REQUIRE_EQ(second_success.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(second_success.result, 0);
    REQUIRE_EQ(second_success.conn_id, conn_id);
    REQUIRE_EQ(second_success.upstream_episode, second_episode);

    // A saved episode-1 completion cannot re-enter the retry callback after the
    // slot has moved to episode 2. Snapshot every externally-visible transition
    // point, then prove both the Connection and passive health stay unchanged.
    const u8 attempts_before_stale = conn->upstream_attempts;
    const u8 backend_before_stale = conn->upstream_backend_idx;
    const u16 status_before_stale = conn->resp_status;
    const i32 fd_before_stale = conn->upstream_fd;
    const i32 map_before_stale = loop->backend.upstream_fd_map[conn_id];
    const u32 owner_before_stale = loop->backend.active_upstream_episode[conn_id];
    const u32 token_before_stale = conn->upstream_episode;
    const auto callback_before_stale = conn->on_upstream_send;
    const BackendHealth first_health_before_stale = *first_health;
    const BackendHealth other_health_before_stale = *other_health;

    loop->dispatch(first_failure);
    CHECK_EQ(conn->upstream_attempts, attempts_before_stale);
    CHECK_EQ(conn->upstream_backend_idx, backend_before_stale);
    CHECK_EQ(conn->resp_status, status_before_stale);
    CHECK_EQ(conn->upstream_fd, fd_before_stale);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], map_before_stale);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], owner_before_stale);
    CHECK_EQ(conn->upstream_episode, token_before_stale);
    CHECK_EQ(conn->on_upstream_send, callback_before_stale);
    CHECK_EQ(first_health->fails, first_health_before_stale.fails);
    CHECK_EQ(first_health->eject_until_us, first_health_before_stale.eject_until_us);
    CHECK_EQ(first_health->active_down, first_health_before_stale.active_down);
    CHECK_EQ(other_health->fails, other_health_before_stale.fails);
    CHECK_EQ(other_health->eject_until_us, other_health_before_stale.eject_until_us);
    CHECK_EQ(other_health->active_down, other_health_before_stale.active_down);
    struct pollfd unexpected_retry{listener_fd, POLLIN, 0};
    CHECK_EQ(poll(&unexpected_retry, 1, 0), 0);

    // The current success is the positive control: production advances to the
    // request-send callbacks and the real peer receives the original bytes.
    loop->dispatch(second_success);
    CHECK_EQ(conn->state, ConnState::Proxying);
    CHECK_EQ(conn->on_upstream_recv, &on_early_upstream_recvd_send_inflight<EpollEventLoop>);
    CHECK_EQ(conn->on_upstream_send, &on_upstream_request_sent<EpollEventLoop>);

    char observed[sizeof(kRequest) - 1]{};
    u32 observed_len = 0;
    while (observed_len < sizeof(observed)) {
        struct pollfd readable{guard.peer_fds[0], POLLIN, 0};
        REQUIRE_GT(poll(&readable, 1, 1000), 0);
        const ssize_t nr = recv(guard.peer_fds[0],
                                observed + observed_len,
                                sizeof(observed) - observed_len,
                                MSG_DONTWAIT);
        REQUIRE_GT(nr, 0);
        observed_len += static_cast<u32>(nr);
    }
    CHECK_EQ(observed_len, sizeof(kRequest) - 1);
    CHECK_EQ(__builtin_memcmp(observed, kRequest, sizeof(kRequest) - 1), 0);
}

TEST(epoll_episode_lifecycle, production_health_probe_retires_before_same_slot_reprobe) {
    ScopedBackendHealthReset health_reset{};
    RouteConfig cfg{};
    const RouteConfig* active = &cfg;
    RealEpollEpisodeGuard guard{};
    REQUIRE(guard.create());
    REQUIRE(guard.init());
    auto* loop = guard.loop;

    auto listener_result = create_listen_socket(0);
    REQUIRE(listener_result.has_value());
    guard.listener_fd = listener_result.value();
    const i32 listener_fd = guard.listener_fd;
    const u16 listener_port = get_port(listener_fd);

    auto upstream_id_result = cfg.add_upstream("health", 0x7F000001, listener_port);
    REQUIRE(upstream_id_result.has_value());
    const u16 upstream_id = static_cast<u16>(upstream_id_result.value());
    static constexpr char kHealthPath[] = "/healthz";
    REQUIRE(cfg.set_upstream_health_check(upstream_id,
                                          kHealthPath,
                                          sizeof(kHealthPath) - 1,
                                          /*interval_ms=*/60'000,
                                          /*status=*/200));
    loop->config_ptr = &active;

    // Production config installation owns the initial health-table reset and
    // deadline arm. Seed an observable down state only after that reset: the
    // first real 200 probe must clear it, not merely preserve a healthy default.
    loop->sweep_health_probes();
    record_active_probe_result(upstream_id, 0, /*healthy=*/false, monotonic_us());
    BackendHealth* health = backend_health(upstream_id, 0);
    REQUIRE(health != nullptr);
    REQUIRE(health->active_down);
    REQUIRE_EQ(health->fails, 1u);

    const std::string expected_request =
        "GET /healthz HTTP/1.1\r\nHost: 127.0.0.1:" + std::to_string(listener_port) +
        "\r\nConnection: close\r\nUser-Agent: rut-healthcheck\r\n\r\n";
    static constexpr char kHealthyResponse[] =
        "HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";

    loop->health_probe_deadline_ns[upstream_id] = 0;
    loop->sweep_health_probes();
    Connection* first_conn = track_single_health_probe(guard, upstream_id, 0);
    REQUIRE(first_conn != nullptr);
    const u32 conn_id = first_conn->id;
    const u32 first_episode = first_conn->upstream_episode;
    const i32 first_fd = first_conn->upstream_fd;
    REQUIRE_EQ(loop->active_count(), 1u);
    REQUIRE(probe_in_flight(upstream_id, 0));
    REQUIRE_GE(first_fd, 0);
    REQUIRE_EQ(first_episode, 1u);
    CHECK(first_conn->is_health_probe);
    CHECK_EQ(first_conn->fd, -1);
    CHECK_EQ(first_conn->request_config, &cfg);
    CHECK_EQ(first_conn->on_upstream_send, &on_probe_connected<EpollEventLoop>);
    CHECK(!first_conn->timer_node.empty());
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], first_episode);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], first_fd);

    REQUIRE(accept_real_upstream_peer(listener_fd, guard.peer_fds[0]));
    IoEvent first_connect{};
    REQUIRE(wait_for_real_upstream_completion(*loop, first_connect));
    REQUIRE_EQ(first_connect.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(first_connect.result, 0);
    REQUIRE_EQ(first_connect.conn_id, conn_id);
    REQUIRE_EQ(first_connect.upstream_episode, first_episode);

    loop->dispatch(first_connect);
    CHECK_EQ(first_conn->on_upstream_send, &on_probe_sent<EpollEventLoop>);
    std::vector<char> first_observed(expected_request.size());
    REQUIRE(recv_exact_from_real_peer(
        guard.peer_fds[0], first_observed.data(), static_cast<u32>(first_observed.size())));
    CHECK_EQ(
        __builtin_memcmp(first_observed.data(), expected_request.data(), expected_request.size()),
        0);

    IoEvent first_send{};
    REQUIRE(wait_for_real_upstream_event(*loop, IoEventType::UpstreamSend, first_send));
    REQUIRE_EQ(first_send.result, static_cast<i32>(expected_request.size()));
    REQUIRE_EQ(first_send.upstream_episode, first_episode);
    loop->dispatch(first_send);
    CHECK_EQ(first_conn->on_upstream_recv, &on_probe_response<EpollEventLoop>);
    CHECK_EQ(first_conn->on_upstream_send, nullptr);
    REQUIRE_EQ(
        send(guard.peer_fds[0], kHealthyResponse, sizeof(kHealthyResponse) - 1, MSG_NOSIGNAL),
        static_cast<ssize_t>(sizeof(kHealthyResponse) - 1));

    IoEvent first_response{};
    REQUIRE(wait_for_real_upstream_event(*loop, IoEventType::UpstreamRecv, first_response));
    REQUIRE_EQ(first_response.result, static_cast<i32>(sizeof(kHealthyResponse) - 1));
    REQUIRE_EQ(first_response.upstream_episode, first_episode);
    loop->dispatch(first_response);
    const bool first_released = loop->active_count() == 0;
    if (first_released) guard.release_conn(*first_conn, conn_id);
    REQUIRE(first_released);

    CHECK_EQ(loop->free_top, EpollEventLoop::kMaxConns);
    CHECK_FALSE(probe_in_flight(upstream_id, 0));
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], 0u);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], -1);
    CHECK_EQ(first_conn->upstream_episode, first_episode + 1);
    CHECK_EQ(first_conn->upstream_fd, -1);
    CHECK(first_conn->timer_node.empty());
    CHECK_EQ(first_conn->on_recv, nullptr);
    CHECK_EQ(first_conn->on_send, nullptr);
    CHECK_EQ(first_conn->on_upstream_recv, nullptr);
    CHECK_EQ(first_conn->on_upstream_send, nullptr);
    CHECK_FALSE(first_conn->upstream_recv_armed);
    CHECK_FALSE(first_conn->upstream_send_armed);
    const auto& first_retired_send_state = loop->backend.upstream_send_state[conn_id];
    CHECK_EQ(first_retired_send_state.src, nullptr);
    CHECK_EQ(first_retired_send_state.fd, -1);
    CHECK_EQ(first_retired_send_state.remaining, 0u);
    CHECK_EQ(first_retired_send_state.upstream_episode, 0u);
    CHECK_EQ(loop->backend.pending_count, 0u);
    CHECK_FALSE(health->active_down);
    CHECK_EQ(health->fails, 0u);
    CHECK_EQ(health->eject_until_us, 0u);
    errno = 0;
    CHECK_EQ(fcntl(first_fd, F_GETFD), -1);
    CHECK_EQ(errno, EBADF);

    // A second due sweep must allocate the LIFO slot and the descriptor just
    // closed by production teardown. No test code begins or tags the episode.
    loop->health_probe_deadline_ns[upstream_id] = 0;
    loop->sweep_health_probes();
    Connection* second_conn = track_single_health_probe(guard, upstream_id, 0);
    REQUIRE(second_conn != nullptr);
    REQUIRE_EQ(second_conn, first_conn);
    REQUIRE_EQ(second_conn->id, conn_id);
    const u32 second_episode = second_conn->upstream_episode;
    const i32 second_fd = second_conn->upstream_fd;
    REQUIRE_EQ(second_episode, first_episode + 1);
    REQUIRE_EQ(second_fd, first_fd);
    REQUIRE_EQ(loop->active_count(), 1u);
    REQUIRE(probe_in_flight(upstream_id, 0));
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], second_episode);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], second_fd);
    CHECK_EQ(second_conn->on_upstream_send, &on_probe_connected<EpollEventLoop>);
    CHECK(!second_conn->timer_node.empty());

    REQUIRE(accept_real_upstream_peer(listener_fd, guard.peer_fds[1]));
    IoEvent second_connect{};
    REQUIRE(wait_for_real_upstream_completion(*loop, second_connect));
    REQUIRE_EQ(second_connect.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(second_connect.result, 0);
    REQUIRE_EQ(second_connect.conn_id, conn_id);
    REQUIRE_EQ(second_connect.upstream_episode, second_episode);

    // The saved episode-1 completion is a real kernel-connect result. Replaying
    // it while episode 2 owns the same slot and numeric fd must be a total no-op;
    // without the dispatch token fence it would invoke on_probe_connected and
    // put the health request on peer 2, making the wire assertion non-vacuous.
    const i32 fd_before_stale = second_conn->upstream_fd;
    const i32 map_before_stale = loop->backend.upstream_fd_map[conn_id];
    const u32 owner_before_stale = loop->backend.active_upstream_episode[conn_id];
    const u32 token_before_stale = second_conn->upstream_episode;
    const auto downstream_recv_callback_before_stale = second_conn->on_recv;
    const auto downstream_send_callback_before_stale = second_conn->on_send;
    const auto upstream_recv_callback_before_stale = second_conn->on_upstream_recv;
    const auto upstream_send_callback_before_stale = second_conn->on_upstream_send;
    const ListNode* timer_prev_before_stale = second_conn->timer_node.prev;
    const ListNode* timer_next_before_stale = second_conn->timer_node.next;
    const u16 timer_slot_before_stale = second_conn->timer_slot;
    const BackendHealth health_before_stale = *health;
    const u32 pending_before_stale = loop->backend.pending_count;
    const auto send_state_before_stale = loop->backend.upstream_send_state[conn_id];
    const u32 request_len_before_stale = second_conn->recv_buf.len();
    const u32 response_len_before_stale = second_conn->upstream_recv_buf.len();
    const u32 pending_ops_before_stale = second_conn->pending_ops;
    const bool recv_armed_before_stale = second_conn->upstream_recv_armed;
    const bool send_armed_before_stale = second_conn->upstream_send_armed;

    loop->dispatch(first_connect);
    CHECK_EQ(second_conn->upstream_fd, fd_before_stale);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], map_before_stale);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], owner_before_stale);
    CHECK_EQ(second_conn->upstream_episode, token_before_stale);
    CHECK_EQ(second_conn->on_recv, downstream_recv_callback_before_stale);
    CHECK_EQ(second_conn->on_send, downstream_send_callback_before_stale);
    CHECK_EQ(second_conn->on_upstream_recv, upstream_recv_callback_before_stale);
    CHECK_EQ(second_conn->on_upstream_send, upstream_send_callback_before_stale);
    CHECK_EQ(second_conn->timer_node.prev, timer_prev_before_stale);
    CHECK_EQ(second_conn->timer_node.next, timer_next_before_stale);
    CHECK_EQ(second_conn->timer_slot, timer_slot_before_stale);
    CHECK_EQ(health->fails, health_before_stale.fails);
    CHECK_EQ(health->eject_until_us, health_before_stale.eject_until_us);
    CHECK_EQ(health->active_down, health_before_stale.active_down);
    CHECK_EQ(loop->backend.pending_count, pending_before_stale);
    const auto& send_state_after_stale = loop->backend.upstream_send_state[conn_id];
    CHECK_EQ(send_state_after_stale.src, send_state_before_stale.src);
    CHECK_EQ(send_state_after_stale.fd, send_state_before_stale.fd);
    CHECK_EQ(send_state_after_stale.offset, send_state_before_stale.offset);
    CHECK_EQ(send_state_after_stale.remaining, send_state_before_stale.remaining);
    CHECK_EQ(send_state_after_stale.upstream_episode, send_state_before_stale.upstream_episode);
    CHECK_EQ(second_conn->recv_buf.len(), request_len_before_stale);
    CHECK_EQ(second_conn->upstream_recv_buf.len(), response_len_before_stale);
    CHECK_EQ(second_conn->pending_ops, pending_ops_before_stale);
    CHECK_EQ(second_conn->upstream_recv_armed, recv_armed_before_stale);
    CHECK_EQ(second_conn->upstream_send_armed, send_armed_before_stale);
    CHECK(probe_in_flight(upstream_id, 0));
    CHECK_EQ(loop->active_count(), 1u);
    char unexpected_byte = 0;
    errno = 0;
    CHECK_EQ(recv(guard.peer_fds[1], &unexpected_byte, 1, MSG_PEEK | MSG_DONTWAIT), -1);
    CHECK(errno == EAGAIN || errno == EWOULDBLOCK);

    // The current token is the positive control: it advances production to the
    // send callback and peer 2 receives the exact generated health request.
    loop->dispatch(second_connect);
    CHECK_EQ(second_conn->on_upstream_send, &on_probe_sent<EpollEventLoop>);
    std::vector<char> second_observed(expected_request.size());
    REQUIRE(recv_exact_from_real_peer(
        guard.peer_fds[1], second_observed.data(), static_cast<u32>(second_observed.size())));
    CHECK_EQ(
        __builtin_memcmp(second_observed.data(), expected_request.data(), expected_request.size()),
        0);

    IoEvent second_send{};
    REQUIRE(wait_for_real_upstream_event(*loop, IoEventType::UpstreamSend, second_send));
    REQUIRE_EQ(second_send.result, static_cast<i32>(expected_request.size()));
    REQUIRE_EQ(second_send.upstream_episode, second_episode);
    loop->dispatch(second_send);
    CHECK_EQ(second_conn->on_upstream_recv, &on_probe_response<EpollEventLoop>);
    REQUIRE_EQ(
        send(guard.peer_fds[1], kHealthyResponse, sizeof(kHealthyResponse) - 1, MSG_NOSIGNAL),
        static_cast<ssize_t>(sizeof(kHealthyResponse) - 1));

    IoEvent second_response{};
    REQUIRE(wait_for_real_upstream_event(*loop, IoEventType::UpstreamRecv, second_response));
    REQUIRE_EQ(second_response.result, static_cast<i32>(sizeof(kHealthyResponse) - 1));
    REQUIRE_EQ(second_response.upstream_episode, second_episode);
    loop->dispatch(second_response);
    const bool second_released = loop->active_count() == 0;
    if (second_released) guard.release_conn(*second_conn, conn_id);
    REQUIRE(second_released);

    CHECK_EQ(loop->free_top, EpollEventLoop::kMaxConns);
    CHECK_FALSE(probe_in_flight(upstream_id, 0));
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], 0u);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], -1);
    CHECK_EQ(second_conn->upstream_episode, second_episode + 1);
    CHECK_EQ(second_conn->upstream_fd, -1);
    CHECK(second_conn->timer_node.empty());
    CHECK_EQ(second_conn->on_upstream_recv, nullptr);
    CHECK_EQ(second_conn->on_upstream_send, nullptr);
    CHECK_FALSE(second_conn->upstream_recv_armed);
    CHECK_FALSE(second_conn->upstream_send_armed);
    const auto& second_retired_send_state = loop->backend.upstream_send_state[conn_id];
    CHECK_EQ(second_retired_send_state.src, nullptr);
    CHECK_EQ(second_retired_send_state.fd, -1);
    CHECK_EQ(second_retired_send_state.remaining, 0u);
    CHECK_EQ(second_retired_send_state.upstream_episode, 0u);
    CHECK_EQ(loop->backend.pending_count, 0u);
    CHECK_FALSE(health->active_down);
    CHECK_EQ(health->fails, 0u);
    errno = 0;
    CHECK_EQ(fcntl(second_fd, F_GETFD), -1);
    CHECK_EQ(errno, EBADF);
}

TEST(epoll_episode_lifecycle, recycled_slot_rejects_old_completion_before_dispatch_mutation) {
    RealEpollEpisodeGuard guard{};
    REQUIRE(guard.create());
    REQUIRE(guard.init());
    auto* loop = guard.loop;
    auto listener_result = create_listen_socket(0);
    REQUIRE(listener_result.has_value());
    guard.listener_fd = listener_result.value();
    const i32 listener_fd = guard.listener_fd;

    auto* old_conn = guard.alloc_conn();
    REQUIRE(old_conn != nullptr);
    const u32 conn_id = old_conn->id;
    const u32 first_episode = old_conn->upstream_episode;
    REQUIRE_EQ(first_episode, 1u);
    IoEvent old_completion{};
    REQUIRE(
        connect_real_upstream(guard, *old_conn, listener_fd, guard.peer_fds[0], old_completion));
    REQUIRE_EQ(old_completion.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(old_completion.result, 0);
    REQUIRE_EQ(old_completion.conn_id, conn_id);
    REQUIRE_EQ(old_completion.upstream_episode, first_episode);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], first_episode);

    // Terminal production teardown retires episode 1 and returns this exact
    // Connection slot to the allocator. Its saved completion remains addressable
    // only by conn_id + old episode, as a real late completion would be.
    guard.close_conn(*old_conn);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], 0u);
    auto* current_conn = guard.alloc_conn();
    REQUIRE(current_conn != nullptr);
    REQUIRE_EQ(current_conn->id, conn_id);
    REQUIRE_EQ(current_conn->upstream_episode, first_episode + 1);

    IoEvent current_completion{};
    REQUIRE(connect_real_upstream(
        guard, *current_conn, listener_fd, guard.peer_fds[1], current_completion));
    const u32 second_episode = current_conn->upstream_episode;
    REQUIRE_EQ(second_episode, first_episode + 1);
    REQUIRE_EQ(current_completion.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(current_completion.result, 0);
    REQUIRE_EQ(current_completion.conn_id, conn_id);
    REQUIRE_EQ(current_completion.upstream_episode, second_episode);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], second_episode);

    auto* timer_anchor = guard.alloc_conn();
    REQUIRE(timer_anchor != nullptr);
    loop->timer.add(current_conn, 5);
    loop->timer.add(timer_anchor, 5);
    REQUIRE(loop->alloc_upstream_buf(*current_conn));
    static constexpr char kBufferSentinel[] = "current-buffer";
    REQUIRE_EQ(current_conn->upstream_recv_buf.write(reinterpret_cast<const u8*>(kBufferSentinel),
                                                     sizeof(kBufferSentinel) - 1),
               sizeof(kBufferSentinel) - 1);
    current_conn->state = ConnState::Proxying;
    current_conn->upstream_recv_armed = true;
    current_conn->upstream_send_armed = true;
    current_conn->on_upstream_send = &epoll_episode_counting_callback;
    g_epoll_episode_callback_count = 0;

    const i32 current_fd = current_conn->upstream_fd;
    const i32 current_map = loop->backend.upstream_fd_map[conn_id];
    const ListNode* timer_prev = current_conn->timer_node.prev;
    const ListNode* timer_next = current_conn->timer_node.next;
    const u32 buffer_len = current_conn->upstream_recv_buf.len();
    const ConnState state = current_conn->state;
    const bool recv_armed = current_conn->upstream_recv_armed;
    const bool send_armed = current_conn->upstream_send_armed;

    loop->dispatch(old_completion);
    CHECK_EQ(g_epoll_episode_callback_count, 0u);
    CHECK_EQ(current_conn->timer_node.prev, timer_prev);
    CHECK_EQ(current_conn->timer_node.next, timer_next);
    CHECK_EQ(current_conn->upstream_recv_armed, recv_armed);
    CHECK_EQ(current_conn->upstream_send_armed, send_armed);
    CHECK_EQ(current_conn->upstream_fd, current_fd);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], current_map);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], second_episode);
    CHECK_EQ(current_conn->upstream_episode, second_episode);
    CHECK_EQ(current_conn->upstream_recv_buf.len(), buffer_len);
    CHECK_EQ(
        __builtin_memcmp(
            current_conn->upstream_recv_buf.data(), kBufferSentinel, sizeof(kBufferSentinel) - 1),
        0);
    CHECK_EQ(current_conn->state, state);

    // Positive control: the completion created by episode 2 reaches the probe.
    loop->dispatch(current_completion);
    CHECK_EQ(g_epoll_episode_callback_count, 1u);

    guard.close_conn(*current_conn);
    guard.free_conn(*timer_anchor);
}

TEST(epoll_episode_lifecycle, harvested_raw_connect_is_fenced_across_terminal_same_fd_reuse) {
    RealEpollEpisodeGuard guard{};
    REQUIRE(guard.create());
    REQUIRE(guard.init());
    auto* loop = guard.loop;
    struct itimerspec disarmed_timer{};
    REQUIRE_EQ(timerfd_settime(loop->backend.timer_fd, 0, &disarmed_timer, nullptr), 0);

    auto listener_result = create_listen_socket(0);
    REQUIRE(listener_result.has_value());
    guard.listener_fd = listener_result.value();
    const i32 listener_fd = guard.listener_fd;
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = __builtin_bswap16(get_port(listener_fd));
    addr.sin_addr.s_addr = __builtin_bswap32(0x7F000001);

    Connection* first_conn = guard.alloc_conn();
    REQUIRE(first_conn != nullptr);
    const u32 conn_id = first_conn->id;
    const u32 first_episode = first_conn->upstream_episode;
    REQUIRE_EQ(first_episode, 1u);
    first_conn->upstream_fd = UpstreamPool::create_socket();
    REQUIRE_GE(first_conn->upstream_fd, 0);
    const i32 first_fd = first_conn->upstream_fd;
    REQUIRE(loop->submit_connect(*first_conn, &addr, sizeof(addr)));
    // A synchronous connect would have queued a synthetic completion. The zero
    // count proves this path really armed EPOLLOUT after EINPROGRESS.
    REQUIRE_EQ(loop->backend.pending_count, 0u);
    REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], first_episode);
    REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], first_fd);
    REQUIRE(accept_real_upstream_peer(listener_fd, guard.peer_fds[0]));
    struct pollfd first_ready{loop->backend.epoll_fd, POLLIN, 0};
    REQUIRE_GT(poll(&first_ready, 1, 1000), 0);

    ScopedHeldEpollEvent held(loop->backend.epoll_fd);
    REQUIRE(held.owns_state());
    REQUIRE(held.arm_capture_once());
    IoEvent suppressed{};
    REQUIRE_EQ(loop->backend.wait(&suppressed, 1, loop->conns, EpollEventLoop::kMaxConns), 0u);
    REQUIRE(held.captured());
    REQUIRE_FALSE(held.capture_armed());
    REQUIRE_FALSE(held.failed_closed());
    const u32 captured_raw_events = held.captured_events();
    const u64 captured_raw_data = held.captured_data();
    REQUIRE_NE(captured_raw_events & EPOLLOUT, 0u);
    UpstreamEventToken captured_token{};
    REQUIRE(decode_upstream_event_token(captured_raw_data, &captured_token));
    REQUIRE_EQ(captured_token.conn_id, conn_id);
    REQUIRE_EQ(captured_token.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(captured_token.episode, first_episode);
    REQUIRE_EQ(captured_token.aux, 0u);

    // Production terminal teardown performs DEL while the fd is live, closes
    // it, retires episode 1, and releases this exact allocator slot.
    guard.close_conn(*first_conn);
    REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], 0u);
    REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], -1);
    errno = 0;
    REQUIRE_EQ(fcntl(first_fd, F_GETFD), -1);
    REQUIRE_EQ(errno, EBADF);

    Connection* current_conn = guard.alloc_conn();
    REQUIRE(current_conn != nullptr);
    REQUIRE_EQ(current_conn, first_conn);
    REQUIRE_EQ(current_conn->id, conn_id);
    const u32 current_episode = current_conn->upstream_episode;
    REQUIRE_EQ(current_episode, first_episode + 1);
    current_conn->upstream_fd = UpstreamPool::create_socket();
    REQUIRE_GE(current_conn->upstream_fd, 0);
    const i32 current_fd = current_conn->upstream_fd;
    REQUIRE_EQ(current_fd, first_fd);
    REQUIRE(loop->submit_connect(*current_conn, &addr, sizeof(addr)));
    REQUIRE_EQ(loop->backend.pending_count, 0u);
    REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], current_episode);
    REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], current_fd);
    REQUIRE(accept_real_upstream_peer(listener_fd, guard.peer_fds[1]));
    struct pollfd current_ready{loop->backend.epoll_fd, POLLIN, 0};
    REQUIRE_GT(poll(&current_ready, 1, 1000), 0);

    // Make every relevant current-episode field observable before replay. The
    // old record must be rejected during raw decode, before fd-map access,
    // getsockopt, dispatch, timer refresh, callback, or buffer/state mutation.
    loop->timer.add(current_conn, 5);
    REQUIRE(loop->alloc_upstream_buf(*current_conn));
    static constexpr char kRecvSentinel[] = "current-downstream";
    static constexpr char kUpstreamSentinel[] = "current-upstream";
    REQUIRE_EQ(current_conn->recv_buf.write(reinterpret_cast<const u8*>(kRecvSentinel),
                                            sizeof(kRecvSentinel) - 1),
               sizeof(kRecvSentinel) - 1);
    REQUIRE_EQ(current_conn->upstream_recv_buf.write(reinterpret_cast<const u8*>(kUpstreamSentinel),
                                                     sizeof(kUpstreamSentinel) - 1),
               sizeof(kUpstreamSentinel) - 1);
    current_conn->state = ConnState::Proxying;
    current_conn->pending_ops = 7;
    current_conn->upstream_recv_armed = true;
    current_conn->upstream_send_armed = true;
    current_conn->on_recv = &epoll_episode_counting_callback;
    current_conn->on_send = &epoll_episode_counting_callback;
    current_conn->on_upstream_recv = &epoll_episode_counting_callback;
    current_conn->on_upstream_send = &epoll_episode_counting_callback;
    g_epoll_episode_callback_count = 0;

    const i32 fd_before = current_conn->upstream_fd;
    const i32 map_before = loop->backend.upstream_fd_map[conn_id];
    const u32 owner_before = loop->backend.active_upstream_episode[conn_id];
    const u32 token_before = current_conn->upstream_episode;
    const auto on_recv_before = current_conn->on_recv;
    const auto on_send_before = current_conn->on_send;
    const auto on_upstream_recv_before = current_conn->on_upstream_recv;
    const auto on_upstream_send_before = current_conn->on_upstream_send;
    const ListNode* timer_prev_before = current_conn->timer_node.prev;
    const ListNode* timer_next_before = current_conn->timer_node.next;
    const u16 timer_slot_before = current_conn->timer_slot;
    const u32 pending_before = loop->backend.pending_count;
    const u32 pending_streak_before = loop->backend.pending_streak;
    const auto downstream_send_before = loop->backend.send_state[conn_id];
    const auto upstream_send_before = loop->backend.upstream_send_state[conn_id];
    const u32 recv_len_before = current_conn->recv_buf.len();
    const u32 upstream_len_before = current_conn->upstream_recv_buf.len();
    const u32 pending_ops_before = current_conn->pending_ops;
    const bool upstream_recv_armed_before = current_conn->upstream_recv_armed;
    const bool upstream_send_armed_before = current_conn->upstream_send_armed;
    const ConnState state_before = current_conn->state;

    REQUIRE(held.replay_once());
    IoEvent stale_output{
        0x00ffffffu, -1234, 0xffffu, 1, IoEventType::Count, 1, 0xff, kInvalidUpstreamEventEpisode};
    REQUIRE_EQ(loop->backend.wait(&stale_output, 1, loop->conns, EpollEventLoop::kMaxConns), 0u);
    CHECK(held.replay_consumed());
    CHECK_FALSE(held.replay_armed());
    CHECK_FALSE(held.failed_closed());
    CHECK_EQ(held.captured_events(), captured_raw_events);
    CHECK_EQ(held.captured_data(), captured_raw_data);
    CHECK_EQ(stale_output.type, IoEventType::Count);
    CHECK_EQ(stale_output.upstream_episode, kInvalidUpstreamEventEpisode);
    CHECK_EQ(g_epoll_episode_callback_count, 0u);
    CHECK_EQ(current_conn->upstream_fd, fd_before);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], map_before);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], owner_before);
    CHECK_EQ(current_conn->upstream_episode, token_before);
    CHECK_EQ(current_conn->on_recv, on_recv_before);
    CHECK_EQ(current_conn->on_send, on_send_before);
    CHECK_EQ(current_conn->on_upstream_recv, on_upstream_recv_before);
    CHECK_EQ(current_conn->on_upstream_send, on_upstream_send_before);
    CHECK_EQ(current_conn->timer_node.prev, timer_prev_before);
    CHECK_EQ(current_conn->timer_node.next, timer_next_before);
    CHECK_EQ(current_conn->timer_slot, timer_slot_before);
    CHECK_EQ(loop->backend.pending_count, pending_before);
    CHECK_EQ(loop->backend.pending_streak, pending_streak_before);
    const auto& downstream_send_after = loop->backend.send_state[conn_id];
    CHECK_EQ(downstream_send_after.src, downstream_send_before.src);
    CHECK_EQ(downstream_send_after.fd, downstream_send_before.fd);
    CHECK_EQ(downstream_send_after.offset, downstream_send_before.offset);
    CHECK_EQ(downstream_send_after.remaining, downstream_send_before.remaining);
    CHECK_EQ(downstream_send_after.type, downstream_send_before.type);
    CHECK_EQ(downstream_send_after.tls, downstream_send_before.tls);
    CHECK_EQ(downstream_send_after.tls_wait_events, downstream_send_before.tls_wait_events);
    CHECK_EQ(downstream_send_after.upstream_episode, downstream_send_before.upstream_episode);
    const auto& upstream_send_after = loop->backend.upstream_send_state[conn_id];
    CHECK_EQ(upstream_send_after.src, upstream_send_before.src);
    CHECK_EQ(upstream_send_after.fd, upstream_send_before.fd);
    CHECK_EQ(upstream_send_after.offset, upstream_send_before.offset);
    CHECK_EQ(upstream_send_after.remaining, upstream_send_before.remaining);
    CHECK_EQ(upstream_send_after.type, upstream_send_before.type);
    CHECK_EQ(upstream_send_after.tls, upstream_send_before.tls);
    CHECK_EQ(upstream_send_after.tls_wait_events, upstream_send_before.tls_wait_events);
    CHECK_EQ(upstream_send_after.upstream_episode, upstream_send_before.upstream_episode);
    CHECK_EQ(current_conn->recv_buf.len(), recv_len_before);
    CHECK_EQ(
        __builtin_memcmp(current_conn->recv_buf.data(), kRecvSentinel, sizeof(kRecvSentinel) - 1),
        0);
    CHECK_EQ(current_conn->upstream_recv_buf.len(), upstream_len_before);
    CHECK_EQ(__builtin_memcmp(current_conn->upstream_recv_buf.data(),
                              kUpstreamSentinel,
                              sizeof(kUpstreamSentinel) - 1),
             0);
    CHECK_EQ(current_conn->pending_ops, pending_ops_before);
    CHECK_EQ(current_conn->upstream_recv_armed, upstream_recv_armed_before);
    CHECK_EQ(current_conn->upstream_send_armed, upstream_send_armed_before);
    CHECK_EQ(current_conn->state, state_before);
    char unexpected_byte = 0;
    errno = 0;
    CHECK_EQ(recv(guard.peer_fds[1], &unexpected_byte, 1, MSG_PEEK | MSG_DONTWAIT), -1);
    CHECK(errno == EAGAIN || errno == EWOULDBLOCK);

    // The real episode-2 record was never harvested during replay. A normal
    // wait now returns it, and dispatch reaches the current callback once.
    struct pollfd still_ready{loop->backend.epoll_fd, POLLIN, 0};
    REQUIRE_GT(poll(&still_ready, 1, 1000), 0);
    IoEvent current_completion{};
    REQUIRE_EQ(loop->backend.wait(&current_completion, 1, loop->conns, EpollEventLoop::kMaxConns),
               1u);
    REQUIRE_EQ(current_completion.conn_id, conn_id);
    REQUIRE_EQ(current_completion.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(current_completion.result, 0);
    REQUIRE_EQ(current_completion.upstream_episode, current_episode);
    loop->dispatch(current_completion);
    CHECK_EQ(g_epoll_episode_callback_count, 1u);
    CHECK(held.replay_consumed());
    CHECK_FALSE(held.failed_closed());
}

TEST(epoll_episode_lifecycle, harvested_raw_recv_is_fenced_across_terminal_same_fd_reuse) {
    static constexpr char kFirstPayload[] = "episode-one-recv";
    static constexpr char kCurrentPayload[] = "episode-two-current-recv";

    RealEpollEpisodeGuard guard{};
    REQUIRE(guard.create());
    REQUIRE(guard.init());
    auto* loop = guard.loop;
    struct itimerspec disarmed_timer{};
    REQUIRE_EQ(timerfd_settime(loop->backend.timer_fd, 0, &disarmed_timer, nullptr), 0);
    REQUIRE_EQ(timerfd_settime(loop->backend.yield_timer_fd, 0, &disarmed_timer, nullptr), 0);

    auto listener_result = create_listen_socket(0);
    REQUIRE(listener_result.has_value());
    guard.listener_fd = listener_result.value();
    const i32 listener_fd = guard.listener_fd;
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = __builtin_bswap16(get_port(listener_fd));
    addr.sin_addr.s_addr = __builtin_bswap32(0x7F000001);

    Connection* first_conn = guard.alloc_conn();
    REQUIRE(first_conn != nullptr);
    const u32 conn_id = first_conn->id;
    const u32 first_episode = first_conn->upstream_episode;
    REQUIRE_EQ(first_episode, 1u);
    first_conn->upstream_fd = UpstreamPool::create_socket();
    REQUIRE_GE(first_conn->upstream_fd, 0);
    const i32 first_fd = first_conn->upstream_fd;
    REQUIRE(loop->submit_connect(*first_conn, &addr, sizeof(addr)));
    // Observe the production EINPROGRESS result before accept or wait can
    // consume a synthetic completion.
    REQUIRE_EQ(loop->backend.pending_count, 0u);
    REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], first_episode);
    REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], first_fd);
    REQUIRE(accept_real_upstream_peer(listener_fd, guard.peer_fds[0]));
    IoEvent first_connect{};
    REQUIRE(wait_for_real_upstream_completion(*loop, first_connect));
    REQUIRE_EQ(first_connect.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(first_connect.result, 0);
    REQUIRE_EQ(first_connect.conn_id, conn_id);
    REQUIRE_EQ(first_connect.upstream_episode, first_episode);
    REQUIRE(loop->alloc_upstream_buf(*first_conn));
    REQUIRE(loop->submit_recv_upstream(*first_conn));
    REQUIRE_EQ(loop->backend.pending_count, 0u);

    REQUIRE_EQ(send(guard.peer_fds[0], kFirstPayload, sizeof(kFirstPayload) - 1, MSG_NOSIGNAL),
               static_cast<ssize_t>(sizeof(kFirstPayload) - 1));
    REQUIRE(poll_ready_without_terminal(first_fd, POLLIN, 1000, true));
    REQUIRE(poll_ready_without_terminal(loop->backend.epoll_fd, POLLIN, 1000, true));

    ScopedHeldEpollEvent held(loop->backend.epoll_fd);
    REQUIRE(held.owns_state());
    REQUIRE(held.arm_capture_once());
    IoEvent suppressed{};
    REQUIRE_EQ(loop->backend.wait(&suppressed, 1, loop->conns, EpollEventLoop::kMaxConns), 0u);
    REQUIRE(held.captured());
    REQUIRE_FALSE(held.capture_armed());
    REQUIRE_FALSE(held.failed_closed());
    const u32 captured_raw_events = held.captured_events();
    const u64 captured_raw_data = held.captured_data();
    REQUIRE_NE(captured_raw_events & EPOLLIN, 0u);
    REQUIRE_EQ(captured_raw_events & (EPOLLHUP | EPOLLERR | EPOLLRDHUP), 0u);
    UpstreamEventToken captured_token{};
    REQUIRE(decode_upstream_event_token(captured_raw_data, &captured_token));
    REQUIRE_EQ(captured_token.conn_id, conn_id);
    REQUIRE_EQ(captured_token.type, IoEventType::UpstreamRecv);
    REQUIRE_EQ(captured_token.episode, first_episode);
    REQUIRE_EQ(captured_token.aux, 0u);
    REQUIRE_EQ(first_conn->upstream_recv_buf.len(), 0u);
    char first_peek[sizeof(kFirstPayload) - 1]{};
    REQUIRE_EQ(recv(first_fd, first_peek, sizeof(first_peek), MSG_PEEK | MSG_DONTWAIT),
               static_cast<ssize_t>(sizeof(first_peek)));
    REQUIRE_EQ(__builtin_memcmp(first_peek, kFirstPayload, sizeof(first_peek)), 0);

    // Production terminal teardown removes the live recv registration, closes
    // the socket, retires episode 1, and releases this exact allocator slot.
    guard.close_conn(*first_conn);
    REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], 0u);
    REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], -1);
    errno = 0;
    REQUIRE_EQ(fcntl(first_fd, F_GETFD), -1);
    REQUIRE_EQ(errno, EBADF);

    Connection* current_conn = guard.alloc_conn();
    REQUIRE(current_conn != nullptr);
    REQUIRE_EQ(current_conn, first_conn);
    REQUIRE_EQ(current_conn->id, conn_id);
    const u32 current_episode = current_conn->upstream_episode;
    REQUIRE_EQ(current_episode, first_episode + 1);
    current_conn->upstream_fd = UpstreamPool::create_socket();
    REQUIRE_GE(current_conn->upstream_fd, 0);
    const i32 current_fd = current_conn->upstream_fd;
    REQUIRE_EQ(current_fd, first_fd);
    REQUIRE(loop->submit_connect(*current_conn, &addr, sizeof(addr)));
    REQUIRE_EQ(loop->backend.pending_count, 0u);
    REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], current_episode);
    REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], current_fd);
    REQUIRE(accept_real_upstream_peer(listener_fd, guard.peer_fds[1]));
    IoEvent current_connect{};
    REQUIRE(wait_for_real_upstream_completion(*loop, current_connect));
    REQUIRE_EQ(current_connect.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(current_connect.result, 0);
    REQUIRE_EQ(current_connect.conn_id, conn_id);
    REQUIRE_EQ(current_connect.upstream_episode, current_episode);
    REQUIRE(loop->alloc_upstream_buf(*current_conn));
    REQUIRE(loop->submit_recv_upstream(*current_conn));
    REQUIRE_EQ(loop->backend.pending_count, 0u);

    REQUIRE_EQ(send(guard.peer_fds[1], kCurrentPayload, sizeof(kCurrentPayload) - 1, MSG_NOSIGNAL),
               static_cast<ssize_t>(sizeof(kCurrentPayload) - 1));
    REQUIRE(poll_ready_without_terminal(current_fd, POLLIN, 1000, true));
    REQUIRE(poll_ready_without_terminal(loop->backend.epoll_fd, POLLIN, 1000, true));

    // Make the episode-2 connection state observable. The held episode-1 raw
    // record must be rejected before fd lookup, recv, rearm, timer mutation, or
    // any state that a subsequent dispatch could use.
    Connection* timer_anchor = guard.alloc_conn();
    REQUIRE(timer_anchor != nullptr);
    loop->timer.add(current_conn, 5);
    loop->timer.add(timer_anchor, 5);
    static constexpr char kRecvSentinel[] = "recv-current-downstream";
    static constexpr char kSendSentinel[] = "recv-current-send";
    REQUIRE_EQ(current_conn->recv_buf.write(reinterpret_cast<const u8*>(kRecvSentinel),
                                            sizeof(kRecvSentinel) - 1),
               sizeof(kRecvSentinel) - 1);
    REQUIRE_EQ(current_conn->send_buf.write(reinterpret_cast<const u8*>(kSendSentinel),
                                            sizeof(kSendSentinel) - 1),
               sizeof(kSendSentinel) - 1);
    current_conn->on_recv = &epoll_episode_counting_callback;
    current_conn->on_send = &epoll_episode_counting_callback;
    current_conn->on_upstream_recv = &epoll_episode_counting_callback;
    current_conn->on_upstream_send = &epoll_episode_counting_callback;
    current_conn->state = ConnState::Proxying;
    current_conn->pending_ops = 7;
    current_conn->upstream_recv_armed = true;
    current_conn->upstream_send_armed = true;
    g_epoll_episode_callback_count = 0;

    const Connection* ptr_before = current_conn;
    const u32 id_before = current_conn->id;
    const i32 fd_before = current_conn->upstream_fd;
    const i32 map_before = loop->backend.upstream_fd_map[conn_id];
    const u32 owner_before = loop->backend.active_upstream_episode[conn_id];
    const u32 token_before = current_conn->upstream_episode;
    const auto downstream_send_before = loop->backend.send_state[conn_id];
    const auto upstream_send_before = loop->backend.upstream_send_state[conn_id];
    const auto on_recv_before = current_conn->on_recv;
    const auto on_send_before = current_conn->on_send;
    const auto on_upstream_recv_before = current_conn->on_upstream_recv;
    const auto on_upstream_send_before = current_conn->on_upstream_send;
    const ListNode* timer_prev_before = current_conn->timer_node.prev;
    const ListNode* timer_next_before = current_conn->timer_node.next;
    const u16 timer_slot_before = current_conn->timer_slot;
    const u32 pending_before = loop->backend.pending_count;
    const u32 pending_streak_before = loop->backend.pending_streak;
    const u32 recv_len_before = current_conn->recv_buf.len();
    const u32 send_len_before = current_conn->send_buf.len();
    const u32 upstream_len_before = current_conn->upstream_recv_buf.len();
    const u32 pending_ops_before = current_conn->pending_ops;
    const bool upstream_recv_armed_before = current_conn->upstream_recv_armed;
    const bool upstream_send_armed_before = current_conn->upstream_send_armed;
    const ConnState state_before = current_conn->state;

    REQUIRE(held.replay_once());
    IoEvent stale_output{
        0x00ffffffu, -1234, 0xffffu, 1, IoEventType::Count, 1, 0xff, kInvalidUpstreamEventEpisode};
    REQUIRE_EQ(loop->backend.wait(&stale_output, 1, loop->conns, EpollEventLoop::kMaxConns), 0u);
    CHECK(held.replay_consumed());
    CHECK_FALSE(held.replay_armed());
    CHECK_FALSE(held.failed_closed());
    CHECK_EQ(held.captured_events(), captured_raw_events);
    CHECK_EQ(held.captured_data(), captured_raw_data);
    CHECK_EQ(stale_output.conn_id, 0x00ffffffu);
    CHECK_EQ(stale_output.result, -1234);
    CHECK_EQ(stale_output.buf_id, 0xffffu);
    CHECK_EQ(stale_output.has_buf, 1);
    CHECK_EQ(stale_output.type, IoEventType::Count);
    CHECK_EQ(stale_output.more, 1);
    CHECK_EQ(stale_output.aux, 0xff);
    CHECK_EQ(stale_output.upstream_episode, kInvalidUpstreamEventEpisode);
    CHECK_EQ(g_epoll_episode_callback_count, 0u);
    CHECK_EQ(current_conn, ptr_before);
    CHECK_EQ(current_conn->id, id_before);
    CHECK_EQ(current_conn->upstream_fd, fd_before);
    CHECK_EQ(loop->backend.upstream_fd_map[conn_id], map_before);
    CHECK_EQ(loop->backend.active_upstream_episode[conn_id], owner_before);
    CHECK_EQ(current_conn->upstream_episode, token_before);
    const auto& downstream_send_after = loop->backend.send_state[conn_id];
    CHECK_EQ(downstream_send_after.src, downstream_send_before.src);
    CHECK_EQ(downstream_send_after.fd, downstream_send_before.fd);
    CHECK_EQ(downstream_send_after.offset, downstream_send_before.offset);
    CHECK_EQ(downstream_send_after.remaining, downstream_send_before.remaining);
    CHECK_EQ(downstream_send_after.type, downstream_send_before.type);
    CHECK_EQ(downstream_send_after.tls, downstream_send_before.tls);
    CHECK_EQ(downstream_send_after.tls_wait_events, downstream_send_before.tls_wait_events);
    CHECK_EQ(downstream_send_after.upstream_episode, downstream_send_before.upstream_episode);
    const auto& upstream_send_after = loop->backend.upstream_send_state[conn_id];
    CHECK_EQ(upstream_send_after.src, upstream_send_before.src);
    CHECK_EQ(upstream_send_after.fd, upstream_send_before.fd);
    CHECK_EQ(upstream_send_after.offset, upstream_send_before.offset);
    CHECK_EQ(upstream_send_after.remaining, upstream_send_before.remaining);
    CHECK_EQ(upstream_send_after.type, upstream_send_before.type);
    CHECK_EQ(upstream_send_after.tls, upstream_send_before.tls);
    CHECK_EQ(upstream_send_after.tls_wait_events, upstream_send_before.tls_wait_events);
    CHECK_EQ(upstream_send_after.upstream_episode, upstream_send_before.upstream_episode);
    CHECK_EQ(current_conn->on_recv, on_recv_before);
    CHECK_EQ(current_conn->on_send, on_send_before);
    CHECK_EQ(current_conn->on_upstream_recv, on_upstream_recv_before);
    CHECK_EQ(current_conn->on_upstream_send, on_upstream_send_before);
    CHECK_EQ(current_conn->timer_node.prev, timer_prev_before);
    CHECK_EQ(current_conn->timer_node.next, timer_next_before);
    CHECK_EQ(current_conn->timer_slot, timer_slot_before);
    CHECK_EQ(loop->backend.pending_count, pending_before);
    CHECK_EQ(loop->backend.pending_streak, pending_streak_before);
    CHECK_EQ(current_conn->recv_buf.len(), recv_len_before);
    CHECK_EQ(
        __builtin_memcmp(current_conn->recv_buf.data(), kRecvSentinel, sizeof(kRecvSentinel) - 1),
        0);
    CHECK_EQ(current_conn->send_buf.len(), send_len_before);
    CHECK_EQ(
        __builtin_memcmp(current_conn->send_buf.data(), kSendSentinel, sizeof(kSendSentinel) - 1),
        0);
    CHECK_EQ(current_conn->upstream_recv_buf.len(), upstream_len_before);
    CHECK_EQ(current_conn->pending_ops, pending_ops_before);
    CHECK_EQ(current_conn->upstream_recv_armed, upstream_recv_armed_before);
    CHECK_EQ(current_conn->upstream_send_armed, upstream_send_armed_before);
    CHECK_EQ(current_conn->state, state_before);
    char current_peek[sizeof(kCurrentPayload) - 1]{};
    REQUIRE_EQ(recv(current_fd, current_peek, sizeof(current_peek), MSG_PEEK | MSG_DONTWAIT),
               static_cast<ssize_t>(sizeof(current_peek)));
    REQUIRE_EQ(__builtin_memcmp(current_peek, kCurrentPayload, sizeof(current_peek)), 0);
    REQUIRE(poll_ready_without_terminal(current_fd, POLLIN, 1000, true));
    REQUIRE(poll_ready_without_terminal(loop->backend.epoll_fd, POLLIN, 1000, true));

    // The current raw readiness remained in epoll while the held record was
    // replayed. Its normal wait consumes exactly the episode-2 bytes, and the
    // resulting logical event reaches the current callback exactly once.
    IoEvent current_recv{};
    REQUIRE_EQ(loop->backend.wait(&current_recv, 1, loop->conns, EpollEventLoop::kMaxConns), 1u);
    REQUIRE_EQ(current_recv.conn_id, conn_id);
    REQUIRE_EQ(current_recv.type, IoEventType::UpstreamRecv);
    REQUIRE_EQ(current_recv.result, static_cast<i32>(sizeof(kCurrentPayload) - 1));
    REQUIRE_EQ(current_recv.upstream_episode, current_episode);
    REQUIRE_EQ(current_conn->upstream_recv_buf.len(), sizeof(kCurrentPayload) - 1);
    REQUIRE_EQ(
        __builtin_memcmp(
            current_conn->upstream_recv_buf.data(), kCurrentPayload, sizeof(kCurrentPayload) - 1),
        0);
    char unexpected_byte = 0;
    errno = 0;
    REQUIRE_EQ(recv(current_fd, &unexpected_byte, 1, MSG_PEEK | MSG_DONTWAIT), -1);
    REQUIRE(errno == EAGAIN || errno == EWOULDBLOCK);
    loop->dispatch(current_recv);
    REQUIRE_EQ(g_epoll_episode_callback_count, 1u);

    guard.close_conn(*current_conn);
    REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], 0u);
    REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], -1);
    REQUIRE_EQ(current_conn->upstream_episode, current_episode + 1);
    errno = 0;
    REQUIRE_EQ(fcntl(current_fd, F_GETFD), -1);
    REQUIRE_EQ(errno, EBADF);
    guard.free_conn(*timer_anchor);
}

TEST(epoll_episode_lifecycle, harvested_raw_partial_send_is_fenced_across_terminal_same_fd_reuse) {
    const u8 first_payload[] = {'e', 'p', 'i', 's', 'o', 'd', 'e', '-', 'o', 'n', 'e'};
    const u8 current_payload[] = {'e',
                                  'p',
                                  'i',
                                  's',
                                  'o',
                                  'd',
                                  'e',
                                  '-',
                                  't',
                                  'w',
                                  'o',
                                  '-',
                                  'c',
                                  'u',
                                  'r',
                                  'r',
                                  'e',
                                  'n',
                                  't'};
    static constexpr u8 kFirstFiller = 0x51;
    static constexpr u8 kCurrentFiller = 0xa7;

    RealEpollEpisodeGuard guard{};
    REQUIRE(guard.create());
    REQUIRE(guard.init());
    auto* loop = guard.loop;
    struct itimerspec disarmed_timer{};
    REQUIRE_EQ(timerfd_settime(loop->backend.timer_fd, 0, &disarmed_timer, nullptr), 0);
    REQUIRE_EQ(timerfd_settime(loop->backend.yield_timer_fd, 0, &disarmed_timer, nullptr), 0);

    auto listener_result = create_listen_socket(0);
    REQUIRE(listener_result.has_value());
    guard.listener_fd = listener_result.value();
    const i32 listener_fd = guard.listener_fd;
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = __builtin_bswap16(get_port(listener_fd));
    addr.sin_addr.s_addr = __builtin_bswap32(0x7F000001);

    Connection* first_conn = guard.alloc_conn();
    REQUIRE(first_conn != nullptr);
    const u32 conn_id = first_conn->id;
    const u32 first_episode = first_conn->upstream_episode;
    REQUIRE_EQ(first_episode, 1u);
    first_conn->upstream_fd = UpstreamPool::create_socket();
    REQUIRE_GE(first_conn->upstream_fd, 0);
    const i32 first_fd = first_conn->upstream_fd;
    REQUIRE(loop->submit_connect(*first_conn, &addr, sizeof(addr)));
    // This assertion is deliberately adjacent to submit_connect and precedes
    // accept/wait: a synchronous success/error would already have queued a
    // synthetic completion, so zero proves this is the real EINPROGRESS path.
    REQUIRE_EQ(loop->backend.pending_count, 0u);
    REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], first_episode);
    REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], first_fd);
    REQUIRE(accept_real_upstream_peer(listener_fd, guard.peer_fds[0]));
    IoEvent first_connect{};
    REQUIRE(wait_for_real_upstream_completion(*loop, first_connect));
    REQUIRE_EQ(first_connect.type, IoEventType::UpstreamConnect);
    REQUIRE_EQ(first_connect.result, 0);
    REQUIRE_EQ(first_connect.conn_id, conn_id);
    REQUIRE_EQ(first_connect.upstream_episode, first_episode);
    REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], first_episode);
    REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], first_fd);
    g_epoll_episode_callback_count = 0;
    first_conn->on_upstream_send = &epoll_episode_counting_callback;
    loop->dispatch(first_connect);
    REQUIRE_EQ(g_epoll_episode_callback_count, 1u);

    u32 first_filler_bytes = 0;
    REQUIRE(
        fill_real_tcp_send_queue(first_fd, guard.peer_fds[0], kFirstFiller, first_filler_bytes));
    REQUIRE_GT(first_filler_bytes, 0u);
    REQUIRE(loop->submit_send_upstream(*first_conn, first_payload, sizeof(first_payload)));
    REQUIRE_EQ(loop->backend.pending_count, 0u);
    const auto& first_send = loop->backend.upstream_send_state[conn_id];
    REQUIRE_EQ(first_send.src, first_payload);
    REQUIRE_EQ(first_send.fd, first_fd);
    REQUIRE_EQ(first_send.offset, 0u);
    REQUIRE_EQ(first_send.remaining, sizeof(first_payload));
    REQUIRE_EQ(first_send.type, IoEventType::UpstreamSend);
    REQUIRE_FALSE(first_send.tls);
    REQUIRE_EQ(first_send.tls_wait_events, 0u);
    REQUIRE_EQ(first_send.upstream_episode, first_episode);

    {
        ScopedHeldEpollEvent held(loop->backend.epoll_fd);
        REQUIRE(held.owns_state());
        REQUIRE(held.arm_capture_once());
        REQUIRE(drain_exact_tcp_filler(guard.peer_fds[0], first_filler_bytes, kFirstFiller));
        char unexpected_byte = 0;
        errno = 0;
        REQUIRE_EQ(recv(guard.peer_fds[0], &unexpected_byte, 1, MSG_PEEK | MSG_DONTWAIT), -1);
        REQUIRE(errno == EAGAIN || errno == EWOULDBLOCK);
        REQUIRE(poll_ready_without_terminal(first_fd, POLLOUT, 1000, true));
        REQUIRE(poll_ready_without_terminal(loop->backend.epoll_fd, POLLIN, 1000, true));

        IoEvent suppressed{};
        REQUIRE_EQ(loop->backend.wait(&suppressed, 1, loop->conns, EpollEventLoop::kMaxConns), 0u);
        REQUIRE(held.captured());
        REQUIRE_FALSE(held.capture_armed());
        REQUIRE_FALSE(held.failed_closed());
        const u32 captured_raw_events = held.captured_events();
        const u64 captured_raw_data = held.captured_data();
        REQUIRE_NE(captured_raw_events & EPOLLOUT, 0u);
        REQUIRE_EQ(captured_raw_events & (EPOLLHUP | EPOLLERR | EPOLLRDHUP), 0u);
        UpstreamEventToken captured_token{};
        REQUIRE(decode_upstream_event_token(captured_raw_data, &captured_token));
        REQUIRE_EQ(captured_token.conn_id, conn_id);
        REQUIRE_EQ(captured_token.type, IoEventType::UpstreamRecv);
        REQUIRE_EQ(captured_token.episode, first_episode);
        REQUIRE_EQ(captured_token.aux, 0u);
        const auto& first_send_after_capture = loop->backend.upstream_send_state[conn_id];
        REQUIRE_EQ(first_send_after_capture.src, first_payload);
        REQUIRE_EQ(first_send_after_capture.fd, first_fd);
        REQUIRE_EQ(first_send_after_capture.offset, 0u);
        REQUIRE_EQ(first_send_after_capture.remaining, sizeof(first_payload));
        REQUIRE_EQ(first_send_after_capture.type, IoEventType::UpstreamSend);
        REQUIRE_FALSE(first_send_after_capture.tls);
        REQUIRE_EQ(first_send_after_capture.tls_wait_events, 0u);
        REQUIRE_EQ(first_send_after_capture.upstream_episode, first_episode);
        errno = 0;
        REQUIRE_EQ(recv(guard.peer_fds[0], &unexpected_byte, 1, MSG_PEEK | MSG_DONTWAIT), -1);
        REQUIRE(errno == EAGAIN || errno == EWOULDBLOCK);

        // Production terminal teardown removes the live registration, drops
        // partial-send state, retires episode 1, closes the socket, and frees
        // the allocator slot before the same numeric fd is reused.
        guard.close_conn(*first_conn);
        REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], 0u);
        REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], -1);
        const auto& retired_first_send = loop->backend.upstream_send_state[conn_id];
        REQUIRE_EQ(retired_first_send.src, nullptr);
        REQUIRE_EQ(retired_first_send.fd, -1);
        REQUIRE_EQ(retired_first_send.offset, 0u);
        REQUIRE_EQ(retired_first_send.remaining, 0u);
        REQUIRE_EQ(retired_first_send.type, IoEventType::UpstreamSend);
        REQUIRE_FALSE(retired_first_send.tls);
        REQUIRE_EQ(retired_first_send.tls_wait_events, 0u);
        REQUIRE_EQ(retired_first_send.upstream_episode, 0u);
        errno = 0;
        REQUIRE_EQ(fcntl(first_fd, F_GETFD), -1);
        REQUIRE_EQ(errno, EBADF);
        // Closing the saturated episode after its raw readiness was harvested
        // must expose EOF with no partial-send payload before the slot/fd is
        // reused. A momentary EAGAIN above is not the wire-integrity proof.
        REQUIRE(recv_exact_stream_to_eof(guard.peer_fds[0], nullptr, 0));

        Connection* current_conn = guard.alloc_conn();
        REQUIRE(current_conn != nullptr);
        REQUIRE_EQ(current_conn, first_conn);
        REQUIRE_EQ(current_conn->id, conn_id);
        const u32 current_episode = current_conn->upstream_episode;
        REQUIRE_EQ(current_episode, first_episode + 1);
        current_conn->upstream_fd = UpstreamPool::create_socket();
        REQUIRE_GE(current_conn->upstream_fd, 0);
        const i32 current_fd = current_conn->upstream_fd;
        REQUIRE_EQ(current_fd, first_fd);
        REQUIRE(loop->submit_connect(*current_conn, &addr, sizeof(addr)));
        // As above, observe the production submit result before accept or any
        // backend wait can consume a synthetic completion.
        REQUIRE_EQ(loop->backend.pending_count, 0u);
        REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], current_episode);
        REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], current_fd);
        REQUIRE(accept_real_upstream_peer(listener_fd, guard.peer_fds[1]));
        IoEvent current_connect{};
        REQUIRE(wait_for_real_upstream_completion(*loop, current_connect));
        REQUIRE_EQ(current_connect.type, IoEventType::UpstreamConnect);
        REQUIRE_EQ(current_connect.result, 0);
        REQUIRE_EQ(current_connect.conn_id, conn_id);
        REQUIRE_EQ(current_connect.upstream_episode, current_episode);
        REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], current_episode);
        REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], current_fd);
        g_epoll_episode_callback_count = 0;
        current_conn->on_upstream_send = &epoll_episode_counting_callback;
        loop->dispatch(current_connect);
        REQUIRE_EQ(g_epoll_episode_callback_count, 1u);

        u32 current_filler_bytes = 0;
        REQUIRE(fill_real_tcp_send_queue(
            current_fd, guard.peer_fds[1], kCurrentFiller, current_filler_bytes));
        REQUIRE_GT(current_filler_bytes, 0u);
        REQUIRE(
            loop->submit_send_upstream(*current_conn, current_payload, sizeof(current_payload)));
        REQUIRE_EQ(loop->backend.pending_count, 0u);
        const auto& current_send = loop->backend.upstream_send_state[conn_id];
        REQUIRE_EQ(current_send.src, current_payload);
        REQUIRE_EQ(current_send.fd, current_fd);
        REQUIRE_EQ(current_send.offset, 0u);
        REQUIRE_EQ(current_send.remaining, sizeof(current_payload));
        REQUIRE_EQ(current_send.type, IoEventType::UpstreamSend);
        REQUIRE_FALSE(current_send.tls);
        REQUIRE_EQ(current_send.tls_wait_events, 0u);
        REQUIRE_EQ(current_send.upstream_episode, current_episode);
        REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], current_episode);
        REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], current_fd);
        REQUIRE(drain_exact_tcp_filler(guard.peer_fds[1], current_filler_bytes, kCurrentFiller));
        errno = 0;
        REQUIRE_EQ(recv(guard.peer_fds[1], &unexpected_byte, 1, MSG_PEEK | MSG_DONTWAIT), -1);
        REQUIRE(errno == EAGAIN || errno == EWOULDBLOCK);
        REQUIRE(poll_ready_without_terminal(current_fd, POLLOUT, 1000, true));
        REQUIRE(poll_ready_without_terminal(loop->backend.epoll_fd, POLLIN, 1000, true));

        Connection* timer_anchor = guard.alloc_conn();
        REQUIRE(timer_anchor != nullptr);
        loop->timer.add(current_conn, 5);
        loop->timer.add(timer_anchor, 5);
        REQUIRE(loop->alloc_upstream_buf(*current_conn));
        static constexpr char kRecvSentinel[] = "send-current-recv";
        static constexpr char kSendSentinel[] = "send-current-send";
        static constexpr char kUpstreamSentinel[] = "send-current-upstream";
        REQUIRE_EQ(current_conn->recv_buf.write(reinterpret_cast<const u8*>(kRecvSentinel),
                                                sizeof(kRecvSentinel) - 1),
                   sizeof(kRecvSentinel) - 1);
        REQUIRE_EQ(current_conn->send_buf.write(reinterpret_cast<const u8*>(kSendSentinel),
                                                sizeof(kSendSentinel) - 1),
                   sizeof(kSendSentinel) - 1);
        REQUIRE_EQ(
            current_conn->upstream_recv_buf.write(reinterpret_cast<const u8*>(kUpstreamSentinel),
                                                  sizeof(kUpstreamSentinel) - 1),
            sizeof(kUpstreamSentinel) - 1);
        current_conn->on_recv = &epoll_episode_counting_callback;
        current_conn->on_send = &epoll_episode_counting_callback;
        current_conn->on_upstream_recv = &epoll_episode_counting_callback;
        current_conn->on_upstream_send = &epoll_episode_counting_callback;
        current_conn->state = ConnState::Proxying;
        current_conn->pending_ops = 7;
        current_conn->upstream_recv_armed = true;
        current_conn->upstream_send_armed = true;
        g_epoll_episode_callback_count = 0;

        const Connection* ptr_before = current_conn;
        const u32 id_before = current_conn->id;
        const i32 fd_before = current_conn->upstream_fd;
        const i32 map_before = loop->backend.upstream_fd_map[conn_id];
        const u32 owner_before = loop->backend.active_upstream_episode[conn_id];
        const u32 token_before = current_conn->upstream_episode;
        const auto upstream_send_before = loop->backend.upstream_send_state[conn_id];
        const auto downstream_send_before = loop->backend.send_state[conn_id];
        const auto on_recv_before = current_conn->on_recv;
        const auto on_send_before = current_conn->on_send;
        const auto on_upstream_recv_before = current_conn->on_upstream_recv;
        const auto on_upstream_send_before = current_conn->on_upstream_send;
        const ListNode* timer_prev_before = current_conn->timer_node.prev;
        const ListNode* timer_next_before = current_conn->timer_node.next;
        const u16 timer_slot_before = current_conn->timer_slot;
        const u32 pending_before = loop->backend.pending_count;
        const u32 pending_streak_before = loop->backend.pending_streak;
        const u32 recv_len_before = current_conn->recv_buf.len();
        const u32 send_len_before = current_conn->send_buf.len();
        const u32 upstream_len_before = current_conn->upstream_recv_buf.len();
        const u32 pending_ops_before = current_conn->pending_ops;
        const bool upstream_recv_armed_before = current_conn->upstream_recv_armed;
        const bool upstream_send_armed_before = current_conn->upstream_send_armed;
        const ConnState state_before = current_conn->state;

        // This replay isolates the top raw owner/token fence: the passing path
        // never reaches the lower send-state episode check. Without the top
        // fence, that lower mismatch path could rearm the fd under episode 1 and
        // strand episode-2 progress. The separate
        // stale_tls_send_cannot_rearm_or_hijack_current_recv regression directly
        // exercises the lower fence. Together they give layered coverage; this
        // replay alone does not execute both layers.
        REQUIRE(held.replay_once());
        IoEvent stale_output{0x00ffffffu,
                             -1234,
                             0xffffu,
                             1,
                             IoEventType::Count,
                             1,
                             0xff,
                             kInvalidUpstreamEventEpisode};
        REQUIRE_EQ(loop->backend.wait(&stale_output, 1, loop->conns, EpollEventLoop::kMaxConns),
                   0u);
        CHECK(held.replay_consumed());
        CHECK_FALSE(held.replay_armed());
        CHECK_FALSE(held.failed_closed());
        CHECK_EQ(held.captured_events(), captured_raw_events);
        CHECK_EQ(held.captured_data(), captured_raw_data);
        CHECK_EQ(stale_output.conn_id, 0x00ffffffu);
        CHECK_EQ(stale_output.result, -1234);
        CHECK_EQ(stale_output.buf_id, 0xffffu);
        CHECK_EQ(stale_output.has_buf, 1);
        CHECK_EQ(stale_output.type, IoEventType::Count);
        CHECK_EQ(stale_output.more, 1);
        CHECK_EQ(stale_output.aux, 0xff);
        CHECK_EQ(stale_output.upstream_episode, kInvalidUpstreamEventEpisode);
        CHECK_EQ(g_epoll_episode_callback_count, 0u);
        CHECK_EQ(current_conn, ptr_before);
        CHECK_EQ(current_conn->id, id_before);
        CHECK_EQ(current_conn->upstream_fd, fd_before);
        CHECK_EQ(loop->backend.upstream_fd_map[conn_id], map_before);
        CHECK_EQ(loop->backend.active_upstream_episode[conn_id], owner_before);
        CHECK_EQ(current_conn->upstream_episode, token_before);
        const auto& upstream_send_after = loop->backend.upstream_send_state[conn_id];
        CHECK_EQ(upstream_send_after.src, upstream_send_before.src);
        CHECK_EQ(upstream_send_after.fd, upstream_send_before.fd);
        CHECK_EQ(upstream_send_after.offset, upstream_send_before.offset);
        CHECK_EQ(upstream_send_after.remaining, upstream_send_before.remaining);
        CHECK_EQ(upstream_send_after.type, upstream_send_before.type);
        CHECK_EQ(upstream_send_after.tls, upstream_send_before.tls);
        CHECK_EQ(upstream_send_after.tls_wait_events, upstream_send_before.tls_wait_events);
        CHECK_EQ(upstream_send_after.upstream_episode, upstream_send_before.upstream_episode);
        const auto& downstream_send_after = loop->backend.send_state[conn_id];
        CHECK_EQ(downstream_send_after.src, downstream_send_before.src);
        CHECK_EQ(downstream_send_after.fd, downstream_send_before.fd);
        CHECK_EQ(downstream_send_after.offset, downstream_send_before.offset);
        CHECK_EQ(downstream_send_after.remaining, downstream_send_before.remaining);
        CHECK_EQ(downstream_send_after.type, downstream_send_before.type);
        CHECK_EQ(downstream_send_after.tls, downstream_send_before.tls);
        CHECK_EQ(downstream_send_after.tls_wait_events, downstream_send_before.tls_wait_events);
        CHECK_EQ(downstream_send_after.upstream_episode, downstream_send_before.upstream_episode);
        CHECK_EQ(current_conn->on_recv, on_recv_before);
        CHECK_EQ(current_conn->on_send, on_send_before);
        CHECK_EQ(current_conn->on_upstream_recv, on_upstream_recv_before);
        CHECK_EQ(current_conn->on_upstream_send, on_upstream_send_before);
        CHECK_EQ(current_conn->timer_node.prev, timer_prev_before);
        CHECK_EQ(current_conn->timer_node.next, timer_next_before);
        CHECK_EQ(current_conn->timer_slot, timer_slot_before);
        CHECK_EQ(loop->backend.pending_count, pending_before);
        CHECK_EQ(loop->backend.pending_streak, pending_streak_before);
        CHECK_EQ(current_conn->recv_buf.len(), recv_len_before);
        CHECK_EQ(__builtin_memcmp(
                     current_conn->recv_buf.data(), kRecvSentinel, sizeof(kRecvSentinel) - 1),
                 0);
        CHECK_EQ(current_conn->send_buf.len(), send_len_before);
        CHECK_EQ(__builtin_memcmp(
                     current_conn->send_buf.data(), kSendSentinel, sizeof(kSendSentinel) - 1),
                 0);
        CHECK_EQ(current_conn->upstream_recv_buf.len(), upstream_len_before);
        CHECK_EQ(__builtin_memcmp(current_conn->upstream_recv_buf.data(),
                                  kUpstreamSentinel,
                                  sizeof(kUpstreamSentinel) - 1),
                 0);
        CHECK_EQ(current_conn->pending_ops, pending_ops_before);
        CHECK_EQ(current_conn->upstream_recv_armed, upstream_recv_armed_before);
        CHECK_EQ(current_conn->upstream_send_armed, upstream_send_armed_before);
        CHECK_EQ(current_conn->state, state_before);
        errno = 0;
        CHECK_EQ(recv(guard.peer_fds[1], &unexpected_byte, 1, MSG_PEEK | MSG_DONTWAIT), -1);
        CHECK(errno == EAGAIN || errno == EWOULDBLOCK);
        REQUIRE(poll_ready_without_terminal(current_fd, POLLOUT, 1000, true));
        REQUIRE(poll_ready_without_terminal(loop->backend.epoll_fd, POLLIN, 1000, true));

        IoEvent current_send_completion{};
        REQUIRE_EQ(
            loop->backend.wait(&current_send_completion, 1, loop->conns, EpollEventLoop::kMaxConns),
            1u);
        REQUIRE_EQ(current_send_completion.conn_id, conn_id);
        REQUIRE_EQ(current_send_completion.type, IoEventType::UpstreamSend);
        REQUIRE_EQ(current_send_completion.result, static_cast<i32>(sizeof(current_payload)));
        REQUIRE_EQ(current_send_completion.aux, 0u);
        REQUIRE_EQ(current_send_completion.upstream_episode, current_episode);
        const auto& completed_send = loop->backend.upstream_send_state[conn_id];
        REQUIRE_EQ(completed_send.src, nullptr);
        REQUIRE_EQ(completed_send.fd, -1);
        REQUIRE_EQ(completed_send.offset, 0u);
        REQUIRE_EQ(completed_send.remaining, 0u);
        REQUIRE_EQ(completed_send.type, IoEventType::UpstreamSend);
        REQUIRE_FALSE(completed_send.tls);
        REQUIRE_EQ(completed_send.tls_wait_events, 0u);
        REQUIRE_EQ(completed_send.upstream_episode, 0u);
        // Only after the current partial send has completed, half-close the
        // producer and verify the complete post-filler stream through recv()==0.
        // This excludes a hidden prefix, suffix, or duplicate payload.
        REQUIRE_EQ(shutdown(current_fd, SHUT_WR), 0);
        REQUIRE(
            recv_exact_stream_to_eof(guard.peer_fds[1], current_payload, sizeof(current_payload)));
        loop->dispatch(current_send_completion);
        REQUIRE_EQ(g_epoll_episode_callback_count, 1u);

        guard.close_conn(*current_conn);
        REQUIRE_EQ(loop->backend.active_upstream_episode[conn_id], 0u);
        REQUIRE_EQ(loop->backend.upstream_fd_map[conn_id], -1);
        REQUIRE_EQ(current_conn->upstream_episode, current_episode + 1);
        errno = 0;
        REQUIRE_EQ(fcntl(current_fd, F_GETFD), -1);
        REQUIRE_EQ(errno, EBADF);
        guard.free_conn(*timer_anchor);
    }
}

TEST(epoll_episode, stale_tls_send_cannot_rearm_or_hijack_current_recv) {
    EpollBackend backend{};
    REQUIRE(backend.init(0, -1).has_value());
    i32 fds[2] = {-1, -1};
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_NONBLOCK, 0, fds), 0);
    EpollEpisodeSocketGuard guard{&backend, fds};

    Connection conns[1]{};
    conns[0].reset();
    conns[0].id = 0;
    conns[0].upstream_episode = 1;
    u8 storage[64] = {};
    conns[0].upstream_recv_buf.bind(storage, sizeof(storage));
    REQUIRE(backend.begin_upstream_episode(0, 1));
    static const u8 payload[] = {'s', 't', 'a', 'l', 'e'};
    // Register a current EPOLLIN|EPOLLOUT interest, then make only the
    // stored send state stale. The real fd/readiness path must not perform the
    // stale TLS write or rearm the old WANT_READ state.
    backend.upstream_send_state[0] = {
        payload, fds[0], 0, sizeof(payload), IoEventType::UpstreamSend, true, EPOLLOUT, 1};
    REQUIRE(backend.add_recv_upstream(fds[0], 0, 1));
    backend.upstream_send_state[0] = {
        payload, fds[0], 0, sizeof(payload), IoEventType::UpstreamSend, true, EPOLLIN, 2};

    const auto before = backend.upstream_send_state[0];
    IoEvent events[1]{};
    CHECK_EQ(backend.wait(events, 1, conns, 1), 0u);
    CHECK_EQ(backend.upstream_send_state[0].src, before.src);
    CHECK_EQ(backend.upstream_send_state[0].fd, before.fd);
    CHECK_EQ(backend.upstream_send_state[0].offset, before.offset);
    CHECK_EQ(backend.upstream_send_state[0].remaining, before.remaining);
    CHECK_EQ(backend.upstream_send_state[0].tls, before.tls);
    CHECK_EQ(backend.upstream_send_state[0].tls_wait_events, before.tls_wait_events);
    CHECK_EQ(backend.upstream_send_state[0].upstream_episode, before.upstream_episode);
    u8 peer_payload[sizeof(payload)] = {};
    CHECK_EQ(recv(fds[1], peer_payload, sizeof(peer_payload), MSG_DONTWAIT), -1);
    CHECK(errno == EAGAIN || errno == EWOULDBLOCK);

    const ssize_t nw = write(fds[1], "r", 1);
    CHECK_EQ(nw, 1);
    if (nw != 1) return;
    const u32 event_count = backend.wait(events, 1, conns, 1);
    CHECK_EQ(event_count, 1u);
    if (event_count != 1) return;
    CHECK_EQ(events[0].type, IoEventType::UpstreamRecv);
    CHECK_EQ(events[0].upstream_episode, 1u);
    CHECK_EQ(events[0].result, 1);
    CHECK_EQ(conns[0].upstream_recv_buf.len(), 1u);
}

TEST(epoll_loop, callbacks_static_route_send_keepalive) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());

    RouteConfig cfg;
    cfg.add_static("/health", 0, 204);
    const RouteConfig* active = &cfg;
    loop->config_ptr = &active;

    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = dup(2);
    REQUIRE(c->fd >= 0);
    loop->timer.add(c, loop->keepalive_timeout);

    static const char kReq[] = "GET /health HTTP/1.1\r\nHost: x\r\n\r\n";
    c->recv_buf.write(reinterpret_cast<const u8*>(kReq), sizeof(kReq) - 1);

    on_header_received<EpollEventLoop>(
        static_cast<void*>(loop), *c, make_ev(c->id, IoEventType::Recv, sizeof(kReq) - 1));
    CHECK_EQ(c->resp_status, 204u);
    CHECK_EQ(c->state, ConnState::Sending);
    CHECK_EQ(c->on_send, &on_response_sent<EpollEventLoop>);

    on_response_sent<EpollEventLoop>(
        static_cast<void*>(loop), *c, make_ev(c->id, IoEventType::Send, c->send_buf.len()));
    CHECK_EQ(c->state, ConnState::ReadingHeader);
    CHECK_EQ(c->on_recv, &on_header_received<EpollEventLoop>);

    close(c->fd);
    c->fd = -1;
    loop->free_conn(*c);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(connection_lifecycle,
     downstream_completed_request_count_is_transport_owned_exact_once_and_saturating) {
    SmallLoop loop;
    loop.setup();
    RouteConfig config{};
    REQUIRE(config.add_static("/", 0, 204));

    Connection* conn =
        dispatch_unmatched_request(loop, config, "GET /first HTTP/1.1\r\nHost: x\r\n\r\n");
    REQUIRE(conn != nullptr);
    const u32 id = conn->id;
    CHECK_EQ(conn->downstream_completed_request_count, 0u);

    const u32 first_wire_len = conn->send_buf.len();
    REQUIRE_GT(first_wire_len, 3u);
    loop.inject_and_dispatch(make_ev(id, IoEventType::Send, 3));
    CHECK_EQ(conn->downstream_completed_request_count, 0u);
    loop.inject_and_dispatch(make_ev(id, IoEventType::Send, static_cast<i32>(first_wire_len - 3u)));
    REQUIRE_EQ(conn->downstream_completed_request_count, 1u);
    REQUIRE_EQ(conn->state, ConnState::ReadingHeader);

    // A duplicated terminal callback has no live request-completion ownership.
    on_request_complete<SmallLoop>(&loop, *conn, 204, first_wire_len);
    CHECK_EQ(conn->downstream_completed_request_count, 1u);

    static constexpr char kSecond[] = "GET /second HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kSecond), sizeof(kSecond) - 1u),
               sizeof(kSecond) - 1u);
    const RouteConfig* active = &config;
    loop.config_ptr = &active;
    on_header_received<SmallLoop>(
        &loop, *conn, make_ev(id, IoEventType::Recv, static_cast<i32>(sizeof(kSecond) - 1u)));
    loop.config_ptr = nullptr;
    REQUIRE_EQ(conn->downstream_completed_request_count, 1u);
    const u32 second_wire_len = conn->send_buf.len();
    loop.inject_and_dispatch(make_ev(id, IoEventType::Send, static_cast<i32>(second_wire_len)));
    REQUIRE_EQ(conn->downstream_completed_request_count, 2u);
    REQUIRE_EQ(conn->state, ConnState::ReadingHeader);

    loop.close_conn(*conn);
    CHECK_EQ(loop.conns[id].downstream_completed_request_count, 0u);
    Connection* reused = loop.alloc_conn();
    REQUIRE(reused != nullptr);
    REQUIRE_EQ(reused->id, id);
    CHECK_EQ(reused->downstream_completed_request_count, 0u);

    reused->fd = 81;
    static constexpr char kFailed[] =
        "GET /failed HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
    REQUIRE_EQ(reused->recv_buf.write(reinterpret_cast<const u8*>(kFailed), sizeof(kFailed) - 1u),
               sizeof(kFailed) - 1u);
    loop.config_ptr = &active;
    on_header_received<SmallLoop>(
        &loop, *reused, make_ev(id, IoEventType::Recv, static_cast<i32>(sizeof(kFailed) - 1u)));
    loop.config_ptr = nullptr;
    REQUIRE_EQ(reused->downstream_completed_request_count, 0u);
    loop.inject_and_dispatch(make_ev(id, IoEventType::Send, -EPIPE));
    CHECK_EQ(loop.conns[id].downstream_completed_request_count, 0u);

    Connection* saturating = loop.alloc_conn();
    REQUIRE(saturating != nullptr);
    REQUIRE_EQ(saturating->id, id);
    saturating->downstream_completed_request_count = ~u32{0} - 1u;
    saturating->req_start_us = monotonic_us();
    on_request_complete<SmallLoop>(&loop, *saturating, 204, 0);
    REQUIRE_EQ(saturating->downstream_completed_request_count, ~u32{0});
    saturating->req_start_us = monotonic_us();
    on_request_complete<SmallLoop>(&loop, *saturating, 204, 0);
    CHECK_EQ(saturating->downstream_completed_request_count, ~u32{0});
    saturating->reset();
    CHECK_EQ(saturating->downstream_completed_request_count, 0u);
}

TEST(epoll_loop, callbacks_pipeline_incomplete_rearms_recv) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());

    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = dup(2);
    REQUIRE(c->fd >= 0);
    c->pipeline_depth = 1;
    c->resp_status = 502;
    c->resp_body_mode = BodyMode::Chunked;
    c->resp_body_remaining = 11;
    c->resp_chunk_parser.state = ChunkedParser::State::Data;
    c->resp_chunk_parser.chunk_remaining = 13;
    c->resp_chunk_parser.has_digits = true;
    c->resp_body_sent = 17;
    c->upstream_send_len = 19;
    c->handler_gen = 23;
    c->req_start_us = 29;
    loop->timer.add(c, loop->keepalive_timeout);

    static const char kPartial[] = "GET /next HTTP/1.1\r\nHos";
    c->recv_buf.write(reinterpret_cast<const u8*>(kPartial), sizeof(kPartial) - 1);

    on_header_received<EpollEventLoop>(
        static_cast<void*>(loop), *c, make_ev(c->id, IoEventType::Recv, sizeof(kPartial) - 1));
    CHECK_EQ(c->state, ConnState::ReadingHeader);
    CHECK_EQ(c->on_recv, &on_header_received<EpollEventLoop>);
    CHECK_EQ(c->pipeline_depth, 1u);
    CHECK_EQ(c->recv_buf.len(), static_cast<u32>(sizeof(kPartial) - 1));
    CHECK_EQ(c->resp_status, 502u);
    CHECK_EQ(c->resp_body_mode, BodyMode::Chunked);
    CHECK_EQ(c->resp_body_remaining, 11u);
    CHECK_EQ(c->resp_chunk_parser.state, ChunkedParser::State::Data);
    CHECK_EQ(c->resp_chunk_parser.chunk_remaining, 13u);
    CHECK(c->resp_chunk_parser.has_digits);
    CHECK_EQ(c->resp_body_sent, 17u);
    CHECK_EQ(c->upstream_send_len, 19u);
    CHECK_EQ(c->handler_gen, 23u);
    CHECK_EQ(c->req_start_us, 29u);

    close(c->fd);
    c->fd = -1;
    loop->free_conn(*c);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(epoll_loop, callbacks_capture_truncated_entry) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());

    CaptureRing ring;
    ring.init();
    REQUIRE(loop->set_capture(&ring));

    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = dup(2);
    REQUIRE(c->fd >= 0);
    REQUIRE(c->capture_buf != nullptr);

    c->req_start_us = monotonic_us();
    c->req_method = static_cast<u8>(LogHttpMethod::Get);
    c->req_content_length = 123;
    c->capture_header_len = CaptureEntry::kMaxHeaderLen;
    c->shard_id = 7;
    c->upstream_name[0] = 'u';
    c->upstream_name[1] = 'p';
    c->upstream_name[2] = '\0';
    for (u32 i = 0; i < CaptureEntry::kMaxHeaderLen; i++) c->capture_buf[i] = 'A';

    on_request_complete<EpollEventLoop>(loop, *c, 200, 321);

    CHECK_EQ(ring.available(), 1u);
    CaptureEntry cap{};
    REQUIRE(ring.pop(cap));
    CHECK_EQ(cap.flags & kCaptureFlagTruncated, kCaptureFlagTruncated);
    CHECK_EQ(cap.raw_header_len, static_cast<u16>(CaptureEntry::kMaxHeaderLen));
    CHECK_EQ(cap.resp_status, 200u);

    close(c->fd);
    c->fd = -1;
    loop->free_conn(*c);
    loop->shutdown();
    destroy_real_loop(loop);
}

TEST(epoll_loop, callbacks_upstream_connected_and_send_error_paths) {
    auto* loop = create_real_loop();
    REQUIRE(loop != nullptr);
    auto res = loop->init(0, -1, 0);
    REQUIRE(res.has_value());

    auto* malformed = loop->alloc_conn();
    REQUIRE(malformed != nullptr);
    malformed->fd = dup(2);
    malformed->upstream_fd = dup(2);
    REQUIRE(malformed->fd >= 0);
    REQUIRE(malformed->upstream_fd >= 0);
    malformed->req_malformed = true;
    on_upstream_connected<EpollEventLoop>(static_cast<void*>(loop),
                                          *malformed,
                                          make_ev(malformed->id, IoEventType::UpstreamConnect, 0));
    CHECK_EQ(loop->active_count(), 0u);

    auto* armed = loop->alloc_conn();
    REQUIRE(armed != nullptr);
    armed->fd = dup(2);
    armed->upstream_fd = dup(2);
    REQUIRE(armed->fd >= 0);
    REQUIRE(armed->upstream_fd >= 0);
    static const char kReq[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    armed->recv_buf.write(reinterpret_cast<const u8*>(kReq), sizeof(kReq) - 1);
    armed->req_initial_send_len = armed->recv_buf.len() + 32;
    on_upstream_connected<EpollEventLoop>(
        static_cast<void*>(loop), *armed, make_ev(armed->id, IoEventType::UpstreamConnect, 0));
    CHECK_EQ(armed->state, ConnState::Proxying);
    CHECK_EQ(armed->on_upstream_recv, &on_early_upstream_recvd_send_inflight<EpollEventLoop>);
    CHECK_EQ(armed->on_upstream_send, &on_upstream_request_sent<EpollEventLoop>);
    CHECK(armed->upstream_recv_slice != nullptr);

    armed->upstream_recv_armed = true;
    armed->upstream_recv_buf.reset();
    on_upstream_request_sent<EpollEventLoop>(
        static_cast<void*>(loop), *armed, make_ev(armed->id, IoEventType::UpstreamSend, -32));
    CHECK_EQ(armed->on_upstream_recv, &on_upstream_response<EpollEventLoop>);
    CHECK_EQ(armed->on_upstream_send, nullptr);

    loop->close_conn(*armed);
    CHECK_EQ(loop->active_count(), 0u);
    loop->shutdown();
    destroy_real_loop(loop);
}

// === Coverage: drain inject with no-body response ===

TEST(drain, inject_close_header_no_body) {
    SmallLoop loop;
    loop.setup();
    loop.draining = true;
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    loop.inject_and_dispatch(make_ev(c->id, IoEventType::Recv, 100));
    c->upstream_fd = 100;
    c->on_upstream_send = &on_upstream_connected<SmallLoop>;
    loop.inject_and_dispatch(make_ev(c->id, IoEventType::UpstreamConnect, 0));
    loop.inject_and_dispatch(make_ev(c->id, IoEventType::UpstreamSend, 100));

    // 204 No Content — no body, no Connection header → inject "Connection: close"
    static const char resp204[] = "HTTP/1.1 204 No Content\r\n\r\n";
    u32 rlen = sizeof(resp204) - 1;
    c->upstream_recv_buf.reset();
    u8* dst = c->upstream_recv_buf.write_ptr();
    for (u32 j = 0; j < rlen; j++) dst[j] = static_cast<u8>(resp204[j]);
    c->upstream_recv_buf.commit(rlen);
    IoEvent ev = make_ev(c->id, IoEventType::UpstreamRecv, static_cast<i32>(rlen));
    loop.backend.inject(ev);
    IoEvent events[8];
    u32 n = loop.backend.wait(events, 8);
    for (u32 i = 0; i < n; i++) loop.dispatch(events[i]);
    CHECK_EQ(c->keep_alive, false);
}

