TEST(metadata, fallback_all_methods) {
    SmallLoop loop;
    loop.setup();
    // Test each method through capture_request_metadata fallback
    struct {
        const char* req;
        u32 len;
        u8 expected;
    } cases[] = {
        {"GET / HTTP/1.1\r\nH", 17, static_cast<u8>(LogHttpMethod::Get)},
        {"POST / HTTP/1.1\r\nH", 18, static_cast<u8>(LogHttpMethod::Post)},
        {"PUT / HTTP/1.1\r\nH", 17, static_cast<u8>(LogHttpMethod::Put)},
        {"DELETE / HTTP/1.1\r\nH", 20, static_cast<u8>(LogHttpMethod::Delete)},
        {"PATCH / HTTP/1.1\r\nH", 19, static_cast<u8>(LogHttpMethod::Patch)},
        {"HEAD / HTTP/1.1\r\nH", 18, static_cast<u8>(LogHttpMethod::Head)},
        {"OPTIONS / HTTP/1.1\r\nH", 21, static_cast<u8>(LogHttpMethod::Options)},
        {"CONNECT / HTTP/1.1\r\nH", 21, static_cast<u8>(LogHttpMethod::Connect)},
        {"TRACE / HTTP/1.1\r\nH", 19, static_cast<u8>(LogHttpMethod::Trace)},
    };
    for (auto& tc : cases) {
        loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 50));
        auto* c = loop.find_fd(50);
        if (!c) continue;
        c->recv_buf.reset();
        u8* dst = c->recv_buf.write_ptr();
        for (u32 j = 0; j < tc.len; j++) dst[j] = static_cast<u8>(tc.req[j]);
        c->recv_buf.commit(tc.len);
        capture_request_metadata(*c);
        CHECK_EQ(c->req_method, tc.expected);
        loop.close_conn(*c);
    }
}

TEST(metadata, format_static_response_wire_format) {
    struct TestCase {
        u16 code;
        const char* reason;
        u32 body_len;
        bool keep_alive;
    };

    const TestCase cases[] = {
        {100, "Unknown", 0, true},
        {200, "OK", 2, true},
        {201, "Created", 7, false},
        {204, "No Content", 0, true},
        {301, "Moved Permanently", 17, false},
        {302, "Found", 5, true},
        {304, "Not Modified", 0, false},
        {400, "Bad Request", 11, true},
        {401, "Unauthorized", 12, false},
        {403, "Forbidden", 9, true},
        {404, "Not Found", 9, false},
        {405, "Method Not Allowed", 18, true},
        {429, "Too Many Requests", 17, false},
        {500, "Internal Server Error", 21, true},
        {502, "Bad Gateway", 11, false},
        {503, "Service Unavailable", 19, true},
        {418, "Unknown", 7, false},
    };

    for (const auto& tc : cases) {
        Connection conn;
        conn.reset();
        u8 send_storage[4096];
        conn.send_buf.bind(send_storage, sizeof(send_storage));

        CHECK(__builtin_strcmp(status_reason(tc.code), tc.reason) == 0);
        format_static_response(conn, tc.code, tc.keep_alive);

        const u8* data = conn.send_buf.data();
        const u32 len = conn.send_buf.len();
        REQUIRE(data != nullptr);
        CHECK_GT(len, 0u);

        CHECK_EQ(data[9], static_cast<u8>('0' + (tc.code / 100) % 10));
        CHECK_EQ(data[10], static_cast<u8>('0' + (tc.code / 10) % 10));
        CHECK_EQ(data[11], static_cast<u8>('0' + tc.code % 10));

        u32 body_start = 0;
        u32 cl_val = 0;
        bool found_headers_end = false;
        bool found_cl = false;
        for (u32 i = 0; i + 3 < len; i++) {
            if (!found_cl && i + 16 < len && data[i] == 'C' && data[i + 1] == 'o' &&
                data[i + 8] == 'L') {
                u32 j = i + 16;
                while (j < len && data[j] >= '0' && data[j] <= '9') {
                    cl_val = cl_val * 10 + (data[j] - '0');
                    j++;
                }
                found_cl = true;
            }
            if (data[i] == '\r' && data[i + 1] == '\n' && data[i + 2] == '\r' &&
                data[i + 3] == '\n') {
                body_start = i + 4;
                found_headers_end = true;
                break;
            }
        }

        CHECK(found_cl);
        CHECK(found_headers_end);
        CHECK_EQ(cl_val, tc.body_len);
        CHECK_EQ(len - body_start, tc.body_len);

        const char* keep_hdr =
            tc.keep_alive ? "Connection: keep-alive\r\n" : "Connection: close\r\n";
        const u32 keep_hdr_len = tc.keep_alive ? 24u : 19u;
        bool found_keep_hdr = false;
        for (u32 i = 0; i + keep_hdr_len <= len; i++) {
            bool match = true;
            for (u32 j = 0; j < keep_hdr_len; j++) {
                if (data[i + j] != static_cast<u8>(keep_hdr[j])) {
                    match = false;
                    break;
                }
            }
            if (match) {
                found_keep_hdr = true;
                break;
            }
        }
        CHECK(found_keep_hdr);

        if (tc.body_len > 0) {
            bool found_body = true;
            for (u32 j = 0; j < tc.body_len; j++) {
                if (data[body_start + j] != static_cast<u8>(tc.reason[j])) {
                    found_body = false;
                    break;
                }
            }
            CHECK(found_body);
        }

        conn.send_buf.bind(nullptr, 0);
    }
}

TEST(local_response_persistence, exact_request_boundary_matrix) {
    SmallLoop loop;
    loop.setup();
    auto* conn = loop.alloc_conn();
    REQUIRE(conn != nullptr);

    auto classify = [&](const char* raw) -> bool {
        conn->recv_buf.reset();
        const u32 len = static_cast<u32>(strlen(raw));
        const u32 written = conn->recv_buf.write(reinterpret_cast<const u8*>(raw), len);
        CHECK_EQ(written, len);
        if (written != len) return false;
        capture_request_metadata(*conn);
        return ordinary_local_response_request_boundary_reusable(*conn);
    };

    CHECK(classify("GET / HTTP/1.1\r\nHost: x\r\n\r\n"));
    CHECK(classify("POST / HTTP/1.1\r\nContent-Length: 0\r\n\r\n"));
    CHECK(classify("POST / HTTP/1.1\r\nContent-Length: 3\r\n\r\nabc"));
    CHECK(!classify("POST / HTTP/1.1\r\nContent-Length: 3\r\n\r\nab"));
    CHECK(classify("POST / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n3\r\nabc\r\n0\r\n\r\n"));
    CHECK(!classify("POST / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n3\r\nab"));
    CHECK(!classify("POST / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\nz\r\n"));
    CHECK(
        classify("POST / HTTP/1.1\r\nContent-Length: 3\r\n\r\nabc"
                 "GET /next HTTP/1.1\r\nHost: x\r\n\r\n"));
    CHECK(
        !classify("POST / HTTP/1.0\r\nConnection: keep-alive\r\n"
                  "Transfer-Encoding: chunked\r\n\r\n0\r\n\r\n"));
    CHECK(!classify("POST / HTTP/1.1\r\nTransfer-Encoding: gzip\r\n\r\n"));

    REQUIRE(classify("GET / HTTP/1.1\r\nHost: x\r\n\r\n"));
    conn->protocol = ConnProtocol::Http2;
    CHECK(!ordinary_local_response_request_boundary_reusable(*conn));
    conn->protocol = ConnProtocol::Http11;
    conn->req_client_transfer_encoding = RequestTransferEncoding::Unparsed;
    CHECK(!ordinary_local_response_request_boundary_reusable(*conn));
    capture_request_metadata(*conn);
    conn->req_client_has_transfer_encoding = true;
    CHECK(!ordinary_local_response_request_boundary_reusable(*conn));
    capture_request_metadata(*conn);
    conn->req_initial_send_len = conn->req_header_end - 1;
    CHECK(!ordinary_local_response_request_boundary_reusable(*conn));
    capture_request_metadata(*conn);
    conn->req_initial_send_len = conn->recv_buf.len() + 1;
    CHECK(!ordinary_local_response_request_boundary_reusable(*conn));

    conn->recv_buf.reset();
    static constexpr char kReset[] = "GET / HTTP/1.1\r\nTE: trailers\r\n\r\n";
    REQUIRE_EQ(conn->recv_buf.write(reinterpret_cast<const u8*>(kReset), sizeof(kReset) - 1),
               sizeof(kReset) - 1);
    capture_request_metadata(*conn);
    CHECK_EQ(static_cast<u8>(conn->req_client_transfer_encoding),
             static_cast<u8>(RequestTransferEncoding::None));
    CHECK(ordinary_local_response_request_boundary_reusable(*conn));

    static constexpr char kChunkedPipeline[] =
        "POST / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n"
        "3\r\nabc\r\n0\r\n\r\n"
        "GET /next HTTP/1.1\r\nHost: x\r\n\r\n";
    REQUIRE(classify(kChunkedPipeline));
    const u32 exact_chunked_end = conn->req_initial_send_len;
    REQUIRE_GT(exact_chunked_end, conn->req_header_end);
    REQUIRE_LT(exact_chunked_end, conn->recv_buf.len());
    conn->req_initial_send_len = exact_chunked_end - 1;
    CHECK(!ordinary_local_response_request_boundary_reusable(*conn));
    conn->req_initial_send_len = exact_chunked_end + 1;
    CHECK(!ordinary_local_response_request_boundary_reusable(*conn));
    conn->req_initial_send_len = exact_chunked_end;
    CHECK(ordinary_local_response_request_boundary_reusable(*conn));
}

TEST(local_response_persistence, ordinary_jit_connection_close_owns_send_until_terminal) {
    for (const bool recv_stays_live : {false, true}) {
        AsyncSmallLoop loop;
        loop.setup();
        RouteConfig config{};
        REQUIRE(config.add_jit_handler(
            "/local", kRouteMethodGet, &response_read_timeout_later_handler, false));
        const RouteConfig* active = &config;
        loop.config_ptr = &active;
        loop.dispatch(make_ev(0, IoEventType::Accept, 42));
        Connection* conn = loop.find_fd(42);
        REQUIRE(conn != nullptr);
        REQUIRE(conn->recv_armed);

        static constexpr char kRequests[] =
            "GET /local HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n"
            "GET /local HTTP/1.1\r\nHost: x\r\n\r\n";
        REQUIRE_EQ(
            conn->recv_buf.write(reinterpret_cast<const u8*>(kRequests), sizeof(kRequests) - 1),
            sizeof(kRequests) - 1);
        response_read_timeout_later_handler_calls = 0;
        loop.dispatch(make_ev_more(conn->id,
                                   IoEventType::Recv,
                                   static_cast<i32>(sizeof(kRequests) - 1),
                                   recv_stays_live ? 1 : 0));

        REQUIRE_EQ(conn->state, ConnState::Sending);
        REQUIRE_EQ(conn->on_send, &on_response_sent<AsyncSmallLoop>);
        CHECK_EQ(response_read_timeout_later_handler_calls, 1u);
        CHECK_FALSE(conn->keep_alive);
        static constexpr char kExpected[] =
            "HTTP/1.1 204 No Content\r\n"
            "Content-Length: 0\r\n"
            "Connection: close\r\n"
            "\r\n";
        REQUIRE_EQ(conn->send_buf.len(), sizeof(kExpected) - 1);
        CHECK_EQ(__builtin_memcmp(conn->send_buf.data(), kExpected, sizeof(kExpected) - 1), 0);
        CHECK_EQ(conn->recv_armed, recv_stays_live);
        CHECK_EQ(conn->pipeline_depth, 0u);
        const u32 id = conn->id;
        const u32 send_len = conn->send_buf.len();
        REQUIRE_GT(send_len, 1u);

        loop.backend.clear_ops();
        loop.dispatch(make_ev(id, IoEventType::Send, 1));
        REQUIRE_EQ(loop.conns[id].fd, 42);
        CHECK_EQ(loop.conns[id].state, ConnState::Sending);
        CHECK_EQ(loop.conns[id].on_send, &on_response_sent<AsyncSmallLoop>);
        CHECK_EQ(loop.conns[id].send_progress, 1u);
        CHECK_EQ(response_read_timeout_later_handler_calls, 1u);
        CHECK_EQ(loop.conns[id].pipeline_depth, 0u);
        CHECK_EQ(loop.conns[id].recv_buf.len(), sizeof(kRequests) - 1);
        CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
        const MockOp* remainder = loop.backend.last_op(MockOp::Send);
        REQUIRE(remainder != nullptr);
        CHECK_EQ(remainder->send_buf, conn->send_buf.data() + 1);
        CHECK_EQ(remainder->send_len, send_len - 1);

        loop.backend.clear_ops();
        loop.dispatch(make_ev(id, IoEventType::Send, static_cast<i32>(send_len - 1)));
        CHECK_EQ(loop.conns[id].fd, -1);
        CHECK_EQ(response_read_timeout_later_handler_calls, 1u);
        CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
        if (recv_stays_live) {
            CHECK_EQ(loop.pending_free_count, 1u);
            CHECK_GT(loop.backend.count_ops(MockOp::Cancel), 0u);
        } else {
            CHECK_EQ(loop.pending_free_count, 0u);
            CHECK_EQ(loop.backend.count_ops(MockOp::Cancel), 0u);
        }
    }
}

TEST(local_response_persistence, ordinary_publishers_share_wire_and_lifecycle_decision) {
    auto make_loop = [] {
        auto loop = std::make_unique<SmallLoop>();
        loop->setup();
        return loop;
    };
    auto dispatch = [](SmallLoop& loop, RouteConfig* config, const char* request) -> Connection* {
        const RouteConfig* active = config;
        loop.config_ptr = config == nullptr ? nullptr : &active;
        loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
        Connection* conn = loop.find_fd(42);
        if (conn == nullptr) return nullptr;
        conn->recv_buf.reset();
        const u32 len = static_cast<u32>(strlen(request));
        if (conn->recv_buf.write(reinterpret_cast<const u8*>(request), len) != len) return nullptr;
        loop.dispatch(make_ev(conn->id, IoEventType::Recv, static_cast<i32>(len)));
        loop.config_ptr = nullptr;
        return conn;
    };
    auto check_wire = [&](const Connection& conn, bool keep_alive) {
        CHECK_EQ(conn.keep_alive, keep_alive);
        CHECK(buf_has(conn.send_buf.data(),
                      conn.send_buf.len(),
                      keep_alive ? "Connection: keep-alive\r\n" : "Connection: close\r\n"));
    };

    {
        auto loop = make_loop();
        Connection* conn = dispatch(*loop, nullptr, "GET / HTTP/1.1\r\nHost: x\r\n\r\n");
        REQUIRE(conn != nullptr);
        check_wire(*conn, true);  // legacy/default 200
    }
    {
        auto loop = make_loop();
        Connection* conn =
            dispatch(*loop, nullptr, "GET / HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n");
        REQUIRE(conn != nullptr);
        check_wire(*conn, false);
    }
    {
        auto loop = make_loop();
        RouteConfig config{};
        REQUIRE(config.add_static("/local", kRouteMethodGet, 204));
        Connection* conn = dispatch(*loop,
                                    &config,
                                    "GET /local HTTP/1.0\r\nHost: x\r\n"
                                    "Connection: keep-alive\r\n\r\n");
        REQUIRE(conn != nullptr);
        check_wire(*conn, true);  // lifecycle only; #282 owns the status-line version
    }
    {
        auto loop = make_loop();
        RouteConfig config{};
        REQUIRE(config.add_jit_handler(
            "/local", kRouteMethodGet, &response_read_timeout_later_handler, false));
        Connection* conn = dispatch(*loop, &config, "GET /local HTTP/1.1\r\nHost: x\r\n\r\n");
        REQUIRE(conn != nullptr);
        CHECK_EQ(conn->resp_status, 204u);
        check_wire(*conn, true);  // immediate JIT ReturnStatus
    }
    {
        auto loop = make_loop();
        ShardMetrics shard{};
        shard.init();
        ShardMetrics* shards[] = {&shard};
        loop->all_shard_metrics = shards;
        loop->shard_metrics_count = 1;
        Connection* conn = dispatch(*loop, nullptr, "GET /metrics HTTP/1.1\r\nHost: x\r\n\r\n");
        REQUIRE(conn != nullptr);
        CHECK_EQ(conn->resp_status, 200u);
        check_wire(*conn, true);
    }
    {
        auto loop = make_loop();
        RouteConfig config{};
        REQUIRE(config.add_static("/local", kRouteMethodGet, 204));
        loop->draining = true;
        Connection* conn = dispatch(*loop, &config, "GET /local HTTP/1.1\r\nHost: x\r\n\r\n");
        REQUIRE(conn != nullptr);
        check_wire(*conn, false);  // drain already active at publication
    }
    {
        auto loop = make_loop();
        Connection* conn = dispatch(*loop, nullptr, "GET / HTTP/1.1\r\nHost: x\r\n\r\n");
        REQUIRE(conn != nullptr);
        const u32 id = conn->id;
        const u32 len = conn->send_buf.len();
        loop->draining = true;
        loop->inject_and_dispatch(make_ev(id, IoEventType::Send, static_cast<i32>(len)));
        CHECK_EQ(loop->conns[id].fd, -1);  // drain began after publication
    }
}

