    static const char kCoalesced[] =
        "HTTP/1.1 100 Continue\r\n\r\n"
        "HTTP/1.1 413 Request Entity Too Large\r\n"
        "Content-Length: 0\r\n"
        "Connection: close\r\n"
        "\r\n";
