// === Coverage: legacy EventLoop<Backend> alloc_upstream_buf ===

static u64 state_invariant_wait_recv_then_status(
    void*, jit::HandlerCtx* ctx, const u8*, u32, void*);

TEST(legacy_loop, alloc_upstream_buf) {
    auto loop = std::make_unique<EventLoop<MockBackend>>();
    auto initialized = loop->init(0, -1);
    REQUIRE(initialized);
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);

    CHECK(loop->alloc_upstream_buf(*c));
    CHECK(c->upstream_recv_slice != nullptr);
    CHECK(loop->alloc_upstream_buf(*c));

    loop->free_conn(*c);
    loop->shutdown();
}

TEST(legacy_loop, lazy_aux_buffers_handle_exhaustion_atomically) {
    auto loop = std::make_unique<EventLoop<MockBackend>>();
    REQUIRE(loop->init(0, -1).has_value());
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);

    // Lazy buffers bind exactly once and are released with the connection.
    CHECK(loop->alloc_response_header_buf(*c));
    u8* response_headers = c->response_header_slice;
    REQUIRE(response_headers != nullptr);
    CHECK(loop->alloc_response_header_buf(*c));
    CHECK_EQ(c->response_header_slice, response_headers);

    CHECK(loop->alloc_ws_terminate_bufs(*c));
    u8* ws_c2u = c->ws_c2u_msg;
    u8* ws_u2c = c->ws_u2c_msg;
    REQUIRE(ws_c2u != nullptr);
    REQUIRE(ws_u2c != nullptr);
    CHECK(loop->alloc_ws_terminate_bufs(*c));
    CHECK_EQ(c->ws_c2u_msg, ws_c2u);
    CHECK_EQ(c->ws_u2c_msg, ws_u2c);

    c->fd = -1;
    loop->free_conn(*c);

    c = loop->alloc_conn();
    REQUIRE(c != nullptr);

    // Freeze growth at the currently committed size, then leave one slice.
    // The two-slice WebSocket allocation must roll the first allocation back.
    const u32 original_max = loop->pool.max_count;
    loop->pool.max_count = loop->pool.count;
    std::vector<u8*> held;
    while (loop->pool.available() > 1) held.push_back(loop->pool.alloc());
    REQUIRE_EQ(loop->pool.available(), 1u);
    CHECK(!loop->alloc_ws_terminate_bufs(*c));
    CHECK_EQ(c->ws_c2u_msg, nullptr);
    CHECK_EQ(c->ws_u2c_msg, nullptr);
    CHECK_EQ(loop->pool.available(), 1u);

    u8* last = loop->pool.alloc();
    REQUIRE(last != nullptr);
    REQUIRE_EQ(loop->pool.available(), 0u);
    CHECK(!loop->alloc_upstream_buf(*c));
    CHECK(!loop->alloc_response_header_buf(*c));
    CHECK(!loop->alloc_ws_terminate_bufs(*c));

    loop->pool.max_count = original_max;
    loop->pool.free(last);
    for (u8* slice : held) loop->pool.free(slice);
    c->fd = -1;
    loop->free_conn(*c);
    loop->shutdown();
}

TEST(legacy_async_loop, immediate_free_releases_all_lazy_buffers) {
    auto loop = std::make_unique<EventLoop<AsyncMockBackend>>();
    REQUIRE(loop->init(0, -1).has_value());
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    REQUIRE(loop->alloc_upstream_buf(*c));
    REQUIRE(loop->alloc_response_header_buf(*c));
    REQUIRE(loop->alloc_ws_terminate_bufs(*c));

    c->fd = -1;
    c->pending_ops = 0;
    loop->free_conn(*c);
    CHECK_EQ(c->recv_slice, nullptr);
    CHECK_EQ(c->send_slice, nullptr);
    CHECK_EQ(c->upstream_recv_slice, nullptr);
    CHECK_EQ(c->response_header_slice, nullptr);
    CHECK_EQ(c->ws_c2u_msg, nullptr);
    CHECK_EQ(c->ws_u2c_msg, nullptr);
    loop->shutdown();
}

static void legacy_noop_recv_cb(void*, rut::ConnectionBase&, rut::IoEvent) {}

// Drives EventLoop<MockBackend>'s timer-tick ladder and the dispatch refresh
// across the proxy-timeout / @throttle branches that the rebase merged into the
// legacy loop — exercised by neither the e2e (epoll/io_uring) nor the other
// legacy tests. Tick: a Proxying-stalled conn → 504, a throttle_paused conn →
// resume, an idle conn → close. Refresh: a throttle_paused conn's timer is NOT
// bumped (so the byte-rate window owns it); a non-paused one is.
TEST(legacy_loop, timer_tick_and_refresh_throttle_proxy_branches) {
    auto loop = std::make_unique<EventLoop<MockBackend>>();
    REQUIRE(loop->init(0, -1).has_value());
    ShardMetrics metrics;
    metrics.init();
    loop->metrics = &metrics;
    ShardEpoch epoch;
    epoch.epoch.store(0, std::memory_order_relaxed);
    loop->epoch = &epoch;

    // Tick: throttle_paused (budget recovered) → throttle_resume → re-arm.
    auto* a = loop->alloc_conn();
    REQUIRE(a != nullptr);
    a->fd = -1;
    a->throttle_paused = true;
    a->throttle_down_bps = 1'000'000u;
    a->throttle_tat_ns = 0;  // not ahead → resume completes
    a->throttle_pending_len = 0;
    REQUIRE(loop->alloc_upstream_buf(*a));
    loop->timer.add(a, 1);

    // Tick: Proxying with no response yet → respond_upstream_timeout (504).
    auto* b = loop->alloc_conn();
    REQUIRE(b != nullptr);
    b->fd = -1;
    b->state = ConnState::Proxying;
    b->proxy_resp_started = false;
    loop->timer.add(b, 1);

    // Tick: idle keep-alive → close.
    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = -1;
    c->state = ConnState::ReadingHeader;
    loop->timer.add(c, 1);

    IoEvent tick{};
    tick.type = IoEventType::Timeout;
    // Conns were added one slot ahead (add(_, 1)); the wheel fires slots[cursor]
    // then advances, so two ticks are needed to reach their slot.
    tick.result = 2;
    loop->dispatch(tick);  // fires a, b, c → tick ladder branches
    CHECK(!a->throttle_paused);

    // Refresh: a throttle_paused conn with a live callback → refresh is skipped.
    auto* d = loop->alloc_conn();
    REQUIRE(d != nullptr);
    d->fd = -1;
    d->throttle_paused = true;
    d->on_recv = &legacy_noop_recv_cb;
    IoEvent rd{};
    rd.type = IoEventType::Recv;
    rd.conn_id = d->id;
    rd.result = 1;
    loop->dispatch(rd);  // covers the `if (!throttle_paused) refresh` skip

    // Refresh: a non-paused Proxying conn → refresh with the upstream deadline.
    auto* e = loop->alloc_conn();
    REQUIRE(e != nullptr);
    e->fd = -1;
    e->state = ConnState::Proxying;
    e->on_recv = &legacy_noop_recv_cb;
    IoEvent re{};
    re.type = IoEventType::Recv;
    re.conn_id = e->id;
    re.result = 1;
    loop->dispatch(re);

    loop->shutdown();
}

TEST(legacy_loop, sync_submit_and_close_paths) {
    auto loop = std::make_unique<EventLoop<MockBackend>>();
    auto initialized = loop->init(0, -1);
    REQUIRE(initialized);
    ShardMetrics metrics;
    metrics.init();
    metrics.connections_active = 1;
    metrics.requests_active = 1;
    loop->metrics = &metrics;
    ShardEpoch epoch;
    epoch.epoch.store(0, std::memory_order_relaxed);
    loop->epoch = &epoch;

    auto* c = loop->alloc_conn();
    REQUIRE(c != nullptr);
    c->fd = dup(2);
    REQUIRE(c->fd >= 0);
    c->upstream_fd = dup(2);
    REQUIRE(c->upstream_fd >= 0);
    c->req_start_us = 1;
    CHECK(loop->alloc_upstream_buf(*c));

    static const u8 kBody[] = {'o', 'k'};
    sockaddr_in addr{};
    CHECK(loop->submit_recv(*c));
    loop->submit_send(*c, kBody, sizeof(kBody));
    CHECK(loop->submit_connect(*c, &addr, sizeof(addr)));
    CHECK(loop->submit_send_upstream(*c, kBody, sizeof(kBody)));
    CHECK(loop->submit_recv_upstream(*c));

    loop->backend.fail_connect = true;
    CHECK(!loop->submit_connect(*c, &addr, sizeof(addr)));
    loop->backend.fail_upstream_send = true;
    CHECK(!loop->submit_send_upstream(*c, kBody, sizeof(kBody)));
    loop->backend.fail_upstream_recv = true;
    CHECK(!loop->submit_recv_upstream(*c));

    loop->close_conn(*c);
    CHECK_EQ(metrics.connections_closed, 1u);
    CHECK_EQ(metrics.connections_active, 0u);
    CHECK_EQ(metrics.requests_active, 0u);
    CHECK_EQ(epoch.epoch.load(std::memory_order_relaxed), 1u);
    loop->shutdown();
}

