TEST(slot_hygiene, on_send_cleared_after_response_header_sent) {
    SmallLoop loop;
    loop.setup();
    auto* c = setup_proxy_conn(loop);
    REQUIRE(c != nullptr);
    // Large response → streaming (on_response_header_sent)
    static const char kResp[] =
        "HTTP/1.1 200 OK\r\n"
        "Content-Length: 10000\r\n"
        "\r\n";
    u32 rlen = sizeof(kResp) - 1;
    c->upstream_recv_buf.reset();
    u8* dst = c->upstream_recv_buf.write_ptr();
    for (u32 j = 0; j < rlen; j++) dst[j] = static_cast<u8>(kResp[j]);
    c->upstream_recv_buf.commit(rlen);
    IoEvent ev = make_ev(c->id, IoEventType::UpstreamRecv, static_cast<i32>(rlen));
    loop.backend.inject(ev);
    IoEvent events[8];
    u32 n = loop.backend.wait(events, 8);
    for (u32 i = 0; i < n; i++) loop.dispatch(events[i]);
    CHECK_EQ(c->on_send, &on_response_header_sent<SmallLoop>);
    // Send headers → on_send cleared
    loop.inject_and_dispatch(make_ev(c->id, IoEventType::Send, static_cast<i32>(rlen)));
    CHECK_EQ(c->on_send, nullptr);
}

// ==========================================================================
// Exhaustive dispatch tests: verify per-event-type slot isolation and
// centralized null-slot handling.
// ==========================================================================

// --- Part 1: handle_unhandled_recv (null on_recv) ---
// Tests the centralized Recv tolerance in dispatch_event.

TEST(dispatch, null_recv_data_keepalive_preserves_buf) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    // Process request so on_send is set
    loop.inject_and_dispatch(make_ev(c->id, IoEventType::Recv, 100));
    c->on_recv = nullptr;
    c->keep_alive = true;
    // Write data then dispatch → handle_unhandled_recv preserves buf
    c->recv_buf.reset();
    u8* dst = c->recv_buf.write_ptr();
    dst[0] = 'A';
    c->recv_buf.commit(1);
    loop.dispatch(make_ev(c->id, IoEventType::Recv, 50));
    CHECK(c->fd >= 0);
    CHECK_GT(c->recv_buf.len(), 0u);  // preserved for pipeline
}

TEST(dispatch, null_recv_data_no_keepalive_drains_buf) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    // Process request so on_send is set (dispatch guard needs at least one slot)
    REQUIRE(dispatch_complete_http1_test_request(loop, *c));
    c->on_recv = nullptr;
    c->keep_alive = false;
    // Write data then dispatch directly → handle_unhandled_recv → reset.
    c->recv_buf.reset();
    u8* dst = c->recv_buf.write_ptr();
    for (u32 j = 0; j < 50; j++) dst[j] = static_cast<u8>(j);
    c->recv_buf.commit(50);
    loop.dispatch(make_ev(c->id, IoEventType::Recv, 50));
    CHECK(c->fd >= 0);
    CHECK_EQ(c->recv_buf.len(), 0u);  // drained
}

TEST(dispatch, null_recv_eof_tolerates_halfclose) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    loop.inject_and_dispatch(make_ev(c->id, IoEventType::Recv, 100));
    c->on_recv = nullptr;
    loop.dispatch(make_ev(c->id, IoEventType::Recv, 0));  // EOF
    CHECK(c->fd >= 0);                                    // tolerated
}

TEST(dispatch, null_recv_enobufs_closes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    // Process request so slots are active
    REQUIRE(dispatch_complete_http1_test_request(loop, *c));
    c->on_recv = nullptr;
    u32 cid = c->id;
    loop.dispatch(make_ev(cid, IoEventType::Recv, -105));  // -ENOBUFS
    CHECK_EQ(loop.conns[cid].fd, -1);
}

// --- Part 2: null upstream slots (ignored) ---

TEST(dispatch, null_upstream_recv_ignored) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    c->on_upstream_recv = nullptr;
    loop.dispatch(make_ev(c->id, IoEventType::UpstreamRecv, 100));
    CHECK(c->fd >= 0);
}

TEST(dispatch, null_upstream_recv_enobufs_closes) {
    SmallLoop loop;
    loop.setup();
    loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
    auto* c = loop.find_fd(42);
    REQUIRE(c != nullptr);
    // Process request so on_send is set (dispatch guard active)
    REQUIRE(dispatch_complete_http1_test_request(loop, *c));
    c->on_upstream_recv = nullptr;
    u32 cid = c->id;
    // -ENOBUFS on null upstream_recv → close (prevent hot-loop)
    loop.dispatch(make_ev(cid, IoEventType::UpstreamRecv, -105));
    CHECK_EQ(loop.conns[cid].fd, -1);
}

TEST(proxy_response, header_enobufs_never_parses_or_publishes_copied_prefix) {
    static constexpr const char* kLossyPrefixes[] = {
        "HTTP/1.1 200 OK\r\nContent-Len",
        "HTTP/1.1 200 OK\r\nContent-Length: 12\r\n\r\nhello",
    };
    for (const char* prefix : kLossyPrefixes) {
        SmallLoop loop;
        loop.setup();
        loop.inject_and_dispatch(make_ev(0, IoEventType::Accept, 42));
        Connection* conn = loop.find_fd(42);
        REQUIRE(conn != nullptr);
        REQUIRE(loop.alloc_upstream_buf(*conn));
        const u32 len = static_cast<u32>(strlen(prefix));
        REQUIRE_EQ(conn->upstream_recv_buf.write(reinterpret_cast<const u8*>(prefix), len), len);
        conn->upstream_fd = 100;
        conn->state = ConnState::Proxying;
        conn->on_upstream_recv = &on_upstream_response<SmallLoop>;
        loop.backend.clear_ops();
        const u32 id = conn->id;

        on_upstream_response<SmallLoop>(
            &loop, *conn, make_ev(id, IoEventType::UpstreamRecv, -ENOBUFS));

        CHECK_EQ(loop.conns[id].fd, -1);
        CHECK_EQ(loop.backend.count_ops(MockOp::Send), 0u);
    }
}

TEST(proxy_response, ordinary_h1_recv_rearm_failure_closes_at_each_header_transition) {
    enum class Transition : u8 { Initial, IncompleteHeader, Interim, HeaderToBody };
    for (const Transition transition : {Transition::Initial,
                                        Transition::IncompleteHeader,
                                        Transition::Interim,
                                        Transition::HeaderToBody}) {
        AsyncSmallLoop loop;
        loop.setup();
        Connection* conn = loop.alloc_conn();
        REQUIRE(conn != nullptr);
        REQUIRE(loop.alloc_upstream_buf(*conn));
        conn->fd = 42;
        conn->upstream_fd = 100;
        conn->state = ConnState::Proxying;
        loop.backend.fail_upstream_recv = true;
        const u32 id = conn->id;

        switch (transition) {
            case Transition::Initial: {
                static constexpr u8 kRequest[] = "GET / HTTP/1.1\r\nHost: test\r\n\r\n";
                REQUIRE_EQ(conn->recv_buf.write(kRequest, sizeof(kRequest) - 1u),
                           sizeof(kRequest) - 1u);
                conn->req_initial_send_len = sizeof(kRequest) - 1u;
                conn->req_body_mode = BodyMode::None;
                on_upstream_request_sent<AsyncSmallLoop>(
                    &loop,
                    *conn,
                    make_ev(
                        id, IoEventType::UpstreamSend, static_cast<i32>(sizeof(kRequest) - 1u)));
                break;
            }
            case Transition::IncompleteHeader: {
                static constexpr u8 kPartial[] = "HTTP/1.1 200 OK\r\nContent-Len";
                REQUIRE_EQ(conn->upstream_recv_buf.write(kPartial, sizeof(kPartial) - 1u),
                           sizeof(kPartial) - 1u);
                on_upstream_response<AsyncSmallLoop>(
                    &loop,
                    *conn,
                    make_ev(
                        id, IoEventType::UpstreamRecv, static_cast<i32>(sizeof(kPartial) - 1u)));
                break;
            }
            case Transition::Interim: {
                static constexpr u8 kInterim[] = "HTTP/1.1 100 Continue\r\n\r\n";
                REQUIRE_EQ(conn->upstream_recv_buf.write(kInterim, sizeof(kInterim) - 1u),
                           sizeof(kInterim) - 1u);
                on_upstream_response<AsyncSmallLoop>(
                    &loop,
                    *conn,
                    make_ev(
                        id, IoEventType::UpstreamRecv, static_cast<i32>(sizeof(kInterim) - 1u)));
                break;
            }
            case Transition::HeaderToBody: {
                static constexpr u8 kHeader[] = "HTTP/1.1 200 OK\r\nContent-Length: 12\r\n\r\n";
                REQUIRE_EQ(conn->upstream_recv_buf.write(kHeader, sizeof(kHeader) - 1u),
                           sizeof(kHeader) - 1u);
                conn->upstream_send_len = sizeof(kHeader) - 1u;
                conn->resp_body_mode = BodyMode::ContentLength;
                conn->resp_body_remaining = 12;
                on_response_header_sent<AsyncSmallLoop>(
                    &loop,
                    *conn,
                    make_ev(id, IoEventType::Send, static_cast<i32>(sizeof(kHeader) - 1u)));
                break;
            }
        }

        CHECK_EQ(loop.conns[id].fd, -1);
        CHECK_EQ(loop.backend.count_ops(MockOp::Recv), 0u);
    }
}

