TEST(iouring_staged_local_send, rejects_deadline_and_request_buffer_owners_without_mutation) {
    static constexpr u8 kResponse[] = "HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\n\r\n";
    u32 cases = 0;
    const auto rejected = [&](auto&& make_unsafe, bool use_send_buf = false) {
        StagedLocalSendFixture fixture;
        REQUIRE(fixture.stage(kResponse, sizeof(kResponse) - 1u));
        auto* loop = fixture.loop;
        Connection& conn = *fixture.conn;
        if (use_send_buf)
            REQUIRE_EQ(conn.send_buf.write(kResponse, sizeof(kResponse) - 1u),
                       sizeof(kResponse) - 1u);
        make_unsafe(*loop, conn);
        const u8* const src = use_send_buf ? conn.send_buf.data() : conn.response_header_buf.data();
        const u32 len = use_send_buf ? conn.send_buf.len() : conn.response_header_buf.len();
        const u32 head_before = __atomic_load_n(loop->backend.sq_head, __ATOMIC_ACQUIRE);
        const u32 tail_before = __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
        const u32 backend_pending_before = loop->backend.pending;
        const u32 conn_pending_before = conn.pending_ops;
        const auto send_before = loop->backend.send_state[conn.id];
        const auto upstream_send_before = loop->backend.upstream_send_state[conn.id];
        u32 attempts = 0;
        u32 enter_calls = 0;

        CHECK_FALSE(loop->test_submit_staged_local_response(
            conn,
            src,
            len,
            [&]() { ++attempts; },
            [&]() {
                ++enter_calls;
                return 1;
            }));
        CHECK_EQ(attempts, 0u);
        CHECK_EQ(enter_calls, 0u);
        CHECK_EQ(__atomic_load_n(loop->backend.sq_head, __ATOMIC_ACQUIRE), head_before);
        CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE), tail_before);
        CHECK_EQ(loop->backend.pending, backend_pending_before);
        CHECK_EQ(conn.pending_ops, conn_pending_before);
        CHECK_FALSE(conn.send_armed);
        CHECK(same_send_state(loop->backend.send_state[conn.id], send_before));
        CHECK(same_send_state(loop->backend.upstream_send_state[conn.id], upstream_send_before));
        CHECK_EQ(conn.response_header_buf.len(), sizeof(kResponse) - 1u);
        CHECK(__builtin_memcmp(
                  conn.response_header_buf.data(), kResponse, sizeof(kResponse) - 1u) == 0);
        ++cases;
    };

    rejected([](IoUringEventLoop&, Connection& c) {
        c.response_read_deadline_state = ResponseReadDeadlineState::Validated;
    });
    rejected([](IoUringEventLoop&, Connection& c) {
        c.response_read_deadline_state = ResponseReadDeadlineState::Armed;
    });
    rejected([](IoUringEventLoop&, Connection& c) {
        c.response_read_deadline_state = ResponseReadDeadlineState::ExpiryPending;
    });
    rejected([](IoUringEventLoop&, Connection& c) {
        c.response_read_deadline_post_commit_phase = ResponseReadDeadlinePostCommitPhase::Buffering;
    });
    rejected([](IoUringEventLoop&, Connection& c) {
        c.response_read_deadline_send_owner_active = true;
    });
    rejected([](IoUringEventLoop&, Connection& c) {
        c.response_read_deadline_send_close_target_owned = true;
    });
    rejected([](IoUringEventLoop&, Connection& c) {
        c.response_read_deadline_send_close_cancel_owned = true;
    });
    rejected([](IoUringEventLoop&, Connection&) {}, true);
    rejected([](IoUringEventLoop&, Connection& c) { c.upstream_send_armed = true; });
    rejected([](IoUringEventLoop& loop, Connection& c) {
        loop.backend.upstream_send_state[c.id].remaining = 1;
    });
    rejected([](IoUringEventLoop&, Connection& c) { c.upstream_send_len = 1; });
    rejected([](IoUringEventLoop&, Connection& c) { c.retry_req_send_len = 1; });
    rejected([](IoUringEventLoop&, Connection& c) { c.pipeline_stash_len = 1; });
    rejected([](IoUringEventLoop&, Connection& c) { c.response_mutations_snapshotted = true; });
    rejected([](IoUringEventLoop&, Connection& c) { c.upstream_request_incomplete = true; });
    CHECK_EQ(cases, 15u);
}

static u64 response_read_deadline_neutrality_test_handler(
    void*, jit::HandlerCtx*, const u8*, u32, void*) {
    return 0;
}

template <typename Value>
void make_response_read_deadline_owner_non_neutral(Value& value, const Value& neutral) {
    if constexpr (std::is_same_v<Value, bool>) {
        value = !neutral;
    } else if constexpr (std::is_same_v<Value, jit::HandlerFn>) {
        value = &response_read_deadline_neutrality_test_handler;
    } else if constexpr (std::is_pointer_v<Value>) {
        static const u8 marker = 0;
        value = &marker;
    } else if constexpr (std::is_enum_v<Value>) {
        using Raw = std::underlying_type_t<Value>;
        value = static_cast<Value>(static_cast<Raw>(neutral) == 0 ? 1 : 0);
    } else {
        value = neutral == Value{0} ? Value{1} : Value{0};
    }
}

TEST(iouring_upstream_recv, response_deadline_neutrality_inventory_is_exhaustive) {
    Connection conn;
    conn.reset();
    REQUIRE(conn.response_read_deadline_owner_is_neutral());
    u32 fields_tested = 0;
    const auto reject_each = [&](auto& value, const auto& neutral) {
        using Value = std::remove_cvref_t<decltype(value)>;
        make_response_read_deadline_owner_non_neutral<Value>(value, neutral);
        CHECK_FALSE(conn.response_read_deadline_owner_is_neutral());
        value = neutral;
        CHECK(conn.response_read_deadline_owner_is_neutral());
        ++fields_tested;
    };
    Connection::visit_response_read_deadline_owner_fields(conn, reject_each);
    Connection::visit_response_read_deadline_send_owner_fields(conn, reject_each);
    Connection::visit_response_read_deadline_send_close_owner_fields(conn, reject_each);
    ResponseReadDeadlineUploadProof::visit_owner_fields(conn.response_read_deadline_upload,
                                                        reject_each);
    ResponseReadDeadlineUploadProof::visit_owner_fields(
        conn.response_read_deadline_first_batch_upload, reject_each);
    CHECK_EQ(fields_tested, 68u);

    // The same canonical inventory drives both clear paths, including the
    // separately-lived send-close owner that clear_response_read_deadline()
    // intentionally preserves until slot reset.
    Connection::visit_response_read_deadline_owner_fields(conn, [&](auto& value, const auto& n) {
        make_response_read_deadline_owner_non_neutral(value, n);
    });
    Connection::visit_response_read_deadline_send_owner_fields(
        conn, [&](auto& value, const auto& n) {
            make_response_read_deadline_owner_non_neutral(value, n);
        });
    ResponseReadDeadlineUploadProof::visit_owner_fields(
        conn.response_read_deadline_upload, [&](auto& value, const auto& n) {
            make_response_read_deadline_owner_non_neutral(value, n);
        });
    ResponseReadDeadlineUploadProof::visit_owner_fields(
        conn.response_read_deadline_first_batch_upload, [&](auto& value, const auto& n) {
            make_response_read_deadline_owner_non_neutral(value, n);
        });
    conn.clear_response_read_deadline();
    CHECK(conn.response_read_deadline_owner_is_neutral());
    Connection::visit_response_read_deadline_send_close_owner_fields(
        conn, [&](auto& value, const auto& n) {
            make_response_read_deadline_owner_non_neutral(value, n);
        });
    conn.clear_response_read_deadline();
    CHECK_FALSE(conn.response_read_deadline_owner_is_neutral());
    conn.reset();
    CHECK(conn.response_read_deadline_owner_is_neutral());
}

struct ScopedOneShotSelectorResources {
    IoUringEventLoop* loop = nullptr;
    Connection* conn = nullptr;
    SSL_CTX* ssl_ctx = nullptr;
    i32 peer_fd = -1;
    u32 sq_tail_before = 0;
    u32 backend_pending_before = 0;
    bool ring_snapshot = false;

    ~ScopedOneShotSelectorResources() {
        if (loop == nullptr) return;
        if (ring_snapshot) {
            __atomic_store_n(loop->backend.sq_tail, sq_tail_before, __ATOMIC_RELEASE);
            loop->backend.pending = backend_pending_before;
        }
        if (conn != nullptr) {
            conn->pending_ops = 0;
            conn->upstream_recv_armed = false;
            if (conn->fd >= 0)
                loop->close_conn(*conn);
            else if (conn->recv_slice != nullptr)
                loop->free_conn(*conn);
        }
        if (peer_fd >= 0) close(peer_fd);
        if (ssl_ctx != nullptr) SSL_CTX_free(ssl_ctx);
    }

    void snapshot_ring() {
        sq_tail_before = __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
        backend_pending_before = loop->backend.pending;
        ring_snapshot = true;
    }
};

TEST(iouring_upstream_recv, one_shot_selector_is_narrow_and_episode_stable) {
    ScopedIoUringLoopForRetirement guard;
    if (!guard.init()) SKIP("io_uring unavailable");
    auto* loop = guard.loop;
    Connection* conn = loop->alloc_conn();
    REQUIRE(conn != nullptr);
    ScopedOneShotSelectorResources resources;
    resources.loop = loop;
    resources.conn = conn;

    RouteConfig pinned;
    pinned.upstream_count = 1;
    RouteConfig hot;
    hot.upstream_count = 0;
    const RouteConfig* hot_ptr = &hot;
    loop->config_ptr = &hot_ptr;

    i32 downstream[2] = {-1, -1};
    REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0, downstream), 0);
    conn->fd = downstream[0];
    resources.peer_fd = downstream[1];
    conn->upstream_fd = dup(STDERR_FILENO);
    REQUIRE_GE(conn->upstream_fd, 0);
    resources.ssl_ctx = SSL_CTX_new(TLS_server_method());
    REQUIRE(resources.ssl_ctx != nullptr);
    conn->tls_engine.ssl = SSL_new(resources.ssl_ctx);
    REQUIRE(conn->tls_engine.ssl != nullptr);
    conn->state = ConnState::Proxying;
    conn->request_config = &pinned;
    conn->req_start_us = monotonic_us();
    conn->upstream_attempts = 1;
    conn->request_upload_complete = true;
    conn->tls_active = true;
    conn->tls_handshake_complete = true;
    conn->protocol = ConnProtocol::Http11;
    conn->on_upstream_recv = &on_upstream_response<IoUringEventLoop>;

    // Selection is bound to the request-pinned config, not the deliberately
    // invalid hot active one.
    CHECK(loop->use_one_shot_upstream_recv(*conn));
    hot.upstream_count = 1;
    pinned.upstream_count = 0;
    CHECK_FALSE(loop->use_one_shot_upstream_recv(*conn));
    pinned.upstream_count = 1;
    hot.upstream_count = 0;
    CHECK(loop->use_one_shot_upstream_recv(*conn));
    conn->on_upstream_recv = &on_response_body_recvd<IoUringEventLoop>;
    conn->state = ConnState::Sending;
    conn->tls_proxy_stream = true;
    CHECK(loop->use_one_shot_upstream_recv(*conn));
    conn->on_upstream_recv = &on_upstream_response<IoUringEventLoop>;
    conn->state = ConnState::Proxying;

    auto rejected_while = [&](auto mutate, auto restore) {
        mutate();
        CHECK_FALSE(loop->use_one_shot_upstream_recv(*conn));
        restore();
        CHECK(loop->use_one_shot_upstream_recv(*conn));
    };
    rejected_while([&] { conn->tls_active = false; }, [&] { conn->tls_active = true; });
    rejected_while([&] { conn->tls_handshake_complete = false; },
                   [&] { conn->tls_handshake_complete = true; });
    rejected_while([&] { conn->protocol = ConnProtocol::Http2; },
                   [&] { conn->protocol = ConnProtocol::Http11; });
    rejected_while([&] { conn->request_config = nullptr; },
                   [&] { conn->request_config = &pinned; });
    rejected_while([&] { conn->request_upload_complete = false; },
                   [&] { conn->request_upload_complete = true; });
    rejected_while([&] { conn->req_client_has_content_length = true; },
                   [&] { conn->req_client_has_content_length = false; });
    rejected_while([&] { conn->req_client_has_transfer_encoding = true; },
                   [&] { conn->req_client_has_transfer_encoding = false; });
    rejected_while([&] { conn->req_client_has_expect = true; },
                   [&] { conn->req_client_has_expect = false; });
    rejected_while([&] { conn->req_body_mode = BodyMode::ContentLength; },
                   [&] { conn->req_body_mode = BodyMode::None; });
    rejected_while([&] { conn->req_body_streamed = true; },
                   [&] { conn->req_body_streamed = false; });
    rejected_while([&] { conn->req_wants_upgrade = true; },
                   [&] { conn->req_wants_upgrade = false; });
    rejected_while([&] { conn->is_health_probe = true; }, [&] { conn->is_health_probe = false; });
    rejected_while([&] { conn->is_ws_tunnel = true; }, [&] { conn->is_ws_tunnel = false; });
    rejected_while([&] { conn->response_read_deadline_state = ResponseReadDeadlineState::Armed; },
                   [&] { conn->response_read_deadline_state = ResponseReadDeadlineState::None; });
    rejected_while([&] { conn->upstream_abandoned = true; },
                   [&] { conn->upstream_abandoned = false; });
    rejected_while([&] { conn->upstream_recv_terminal_stale = true; },
                   [&] { conn->upstream_recv_terminal_stale = false; });
    rejected_while([&] { conn->upstream_recv_idle_stale_bytes = true; },
                   [&] { conn->upstream_recv_idle_stale_bytes = false; });
    rejected_while([&] { conn->upstream_recv_pause_rearm_pending = true; },
                   [&] { conn->upstream_recv_pause_rearm_pending = false; });
    // Attempts can change only when a retry selects a new upstream episode;
    // an existing selected episode remains one-shot across response progress.
    rejected_while([&] { conn->upstream_attempts = 2; }, [&] { conn->upstream_attempts = 1; });
    rejected_while([&] { conn->on_upstream_recv = &test_sentinel_callback<IoUringEventLoop>; },
                   [&] { conn->on_upstream_recv = &on_upstream_response<IoUringEventLoop>; });

    // Both facts are mutable during one response episode. They must not switch
    // a receive that began one-shot back to multishot after first response data
    // or a control-plane drain request.
    conn->upstream_reused = true;
    CHECK(loop->use_one_shot_upstream_recv(*conn));
    loop->drain(5);
    CHECK(loop->use_one_shot_upstream_recv(*conn));

    resources.snapshot_ring();
    const u32 tail_before = resources.sq_tail_before;
    REQUIRE(loop->submit_recv_upstream(*conn));
    CHECK(conn->upstream_recv_armed);
    CHECK_EQ(conn->pending_ops, 1u);
    const auto& first = loop->backend.sq_entries[tail_before & *loop->backend.sq_ring_mask];
    CHECK_EQ(first.ioprio & IORING_RECV_MULTISHOT, 0u);

    // An already-armed call is idempotent. Each simulated terminal one-shot
    // completion releases exactly one owner before the next arm acquires one.
    CHECK(loop->submit_recv_upstream(*conn));
    CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE), tail_before + 1u);
    for (u32 i = 0; i < 3; ++i) {
        conn->upstream_recv_armed = false;
        REQUIRE_GT(conn->pending_ops, 0u);
        --conn->pending_ops;
        REQUIRE(loop->submit_recv_upstream(*conn));
        CHECK(conn->upstream_recv_armed);
        CHECK_EQ(conn->pending_ops, 1u);
        const auto& sqe =
            loop->backend.sq_entries[(tail_before + 1u + i) & *loop->backend.sq_ring_mask];
        CHECK_EQ(sqe.ioprio & IORING_RECV_MULTISHOT, 0u);
    }

    // An excluded episode still uses the retained multishot primitive.
    conn->upstream_recv_armed = false;
    --conn->pending_ops;
    conn->req_body_streamed = true;
    REQUIRE(loop->submit_recv_upstream(*conn));
    const auto& excluded =
        loop->backend.sq_entries[(tail_before + 4u) & *loop->backend.sq_ring_mask];
    CHECK((excluded.ioprio & IORING_RECV_MULTISHOT) != 0);
}

struct OneShotRecvFixture {
    RouteConfig config;
    IoUringEventLoop* loop = nullptr;
    Connection* conn = nullptr;
    SSL_CTX* ssl_ctx = nullptr;
    i32 peer_fd = -1;
    u32 sq_tail_before = 0;
    u32 backend_pending_before = 0;
    bool ring_snapshot = false;

    ~OneShotRecvFixture() { cleanup(); }

    bool stage(IoUringEventLoop* event_loop) {
        if (event_loop == nullptr || loop != nullptr) return false;
        loop = event_loop;
        sq_tail_before = __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
        backend_pending_before = loop->backend.pending;
        ring_snapshot = true;
        config.upstream_count = 1;
        conn = loop->alloc_conn();
        if (conn == nullptr || !loop->alloc_upstream_buf(*conn)) return false;
        i32 downstream[2] = {-1, -1};
        if (socketpair(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0, downstream) != 0) return false;
        conn->fd = downstream[0];
        peer_fd = downstream[1];
        conn->upstream_fd = dup(STDERR_FILENO);
        if (conn->upstream_fd < 0) return false;
        ssl_ctx = SSL_CTX_new(TLS_server_method());
        if (ssl_ctx == nullptr) return false;
        conn->tls_engine.ssl = SSL_new(ssl_ctx);
        if (conn->tls_engine.ssl == nullptr) return false;
        conn->tls_active = true;
        conn->tls_handshake_complete = true;
        conn->protocol = ConnProtocol::Http11;
        conn->state = ConnState::Proxying;
        conn->request_config = &config;
        conn->req_start_us = monotonic_us();
        conn->upstream_attempts = 1;
        conn->request_upload_complete = true;
        conn->on_upstream_recv = &on_upstream_response<IoUringEventLoop>;
        return loop->use_one_shot_upstream_recv(*conn);
    }

    void restore_ring() {
        if (loop == nullptr || !ring_snapshot) return;
        __atomic_store_n(loop->backend.sq_tail, sq_tail_before, __ATOMIC_RELEASE);
        loop->backend.pending = backend_pending_before;
        ring_snapshot = false;
    }

    void cleanup() {
        if (loop == nullptr) return;
        restore_ring();
        if (conn != nullptr) {
            conn->pending_ops = 0;
            conn->upstream_recv_armed = false;
            conn->upstream_recv_paused_for_send = false;
            conn->upstream_recv_pause_cancel_pending = false;
            conn->upstream_recv_pause_rearm_pending = false;
            conn->upstream_recv_cancel_inflight = false;
            conn->upstream_recv_terminal_stale = false;
            if (conn->fd >= 0)
                loop->close_conn(*conn);
            else if (conn->recv_slice != nullptr)
                loop->free_conn(*conn);
        }
        conn = nullptr;
        if (peer_fd >= 0) close(peer_fd);
        peer_fd = -1;
        if (ssl_ctx != nullptr) SSL_CTX_free(ssl_ctx);
        ssl_ctx = nullptr;
        loop = nullptr;
    }
};

TEST(iouring_upstream_recv, terminal_dispatch_rearms_once_across_reuse_clear_and_drain) {
    ScopedIoUringLoopForRetirement guard;
    if (!guard.init()) SKIP("io_uring unavailable");
    auto* loop = guard.loop;
    OneShotRecvFixture fixture;
    REQUIRE(fixture.stage(loop));
    Connection& conn = *fixture.conn;
    conn.upstream_reused = true;
    REQUIRE(loop->submit_recv_upstream(conn));
    REQUIRE(conn.upstream_recv_armed);
    REQUIRE_EQ(conn.pending_ops, 1u);
    static constexpr u8 kFirst[] = "HTTP/";
    REQUIRE_EQ(conn.upstream_recv_buf.write(kFirst, sizeof(kFirst) - 1u), sizeof(kFirst) - 1u);

    const IoEvent first{conn.id,
                        static_cast<i32>(sizeof(kFirst) - 1u),
                        0,
                        0,
                        IoEventType::UpstreamRecv,
                        0,
                        0,
                        conn.upstream_episode};
    loop->dispatch(first);

    CHECK_FALSE(conn.upstream_reused);  // first response byte clears this mutable fact
    CHECK(conn.upstream_recv_armed);
    CHECK_EQ(conn.pending_ops, 1u);
    CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE), fixture.sq_tail_before + 2u);
    const auto& second_sqe =
        loop->backend.sq_entries[(fixture.sq_tail_before + 1u) & *loop->backend.sq_ring_mask];
    CHECK_EQ(second_sqe.ioprio & IORING_RECV_MULTISHOT, 0u);

    loop->drain(5);  // mutable control-plane state must not change this episode's mode
    static constexpr u8 kSecond[] = "1.1 ";
    REQUIRE_EQ(conn.upstream_recv_buf.write(kSecond, sizeof(kSecond) - 1u), sizeof(kSecond) - 1u);
    const IoEvent second{conn.id,
                         static_cast<i32>(sizeof(kSecond) - 1u),
                         0,
                         0,
                         IoEventType::UpstreamRecv,
                         0,
                         0,
                         conn.upstream_episode};
    loop->dispatch(second);

    CHECK(conn.upstream_recv_armed);
    CHECK_EQ(conn.pending_ops, 1u);
    CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE), fixture.sq_tail_before + 3u);
    const auto& third_sqe =
        loop->backend.sq_entries[(fixture.sq_tail_before + 2u) & *loop->backend.sq_ring_mask];
    CHECK_EQ(third_sqe.ioprio & IORING_RECV_MULTISHOT, 0u);
    fixture.cleanup();
}

TEST(iouring_upstream_recv, terminal_eof_error_and_pause_cancel_account_exactly_once) {
    for (const i32 terminal : {0, -ECONNRESET}) {
        ScopedIoUringLoopForRetirement guard;
        if (!guard.init()) SKIP("io_uring unavailable");
        auto* loop = guard.loop;
        OneShotRecvFixture fixture;
        REQUIRE(fixture.stage(loop));
        Connection& conn = *fixture.conn;
        const u32 id = conn.id;
        REQUIRE(loop->submit_recv_upstream(conn));
        REQUIRE_EQ(conn.pending_ops, 1u);

        loop->dispatch(
            {id, terminal, 0, 0, IoEventType::UpstreamRecv, 0, 0, conn.upstream_episode});

        CHECK_EQ(loop->conns[id].fd, -1);
        CHECK_EQ(loop->conns[id].pending_ops, 0u);
        CHECK_FALSE(loop->conns[id].upstream_recv_armed);
        fixture.cleanup();
    }

    ScopedIoUringLoopForRetirement guard;
    if (!guard.init()) SKIP("io_uring unavailable");
    auto* loop = guard.loop;
    OneShotRecvFixture fixture;
    REQUIRE(fixture.stage(loop));
    Connection& conn = *fixture.conn;
    REQUIRE(loop->submit_recv_upstream(conn));
    REQUIRE(loop->pause_upstream_recv_for_send(conn));
    REQUIRE_EQ(conn.pending_ops, 2u);  // one recv target plus one cancel owner
    conn.upstream_recv_paused_for_send = false;
    REQUIRE(loop->submit_recv_upstream(conn));
    REQUIRE(conn.upstream_recv_pause_rearm_pending);

    loop->dispatch(
        {conn.id, -ECANCELED, 0, 0, IoEventType::UpstreamRecv, 0, 0, conn.upstream_episode});
    CHECK_EQ(conn.pending_ops, 1u);
    CHECK_FALSE(conn.upstream_recv_armed);
    CHECK_FALSE(conn.upstream_recv_cancel_inflight);
    CHECK(conn.upstream_recv_pause_cancel_pending);

    loop->dispatch({conn.id,
                    -ENOENT,
                    0,
                    0,
                    IoEventType::UpstreamRecv,
                    0,
                    kPauseCancelAux,
                    conn.upstream_episode});
    CHECK_EQ(conn.pending_ops, 1u);  // cancel drained, exactly one replacement recv acquired
    CHECK(conn.upstream_recv_armed);
    CHECK_FALSE(conn.upstream_recv_pause_cancel_pending);
    CHECK_FALSE(conn.upstream_recv_pause_rearm_pending);
    const auto& replacement =
        loop->backend.sq_entries[(fixture.sq_tail_before + 2u) & *loop->backend.sq_ring_mask];
    CHECK_EQ(replacement.ioprio & IORING_RECV_MULTISHOT, 0u);
    fixture.cleanup();
}

TEST(iouring_upstream_recv, ring_full_closes_initial_incomplete_and_tls_low_water_rearms) {
    enum class Rearm : u8 { Initial, IncompleteHeader, TlsLowWater };
    for (const Rearm rearm : {Rearm::Initial, Rearm::IncompleteHeader, Rearm::TlsLowWater}) {
        for (const bool ring_full : {false, true}) {
            ScopedIoUringLoopForRetirement guard;
            if (!guard.init()) SKIP("io_uring unavailable");
            auto* loop = guard.loop;
            OneShotRecvFixture fixture;
            REQUIRE(fixture.stage(loop));
            Connection& conn = *fixture.conn;
            const u32 id = conn.id;

            if (rearm == Rearm::Initial) {
                static constexpr u8 kRequest[] = "GET / HTTP/1.1\r\nHost: test\r\n\r\n";
                REQUIRE_EQ(conn.recv_buf.write(kRequest, sizeof(kRequest) - 1u),
                           sizeof(kRequest) - 1u);
                conn.req_initial_send_len = sizeof(kRequest) - 1u;
            } else if (rearm == Rearm::IncompleteHeader) {
                static constexpr u8 kPartial[] = "HTTP/1.1 200 OK\r\nContent-Len";
                REQUIRE_EQ(conn.upstream_recv_buf.write(kPartial, sizeof(kPartial) - 1u),
                           sizeof(kPartial) - 1u);
            } else {
                void* region = mmap(nullptr,
                                    IoUringEventLoop::kTlsOutBufCap,
                                    PROT_READ | PROT_WRITE,
                                    MAP_PRIVATE | MAP_ANONYMOUS,
                                    -1,
                                    0);
                REQUIRE(region != MAP_FAILED);
                conn.tls_out_slice = static_cast<u8*>(region);
                conn.tls_out_buf.bind(conn.tls_out_slice, IoUringEventLoop::kTlsOutBufCap);
                static constexpr u8 kCiphertext = 0x17;
                REQUIRE_EQ(conn.tls_out_buf.write(&kCiphertext, 1), 1u);
                conn.tls_out_inflight = true;
                conn.tls_out_inflight_len = 1;
                conn.tls_recv_paused_hw = true;
                conn.tls_proxy_stream = true;
                conn.resp_fully_buffered = false;
            }

            u32 full_pending = 0;
            if (ring_full) {
                const u32 sq_head = __atomic_load_n(loop->backend.sq_head, __ATOMIC_ACQUIRE);
                __atomic_store_n(loop->backend.sq_tail,
                                 sq_head + loop->backend.sq_ring_entries,
                                 __ATOMIC_RELEASE);
                loop->backend.pending =
                    fixture.backend_pending_before + loop->backend.sq_ring_entries;
                full_pending = loop->backend.pending;
            }
            const u32 tail_before_trigger =
                __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
            const i32 fd_before_trigger = conn.fd;
            REQUIRE_GE(fd_before_trigger, 0);

            if (rearm == Rearm::Initial) {
                on_upstream_request_sent<IoUringEventLoop>(
                    loop,
                    conn,
                    {id,
                     static_cast<i32>(conn.req_initial_send_len),
                     0,
                     0,
                     IoEventType::UpstreamSend,
                     0,
                     0,
                     conn.upstream_episode});
            } else if (rearm == Rearm::IncompleteHeader) {
                on_upstream_response<IoUringEventLoop>(
                    loop,
                    conn,
                    {id,
                     static_cast<i32>(conn.upstream_recv_buf.len()),
                     0,
                     0,
                     IoEventType::UpstreamRecv,
                     0,
                     0,
                     conn.upstream_episode});
            } else {
                tls_on_out_drain<IoUringEventLoop>(
                    loop, conn, {id, 1, 0, 0, IoEventType::Send, 0, 0, conn.upstream_episode});
            }

            if (!ring_full) {
                CHECK_EQ(loop->conns[id].fd, fd_before_trigger);
                CHECK_GE(loop->conns[id].fd, 0);
                CHECK(loop->conns[id].upstream_recv_armed);
                CHECK_EQ(loop->conns[id].pending_ops, 1u);
                CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE),
                         tail_before_trigger + 1u);
                CHECK_EQ(loop->backend.pending, fixture.backend_pending_before + 1u);
                const auto& sqe =
                    loop->backend.sq_entries[tail_before_trigger & *loop->backend.sq_ring_mask];
                CHECK_EQ(sqe.ioprio & IORING_RECV_MULTISHOT, 0u);
            } else {
                CHECK_EQ(loop->conns[id].fd, -1);
                CHECK_EQ(loop->conns[id].pending_ops, 0u);
                CHECK_FALSE(loop->conns[id].upstream_recv_armed);
                CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE),
                         tail_before_trigger);
                CHECK_EQ(loop->backend.pending, full_pending);
            }
        }
    }
}

void prepare_recv_only_retirement(Connection& conn, u32 episode) {
    conn.upstream_episode = episode;
    conn.upstream_fd = 42;
    conn.upstream_recv_armed = true;
    conn.pending_ops = 1;
}

void drain_strict_recv_retirement(IoUringEventLoop* loop,
                                  Connection& conn,
                                  u32 episode,
                                  bool cancel_first);

TEST(iouring_retirement, strict_clean_success_callbacks_retire_live_recv_before_close) {
    for (const bool streaming : {false, true}) {
        ScopedIoUringLoopForRetirement guard;
        if (!guard.init()) SKIP("io_uring unavailable");
        auto* loop = guard.loop;
        Connection* conn = loop->alloc_conn();
        REQUIRE(conn != nullptr);
        REQUIRE(loop->alloc_upstream_buf(*conn));
        const u32 id = conn->id;
        const u32 free_before = loop->free_top;
        const u32 episode = streaming ? 503u : 501u;
        i32 downstream[2] = {-1, -1};
        i32 upstream[2] = {-1, -1};
        REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0, downstream), 0);
        REQUIRE_EQ(socketpair(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0, upstream), 0);
        conn->fd = downstream[0];
        conn->upstream_fd = upstream[0];
        conn->upstream_episode = episode;
        conn->upstream_recv_armed = true;
        conn->pending_ops = 1;
        conn->response_policy_id = 1;
        conn->upstream_keep_alive = true;  // mutation guard: strict success must not pool
        conn->keep_alive = false;
        conn->resp_status = 200;
        conn->resp_body_mode = BodyMode::ContentLength;
        conn->resp_body_remaining = 0;
        conn->resp_body_sent = streaming ? 118u : 116u;
        conn->state = ConnState::Sending;
        if (streaming) {
            static constexpr u8 kFinalBody[] = {'o', 'k'};
            REQUIRE_EQ(conn->upstream_recv_buf.write(kFinalBody, sizeof(kFinalBody)),
                       sizeof(kFinalBody));
            conn->upstream_send_len = sizeof(kFinalBody);
            conn->set_slots(nullptr,
                            &on_response_body_sent<IoUringEventLoop>,
                            &on_response_body_recvd<IoUringEventLoop>,
                            nullptr);
        } else {
            conn->set_slots(nullptr, &on_proxy_response_sent<IoUringEventLoop>, nullptr, nullptr);
        }
        const u32 sq_tail_before = __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
        const u32 backend_pending_before = loop->backend.pending;

        if (streaming)
            on_response_body_sent<IoUringEventLoop>(
                loop, *conn, {id, 2, 0, 0, IoEventType::Send, 0});
        else
            on_proxy_response_sent<IoUringEventLoop>(
                loop, *conn, {id, 1, 0, 0, IoEventType::Send, 0});

        Connection& retired = loop->conns[id];
        CHECK_EQ(retired.fd, -1);
        CHECK_EQ(retired.upstream_fd, -1);
        CHECK_EQ(retired.upstream_retiring_episode, episode);
        CHECK(retired.upstream_retirement_active);
        CHECK_EQ(retired.upstream_retirement_target_owned, kUpstreamOpRecv);
        CHECK_EQ(retired.upstream_retirement_cancel_owned, kUpstreamOpRecv);
        CHECK_EQ(retired.upstream_retirement_cancel_retry, 0u);
        CHECK_EQ(retired.pending_ops, 2u);
        CHECK_EQ(retired.idle_return_fd, -1);
        CHECK_EQ(loop->pending_free_count, 1u);
        CHECK_EQ(loop->free_top, free_before);
        CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE), sq_tail_before + 1u);
        UpstreamEventToken cancel_token{};
        REQUIRE(decode_upstream_event_token(
            loop->backend.sq_entries[sq_tail_before & *loop->backend.sq_ring_mask].user_data,
            &cancel_token));
        CHECK_EQ(cancel_token.conn_id, id);
        CHECK_EQ(cancel_token.type, IoEventType::UpstreamRecv);
        CHECK_EQ(cancel_token.episode, episode);
        CHECK_EQ(cancel_token.aux, kUpstreamRetirementCancelAux);
        u8 byte = 0;
        CHECK_EQ(recv(upstream[1], &byte, 1, MSG_DONTWAIT), 0);

        __atomic_store_n(loop->backend.sq_tail, sq_tail_before, __ATOMIC_RELEASE);
        loop->backend.pending = backend_pending_before;
        drain_strict_recv_retirement(loop, retired, episode, streaming);
        CHECK_EQ(loop->pending_free_count, 0u);
        CHECK_EQ(loop->free_top, free_before + 1u);
        close(downstream[1]);
        close(upstream[1]);
    }
}

TEST(iouring_retirement, clean_success_accepts_only_exact_active_or_terminal_retirement) {
    ScopedIoUringLoopForRetirement guard;
    if (!guard.init()) SKIP("io_uring unavailable");
    auto* loop = guard.loop;

    Connection* active = loop->alloc_conn();
    REQUIRE(active != nullptr);
    constexpr u32 kActiveEpisode = 511;
    active->upstream_episode = kActiveEpisode;
    active->upstream_fd = dup(STDERR_FILENO);
    REQUIRE_GE(active->upstream_fd, 0);
    active->upstream_recv_armed = true;
    active->pending_ops = 1;
    const u32 sq_tail_before = __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
    const u32 backend_pending_before = loop->backend.pending;
    REQUIRE(loop->begin_strict_upstream_retirement(*active));
    close(active->upstream_fd);
    active->upstream_fd = -1;
    active->upstream_recv_armed = false;
    active->upstream_abandoned = true;
    active->clear_slots();
    const u32 sq_tail_after_begin = __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
    REQUIRE(loop->prepare_clean_strict_upstream_retirement(*active));
    CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE), sq_tail_after_begin);
    CHECK_EQ(active->upstream_retiring_episode, kActiveEpisode);
    CHECK(active->upstream_retirement_active);

    // Complete-content-length response-deadline retirement can observe another
    // F_MORE record after ownership moved to the retirement ledger. The backend
    // marker is then armed again while the exact recv target/cancel owners remain
    // authoritative; clean completion must accept it and the subsequent generic
    // detach clears the marker before any downstream boundary is admitted.
    active->upstream_recv_armed = true;
    REQUIRE(loop->prepare_clean_strict_upstream_retirement(*active));
    CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE), sq_tail_after_begin);
    active->upstream_recv_armed = false;

    __atomic_store_n(loop->backend.sq_tail, sq_tail_before, __ATOMIC_RELEASE);
    loop->backend.pending = backend_pending_before;
    drain_strict_recv_retirement(loop, *active, kActiveEpisode, false);
    REQUIRE_FALSE(active->upstream_retirement_active);
    REQUIRE(loop->prepare_clean_strict_upstream_retirement(*active));
    CHECK_EQ(active->upstream_retiring_episode, kActiveEpisode);

    Connection* malformed = loop->alloc_conn();
    REQUIRE(malformed != nullptr);
    malformed->upstream_fd = -1;
    malformed->upstream_episode = 522;
    malformed->upstream_retiring_episode = 521;
    malformed->upstream_abandoned = true;
    malformed->upstream_retirement_active = true;  // no owner: impossible active state
    CHECK_FALSE(loop->prepare_clean_strict_upstream_retirement(*malformed));
    malformed->upstream_retirement_active = false;
    malformed->upstream_retirement_target_owned = kUpstreamOpSend;  // not recv-only
    CHECK_FALSE(loop->prepare_clean_strict_upstream_retirement(*malformed));
    malformed->upstream_retirement_target_owned = 0;

    const auto prepare_closed_terminal = [&](u32 retiring, u32 current, bool quarantined) {
        malformed->upstream_retiring_episode = retiring;
        malformed->upstream_episode = current;
        malformed->upstream_episode_quarantined = quarantined;
        malformed->upstream_retirement_active = false;
        malformed->upstream_retirement_target_owned = 0;
        malformed->upstream_retirement_cancel_owned = 0;
        malformed->upstream_retirement_cancel_retry = 0;
        malformed->pending_ops = 0;
    };
    prepare_closed_terminal(521, 522, false);
    malformed->upstream_retirement_active = true;
    malformed->upstream_retirement_cancel_retry = kUpstreamOpRecv;
    CHECK_FALSE(loop->prepare_clean_strict_upstream_retirement(*malformed));

    prepare_closed_terminal(521, 520, false);  // reversed history
    CHECK_FALSE(loop->prepare_clean_strict_upstream_retirement(*malformed));
    prepare_closed_terminal(521, 523, false);  // skipped successor
    CHECK_FALSE(loop->prepare_clean_strict_upstream_retirement(*malformed));
    prepare_closed_terminal(521, 522, false);
    malformed->upstream_recv_armed = true;  // no retired recv target owns this marker
    CHECK_FALSE(loop->prepare_clean_strict_upstream_retirement(*malformed));
    malformed->upstream_recv_armed = false;
    prepare_closed_terminal(kIoUserDataMaxUpstreamEpisode - 1u,
                            kInvalidUpstreamEventEpisode,
                            true);  // only max may quarantine
    CHECK_FALSE(loop->prepare_clean_strict_upstream_retirement(*malformed));
    prepare_closed_terminal(
        kIoUserDataMaxUpstreamEpisode, kInvalidUpstreamEventEpisode, false);  // missing quarantine
    CHECK_FALSE(loop->prepare_clean_strict_upstream_retirement(*malformed));
    prepare_closed_terminal(kIoUserDataMaxUpstreamEpisode,
                            kInvalidUpstreamEventEpisode,
                            true);  // exact exhausted successor tombstone
    CHECK(loop->prepare_clean_strict_upstream_retirement(*malformed));

    loop->free_conn(*malformed);
    loop->free_conn(*active);
}

void drain_strict_recv_retirement(IoUringEventLoop* loop,
                                  Connection& conn,
                                  u32 episode,
                                  bool cancel_first) {
    const IoEvent target{conn.id, -ECANCELED, 0, 0, IoEventType::UpstreamRecv, 0, 0, episode};
    const IoEvent cancel{conn.id,
                         -ENOENT,
                         0,
                         0,
                         IoEventType::UpstreamRecv,
                         0,
                         kUpstreamRetirementCancelAux,
                         episode};
    loop->dispatch(cancel_first ? cancel : target);
    loop->dispatch(cancel_first ? target : cancel);
}

bool stage_http1_boundary_retirement(IoUringEventLoop* loop,
                                     const RouteConfig* old_config,
                                     ShardEpoch* epoch,
                                     ShardMetrics* metrics,
                                     const u8* buffered,
                                     u32 buffered_len,
                                     Connection** out,
                                     i32* peer_fd) {
    if (loop == nullptr || out == nullptr || peer_fd == nullptr) return false;
    Connection* conn = loop->alloc_conn();
    if (conn == nullptr || !loop->alloc_upstream_buf(*conn)) return false;
    i32 pair[2] = {-1, -1};
    if (socketpair(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0, pair) != 0) return false;
    conn->fd = pair[0];
    *peer_fd = pair[1];
    conn->upstream_fd = dup(STDERR_FILENO);
    if (conn->upstream_fd < 0) return false;

    constexpr u32 kEpisode = 101;
    conn->upstream_episode = kEpisode;
    conn->recv_armed = true;
    conn->upstream_recv_armed = true;
    conn->pending_ops = 2;  // downstream recv + retiring upstream recv
    if (!loop->begin_strict_upstream_retirement(*conn)) return false;

    // The strict transport handoff has already detached the old upstream and
    // queued the downstream response. Drive the real production send dispatch
    // and callback from this exact state; no semantic admission is bypassed.
    close(conn->upstream_fd);
    conn->upstream_fd = -1;
    conn->upstream_recv_armed = false;
    conn->upstream_abandoned = true;
    conn->upstream_keep_alive = false;
    conn->response_policy_id = 0;
    conn->keep_alive = true;
    conn->resp_status = 200;
    conn->resp_body_sent = 2;
    conn->req_start_us = monotonic_us();
    conn->request_config = old_config;
    conn->state = ConnState::Sending;
    conn->set_slots(nullptr, &on_proxy_response_sent<IoUringEventLoop>, nullptr, nullptr);
    conn->send_armed = true;
    conn->pending_ops++;  // downstream response send
    if (buffered_len > 0 && conn->recv_buf.write(buffered, buffered_len) != buffered_len)
        return false;

    loop->epoch = epoch;
    loop->metrics = metrics;
    *out = conn;
    return true;
}

bool harvest_http1_boundary_recv(IoUringEventLoop* loop,
                                 Connection& conn,
                                 const u8* bytes,
                                 u32 len,
                                 i32 result,
                                 bool more,
                                 IoEvent* out) {
    if (loop == nullptr || out == nullptr) return false;
    constexpr u16 kBufId = 29;
    if (result > 0) {
        if (bytes == nullptr || len != static_cast<u32>(result) || len > 4096) return false;
        __builtin_memcpy(loop->backend.buf_base + static_cast<u64>(kBufId) * 4096, bytes, len);
    }
    const u32 cq_tail = __atomic_load_n(loop->backend.cq_tail, __ATOMIC_ACQUIRE);
    auto& cqe = loop->backend.cq_entries[cq_tail & *loop->backend.cq_ring_mask];
    cqe.user_data = encode_non_upstream_user_data({conn.id, IoEventType::Recv, 0});
    cqe.res = result;
    cqe.flags = more ? IORING_CQE_F_MORE : 0;
    if (result > 0)
        cqe.flags |= IORING_CQE_F_BUFFER | (static_cast<u32>(kBufId) << IORING_CQE_BUFFER_SHIFT);
    __atomic_store_n(loop->backend.cq_tail, cq_tail + 1, __ATOMIC_RELEASE);
    loop->backend.pending = 0;
    IoEvent events[2]{};
    const u32 n = loop->backend.wait(events, 2, loop->conns, IoUringEventLoop::kMaxConns);
    if (n != 1) return false;
    *out = events[0];
    return true;
}

struct RawDownstreamRecvBatch {
    ScopedIoUringLoopForRetirement guard;
    Connection* conns[2] = {nullptr, nullptr};
    u16 next_buf_id = 101;

    bool init(u32 count = 1) {
        if (count == 0 || count > 2 || !guard.init()) return false;
        for (u32 i = 0; i < count; i++) {
            conns[i] = guard.loop->alloc_conn();
            if (conns[i] == nullptr) return false;
            conns[i]->fd = static_cast<i32>(42 + i);
            conns[i]->recv_armed = true;
            conns[i]->pending_ops = 1;
        }
        // Synthetic CQEs below are already visible.  Keep the init-time timer
        // SQE out of these exact raw-CQ ownership tests.
        guard.loop->backend.pending = 0;
        return true;
    }

    u32 head() const { return __atomic_load_n(guard.loop->backend.cq_head, __ATOMIC_ACQUIRE); }

    u32 tail() const { return __atomic_load_n(guard.loop->backend.cq_tail, __ATOMIC_ACQUIRE); }

    u16 buffer_tail() const {
        return __atomic_load_n(&guard.loop->backend.buf_ring->tail, __ATOMIC_ACQUIRE);
    }

    bool append_recv(
        Connection& conn, const u8* bytes, u32 len, bool more, u16 forced_buf_id = UINT16_MAX) {
        if (bytes == nullptr || len == 0 || len > kProvidedBufSize) return false;
        const u16 buf_id = forced_buf_id == UINT16_MAX ? next_buf_id++ : forced_buf_id;
        if (buf_id >= kProvidedBufCount) return false;
        __builtin_memcpy(
            guard.loop->backend.buf_base + static_cast<u64>(buf_id) * kProvidedBufSize, bytes, len);
        u32 cursor = tail();
        auto& cqe = guard.loop->backend.cq_entries[cursor & *guard.loop->backend.cq_ring_mask];
        cqe.user_data = encode_non_upstream_user_data({conn.id, IoEventType::Recv, 0});
        cqe.res = static_cast<i32>(len);
        cqe.flags = IORING_CQE_F_BUFFER | (static_cast<u32>(buf_id) << IORING_CQE_BUFFER_SHIFT) |
                    (more ? IORING_CQE_F_MORE : 0u);
        __atomic_store_n(guard.loop->backend.cq_tail, cursor + 1u, __ATOMIC_RELEASE);
        return true;
    }

    void append_terminal(Connection& conn, i32 result) {
        u32 cursor = tail();
        auto& cqe = guard.loop->backend.cq_entries[cursor & *guard.loop->backend.cq_ring_mask];
        cqe.user_data = encode_non_upstream_user_data({conn.id, IoEventType::Recv, 0});
        cqe.res = result;
        cqe.flags = 0;
        __atomic_store_n(guard.loop->backend.cq_tail, cursor + 1u, __ATOMIC_RELEASE);
    }

    void append_send(Connection& conn, i32 result) {
        u32 cursor = tail();
        auto& cqe = guard.loop->backend.cq_entries[cursor & *guard.loop->backend.cq_ring_mask];
        cqe.user_data = encode_non_upstream_user_data({conn.id, IoEventType::Send, 0});
        cqe.res = result;
        cqe.flags = 0;
        __atomic_store_n(guard.loop->backend.cq_tail, cursor + 1u, __ATOMIC_RELEASE);
    }

    void append_close_cancel(Connection& conn, i32 result) {
        u32 cursor = tail();
        auto& cqe = guard.loop->backend.cq_entries[cursor & *guard.loop->backend.cq_ring_mask];
        cqe.user_data =
            IoUringBackend::encode_user_data(conn.id, IoEventType::Recv, kDownstreamCloseCancelAux);
        cqe.res = result;
        cqe.flags = 0;
        __atomic_store_n(guard.loop->backend.cq_tail, cursor + 1u, __ATOMIC_RELEASE);
    }

    void append_tagged_recv(Connection& conn, i32 result, u32 aux, u32 flags) {
        u32 cursor = tail();
        auto& cqe = guard.loop->backend.cq_entries[cursor & *guard.loop->backend.cq_ring_mask];
        cqe.user_data = IoUringBackend::encode_user_data(conn.id, IoEventType::Recv, aux);
        cqe.res = result;
        cqe.flags = flags;
        __atomic_store_n(guard.loop->backend.cq_tail, cursor + 1u, __ATOMIC_RELEASE);
    }

    void append_timeout(u32 witness) {
        u32 cursor = tail();
        auto& cqe = guard.loop->backend.cq_entries[cursor & *guard.loop->backend.cq_ring_mask];
        cqe.user_data = encode_non_upstream_user_data({0, IoEventType::Timeout, 0});
        cqe.res = static_cast<i32>(witness);
        cqe.flags = 0;
        __atomic_store_n(guard.loop->backend.cq_tail, cursor + 1u, __ATOMIC_RELEASE);
    }

    u32 wait(IoEvent* events, u32 max_events = 8) {
        guard.loop->backend.pending = 0;
        return guard.loop->backend.wait(
            events, max_events, guard.loop->conns, IoUringEventLoop::kMaxConns);
    }
};

static constexpr u8 kSplitHeaderPrefix[] =
    "GET /ledger?q=raw HTTP/1.1\r\n"
    "Host: client.exam";
static constexpr u8 kSplitHeaderSuffix[] =
    "ple.with.a.long.name\r\n"
    "Connection: close\r\n"
    "X-Test: keep\r\n"
    "\r\n";
static_assert(sizeof(kSplitHeaderPrefix) - 1u == 45u);
static_assert(sizeof(kSplitHeaderSuffix) - 1u == 57u);

TEST(iouring_downstream_recv_barrier, split_positive_is_copied_one_per_wait) {
    for (const bool terminal_suffix : {false, true}) {
        RawDownstreamRecvBatch fixture;
        if (!fixture.init()) SKIP("io_uring unavailable");
        Connection& conn = *fixture.conns[0];
        const u32 initial_head = fixture.head();
        const u16 initial_buffer_tail = fixture.buffer_tail();
        REQUIRE(
            fixture.append_recv(conn, kSplitHeaderPrefix, sizeof(kSplitHeaderPrefix) - 1u, true));
        REQUIRE(fixture.append_recv(
            conn, kSplitHeaderSuffix, sizeof(kSplitHeaderSuffix) - 1u, !terminal_suffix));

        IoEvent events[4]{};
        REQUIRE_EQ(fixture.wait(events, 4), 1u);
        CHECK_EQ(events[0].type, IoEventType::Recv);
        CHECK_EQ(events[0].result, 45);
        CHECK_EQ(events[0].more, 1u);
        CHECK_EQ(conn.recv_buf.len(), 45u);
        CHECK_EQ(memcmp(conn.recv_buf.data(), kSplitHeaderPrefix, 45), 0);
        CHECK_EQ(fixture.head(), initial_head + 1u);
        CHECK_EQ(fixture.buffer_tail(), static_cast<u16>(initial_buffer_tail + 1u));
        REQUIRE(fixture.guard.loop->backend.deferred_downstream_recv.active);
        CHECK_EQ(fixture.guard.loop->backend.deferred_downstream_recv.head, initial_head + 1u);
        CHECK_EQ(fixture.guard.loop->backend.deferred_downstream_recv.user_data,
                 encode_non_upstream_user_data({conn.id, IoEventType::Recv, 0}));

        REQUIRE_EQ(fixture.wait(events, 4), 1u);
        CHECK_EQ(events[0].type, IoEventType::Recv);
        CHECK_EQ(events[0].result, 57);
        CHECK_EQ(events[0].more, terminal_suffix ? 0u : 1u);
        CHECK_EQ(conn.recv_buf.len(), 102u);
        CHECK_EQ(memcmp(conn.recv_buf.data(), kSplitHeaderPrefix, 45), 0);
        CHECK_EQ(memcmp(conn.recv_buf.data() + 45, kSplitHeaderSuffix, 57), 0);
        CHECK_EQ(fixture.head(), initial_head + 2u);
        CHECK_EQ(fixture.buffer_tail(), static_cast<u16>(initial_buffer_tail + 2u));
        CHECK_FALSE(fixture.guard.loop->backend.deferred_downstream_recv.active);
        CHECK_EQ(fixture.guard.loop->backend.failure_code(), 0);
    }
}

TEST(iouring_downstream_recv_barrier, cq_order_stops_before_suffix_in_both_interleavings) {
    for (const bool timeout_before_suffix : {false, true}) {
        RawDownstreamRecvBatch fixture;
        if (!fixture.init()) SKIP("io_uring unavailable");
        Connection& conn = *fixture.conns[0];
        REQUIRE(
            fixture.append_recv(conn, kSplitHeaderPrefix, sizeof(kSplitHeaderPrefix) - 1u, true));
        if (timeout_before_suffix) fixture.append_timeout(17);
        REQUIRE(
            fixture.append_recv(conn, kSplitHeaderSuffix, sizeof(kSplitHeaderSuffix) - 1u, true));
        if (!timeout_before_suffix) fixture.append_timeout(17);

        IoEvent events[4]{};
        const u32 first_count = fixture.wait(events, 4);
        REQUIRE_EQ(first_count, timeout_before_suffix ? 2u : 1u);
        CHECK_EQ(events[0].type, IoEventType::Recv);
        CHECK_EQ(conn.recv_buf.len(), 45u);
        if (timeout_before_suffix) {
            CHECK_EQ(events[1].type, IoEventType::Timeout);
            CHECK_EQ(events[1].result, 17);
        }

        const u32 second_count = fixture.wait(events, 4);
        REQUIRE_EQ(second_count, timeout_before_suffix ? 1u : 2u);
        CHECK_EQ(events[0].type, IoEventType::Recv);
        CHECK_EQ(conn.recv_buf.len(), 102u);
        if (!timeout_before_suffix) {
            CHECK_EQ(events[1].type, IoEventType::Timeout);
            CHECK_EQ(events[1].result, 17);
        }
    }
}

TEST(iouring_downstream_recv_barrier, different_connections_and_terminals_do_not_barrier) {
    RawDownstreamRecvBatch fixture;
    if (!fixture.init(2)) SKIP("io_uring unavailable");
    Connection& a = *fixture.conns[0];
    Connection& b = *fixture.conns[1];
    static constexpr u8 kA[] = "a";
    static constexpr u8 kB[] = "bb";
    REQUIRE(fixture.append_recv(a, kA, sizeof(kA) - 1u, true));
    REQUIRE(fixture.append_recv(b, kB, sizeof(kB) - 1u, true));
    fixture.append_terminal(a, 0);
    fixture.append_terminal(b, -ECONNRESET);

    IoEvent events[6]{};
    REQUIRE_EQ(fixture.wait(events, 6), 4u);
    CHECK_EQ(events[0].conn_id, a.id);
    CHECK_EQ(events[0].result, 1);
    CHECK_EQ(events[1].conn_id, b.id);
    CHECK_EQ(events[1].result, 2);
    CHECK_EQ(events[2].conn_id, a.id);
    CHECK_EQ(events[2].result, 0);
    CHECK_EQ(events[3].conn_id, b.id);
    CHECK_EQ(events[3].result, -ECONNRESET);
    CHECK_EQ(a.recv_buf.len(), 1u);
    CHECK_EQ(b.recv_buf.len(), 2u);
    CHECK_FALSE(fixture.guard.loop->backend.deferred_downstream_recv.active);
    CHECK_EQ(fixture.guard.loop->backend.failure_code(), 0);
}

TEST(iouring_downstream_recv_barrier, pipeline_overflow_closes_live_and_terminal_recv_once) {
    static constexpr u8 kFirst[] = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    static constexpr u8 kSuccessor[] = "GET /next HTTP/1.1\r\nHost: x\r\n\r\n";
    static constexpr u8 kResponse[] = "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n";

    for (const bool terminal_recv : {false, true}) {
        for (const bool cancel_first : {false, true}) {
            // A terminal-consumed Recv has no close cancel to drain; the
            // cancel_first dimension is meaningful only for the live owner.
            if (terminal_recv && cancel_first) continue;
            RawDownstreamRecvBatch fixture;
            if (!fixture.init()) SKIP("io_uring unavailable");
            auto* loop = fixture.guard.loop;
            ShardMetrics metrics{};
            metrics.init();
            ShardEpoch epoch{};
            epoch.epoch.store(1, std::memory_order_relaxed);
            loop->metrics = &metrics;
            loop->epoch = &epoch;
            Connection& conn = *fixture.conns[0];
            const u32 id = conn.id;
            REQUIRE_EQ(conn.recv_buf.write(kFirst, sizeof(kFirst) - 1u), sizeof(kFirst) - 1u);
            conn.req_initial_send_len = sizeof(kFirst) - 1u;
            conn.pipeline_depth = Connection::kMaxPipelineDepth;
            conn.keep_alive = true;
            conn.req_client_keep_alive = true;
            conn.req_start_us = monotonic_us();
            conn.resp_status = 200;
            conn.state = ConnState::Sending;
            REQUIRE_EQ(conn.send_buf.write(kResponse, sizeof(kResponse) - 1u),
                       sizeof(kResponse) - 1u);
            conn.send_armed = true;
            conn.pending_ops = 2;  // downstream Recv + response Send
            conn.on_recv = nullptr;
            conn.on_send = &on_response_sent<IoUringEventLoop>;
            fixture.guard.loop->backend.send_state[id] = {
                conn.send_buf.data(), conn.fd, 0, conn.send_buf.len(), IoEventType::Send, 0, 0};

            REQUIRE(fixture.append_recv(conn, kSuccessor, sizeof(kSuccessor) - 1u, !terminal_recv));
            fixture.append_send(conn, static_cast<i32>(conn.send_buf.len()));
            IoEvent events[4]{};
            REQUIRE_EQ(fixture.wait(events, 4), 2u);
            const u32 sq_tail_before_close =
                __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
            loop->dispatch(events[0]);
            loop->dispatch(events[1]);

            CHECK_EQ(metrics.requests_total, 1u);
            CHECK_EQ(metrics.requests_active, 0u);
            CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), 2u);
            CHECK_EQ(loop->backend.failure_code(), 0);
            if (terminal_recv) {
                CHECK_EQ(loop->backend.pending, 0u);
                CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE),
                         sq_tail_before_close);
                CHECK_EQ(loop->pending_free_count, 0u);
                CHECK_EQ(loop->free_top, IoUringEventLoop::kMaxConns);
            } else {
                // The only newly submitted operation is the close cancel for
                // the still-live multishot Recv. No rearm or second cancel is
                // allowed while the slot waits for both terminal records.
                CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE),
                         sq_tail_before_close + 1u);
                CHECK_EQ(loop->pending_free_count, 1u);
                CHECK_EQ(loop->conns[id].pending_ops, 2u);
                const u32 close_sq_tail = __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
                __atomic_store_n(loop->backend.sq_tail, sq_tail_before_close, __ATOMIC_RELEASE);
                loop->backend.pending = 0;
                if (cancel_first) {
                    fixture.append_close_cancel(conn, 1);
                    fixture.append_terminal(conn, -ECANCELED);
                } else {
                    fixture.append_terminal(conn, -ECANCELED);
                    fixture.append_close_cancel(conn, 1);
                }
                REQUIRE_EQ(fixture.wait(events, 4), 2u);
                loop->dispatch(events[0]);
                loop->dispatch(events[1]);
                CHECK_EQ(loop->backend.failure_code(), 0);
                CHECK_EQ(loop->pending_free_count, 0u);
                CHECK_EQ(loop->free_top, IoUringEventLoop::kMaxConns);
                CHECK_EQ(loop->conns[id].pending_ops, 0u);
                CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE),
                         sq_tail_before_close);
                CHECK_EQ(close_sq_tail, sq_tail_before_close + 1u);
            }
            CHECK_EQ(fixture.head(), fixture.tail());
            const u32 free_top_after_close = loop->free_top;
            loop->reclaim_slot(id);  // no-op: the close ledger already reclaimed once
            CHECK_EQ(loop->free_top, free_top_after_close);
        }
    }
}

TEST(iouring_downstream_recv_barrier, close_cancel_count_is_not_payload_and_accounts_both_orders) {
    for (const bool cancel_first : {false, true}) {
        RawDownstreamRecvBatch fixture;
        if (!fixture.init()) SKIP("io_uring unavailable");
        Connection& conn = *fixture.conns[0];
        const u32 conn_id = conn.id;
        const u16 buffer_tail_before = fixture.buffer_tail();
        conn.pending_ops = 2;  // recv target + close cancel SQE
        if (cancel_first) {
            fixture.append_close_cancel(conn, 1);
            fixture.append_terminal(conn, -ECANCELED);
        } else {
            fixture.append_terminal(conn, -ECANCELED);
            fixture.append_close_cancel(conn, 1);
        }
        conn.fd = -1;
        fixture.guard.loop->free_conn(conn);
        REQUIRE_EQ(fixture.guard.loop->pending_free_count, 1u);

        IoEvent events[2]{};
        REQUIRE_EQ(fixture.wait(events, 2), 2u);
        CHECK_EQ(events[cancel_first ? 0u : 1u].type, IoEventType::Recv);
        CHECK_EQ(events[cancel_first ? 0u : 1u].result, 1);
        CHECK_EQ(events[cancel_first ? 0u : 1u].aux, kDownstreamCloseCancelAux);
        CHECK_EQ(events[cancel_first ? 1u : 0u].type, IoEventType::Recv);
        CHECK_EQ(events[cancel_first ? 1u : 0u].result, -ECANCELED);
        CHECK_EQ(events[cancel_first ? 1u : 0u].aux, 0u);
        CHECK_EQ(fixture.buffer_tail(), buffer_tail_before);
        CHECK_EQ(fixture.guard.loop->backend.failure_code(), 0);

        fixture.guard.loop->dispatch(events[0]);
        CHECK_EQ(fixture.guard.loop->pending_free_count, 1u);
        CHECK_EQ(fixture.guard.loop->conns[conn_id].pending_ops, 1u);
        fixture.guard.loop->dispatch(events[1]);
        CHECK_EQ(fixture.guard.loop->pending_free_count, 0u);
        CHECK_EQ(fixture.guard.loop->free_top, IoUringEventLoop::kMaxConns);
    }
}

TEST(iouring_downstream_recv_barrier, frozen_duplicate_target_cannot_steal_cancel_accounting) {
    for (const bool cancel_first : {false, true}) {
        RawDownstreamRecvBatch fixture;
        if (!fixture.init()) SKIP("io_uring unavailable");
        Connection& conn = *fixture.conns[0];
        const u32 conn_id = conn.id;
        conn.pending_ops = 2;  // recv target + close cancel SQE; duplicate owns neither
        if (cancel_first) fixture.append_close_cancel(conn, 1);
        fixture.append_terminal(conn, -ECANCELED);
        fixture.append_terminal(conn, -ECANCELED);
        if (!cancel_first) fixture.append_close_cancel(conn, 1);
        conn.fd = -1;
        fixture.guard.loop->free_conn(conn);
        REQUIRE_EQ(fixture.guard.loop->pending_free_count, 1u);

        IoEvent events[3]{};
        REQUIRE_EQ(fixture.wait(events, 3), 2u);
        const u32 cancel_index = cancel_first ? 0u : 1u;
        const u32 target_index = cancel_first ? 1u : 0u;
        CHECK_EQ(events[cancel_index].type, IoEventType::Recv);
        CHECK_EQ(events[cancel_index].result, 1);
        CHECK_EQ(events[cancel_index].aux, kDownstreamCloseCancelAux);
        CHECK_EQ(events[target_index].type, IoEventType::Recv);
        CHECK_EQ(events[target_index].result, -ECANCELED);
        CHECK_EQ(events[target_index].aux, 0u);
        CHECK_EQ(fixture.head(), fixture.tail());
        CHECK_EQ(fixture.guard.loop->backend.failure_code(), 0);

        fixture.guard.loop->dispatch(events[0]);
        CHECK_EQ(fixture.guard.loop->pending_free_count, 1u);
        CHECK_EQ(fixture.guard.loop->conns[conn_id].pending_ops, 1u);
        fixture.guard.loop->dispatch(events[1]);
        CHECK_EQ(fixture.guard.loop->pending_free_count, 0u);
        CHECK_EQ(fixture.guard.loop->free_top, IoUringEventLoop::kMaxConns);
    }
}

TEST(iouring_downstream_recv_barrier, terminal_window_quarantines_old_records_and_hands_off) {
    RawDownstreamRecvBatch fixture;
    if (!fixture.init()) SKIP("io_uring unavailable");
    Connection& conn = *fixture.conns[0];
    static constexpr u8 kTerminal[] = "terminal";
    static constexpr u8 kOldOne[] = "old-one";
    static constexpr u8 kOldTwo[] = "old-two";
    static constexpr u8 kNew[] = "new-owner";
    const u16 buffer_tail_before = fixture.buffer_tail();
    REQUIRE(fixture.append_recv(conn, kTerminal, sizeof(kTerminal) - 1u, false));
    REQUIRE(fixture.append_recv(conn, kOldOne, sizeof(kOldOne) - 1u, true));
    fixture.append_timeout(23);
    REQUIRE(fixture.append_recv(conn, kOldTwo, sizeof(kOldTwo) - 1u, true));
    fixture.append_close_cancel(conn, 1);  // separate close-cancel ownership remains visible

    IoEvent events[4]{};
    REQUIRE_EQ(fixture.wait(events, 1), 1u);  // max-events interrupts the frozen interval
    CHECK_EQ(events[0].type, IoEventType::Recv);
    CHECK_EQ(events[0].result, static_cast<i32>(sizeof(kTerminal) - 1u));
    REQUIRE_EQ(fixture.guard.loop->backend.downstream_recv_terminal_window_count, 1u);
    const u32 frozen_tail =
        fixture.guard.loop->backend.downstream_recv_terminal_windows[0].tail_exclusive;

    // The terminal callback may install a new owner with the same generation-
    // less token.  Append its CQE after the frozen tail before resuming.
    conn.recv_buf.reset();
    conn.fd = 77;
    conn.recv_armed = true;
    conn.pending_ops = 9;
    REQUIRE(fixture.append_recv(conn, kNew, sizeof(kNew) - 1u, true));

    REQUIRE_EQ(fixture.wait(events, 4), 2u);
    CHECK_EQ(events[0].type, IoEventType::Timeout);
    CHECK_EQ(events[0].result, 23);
    CHECK_EQ(events[1].type, IoEventType::Recv);
    CHECK_EQ(events[1].result, 1);
    CHECK_EQ(events[1].aux, kDownstreamCloseCancelAux);
    CHECK_EQ(conn.recv_buf.len(), 0u);
    CHECK_EQ(conn.pending_ops, 9u);
    CHECK(conn.recv_armed);
    CHECK_EQ(fixture.buffer_tail(), static_cast<u16>(buffer_tail_before + 3u));
    CHECK_EQ(fixture.head(), frozen_tail);
    CHECK_EQ(fixture.guard.loop->backend.downstream_recv_terminal_window_count, 0u);

    REQUIRE_EQ(fixture.wait(events, 1), 1u);
    CHECK_EQ(events[0].type, IoEventType::Recv);
    CHECK_EQ(events[0].result, static_cast<i32>(sizeof(kNew) - 1u));
    CHECK_EQ(conn.recv_buf.len(), sizeof(kNew) - 1u);
    CHECK_EQ(memcmp(conn.recv_buf.data(), kNew, sizeof(kNew) - 1u), 0);
    CHECK_EQ(conn.pending_ops, 9u);
    CHECK_EQ(fixture.buffer_tail(), static_cast<u16>(buffer_tail_before + 4u));
    CHECK_EQ(fixture.guard.loop->backend.failure_code(), 0);
}

TEST(iouring_downstream_recv_barrier, terminal_second_positive_uses_exact_deferred_marker) {
    RawDownstreamRecvBatch fixture;
    if (!fixture.init()) SKIP("io_uring unavailable");
    Connection& conn = *fixture.conns[0];
    static constexpr u8 kTerminal[] = "terminal";
    static constexpr u8 kOld[] = "old-after-terminal";
    REQUIRE(fixture.append_recv(conn, kTerminal, sizeof(kTerminal) - 1u, false));
    REQUIRE(fixture.append_recv(conn, kOld, sizeof(kOld) - 1u, true));
    fixture.append_timeout(29);
    const u16 buffer_tail_before = fixture.buffer_tail();
    IoEvent events[3]{};
    REQUIRE_EQ(fixture.wait(events, 3), 1u);
    CHECK_EQ(events[0].type, IoEventType::Recv);
    REQUIRE(fixture.guard.loop->backend.deferred_downstream_recv.active);
    CHECK(fixture.guard.loop->backend.deferred_downstream_recv.prior_terminal);
    CHECK_EQ(fixture.guard.loop->backend.deferred_downstream_recv.head, fixture.head());
    CHECK_EQ(fixture.guard.loop->backend.deferred_downstream_recv.frozen_tail, fixture.tail());
    CHECK_EQ(fixture.buffer_tail(), static_cast<u16>(buffer_tail_before + 1u));

    REQUIRE_EQ(fixture.wait(events, 3), 1u);
    CHECK_EQ(events[0].type, IoEventType::Timeout);
    CHECK_EQ(events[0].result, 29);
    CHECK_EQ(conn.recv_buf.len(), sizeof(kTerminal) - 1u);
    CHECK_EQ(fixture.buffer_tail(), static_cast<u16>(buffer_tail_before + 2u));
    CHECK_FALSE(fixture.guard.loop->backend.deferred_downstream_recv.active);
    CHECK_EQ(fixture.guard.loop->backend.failure_code(), 0);
}

