TEST(http1_pipeline_generation_activation,
     forged_route_target_reuse_retry_and_transform_reject_before_upstream_effect) {
    enum class Forgery : u8 {
        AnyRoute,
        PolicyZero,
        MultipleEndpoints,
        MaxInflight,
        Reused,
        Retry,
        TargetTransform,
    };
    static constexpr u8 kSuccessor[] = "GET /one HTTP/1.1\r\nHost: client.example\r\n\r\n";
    for (const Forgery forgery : {Forgery::AnyRoute,
                                  Forgery::PolicyZero,
                                  Forgery::MultipleEndpoints,
                                  Forgery::MaxInflight,
                                  Forgery::Reused,
                                  Forgery::Retry,
                                  Forgery::TargetTransform}) {
        ScopedBackendHealthReset health_reset{};
        ScopedIoUringLoopForRetirement guard;
        if (!guard.init()) SKIP("io_uring unavailable");
        auto* loop = guard.loop;
        RouteConfig config{};
        PreconnectConnectSubmitFixture fixture{};
        u32 ignored_episode = 0;
        REQUIRE(stage_late_failure_response(loop,
                                            config,
                                            LateFailureSite::ConnectCompletion,
                                            AsyncConnectFailureProfile::BodylessGet,
                                            &fixture,
                                            &ignored_episode,
                                            &response_buffering_request_policy_runtime_handler));
        Connection& conn = *fixture.conn;
        const u32 id = conn.id;
        switch (forgery) {
            case Forgery::AnyRoute:
                config.routes[0].method = kRouteMethodAny;
                break;
            case Forgery::PolicyZero:
                config.routes[0].fn = &response_read_deadline_handler;
                break;
            case Forgery::MultipleEndpoints:
                config.upstreams[0].addr_count = 2;
                config.upstreams[0].addrs[1] = config.upstreams[0].addrs[0];
                break;
            case Forgery::MaxInflight:
                config.upstreams[0].max_inflight = 1;
                break;
            case Forgery::Reused:
            case Forgery::Retry:
            case Forgery::TargetTransform:
                config.routes[0].fn = &response_coalesced_phase1_handler;
                response_coalesced_phase1_mutation_conn = &conn;
                response_coalesced_phase1_mutation_kind =
                    forgery == Forgery::Reused ? 1 : (forgery == Forgery::Retry ? 2 : 3);
                break;
        }
        REQUIRE_EQ(conn.recv_buf.write(kSuccessor, sizeof(kSuccessor) - 1u),
                   sizeof(kSuccessor) - 1u);
        loop->backend.send_state[id].remaining = 0;
        const u32 response1_len = conn.response_header_buf.len();
        loop->dispatch({id, static_cast<i32>(response1_len), 0, 0, IoEventType::Send, 0});
        response_coalesced_phase1_mutation_conn = nullptr;
        response_coalesced_phase1_mutation_kind = 0;

        CHECK_EQ(loop->conns[id].fd, -1);
        CHECK_EQ(loop->conns[id].upstream_fd, -1);
        CHECK_FALSE(loop->conns[id].upstream_slot_held);
        CHECK_FALSE(loop->conns[id].upstream_connect_armed);
        CHECK_FALSE(loop->conns[id].upstream_send_armed);
        CHECK_FALSE(loop->conns[id].upstream_recv_armed);
        CHECK_EQ(loop->backend.upstream_send_state[id].remaining, 0u);
        CHECK_EQ(loop->conns[id].response_header_buf.len(), 0u);
        cleanup_late_failure_fixture(loop, fixture);
    }
}

TEST(iouring_validated_failure_pipeline,
     complete_late_successor_dispatches_once_across_sites_and_request_profiles) {
    struct Case {
        LateFailureSite site;
        AsyncConnectFailureProfile profile;
    };
    static constexpr Case kCases[] = {
        {LateFailureSite::SocketCreate, AsyncConnectFailureProfile::BodylessGet},
        {LateFailureSite::ConnectSubmit, AsyncConnectFailureProfile::FixedUpload},
        {LateFailureSite::ConnectCompletion, AsyncConnectFailureProfile::Head},
    };
    static constexpr u8 kSuccessor[] = "GET /two HTTP/1.1\r\nHost: client.example\r\n\r\n";

    for (const Case& test : kCases) {
        ScopedBackendHealthReset health_reset{};
        ScopedIoUringLoopForRetirement guard;
        if (!guard.init()) SKIP("io_uring unavailable");
        auto* loop = guard.loop;
        ShardEpoch epoch{};
        epoch.epoch.store(0, std::memory_order_relaxed);
        ShardMetrics metrics{};
        metrics.init();
        AccessLogRing access_log{};
        access_log.init();
        CaptureRing capture{};
        capture.init();
        loop->epoch = &epoch;
        loop->metrics = &metrics;
        loop->access_log = &access_log;
        REQUIRE(loop->set_capture(&capture));

        RouteConfig config{};
        PreconnectConnectSubmitFixture fixture{};
        u32 failed_episode = 0;
        REQUIRE(stage_late_failure_response(
            loop, config, test.site, test.profile, &fixture, &failed_episode));
        REQUIRE(config.add_static("/two", kRouteMethodGet, 204));
        Connection& conn = *fixture.conn;
        const u32 id = conn.id;
        BackendHealth* health = backend_health(0, 0);
        REQUIRE(health != nullptr);
        const u32 expected_health = test.site == LateFailureSite::ConnectCompletion ? 1u : 0u;
        REQUIRE_EQ(health->fails, expected_health);
        REQUIRE_EQ(metrics.requests_total, 0u);
        REQUIRE_EQ(metrics.requests_active, 1u);
        REQUIRE_EQ(epoch.epoch.load(std::memory_order_acquire), 1u);
        REQUIRE_EQ(conn.upstream_attempts, 1u);

        const u32 advanced_episode = conn.upstream_episode;
        const auto check_connect_completion_neutrality = [&] {
            CHECK_EQ(conn.upstream_episode, advanced_episode);
            CHECK_EQ(conn.upstream_retiring_episode, failed_episode);
            CHECK_FALSE(conn.upstream_retirement_active);
            CHECK_EQ(conn.upstream_retirement_target_owned, 0u);
            CHECK_EQ(conn.upstream_retirement_cancel_owned, 0u);
            CHECK_EQ(conn.upstream_retirement_cancel_retry, 0u);
            CHECK_EQ(loop->upstream_retirement_retry_count, 0u);
            CHECK_EQ(conn.upstream_close_episode, 0u);
            CHECK_EQ(conn.upstream_close_target_owned, 0u);
            CHECK_EQ(conn.upstream_close_cancel_owned, 0u);
            CHECK_FALSE(conn.upstream_close_pause_cancel_owned);
            CHECK_EQ(conn.response_read_deadline_state, ResponseReadDeadlineState::None);
            CHECK(conn.response_read_deadline_owner_is_neutral());
        };
        if (test.site == LateFailureSite::ConnectCompletion) {
            CHECK_NE(advanced_episode, failed_episode);
            check_connect_completion_neutrality();
        }

        // The successor arrives only after request 1 has been admitted and its
        // configured 502 Send owns the downstream. The multishot Recv remains
        // live (F_MORE), so no second Recv owner may be fabricated.
        const u32 request1_len = conn.req_initial_send_len;
        REQUIRE_EQ(conn.recv_buf.len(), request1_len);
        REQUIRE_EQ(conn.recv_buf.write(kSuccessor, sizeof(kSuccessor) - 1u),
                   sizeof(kSuccessor) - 1u);
        const u32 response1_len = conn.response_header_buf.len();
        __atomic_store_n(loop->backend.sq_tail, fixture.sq_tail, __ATOMIC_RELEASE);
        loop->backend.pending = fixture.backend_pending;
        loop->backend.send_state[id].remaining = 0;
        loop->dispatch({id, static_cast<i32>(response1_len), 0, 0, IoEventType::Send, 0});

        REQUIRE_GE(conn.fd, 0);
        CHECK_EQ(conn.pipeline_depth, 1u);
        CHECK_NE(conn.handler_gen, 0u);
        CHECK_EQ(conn.http1_pipeline_request_generation, conn.handler_gen);
        CHECK_EQ(conn.upstream_attempts, 0u);
        CHECK_EQ(conn.recv_buf.len(), sizeof(kSuccessor) - 1u);
        CHECK(http1_pipeline_request_generation_provisional_is_stable(
            conn,
            ResponseReadDeadlineProfile::BodylessNonHeadContentLengthZero,
            ForwardResponseBufferingMode::CompleteContentLength,
            static_cast<u8>(LogHttpMethod::Get),
            kRouteMethodGet));
        const ResponseReadDeadlineUploadProof saved_proof = conn.response_read_deadline_upload;
        ResponseReadDeadlineUploadProof successor_preflight{};
        successor_preflight.handler_generation = conn.http1_pipeline_request_generation;
        conn.response_read_deadline_upload = successor_preflight;
        CHECK(http1_pipeline_request_generation_jit_candidate_is_stable(
            conn,
            successor_preflight,
            ResponseReadDeadlineProfile::BodylessNonHeadContentLengthZero,
            ForwardResponseBufferingMode::CompleteContentLength,
            static_cast<u8>(LogHttpMethod::Get),
            kRouteMethodGet,
            static_cast<u16>(RequestPolicyId::Http11FixedStrip)));
        conn.response_read_deadline_upload = saved_proof;
        CHECK_EQ(conn.resp_status, 204u);
        CHECK_EQ(conn.on_send, &on_response_sent<IoUringEventLoop>);
        CHECK(conn.send_armed);
        CHECK(conn.recv_armed);
        CHECK_EQ(conn.pending_ops, 2u);
        CHECK_EQ(metrics.requests_total, 1u);
        CHECK_EQ(metrics.requests_active, 1u);
        CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), 3u);
        CHECK(buf_has(conn.send_buf.data(), conn.send_buf.len(), "HTTP/1.1 204"));
        CHECK_EQ(health->fails, expected_health);
        if (test.site == LateFailureSite::ConnectCompletion) check_connect_completion_neutrality();

        AccessLogEntry access1{};
        REQUIRE(access_log.pop(access1));
        CHECK_EQ(access1.status, 502u);
        AccessLogEntry no_access{};
        CHECK_FALSE(access_log.pop(no_access));
        CaptureEntry capture1{};
        REQUIRE(capture.pop(capture1));
        CHECK_EQ(capture1.resp_status, 502u);
        CaptureEntry no_capture{};
        CHECK_FALSE(capture.pop(no_capture));

        if (test.site == LateFailureSite::ConnectCompletion) {
            const u32 pending_before_duplicate = conn.pending_ops;
            const u64 requests_before_duplicate = metrics.requests_total;
            const u64 epoch_before_duplicate = epoch.epoch.load(std::memory_order_acquire);
            const u32 request2_len = conn.recv_buf.len();
            const u32 request2_send_len = conn.send_buf.len();
            const auto request2_handler_before_duplicate = conn.on_send;
            const bool send_armed_before_duplicate = conn.send_armed;
            const bool recv_armed_before_duplicate = conn.recv_armed;
            const u32 pipeline_depth_before_duplicate = conn.pipeline_depth;
            REQUIRE_EQ(request2_len, sizeof(kSuccessor) - 1u);
            REQUIRE_EQ(__builtin_memcmp(conn.recv_buf.data(), kSuccessor, request2_len), 0);
            loop->dispatch(
                {id, -ECONNREFUSED, 0, 0, IoEventType::UpstreamConnect, 0, 0, failed_episode});
            CHECK_EQ(conn.pending_ops, pending_before_duplicate);
            CHECK_EQ(conn.recv_buf.len(), request2_len);
            CHECK_EQ(__builtin_memcmp(conn.recv_buf.data(), kSuccessor, request2_len), 0);
            CHECK_EQ(conn.send_buf.len(), request2_send_len);
            CHECK_EQ(conn.on_send, request2_handler_before_duplicate);
            CHECK_EQ(conn.on_send, &on_response_sent<IoUringEventLoop>);
            CHECK_EQ(conn.send_armed, send_armed_before_duplicate);
            CHECK_EQ(conn.recv_armed, recv_armed_before_duplicate);
            CHECK_EQ(conn.pipeline_depth, pipeline_depth_before_duplicate);
            CHECK_EQ(conn.resp_status, 204u);
            CHECK_EQ(metrics.requests_total, requests_before_duplicate);
            CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), epoch_before_duplicate);
            CHECK_EQ(health->fails, expected_health);
            check_connect_completion_neutrality();
        }

        const u32 response2_len = conn.send_buf.len();
        __atomic_store_n(loop->backend.sq_tail, fixture.sq_tail, __ATOMIC_RELEASE);
        loop->backend.pending = fixture.backend_pending;
        loop->backend.send_state[id].remaining = 0;
        loop->dispatch({id, static_cast<i32>(response2_len), 0, 0, IoEventType::Send, 0});
        CHECK_EQ(metrics.requests_total, 2u);
        CHECK_EQ(metrics.requests_active, 0u);
        CHECK_EQ(epoch.epoch.load(std::memory_order_acquire), 4u);
        CHECK(conn.recv_armed);
        CHECK_EQ(conn.pending_ops, 1u);
        AccessLogEntry access2{};
        REQUIRE(access_log.pop(access2));
        CHECK_EQ(access2.status, 204u);
        CaptureEntry capture2{};
        REQUIRE(capture.pop(capture2));
        CHECK_EQ(capture2.resp_status, 204u);
        CHECK_EQ(health->fails, expected_health);

        cleanup_late_failure_fixture(loop, fixture);
    }
}

TEST(iouring_validated_failure_pipeline,
     connect_completion_late_arrival_dispatches_exact_close_successor) {
    ScopedBackendHealthReset health_reset{};
    ScopedIoUringLoopForRetirement guard;
    if (!guard.init()) SKIP("io_uring unavailable");
    auto* loop = guard.loop;
    ShardMetrics metrics{};
    metrics.init();
    loop->metrics = &metrics;
    RouteConfig config{};
    REQUIRE(install_representation200_exact(config, "/two"));
    PreconnectConnectSubmitFixture fixture{};
    u32 failed_episode = 0;
    REQUIRE(stage_late_failure_response(loop,
                                        config,
                                        LateFailureSite::ConnectCompletion,
                                        AsyncConnectFailureProfile::BodylessGet,
                                        &fixture,
                                        &failed_episode));
    REQUIRE(config.add_static("/two", kRouteMethodGet, 204));
    Connection& conn = *fixture.conn;
    const u32 id = conn.id;
    static constexpr u8 kSuccessor[] =
        "GET /two HTTP/1.1\r\nHost: client.example\r\nConnection: close\r\n\r\n";

    // Publication of request1's configured response already owns Send. Only
    // now does request2 arrive through the still-live downstream Recv owner.
    REQUIRE(conn.send_armed);
    REQUIRE_EQ(conn.upstream_attempts, 1u);
    REQUIRE_EQ(conn.recv_buf.write(kSuccessor, sizeof(kSuccessor) - 1u), sizeof(kSuccessor) - 1u);
    __atomic_store_n(loop->backend.sq_tail, fixture.sq_tail, __ATOMIC_RELEASE);
    loop->backend.pending = fixture.backend_pending;
    const u32 response1_len = conn.response_header_buf.len();
    loop->backend.send_state[id].remaining = 0;
    loop->dispatch({id, static_cast<i32>(response1_len), 0, 0, IoEventType::Send, 0});

    REQUIRE_GE(conn.fd, 0);
    CHECK_EQ(conn.resp_status, 200u);
    CHECK_EQ(conn.pipeline_depth, 1u);
    CHECK_EQ(conn.http1_pipeline_request_generation, conn.handler_gen);
    CHECK_FALSE(conn.keep_alive);
    CHECK_EQ(conn.upstream_attempts, 0u);
    CHECK_EQ(conn.upstream_retiring_episode, failed_episode);
    CHECK_FALSE(conn.upstream_connect_armed);
    CHECK_FALSE(conn.upstream_send_armed);
    CHECK_FALSE(conn.upstream_recv_armed);
    u8 normalized[SmallLoop::kBufSize]{};
    REQUIRE(conn.send_buf.len() <= sizeof(normalized));
    __builtin_memcpy(normalized, conn.send_buf.data(), conn.send_buf.len());
    REQUIRE(normalize_redirect_date(normalized, conn.send_buf.len()));
    const std::string expected = expected_representation200_wire(false, false);
    REQUIRE_EQ(conn.send_buf.len(), static_cast<u32>(expected.size()));
    CHECK_EQ(__builtin_memcmp(normalized, expected.data(), expected.size()), 0);

    const u32 response2_len = conn.send_buf.len();
    loop->backend.send_state[id].remaining = 0;
    loop->dispatch({id, static_cast<i32>(response2_len), 0, 0, IoEventType::Send, 0});
    CHECK_EQ(loop->conns[id].fd, -1);
    CHECK_EQ(metrics.requests_total, 2u);
    CHECK_EQ(metrics.requests_active, 0u);
    cleanup_late_failure_fixture(loop, fixture);
}

TEST(iouring_validated_failure_pipeline,
     complete_positive_terminal_successor_consumes_recv_before_immediate_dispatch) {
    ScopedBackendHealthReset health_reset{};
    ScopedIoUringLoopForRetirement guard;
    if (!guard.init()) SKIP("io_uring unavailable");
    auto* loop = guard.loop;
    ShardMetrics metrics{};
    metrics.init();
    loop->metrics = &metrics;
    RouteConfig config{};
    PreconnectConnectSubmitFixture fixture{};
    u32 failed_episode = 0;
    REQUIRE(stage_late_failure_response(loop,
                                        config,
                                        LateFailureSite::ConnectCompletion,
                                        AsyncConnectFailureProfile::BodylessGet,
                                        &fixture,
                                        &failed_episode));
    REQUIRE(config.add_static("/two", kRouteMethodGet, 206));
    Connection& conn = *fixture.conn;
    const u32 id = conn.id;
    static constexpr u8 kSuccessor[] = "GET /two HTTP/1.1\r\nHost: client.example\r\n\r\n";

    // Request 2 arrives only after the validated failure has staged request 1's
    // downstream Send. Deliver it through the still-live multishot Recv as a
    // positive terminal event, rather than pre-populating a fixture state.
    REQUIRE(conn.send_armed);
    REQUIRE(conn.recv_armed);
    REQUIRE_EQ(conn.pending_ops, 2u);
    REQUIRE_EQ(conn.recv_buf.write(kSuccessor, sizeof(kSuccessor) - 1u), sizeof(kSuccessor) - 1u);
    __atomic_store_n(loop->backend.sq_tail, fixture.sq_tail, __ATOMIC_RELEASE);
    loop->backend.pending = fixture.backend_pending;
    const u32 tail_before_terminal_recv = __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
    loop->dispatch({id, static_cast<i32>(sizeof(kSuccessor) - 1u), 0, 0, IoEventType::Recv, 0});

    REQUIRE_GE(conn.fd, 0);
    CHECK(conn.send_armed);
    CHECK_FALSE(conn.recv_armed);
    CHECK_EQ(conn.pending_ops, 1u);
    CHECK_EQ(conn.recv_buf.len(), conn.req_initial_send_len + sizeof(kSuccessor) - 1u);
    CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE), tail_before_terminal_recv);
    CHECK_EQ(metrics.requests_total, 0u);
    CHECK_EQ(metrics.requests_active, 1u);

    const u32 response1_len = conn.response_header_buf.len();
    loop->backend.send_state[id].remaining = 0;
    loop->dispatch({id, static_cast<i32>(response1_len), 0, 0, IoEventType::Send, 0});

    REQUIRE_GE(conn.fd, 0);
    CHECK_EQ(conn.resp_status, 206u);
    CHECK_EQ(conn.on_send, &on_response_sent<IoUringEventLoop>);
    CHECK(conn.send_armed);
    CHECK_FALSE(conn.recv_armed);
    CHECK_EQ(conn.pending_ops, 1u);
    CHECK_EQ(conn.pipeline_depth, 1u);
    CHECK_EQ(conn.recv_buf.len(), sizeof(kSuccessor) - 1u);
    CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE),
             tail_before_terminal_recv + 1u);
    CHECK_EQ(loop->backend.pending, fixture.backend_pending + 1u);
    CHECK_EQ(metrics.requests_total, 1u);
    CHECK_EQ(metrics.requests_active, 1u);
    CHECK(buf_has(conn.send_buf.data(), conn.send_buf.len(), "HTTP/1.1 206"));

    const u32 response2_len = conn.send_buf.len();
    loop->backend.send_state[id].remaining = 0;
    loop->dispatch({id, static_cast<i32>(response2_len), 0, 0, IoEventType::Send, 0});

    REQUIRE_GE(conn.fd, 0);
    CHECK_FALSE(conn.send_armed);
    CHECK(conn.recv_armed);
    CHECK_EQ(conn.pending_ops, 1u);
    CHECK_EQ(conn.pipeline_depth, 0u);
    CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE),
             tail_before_terminal_recv + 2u);
    CHECK_EQ(loop->backend.pending, fixture.backend_pending + 2u);
    CHECK_EQ(metrics.requests_total, 2u);
    CHECK_EQ(metrics.requests_active, 0u);

    cleanup_late_failure_fixture(loop, fixture);
}

TEST(iouring_validated_failure_pipeline,
     fragmented_late_successor_preserves_live_or_rearms_terminal_recv_exactly_once) {
    static constexpr u8 kPartial[] = "GET /two HTTP/1.1\r\nHost: client";
    static constexpr u8 kRemainder[] = ".example\r\n\r\n";

    for (const bool terminal_late_recv : {false, true}) {
        ScopedBackendHealthReset health_reset{};
        ScopedIoUringLoopForRetirement guard;
        if (!guard.init()) SKIP("io_uring unavailable");
        auto* loop = guard.loop;
        ShardMetrics metrics{};
        metrics.init();
        loop->metrics = &metrics;
        RouteConfig config{};
        PreconnectConnectSubmitFixture fixture{};
        u32 failed_episode = 0;
        REQUIRE(stage_late_failure_response(loop,
                                            config,
                                            LateFailureSite::ConnectCompletion,
                                            AsyncConnectFailureProfile::BodylessGet,
                                            &fixture,
                                            &failed_episode));
        REQUIRE(config.add_static("/two", kRouteMethodGet, 205));
        Connection& conn = *fixture.conn;
        const u32 id = conn.id;
        REQUIRE_EQ(conn.upstream_attempts, 1u);
        REQUIRE_EQ(conn.recv_buf.write(kPartial, sizeof(kPartial) - 1u), sizeof(kPartial) - 1u);
        if (terminal_late_recv) {
            conn.recv_armed = false;
            conn.pending_ops--;
        }

        __atomic_store_n(loop->backend.sq_tail, fixture.sq_tail, __ATOMIC_RELEASE);
        loop->backend.pending = fixture.backend_pending;
        const u32 tail_before_send = __atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE);
        const u32 response1_len = conn.response_header_buf.len();
        loop->backend.send_state[id].remaining = 0;
        loop->dispatch({id, static_cast<i32>(response1_len), 0, 0, IoEventType::Send, 0});

        REQUIRE_GE(conn.fd, 0);
        CHECK_EQ(conn.pipeline_depth, 1u);
        CHECK_EQ(conn.http1_pipeline_request_generation, 0u);
        CHECK_EQ(conn.state, ConnState::ReadingHeader);
        CHECK_EQ(conn.on_recv, &on_header_received<IoUringEventLoop>);
        CHECK_EQ(conn.recv_buf.len(), sizeof(kPartial) - 1u);
        CHECK(conn.recv_armed);
        CHECK_EQ(conn.pending_ops, 1u);
        const u32 expected_tail = tail_before_send + (terminal_late_recv ? 1u : 0u);
        CHECK_EQ(__atomic_load_n(loop->backend.sq_tail, __ATOMIC_ACQUIRE), expected_tail);
        CHECK_EQ(metrics.requests_total, 1u);
        CHECK_EQ(metrics.requests_active, 0u);
        CHECK_EQ(conn.upstream_attempts, 1u);

        REQUIRE_EQ(conn.recv_buf.write(kRemainder, sizeof(kRemainder) - 1u),
                   sizeof(kRemainder) - 1u);
        loop->dispatch({id,
                        static_cast<i32>(sizeof(kRemainder) - 1u),
                        0,
                        0,
                        IoEventType::Recv,
                        static_cast<u8>(!terminal_late_recv)});
        REQUIRE_GE(conn.fd, 0);
        CHECK_NE(conn.handler_gen, 0u);
        CHECK_EQ(conn.http1_pipeline_request_generation, conn.handler_gen);
        CHECK_EQ(conn.upstream_attempts, 0u);
        CHECK_EQ(conn.resp_status, 205u);
        CHECK_EQ(conn.on_send, &on_response_sent<IoUringEventLoop>);
        CHECK(conn.send_armed);
        CHECK_EQ(conn.recv_armed, !terminal_late_recv);
        CHECK_EQ(conn.pending_ops, terminal_late_recv ? 1u : 2u);
        CHECK_EQ(metrics.requests_total, 1u);
        CHECK_EQ(metrics.requests_active, 1u);
        CHECK(buf_has(conn.send_buf.data(), conn.send_buf.len(), "HTTP/1.1 205"));

        if (terminal_late_recv) {
            const u32 response2_len = conn.send_buf.len();
            __atomic_store_n(loop->backend.sq_tail, fixture.sq_tail, __ATOMIC_RELEASE);
            loop->backend.pending = fixture.backend_pending;
            loop->backend.send_state[id].remaining = 0;
            loop->dispatch({id, static_cast<i32>(response2_len), 0, 0, IoEventType::Send, 0});
            CHECK_GE(loop->conns[id].fd, 0);
            CHECK(loop->conns[id].recv_armed);
            CHECK_EQ(loop->conns[id].pending_ops, 1u);
            CHECK_EQ(metrics.requests_total, 2u);
            CHECK_EQ(metrics.requests_active, 0u);
        }

        cleanup_late_failure_fixture(loop, fixture);
    }
}

