    REQUIRE_EQ(conn->on_recv, &on_request_policy_body_recvd<IoUringEventLoop>);
    REQUIRE_EQ(conn->request_config, &pinned);

    active = &hot;
    static constexpr u8 kRemainder[] = {'b', 'c'};
